window.RECALL_PHARM = {"chapters":[{"title":"第一章 绪言","questions":[{"type":"D","stem":"名词解释：药理学","answer":"研究药物与机体（包括病原体）相互作用及作用规律的科学，任务是阐明药物作用、作用机制、不良反应及体内过程，为临床合理用药提供理论依据。","rationale":"出自概念手册「绪言」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph01_q001","chapter":"第一章 绪言","chapterIdx":0,"num":1},{"type":"D","stem":"名词解释：药效学","answer":"即药物效应动力学，研究药物对机体的作用、作用机制以及药物剂量与效应之间关系的学科。","rationale":"出自概念手册「绪言」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph01_q002","chapter":"第一章 绪言","chapterIdx":0,"num":2},{"type":"D","stem":"名词解释：药动学","answer":"即药物代谢动力学，研究药物在体内的吸收、分布、代谢、排泄过程以及血药浓度随时间变化规律的学科。","rationale":"出自概念手册「绪言」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph01_q003","chapter":"第一章 绪言","chapterIdx":0,"num":3},{"type":"D","stem":"名词解释：药物","answer":"能影响机体生理功能和/或病理状态，用于预防、治疗、诊断疾病以及计划生育的化学物质。","rationale":"出自概念手册「绪言」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph01_q004","chapter":"第一章 绪言","chapterIdx":0,"num":4},{"type":"D","stem":"名词解释：化学治疗","answer":"用化学药物抑制或杀灭体内病原体（细菌、真菌、病毒、寄生虫等）及肿瘤细胞，以治疗感染性疾病和肿瘤的方法。","rationale":"出自概念手册「绪言」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph01_q005","chapter":"第一章 绪言","chapterIdx":0,"num":5},{"type":"D","stem":"名词解释：化学治疗学","answer":"研究药物、病原体和机体三者之间相互作用规律，以及抗病原体药物合理应用的学科。","rationale":"出自概念手册「绪言」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph01_q006","chapter":"第一章 绪言","chapterIdx":0,"num":6},{"type":"D","stem":"名词解释：新药","answer":"指未曾在中国境内上市销售的药品，包括创新药、改良型新药以及仿制药等注册分类。","rationale":"出自概念手册「绪言」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph01_q007","chapter":"第一章 绪言","chapterIdx":0,"num":7},{"type":"F","stem":"填空题：指未曾在中国境内上市销售的药品，包括创______、改良型新药以及仿制药等注册分类。","answer":"新药","rationale":"出自概念手册「绪言」核心概念：新药。","id":"rph01_q008","chapter":"第一章 绪言","chapterIdx":0,"num":8},{"type":"D","stem":"名词解释：仿制药","answer":"仿制国家已批准上市药品的品种，与被仿制药具有相同的活性成分、剂型、给药途径和治疗作用。","rationale":"出自概念手册「绪言」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph01_q009","chapter":"第一章 绪言","chapterIdx":0,"num":9},{"type":"F","stem":"填空题：仿制国家已批准上市药品的品种，与被______具有相同的活性成分、剂型、给药途径和治疗作用。","answer":"仿制药","rationale":"出自概念手册「绪言」核心概念：仿制药。","id":"rph01_q010","chapter":"第一章 绪言","chapterIdx":0,"num":10},{"type":"D","stem":"名词解释：安慰剂对照","answer":"以不含有效成分的安慰剂作为对照的试验设计，用于排除心理因素、疾病自愈等对疗效和不良反应评价的影响。","rationale":"出自概念手册「绪言」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph01_q011","chapter":"第一章 绪言","chapterIdx":0,"num":11},{"type":"D","stem":"名词解释：双盲法","answer":"临床试验中受试者与观察者均不知道所用药物是试验药还是对照药的设计方法，可减少主观偏倚。","rationale":"出自概念手册「绪言」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph01_q012","chapter":"第一章 绪言","chapterIdx":0,"num":12},{"type":"D","stem":"名词解释：临床药理学","answer":"以人体为对象，研究药物与机体相互作用规律及药物临床应用的学科，是药理学与临床医学的桥梁。","rationale":"出自概念手册「绪言」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph01_q013","chapter":"第一章 绪言","chapterIdx":0,"num":13},{"type":"D","stem":"名词解释：分子药理学","answer":"在分子水平研究药物与受体、酶、离子通道、核酸等靶点相互作用机制及构效关系的学科。","rationale":"出自概念手册「绪言」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph01_q014","chapter":"第一章 绪言","chapterIdx":0,"num":14},{"type":"D","stem":"名词解释：时辰药理学","answer":"研究机体生物节律对药物作用及药物体内过程影响的学科，为择时用药提供依据。","rationale":"出自概念手册「绪言」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph01_q015","chapter":"第一章 绪言","chapterIdx":0,"num":15},{"type":"D","stem":"名词解释：实验药理学","answer":"以整体动物、离体器官、细胞或分子为对象研究药物作用的学科，是新药临床前评价与药理学研究的基础方法。","rationale":"出自概念手册「绪言」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph01_q016","chapter":"第一章 绪言","chapterIdx":0,"num":16},{"type":"S","stem":"简答题：简述药理学的学科任务。","answer":"①阐明药物的作用及其作用机制，为临床合理用药、发挥最佳疗效、防治不良反应提供理论依据；②研究开发新药、发现药物的新用途；③评价药物的安全性与有效性，为药品管理与合理用药提供依据；④为其他生命科学研究提供重要的科学依据和科研方法，以实验药理学与临床药理学为两大研究途径。","rationale":"采分点是“阐明作用与机制—研发新药与新用途—评价安全有效—为其他学科提供方法与依据”。易错是把学科任务写成“研究药物化学结构”或只答临床用药一点。","id":"rph01_q017","chapter":"第一章 绪言","chapterIdx":0,"num":17},{"type":"F","stem":"填空题：药理学的研究内容分为______和______两大部分，前者研究药物对机体的作用及作用机制，后者研究药物在体内的______过程及血药浓度随时间变化的规律。","answer":"①药物效应动力学（药效学）②药物代谢动力学（药动学）③吸收、分布、代谢、排泄（ADME）","rationale":"药效学回答“药物对机体做了什么”，药动学回答“机体对药物做了什么”；ADME四环节顺序不能颠倒。","id":"rph01_q018","chapter":"第一章 绪言","chapterIdx":0,"num":18},{"type":"F","stem":"填空题：药理学的研究方法分为______和______两大类，后者以______为研究对象。","answer":"①实验药理学 ②临床药理学 ③人体（健康志愿者与患者）","rationale":"实验药理学以整体动物、离体器官、细胞或分子为对象；临床药理学以人体为对象，是药理学与临床医学的桥梁，两者互相补充。","id":"rph01_q019","chapter":"第一章 绪言","chapterIdx":0,"num":19},{"type":"T","stem":"判断题：药物与毒物在化学本质上是不能截然分开的，任何药物用量超过治疗浓度时都可能达到中毒浓度而产生毒性作用。","options":{"A":"正确","B":"错误"},"answer":["A"],"rationale":"绪言部分明确指出药物与毒物在化学本质上不能截然分开，较小剂量即剧烈损伤机体健康者称毒物；超过治疗浓度后药物即产生毒性作用。","id":"rph01_q020","chapter":"第一章 绪言","chapterIdx":0,"num":20},{"type":"T","stem":"判断题：药物作用是指药物引起机体生理、生化功能或形态的变化，药物效应是指药物对机体的初始作用。","options":{"A":"正确","B":"错误"},"answer":["B"],"rationale":"两者说反了：作用（action）是药物对机体的初始作用，效应（effect）是作用引起的机体功能或形态变化，作用为动因、效应为结果。","id":"rph01_q021","chapter":"第一章 绪言","chapterIdx":0,"num":21}]},{"title":"第二章 药物效应动力学","questions":[{"type":"D","stem":"名词解释：药物作用","answer":"药物与机体生物大分子（受体、酶、离子通道、转运体、核酸等）相互作用所引起的初始反应，是产生药理效应的起因，具有特异性。","rationale":"出自概念手册「药物效应动力学」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph02_q001","chapter":"第二章 药物效应动力学","chapterIdx":1,"num":1},{"type":"D","stem":"名词解释：药理效应","answer":"药物作用的结果，是机体器官原有功能水平或形态发生的改变，表现为兴奋（功能提高）和抑制（功能降低）两种基本形式。","rationale":"出自概念手册「药物效应动力学」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph02_q002","chapter":"第二章 药物效应动力学","chapterIdx":1,"num":2},{"type":"D","stem":"名词解释：选择性","answer":"一定剂量下药物只对某些组织器官产生明显作用，而对其他组织器官作用很小或无作用，是药物分类、临床选药和不良反应多少的依据。","rationale":"出自概念手册「药物效应动力学」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph02_q003","chapter":"第二章 药物效应动力学","chapterIdx":1,"num":3},{"type":"D","stem":"名词解释：量效关系","answer":"在一定范围内，药物的药理效应随剂量或浓度增加而增强，二者的规律性变化称量效关系，常以量效曲线表示，是确定剂量的基础。","rationale":"出自概念手册「药物效应动力学」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph02_q004","chapter":"第二章 药物效应动力学","chapterIdx":1,"num":4},{"type":"F","stem":"填空题：在一定范围内，药物的药理效应随剂量或浓度增加而增强，二者的规律性变化称______，常以量效曲线表示，是确定剂量的基础。","answer":"量效关系","rationale":"出自概念手册「药物效应动力学」核心概念：量效关系。","id":"rph02_q005","chapter":"第二章 药物效应动力学","chapterIdx":1,"num":5},{"type":"D","stem":"名词解释：阈剂量","answer":"又称最小有效量，指刚能引起药理效应的最小剂量；低于此剂量不出现效应，是确定用药剂量下限和评价药物敏感性的依据。","rationale":"出自概念手册「药物效应动力学」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph02_q006","chapter":"第二章 药物效应动力学","chapterIdx":1,"num":6},{"type":"D","stem":"名词解释：效能","answer":"药物所能产生的最大效应，即量效曲线的最高点（Emax），反映药物内在活性的大小，与剂量无关，是评价药物疗效的重要指标。","rationale":"出自概念手册「药物效应动力学」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph02_q007","chapter":"第二章 药物效应动力学","chapterIdx":1,"num":7},{"type":"D","stem":"名词解释：效价强度","answer":"能引起等效反应（通常取50%效应）时所需的药物剂量或浓度，用量越小效价强度越大，主要反映药物与受体的亲和力高低。","rationale":"出自概念手册「药物效应动力学」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph02_q008","chapter":"第二章 药物效应动力学","chapterIdx":1,"num":8},{"type":"F","stem":"填空题：能引起等效反应（通常取50%效应）时所需的药物剂量或浓度，用量越小______越大，主要反映药物与受体的亲和力高低。","answer":"效价强度","rationale":"出自概念手册「药物效应动力学」核心概念：效价强度。","id":"rph02_q009","chapter":"第二章 药物效应动力学","chapterIdx":1,"num":9},{"type":"D","stem":"名词解释：半数有效量","answer":"能使半数实验动物或观察对象出现阳性反应的剂量，用ED50表示，是评价药物效价强度最常用的参数。","rationale":"出自概念手册「药物效应动力学」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph02_q010","chapter":"第二章 药物效应动力学","chapterIdx":1,"num":10},{"type":"D","stem":"名词解释：治疗指数","answer":"半数致死量与半数有效量的比值，即TI=LD50/ED50，数值越大相对越安全，但不能完全反映药物的安全性。","rationale":"出自概念手册「药物效应动力学」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph02_q011","chapter":"第二章 药物效应动力学","chapterIdx":1,"num":11},{"type":"D","stem":"名词解释：安全范围","answer":"最小有效量与最小中毒量之间的剂量范围，范围越宽用药越安全，比治疗指数更能反映药物的安全性。","rationale":"出自概念手册「药物效应动力学」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph02_q012","chapter":"第二章 药物效应动力学","chapterIdx":1,"num":12},{"type":"D","stem":"名词解释：不良反应","answer":"凡不符合用药目的、给患者带来不适或痛苦甚至损害的反应，包括副反应、毒性反应、后遗效应、继发反应、变态反应、特异质反应和停药反应等。","rationale":"出自概念手册「药物效应动力学」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph02_q013","chapter":"第二章 药物效应动力学","chapterIdx":1,"num":13},{"type":"D","stem":"名词解释：受体","answer":"存在于细胞膜、细胞浆或细胞核内，能识别并特异性结合内源性配体或药物，进而传递信号引起生物效应的大分子物质。","rationale":"出自概念手册「药物效应动力学」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph02_q014","chapter":"第二章 药物效应动力学","chapterIdx":1,"num":14},{"type":"D","stem":"名词解释：亲和力","answer":"药物与受体结合的能力，通常用药物-受体复合物解离常数Kd的负对数pD2表示，亲和力越大越容易与受体结合。","rationale":"出自概念手册「药物效应动力学」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph02_q015","chapter":"第二章 药物效应动力学","chapterIdx":1,"num":15},{"type":"F","stem":"填空题：药物与受体结合的能力，通常用药物-受体复合物解离常数Kd的负对数pD2表示，______越大越容易与受体结合。","answer":"亲和力","rationale":"出自概念手册「药物效应动力学」核心概念：亲和力。","id":"rph02_q016","chapter":"第二章 药物效应动力学","chapterIdx":1,"num":16},{"type":"D","stem":"名词解释：内在活性","answer":"又称效应力，指药物与受体结合后激活受体并产生效应的能力，用α表示；完全激动药α为1，拮抗药α为0。","rationale":"出自概念手册「药物效应动力学」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph02_q017","chapter":"第二章 药物效应动力学","chapterIdx":1,"num":17},{"type":"D","stem":"名词解释：激动药","answer":"既有较强亲和力又有较强内在活性，能与受体结合并激活受体产生效应的药物，如吗啡、肾上腺素。","rationale":"出自概念手册「药物效应动力学」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph02_q018","chapter":"第二章 药物效应动力学","chapterIdx":1,"num":18},{"type":"D","stem":"名词解释：拮抗药","answer":"有较强亲和力而无内在活性（α为0），本身不产生效应，但能占据受体而阻断激动药作用的药物。","rationale":"出自概念手册「药物效应动力学」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph02_q019","chapter":"第二章 药物效应动力学","chapterIdx":1,"num":19},{"type":"D","stem":"名词解释：竞争性拮抗药","answer":"与激动药竞争同一受体且结合可逆，使激动药量效曲线平行右移而最大效应不变，其拮抗强度用pA2表示。","rationale":"出自概念手册「药物效应动力学」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph02_q020","chapter":"第二章 药物效应动力学","chapterIdx":1,"num":20},{"type":"D","stem":"名词解释：非竞争性拮抗药","answer":"与受体结合牢固或作用于邻近的别构位点，使激动药量效曲线右移且最大效应降低，增加激动药浓度也不能完全对抗。","rationale":"出自概念手册「药物效应动力学」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph02_q021","chapter":"第二章 药物效应动力学","chapterIdx":1,"num":21},{"type":"S","stem":"简答题：举例说明药物可能发生哪些不良反应。","answer":"①副作用：治疗剂量下与用药目的无关的作用，由选择性低引起，可预知、难避免，如阿托品解除胃肠绞痛时出现口干、心悸；②毒性反应：剂量过大或用药时间过长致血药浓度达中毒浓度，如庆大霉素引起神经性耳聋；③后遗效应：停药后血药浓度已降至阈浓度以下仍残存的效应，如服长效巴比妥类后次晨困倦、乏力；④停药反应：长期用药突然停药使原病加剧，如长期用β受体阻断药降压后停药血压回升；⑤变态反应：异常免疫反应，与剂量无关、不易预知、药理拮抗药解救无效，如青霉素过敏性休克；⑥特异质反应：少数人因遗传因素对药物反应异常，如琥珀胆碱所致恶性高热。","rationale":"采分点为六类不良反应各举一例（副作用、毒性反应、后遗效应、停药反应、变态反应、特异质反应）。易错是副作用与毒性反应界限不清：副作用发生于治疗量；毒性反应与剂量相关，本质是药理效应的增强和延续。","id":"rph02_q022","chapter":"第二章 药物效应动力学","chapterIdx":1,"num":22},{"type":"F","stem":"填空题：竞争性拮抗药存在时，激动药的量效曲线______，最大效应______。","answer":"①平行右移 ②不变（斜率也不变）","rationale":"与非竞争性拮抗药对比记忆：后者与受体结合牢固、难以逆转，量效曲线右移的同时最大效应降低、斜率降低。","id":"rph02_q023","chapter":"第二章 药物效应动力学","chapterIdx":1,"num":23},{"type":"F","stem":"填空题：治疗指数是指______与______的比值，其值越大表示药物越______，但不能据此判断药物绝对安全。","answer":"①LD50 ②ED50 ③安全","rationale":"三个安全性指标不可混用：治疗指数＝LD50/ED50，安全范围指LD5与ED95之间的距离，安全指数＝LD1/ED99；治疗指数无法评价与机制无关的不良反应（如青霉素过敏）。","id":"rph02_q024","chapter":"第二章 药物效应动力学","chapterIdx":1,"num":24},{"type":"T","stem":"判断题：药物与受体结合后，内在活性决定药物的效能，亲和力决定药物的效价强度。","options":{"A":"正确","B":"错误"},"answer":["A"],"rationale":"笔记明确：亲和力对应效价强度，内在活性对应效能；亲和力相等时效应强度取决于内在活性，内在活性相等时取决于亲和力。","id":"rph02_q025","chapter":"第二章 药物效应动力学","chapterIdx":1,"num":25},{"type":"T","stem":"判断题：安全范围是指LD50与ED50之间的距离，其数值越大药物越安全。","options":{"A":"正确","B":"错误"},"answer":["B"],"rationale":"安全范围是LD5与ED95之间的距离；LD50/ED50是治疗指数。两个概念混淆是常见失分点。","id":"rph02_q026","chapter":"第二章 药物效应动力学","chapterIdx":1,"num":26}]},{"title":"第三章 药物代谢动力学","questions":[{"type":"D","stem":"名词解释：简单扩散","answer":"又称被动转运，药物顺浓度差从高浓度侧向低浓度侧跨膜转运，不耗能、无饱和与竞争现象，是绝大多数药物吸收转运的主要方式。","rationale":"出自概念手册「药物代谢动力学」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph03_q001","chapter":"第三章 药物代谢动力学","chapterIdx":2,"num":1},{"type":"D","stem":"名词解释：主动转运","answer":"药物逆浓度差或电位差跨膜转运，需载体并消耗能量，具有饱和现象和竞争性抑制，如肾小管分泌和某些血脑屏障转运。","rationale":"出自概念手册「药物代谢动力学」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph03_q002","chapter":"第三章 药物代谢动力学","chapterIdx":2,"num":2},{"type":"D","stem":"名词解释：吸收","answer":"药物从用药部位进入血液循环的过程，静脉注射无吸收过程；吸收的速度和程度受给药途径、药物理化性质和首过效应影响。","rationale":"出自概念手册「药物代谢动力学」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph03_q003","chapter":"第三章 药物代谢动力学","chapterIdx":2,"num":3},{"type":"F","stem":"填空题：药物从用药部位进入血液循环的过程，静脉注射无______过程；吸收的速度和程度受给药途径、药物理化性质和首过效应影响。","answer":"吸收","rationale":"出自概念手册「药物代谢动力学」核心概念：吸收。","id":"rph03_q004","chapter":"第三章 药物代谢动力学","chapterIdx":2,"num":4},{"type":"D","stem":"名词解释：首过消除","answer":"又称首过效应，口服药物经胃肠吸收后先经门静脉入肝，部分被肠壁和肝脏代谢灭活，使进入体循环的药量减少。","rationale":"出自概念手册「药物代谢动力学」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph03_q005","chapter":"第三章 药物代谢动力学","chapterIdx":2,"num":5},{"type":"D","stem":"名词解释：分布","answer":"药物吸收后经血液循环转运到各组织器官的过程，受组织血流量、血浆蛋白结合率、药物理化性质和屏障因素影响。","rationale":"出自概念手册「药物代谢动力学」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph03_q006","chapter":"第三章 药物代谢动力学","chapterIdx":2,"num":6},{"type":"D","stem":"名词解释：表观分布容积","answer":"药物在体内达到动态平衡时，体内药量与血药浓度的比值（Vd等于A除以C），反映药物在组织中分布的广窄，并非真实体液容积。","rationale":"出自概念手册「药物代谢动力学」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph03_q007","chapter":"第三章 药物代谢动力学","chapterIdx":2,"num":7},{"type":"D","stem":"名词解释：血浆蛋白结合率","answer":"血中药物与血浆蛋白结合的比例，结合型药物分子大、不易跨膜且暂时无活性，游离型药物才能转运并产生效应。","rationale":"出自概念手册「药物代谢动力学」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph03_q008","chapter":"第三章 药物代谢动力学","chapterIdx":2,"num":8},{"type":"D","stem":"名词解释：血脑屏障","answer":"由脑毛细血管内皮细胞、基膜和星形胶质细胞构成的结构，限制水溶性、解离型和大分子药物进入脑组织。","rationale":"出自概念手册「药物代谢动力学」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph03_q009","chapter":"第三章 药物代谢动力学","chapterIdx":2,"num":9},{"type":"D","stem":"名词解释：生物转化","answer":"药物在体内经酶催化发生化学结构改变的过程，主要在肝脏进行，多数药物转化后活性降低或消失，少数被激活。","rationale":"出自概念手册「药物代谢动力学」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph03_q010","chapter":"第三章 药物代谢动力学","chapterIdx":2,"num":10},{"type":"D","stem":"名词解释：肝药酶","answer":"肝细胞微粒体的混合功能氧化酶系统，主要是细胞色素P450酶系，专一性低、活性个体差异大、易受药物诱导或抑制。","rationale":"出自概念手册「药物代谢动力学」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph03_q011","chapter":"第三章 药物代谢动力学","chapterIdx":2,"num":11},{"type":"D","stem":"名词解释：肝肠循环","answer":"部分药物经胆汁排入肠道后被重吸收回肝，形成循环，使药物作用时间延长，血药浓度出现双峰现象。","rationale":"出自概念手册「药物代谢动力学」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph03_q012","chapter":"第三章 药物代谢动力学","chapterIdx":2,"num":12},{"type":"D","stem":"名词解释：生物利用度","answer":"药物制剂中活性成分被吸收进入体循环的程度与速度，用AUC、Cmax和Tmax表示，分绝对生物利用度与相对生物利用度。","rationale":"出自概念手册「药物代谢动力学」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph03_q013","chapter":"第三章 药物代谢动力学","chapterIdx":2,"num":13},{"type":"F","stem":"填空题：药物制剂中活性成分被吸收进入体循环的程度与速度，用AUC、Cmax和Tmax表示，分绝对______与相对生物利用度。","answer":"生物利用度","rationale":"出自概念手册「药物代谢动力学」核心概念：生物利用度。","id":"rph03_q014","chapter":"第三章 药物代谢动力学","chapterIdx":2,"num":14},{"type":"D","stem":"名词解释：半衰期","answer":"血浆药物浓度下降一半所需的时间，一级动力学药物半衰期恒定，是确定给药间隔和估计达稳态时间的依据。","rationale":"出自概念手册「药物代谢动力学」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph03_q015","chapter":"第三章 药物代谢动力学","chapterIdx":2,"num":15},{"type":"F","stem":"填空题：血浆药物浓度下降一半所需的时间，一级动力学药物______恒定，是确定给药间隔和估计达稳态时间的依据。","answer":"半衰期","rationale":"出自概念手册「药物代谢动力学」核心概念：半衰期。","id":"rph03_q016","chapter":"第三章 药物代谢动力学","chapterIdx":2,"num":16},{"type":"D","stem":"名词解释：清除率","answer":"单位时间内机体能将多少容积血浆中的药物完全清除，反映机体消除药物的总体能力，等于消除速率除以血药浓度。","rationale":"出自概念手册「药物代谢动力学」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph03_q017","chapter":"第三章 药物代谢动力学","chapterIdx":2,"num":17},{"type":"D","stem":"名词解释：一级消除动力学","answer":"又称恒比消除，单位时间内消除恒定比例的药物，血药浓度越高消除得越多，半衰期与剂量和浓度无关。","rationale":"出自概念手册「药物代谢动力学」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph03_q018","chapter":"第三章 药物代谢动力学","chapterIdx":2,"num":18},{"type":"D","stem":"名词解释：零级消除动力学","answer":"又称恒量消除，单位时间内消除恒定数量的药物，消除速率已达饱和，半衰期随血药浓度升高而延长。","rationale":"出自概念手册「药物代谢动力学」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph03_q019","chapter":"第三章 药物代谢动力学","chapterIdx":2,"num":19},{"type":"D","stem":"名词解释：稳态血药浓度","answer":"连续恒速给药时给药速率与消除速率相等，血药浓度趋于稳定的水平，一般经5个半衰期达到。","rationale":"出自概念手册「药物代谢动力学」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph03_q020","chapter":"第三章 药物代谢动力学","chapterIdx":2,"num":20},{"type":"D","stem":"名词解释：负荷剂量","answer":"为使血药浓度迅速达到稳态而首次给予的较大剂量，通常将首剂加倍，适用于半衰期较长或需要迅速起效的药物。","rationale":"出自概念手册「药物代谢动力学」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph03_q021","chapter":"第三章 药物代谢动力学","chapterIdx":2,"num":21},{"type":"S","stem":"简答题：举例说明肝药酶活性和血浆蛋白结合率对药物作用的影响。","answer":"①肝药酶诱导剂（苯巴比妥、苯妥英钠、卡马西平、利福平、地塞米松等）使肝药酶活性增强，加速自身和其他药物的代谢，使药物效应减弱、易产生耐受性；如苯巴比妥加速双香豆素代谢，使抗凝作用减弱。②肝药酶抑制剂（红霉素、氯霉素、西咪替丁、异烟肼、唑类抗真菌药、保泰松等）使肝药酶活性减弱，减慢其他药物代谢，使药物效应增强，甚至蓄积中毒。③血浆蛋白结合率高者，结合型药物暂时失活且不能跨膜转运，只有游离型药物才能分布到组织发挥作用；如保泰松与双香豆素竞争血浆蛋白，使游离型双香豆素增多，抗凝作用增强而易致出血。④故联合用药时须考虑酶诱导、酶抑制与血浆蛋白竞争置换，必要时调整剂量。","rationale":"采分点为“酶诱导→效应减弱、酶抑制→效应增强、蛋白结合竞争→游离型增多致作用增强或中毒”三条机制并各举一例。易错是只说结论不举药名。","id":"rph03_q022","chapter":"第三章 药物代谢动力学","chapterIdx":2,"num":22},{"type":"F","stem":"填空题：血浆半衰期是指______，按一级动力学消除的药物一次给药后经______个半衰期体内药物已基本消除，连续恒量给药经______个半衰期可达稳态血药浓度。","answer":"①血浆药物浓度下降一半所需的时间 ②5 ③5","rationale":"一级动力学t1/2为常数，与剂量无关；恒量重复给药的达稳态时间仅取决于t1/2，与给药剂量、间隔、途径无关，增加剂量只提高稳态浓度而不能提前达稳态。","id":"rph03_q023","chapter":"第三章 药物代谢动力学","chapterIdx":2,"num":23},{"type":"F","stem":"填空题：促进苯巴比妥排泄的方法是______体液，其原理是使弱酸性药物解离型增多、肾小管______减少、排出增多。","answer":"①碱化（如用碳酸氢钠）②重吸收","rationale":"口诀“酸酸碱碱促吸收，酸碱碱酸促排泄”：弱酸性药物在碱性尿中解离增多、脂溶性降低、重吸收减少，故碱化尿液可加速苯巴比妥排泄。","id":"rph03_q024","chapter":"第三章 药物代谢动力学","chapterIdx":2,"num":24},{"type":"T","stem":"判断题：一级消除动力学药物的半衰期随给药剂量增大而延长。","options":{"A":"正确","B":"错误"},"answer":["B"],"rationale":"一级动力学为恒比消除，t1/2恒定，与剂量和初始浓度无关；半衰期随血药浓度（剂量）增大而延长的是零级消除动力学药物。","id":"rph03_q025","chapter":"第三章 药物代谢动力学","chapterIdx":2,"num":25},{"type":"T","stem":"判断题：以半衰期相等的间隔恒量重复给药，达到稳态血药浓度所需的时间仅取决于半衰期，与给药剂量和给药间隔无关。","options":{"A":"正确","B":"错误"},"answer":["A"],"rationale":"达稳态时间仅取决于t1/2；缩短给药间隔或增加剂量只改变稳态浓度高低，负荷剂量可提前达到但不稳定，仍需5个t1/2。","id":"rph03_q026","chapter":"第三章 药物代谢动力学","chapterIdx":2,"num":26}]},{"title":"第四章 影响药物作用的因素","questions":[{"type":"D","stem":"名词解释：个体差异","answer":"相同剂量下不同个体对同一药物的反应存在量与质的差别，表现为高敏性、耐受性和特异质反应，与遗传、年龄和病理状态有关。","rationale":"出自概念手册「影响药物作用的因素」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph04_q001","chapter":"第四章 影响药物作用的因素","chapterIdx":3,"num":1},{"type":"D","stem":"名词解释：耐受性","answer":"连续用药后机体对药物的反应性降低，需增加剂量才能维持原有效应，停药后耐受性可逐渐消失。","rationale":"出自概念手册「影响药物作用的因素」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph04_q002","chapter":"第四章 影响药物作用的因素","chapterIdx":3,"num":2},{"type":"F","stem":"填空题：连续用药后机体对药物的反应性降低，需增加剂量才能维持原有效应，停药后______可逐渐消失。","answer":"耐受性","rationale":"出自概念手册「影响药物作用的因素」核心概念：耐受性。","id":"rph04_q003","chapter":"第四章 影响药物作用的因素","chapterIdx":3,"num":3},{"type":"D","stem":"名词解释：快速耐受性","answer":"短时间内反复用药即迅速产生的耐受性，如麻黄碱、间羟胺反复注射后升压作用迅速减弱。","rationale":"出自概念手册「影响药物作用的因素」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph04_q004","chapter":"第四章 影响药物作用的因素","chapterIdx":3,"num":4},{"type":"D","stem":"名词解释：交叉耐受性","answer":"机体对某药产生耐受后，对同类或作用机制相同的另一药物也产生耐受，如嗜酒者对乙醚、巴比妥类也耐受。","rationale":"出自概念手册「影响药物作用的因素」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph04_q005","chapter":"第四章 影响药物作用的因素","chapterIdx":3,"num":5},{"type":"D","stem":"名词解释：耐药性","answer":"病原体（细菌、病毒、寄生虫）或肿瘤细胞对药物的敏感性降低，与机体耐受性不同，是化疗疗效下降的重要原因。","rationale":"出自概念手册「影响药物作用的因素」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph04_q006","chapter":"第四章 影响药物作用的因素","chapterIdx":3,"num":6},{"type":"D","stem":"名词解释：药物依赖性","answer":"反复用药后机体对药物产生精神上或躯体上的依赖状态，分精神依赖性和躯体依赖性，麻醉药品的依赖性危害最大。","rationale":"出自概念手册「影响药物作用的因素」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph04_q007","chapter":"第四章 影响药物作用的因素","chapterIdx":3,"num":7},{"type":"D","stem":"名词解释：戒断症状","answer":"长期使用具有依赖性的药物后突然停药或减量，出现的一系列生理功能紊乱表现，如烦躁、出汗、呕吐、惊厥等。","rationale":"出自概念手册「影响药物作用的因素」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph04_q008","chapter":"第四章 影响药物作用的因素","chapterIdx":3,"num":8},{"type":"D","stem":"名词解释：停药反应","answer":"长期用药后突然停药使原有疾病复发或加重，又称反跳现象，如长期应用β受体阻断药后骤停诱发心绞痛加重。","rationale":"出自概念手册「影响药物作用的因素」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph04_q009","chapter":"第四章 影响药物作用的因素","chapterIdx":3,"num":9},{"type":"D","stem":"名词解释：药物相互作用","answer":"同时或先后应用两种以上药物时，药物之间在体内或体外发生的相互影响，可表现为药动学或药效学的改变。","rationale":"出自概念手册「影响药物作用的因素」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph04_q010","chapter":"第四章 影响药物作用的因素","chapterIdx":3,"num":10},{"type":"D","stem":"名词解释：配伍禁忌","answer":"药物在体外配伍时直接发生物理性或化学性变化，导致疗效降低或毒性增加，属于制剂与给药环节的禁忌。","rationale":"出自概念手册「影响药物作用的因素」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph04_q011","chapter":"第四章 影响药物作用的因素","chapterIdx":3,"num":11},{"type":"D","stem":"名词解释：肝药酶诱导剂","answer":"能增强肝药酶活性、加速自身或其他药物代谢的药物，使合用药疗效降低，如苯巴比妥、利福平、卡马西平。","rationale":"出自概念手册「影响药物作用的因素」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph04_q012","chapter":"第四章 影响药物作用的因素","chapterIdx":3,"num":12},{"type":"D","stem":"名词解释：肝药酶抑制剂","answer":"能抑制肝药酶活性、减慢其他药物代谢的药物，使合用药血药浓度升高、作用增强甚至中毒，如西咪替丁、酮康唑。","rationale":"出自概念手册「影响药物作用的因素」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph04_q013","chapter":"第四章 影响药物作用的因素","chapterIdx":3,"num":13},{"type":"D","stem":"名词解释：安慰剂","answer":"外观与受试药物相同但不含活性成分的制剂，常用于临床试验作对照，以排除心理因素和疾病自愈的影响。","rationale":"出自概念手册「影响药物作用的因素」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph04_q014","chapter":"第四章 影响药物作用的因素","chapterIdx":3,"num":14},{"type":"D","stem":"名词解释：安慰剂效应","answer":"由安慰剂引起的、并非药物特异性药理作用产生的疗效或不良反应，与患者的心理状态和期望密切相关。","rationale":"出自概念手册「影响药物作用的因素」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph04_q015","chapter":"第四章 影响药物作用的因素","chapterIdx":3,"num":15},{"type":"D","stem":"名词解释：遗传药理学","answer":"研究遗传因素对药物反应影响的学科，涉及药物代谢酶、转运体和受体的基因多态性，是个体化用药的理论基础。","rationale":"出自概念手册「影响药物作用的因素」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph04_q016","chapter":"第四章 影响药物作用的因素","chapterIdx":3,"num":16},{"type":"D","stem":"名词解释：高敏性","answer":"个别个体对某种药物的敏感性高于常人，应用小于常用量的剂量即产生明显的药理效应甚至中毒，是个体差异的一种表现形式。","rationale":"出自概念手册「影响药物作用的因素」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph04_q017","chapter":"第四章 影响药物作用的因素","chapterIdx":3,"num":17},{"type":"S","stem":"简答题：试述影响药物作用的因素。","answer":"①药物方面：剂量（量效关系，剂量过小无效、过大中毒）、剂型与给药途径（影响吸收速度、作用强度，甚至改变作用性质，如硫酸镁口服导泻、注射抗惊厥）、药物相互作用（药效学协同与拮抗、药动学各环节的影响）。②机体方面：年龄（儿童与老年人的代谢和反应差异）、性别与妊娠哺乳期、遗传因素（遗传多态性、种族差异、特异质反应）、病理状态与肝肾功能、心理因素（安慰剂效应）。③长期用药引起的机体反应性变化：耐受性、耐药性、依赖性、停药症状。④联合用药还须注意配伍禁忌。","rationale":"采分点按“药物方面—机体方面—长期用药后的机体反应性变化”三层作答。易错是漏掉安慰剂效应与特异质反应，或把配伍禁忌（体外理化配伍）与药物相互作用混为一谈。","id":"rph04_q018","chapter":"第四章 影响药物作用的因素","chapterIdx":3,"num":18},{"type":"F","stem":"填空题：连续多次用药后机体对药物的反应性降低称______，而病原体或肿瘤细胞对反复应用的化学治疗药物敏感性降低称______。","answer":"①耐受性 ②耐药性（抗药性）","rationale":"耐受性主体是机体，增加剂量可恢复反应且停药后消失；耐药性主体是病原体或肿瘤细胞。另有急性耐受性与交叉耐受性。","id":"rph04_q019","chapter":"第四章 影响药物作用的因素","chapterIdx":3,"num":19},{"type":"F","stem":"填空题：硫酸镁口服产生______和利胆作用，注射给药则产生______和______作用，说明给药途径可改变药物作用的性质。","answer":"①泻下（导泻）②抗惊厥（骨骼肌松弛）③降压","rationale":"同一药物不同途径作用性质可完全不同，是最常考的给药途径影响药效的例子；口服泻下是利用离子障造成肠内高渗。","id":"rph04_q020","chapter":"第四章 影响药物作用的因素","chapterIdx":3,"num":20},{"type":"T","stem":"判断题：安慰剂本身没有特殊的药理活性，但安慰剂效应主要由患者的心理因素引起，可影响药物疗效的评价。","options":{"A":"正确","B":"错误"},"answer":["A"],"rationale":"安慰剂多由乳糖、淀粉等中性物质制成，也可包括假手术等无特殊作用的医疗措施；其效应来自心理因素，故临床试验须设安慰剂对照。","id":"rph04_q021","chapter":"第四章 影响药物作用的因素","chapterIdx":3,"num":21},{"type":"T","stem":"判断题：药物相互作用只发生在药效学环节，药动学环节不会改变药物的作用。","options":{"A":"正确","B":"错误"},"answer":["B"],"rationale":"药动学相互作用发生在体内过程各环节：华法林与阿司匹林竞争血浆蛋白、利福平诱导肝药酶加速环孢素代谢、青霉素与丙磺舒竞争肾小管有机酸分泌。","id":"rph04_q022","chapter":"第四章 影响药物作用的因素","chapterIdx":3,"num":22}]},{"title":"第五章 传出神经系统药理学概论","questions":[{"type":"D","stem":"名词解释：传出神经系统","answer":"包括自主神经系统和躯体运动神经系统，负责把中枢的神经冲动传至效应器，调节内脏活动、腺体分泌和骨骼肌运动。","rationale":"出自概念手册「传出神经系统药理学概论」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph05_q001","chapter":"第五章 传出神经系统药理学概论","chapterIdx":4,"num":1},{"type":"D","stem":"名词解释：自主神经系统","answer":"又称植物神经系统，包括交感神经和副交感神经，主要支配心肌、平滑肌和腺体，其活动多不受意志控制。","rationale":"出自概念手册「传出神经系统药理学概论」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph05_q002","chapter":"第五章 传出神经系统药理学概论","chapterIdx":4,"num":2},{"type":"D","stem":"名词解释：胆碱能神经","answer":"兴奋时末梢释放乙酰胆碱的神经，包括全部交感和副交感神经的节前纤维、副交感神经节后纤维、运动神经及少数交感节后纤维。","rationale":"出自概念手册「传出神经系统药理学概论」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph05_q003","chapter":"第五章 传出神经系统药理学概论","chapterIdx":4,"num":3},{"type":"D","stem":"名词解释：去甲肾上腺素能神经","answer":"兴奋时末梢释放去甲肾上腺素的神经，即绝大多数交感神经节后纤维，是拟肾上腺素药和抗肾上腺素药的作用基础。","rationale":"出自概念手册「传出神经系统药理学概论」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph05_q004","chapter":"第五章 传出神经系统药理学概论","chapterIdx":4,"num":4},{"type":"D","stem":"名词解释：乙酰胆碱","answer":"胆碱能神经的递质，由胆碱和乙酰辅酶A在胆碱乙酰化酶催化下合成，贮存于囊泡，释放后迅速被乙酰胆碱酯酶水解。","rationale":"出自概念手册「传出神经系统药理学概论」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph05_q005","chapter":"第五章 传出神经系统药理学概论","chapterIdx":4,"num":5},{"type":"F","stem":"填空题：胆碱能神经的递质，由胆碱和乙酰辅酶A在胆碱乙酰化酶催化下合成，贮存于囊泡，释放后迅速被______酯酶水解。","answer":"乙酰胆碱","rationale":"出自概念手册「传出神经系统药理学概论」核心概念：乙酰胆碱。","id":"rph05_q006","chapter":"第五章 传出神经系统药理学概论","chapterIdx":4,"num":6},{"type":"D","stem":"名词解释：去甲肾上腺素","answer":"去甲肾上腺素能神经的递质，由酪氨酸经多巴、多巴胺转化而成，贮存于囊泡，释放后主要靠神经末梢再摄取而消除。","rationale":"出自概念手册「传出神经系统药理学概论」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph05_q007","chapter":"第五章 传出神经系统药理学概论","chapterIdx":4,"num":7},{"type":"F","stem":"填空题：______能神经的递质，由酪氨酸经多巴、多巴胺转化而成，贮存于囊泡，释放后主要靠神经末梢再摄取而消除。","answer":"去甲肾上腺素","rationale":"出自概念手册「传出神经系统药理学概论」核心概念：去甲肾上腺素。","id":"rph05_q008","chapter":"第五章 传出神经系统药理学概论","chapterIdx":4,"num":8},{"type":"D","stem":"名词解释：胆碱乙酰化酶","answer":"又称胆碱乙酰转移酶（ChAT），催化胆碱与乙酰辅酶A合成乙酰胆碱，是胆碱能神经的标志酶，可作为其鉴定的依据。","rationale":"出自概念手册「传出神经系统药理学概论」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph05_q009","chapter":"第五章 传出神经系统药理学概论","chapterIdx":4,"num":9},{"type":"D","stem":"名词解释：乙酰胆碱酯酶","answer":"水解乙酰胆碱的酶，存在于胆碱能神经末梢突触间隙和红细胞，使乙酰胆碱迅速失活，保证突触传递的时效性。","rationale":"出自概念手册「传出神经系统药理学概论」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph05_q010","chapter":"第五章 传出神经系统药理学概论","chapterIdx":4,"num":10},{"type":"D","stem":"名词解释：胞裂外排","answer":"神经冲动到达末梢时钙离子内流，促使囊泡与突触前膜融合并把递质释放到突触间隙的过程，是递质释放的主要方式。","rationale":"出自概念手册「传出神经系统药理学概论」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph05_q011","chapter":"第五章 传出神经系统药理学概论","chapterIdx":4,"num":11},{"type":"D","stem":"名词解释：摄取1","answer":"神经末梢突触前膜通过转运体把释放的递质重新摄回囊泡的主动过程，是去甲肾上腺素消除的主要方式，可被可卡因抑制。","rationale":"出自概念手册「传出神经系统药理学概论」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph05_q012","chapter":"第五章 传出神经系统药理学概论","chapterIdx":4,"num":12},{"type":"D","stem":"名词解释：摄取2","answer":"心肌、平滑肌、肝等非神经组织对去甲肾上腺素的摄取，摄取后被细胞内酶代谢，是次要的消除途径。","rationale":"出自概念手册「传出神经系统药理学概论」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph05_q013","chapter":"第五章 传出神经系统药理学概论","chapterIdx":4,"num":13},{"type":"D","stem":"名词解释：单胺氧化酶","answer":"存在于神经末梢线粒体表面的酶，催化去甲肾上腺素、多巴胺等单胺类递质氧化脱氨而失活，其抑制剂可增强递质作用。","rationale":"出自概念手册「传出神经系统药理学概论」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph05_q014","chapter":"第五章 传出神经系统药理学概论","chapterIdx":4,"num":14},{"type":"D","stem":"名词解释：儿茶酚氧位甲基转移酶","answer":"存在于突触间隙和肝细胞的酶，催化去甲肾上腺素等儿茶酚胺的氧位甲基化而使其失活，是递质代谢的重要酶。","rationale":"出自概念手册「传出神经系统药理学概论」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph05_q015","chapter":"第五章 传出神经系统药理学概论","chapterIdx":4,"num":15},{"type":"D","stem":"名词解释：M胆碱受体","answer":"毒蕈碱型胆碱受体，属G蛋白偶联受体，分M1、M2、M3等亚型，主要分布于副交感神经节后纤维支配的效应器。","rationale":"出自概念手册「传出神经系统药理学概论」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph05_q016","chapter":"第五章 传出神经系统药理学概论","chapterIdx":4,"num":16},{"type":"D","stem":"名词解释：N胆碱受体","answer":"烟碱型胆碱受体，属配体门控离子通道，N1位于自主神经节和肾上腺髓质，N2位于骨骼肌运动终板。","rationale":"出自概念手册「传出神经系统药理学概论」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph05_q017","chapter":"第五章 传出神经系统药理学概论","chapterIdx":4,"num":17},{"type":"D","stem":"名词解释：α肾上腺素受体","answer":"分α1和α2亚型，α1主要分布于血管平滑肌，激动时血管收缩；α2位于突触前膜，激动时负反馈抑制递质释放。","rationale":"出自概念手册「传出神经系统药理学概论」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph05_q018","chapter":"第五章 传出神经系统药理学概论","chapterIdx":4,"num":18},{"type":"D","stem":"名词解释：β肾上腺素受体","answer":"分β1、β2、β3亚型，β1主要分布于心脏，激动时心率加快、收缩力增强；β2分布于支气管和骨骼肌血管，激动时舒张。","rationale":"出自概念手册「传出神经系统药理学概论」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph05_q019","chapter":"第五章 传出神经系统药理学概论","chapterIdx":4,"num":19},{"type":"D","stem":"名词解释：突触前受体","answer":"位于神经末梢突触前膜的受体，通过负反馈或正反馈调节递质释放，如突触前α2受体抑制、β2受体促进去甲肾上腺素释放。","rationale":"出自概念手册「传出神经系统药理学概论」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph05_q020","chapter":"第五章 传出神经系统药理学概论","chapterIdx":4,"num":20},{"type":"S","stem":"简答题：简述乙酰胆碱和去甲肾上腺素在体内的合成、贮存、释放和消除。","answer":"①合成：ACh由胆碱与乙酰辅酶A经胆碱乙酰化酶催化生成；NA以左旋酪氨酸为原料，经酪氨酸羟化酶（限速酶）生成左旋多巴，再经多巴脱羧酶生成多巴胺，最后经多巴胺β-羟化酶生成NA。②贮存：ACh与NA均贮存于神经末梢的囊泡中，NA的囊泡摄取可被利血平类阻断。③释放：两者均以量子化胞裂外排方式释放，需Ca2+内流触发，凡抑制囊泡与前膜融合的药物均可影响其释放。④消除：ACh主要被突触间隙的乙酰胆碱酯酶高效水解为乙酸和胆碱；NA主要经神经末梢摄取1（占75%～90%）重新贮存，被非神经组织摄取2的NA由COMT破坏，部分被MAO灭活。","rationale":"采分点为“合成—贮存—释放—消除”四环节及两种递质的差别。易错是NA的限速酶（酪氨酸羟化酶）与ACh的灭活酶（AChE）混淆，以及漏掉以摄取1为主的消除方式。","id":"rph05_q021","chapter":"第五章 传出神经系统药理学概论","chapterIdx":4,"num":21},{"type":"F","stem":"填空题：M受体属于______受体，N受体属于______受体；N1受体位于______，N2受体位于骨骼肌神经肌肉接头。","answer":"①G蛋白耦联 ②离子通道型（配体门控离子通道）③神经节（自主神经节和肾上腺髓质）","rationale":"M1分布于胃壁细胞和中枢、M2在心脏与突触前末梢、M3在腺体和平滑肌；N受体为五聚体构成的钠通道。","id":"rph05_q022","chapter":"第五章 传出神经系统药理学概论","chapterIdx":4,"num":22},{"type":"F","stem":"填空题：多数器官接受交感神经与副交感神经的______支配，两类神经兴奋时的效应往往相互______，同时兴奋时通常显现占优势的神经效应。","answer":"①双重 ②拮抗","rationale":"胃肠道以副交感支配为主，心脏和血管以交感支配为主，故“优势支配”决定了整体表现，这是分析传出神经药物作用的前提。","id":"rph05_q023","chapter":"第五章 传出神经系统药理学概论","chapterIdx":4,"num":23},{"type":"T","stem":"判断题：支配汗腺的交感神经节后纤维释放的递质是乙酰胆碱。","options":{"A":"正确","B":"错误"},"answer":["A"],"rationale":"胆碱能神经包括全部交感与副交感节前纤维、全部副交感节后纤维、运动神经以及极少数交感节后纤维（汗腺分泌、骨骼肌血管舒张）。","id":"rph05_q024","chapter":"第五章 传出神经系统药理学概论","chapterIdx":4,"num":24},{"type":"T","stem":"判断题：N1受体激动表现为骨骼肌收缩，N2受体激动表现为神经节兴奋和肾上腺髓质分泌。","options":{"A":"正确","B":"错误"},"answer":["B"],"rationale":"恰好说反：N1（NN）为神经节受体，激动引起神经节兴奋和肾上腺髓质分泌；N2（NM）为神经肌肉接头受体，激动引起骨骼肌收缩。","id":"rph05_q025","chapter":"第五章 传出神经系统药理学概论","chapterIdx":4,"num":25}]},{"title":"第六章 胆碱受体激动药","questions":[{"type":"D","stem":"名词解释：拟胆碱药","answer":"能产生与乙酰胆碱相似作用的药物，包括直接激动胆碱受体的胆碱受体激动药和抑制胆碱酯酶的抗胆碱酯酶药两大类。","rationale":"出自概念手册「胆碱受体激动药」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph06_q001","chapter":"第六章 胆碱受体激动药","chapterIdx":5,"num":1},{"type":"D","stem":"名词解释：胆碱受体激动药","answer":"能直接与胆碱受体结合并激动受体，产生M样或N样作用的药物，按受体选择性分为M受体激动药和N受体激动药。","rationale":"出自概念手册「胆碱受体激动药」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph06_q002","chapter":"第六章 胆碱受体激动药","chapterIdx":5,"num":2},{"type":"D","stem":"名词解释：M胆碱受体激动药","answer":"选择性激动M受体的药物，产生心脏抑制、平滑肌收缩、腺体分泌增加和瞳孔缩小等副交感神经兴奋的效应。","rationale":"出自概念手册「胆碱受体激动药」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph06_q003","chapter":"第六章 胆碱受体激动药","chapterIdx":5,"num":3},{"type":"D","stem":"名词解释：N胆碱受体激动药","answer":"激动N1或N2受体的药物，N1受体激动表现为神经节兴奋，N2受体激动表现为骨骼肌收缩，临床应用价值有限。","rationale":"出自概念手册「胆碱受体激动药」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph06_q004","chapter":"第六章 胆碱受体激动药","chapterIdx":5,"num":4},{"type":"D","stem":"名词解释：毛果芸香碱","answer":"又称匹鲁卡品，从毛果芸香叶中提取的生物碱，选择性激动M受体，对眼和腺体作用最明显，是治疗青光眼的常用药。","rationale":"出自概念手册「胆碱受体激动药」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph06_q005","chapter":"第六章 胆碱受体激动药","chapterIdx":5,"num":5},{"type":"D","stem":"名词解释：缩瞳","answer":"毛果芸香碱激动虹膜括约肌的M受体，使括约肌收缩、瞳孔缩小，虹膜根部变薄、前房角间隙扩大而房水回流通畅。","rationale":"出自概念手册「胆碱受体激动药」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph06_q006","chapter":"第六章 胆碱受体激动药","chapterIdx":5,"num":6},{"type":"D","stem":"名词解释：调节痉挛","answer":"激动睫状肌M受体使睫状肌收缩、悬韧带松弛、晶状体变凸、屈光度增加，以致视近物清楚而视远物模糊的现象。","rationale":"出自概念手册「胆碱受体激动药」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph06_q007","chapter":"第六章 胆碱受体激动药","chapterIdx":5,"num":7},{"type":"D","stem":"名词解释：眼内压","answer":"眼球内容物对眼球壁产生的压力，正常约为1.3至2.8千帕，房水循环障碍时升高，是青光眼的主要病理基础。","rationale":"出自概念手册「胆碱受体激动药」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph06_q008","chapter":"第六章 胆碱受体激动药","chapterIdx":5,"num":8},{"type":"D","stem":"名词解释：卡巴胆碱","answer":"合成的胆碱酯类，可同时激动M和N受体，不易被乙酰胆碱酯酶水解，作用强而持久，主要用于青光眼和术后尿潴留。","rationale":"出自概念手册「胆碱受体激动药」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph06_q009","chapter":"第六章 胆碱受体激动药","chapterIdx":5,"num":9},{"type":"D","stem":"名词解释：氯贝胆碱","answer":"合成的胆碱酯类，选择性激动M受体，口服有效，主要用于术后腹气胀、尿潴留和胃张力缺乏。","rationale":"出自概念手册「胆碱受体激动药」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph06_q010","chapter":"第六章 胆碱受体激动药","chapterIdx":5,"num":10},{"type":"D","stem":"名词解释：醋甲胆碱","answer":"合成的胆碱酯类，对心血管系统作用明显，可被乙酰胆碱酯酶水解而作用短暂，临床少用，偶用于口腔干燥症。","rationale":"出自概念手册「胆碱受体激动药」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph06_q011","chapter":"第六章 胆碱受体激动药","chapterIdx":5,"num":11},{"type":"D","stem":"名词解释：毒蕈碱","answer":"从毒蕈中提取的生物碱，是M受体的天然激动剂，毒性强，其中毒表现与有机磷中毒的M样症状十分相似。","rationale":"出自概念手册「胆碱受体激动药」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph06_q012","chapter":"第六章 胆碱受体激动药","chapterIdx":5,"num":12},{"type":"D","stem":"名词解释：槟榔碱","answer":"槟榔中的生物碱，可激动M受体并兼有烟碱样作用，曾用于青光眼和驱绦虫，因毒性较大现已少用。","rationale":"出自概念手册「胆碱受体激动药」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph06_q013","chapter":"第六章 胆碱受体激动药","chapterIdx":5,"num":13},{"type":"D","stem":"名词解释：西维美林","answer":"选择性M3受体激动药，可促进唾液和泪液分泌，主要用于干燥综合征引起的口干和眼干，作用时间较毛果芸香碱长。","rationale":"出自概念手册「胆碱受体激动药」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph06_q014","chapter":"第六章 胆碱受体激动药","chapterIdx":5,"num":14},{"type":"D","stem":"名词解释：烟碱","answer":"即尼古丁，N受体激动药，小剂量兴奋神经节和骨骼肌、大剂量则阻断，毒性大而无治疗价值，是吸烟成瘾的主要成分。","rationale":"出自概念手册「胆碱受体激动药」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph06_q015","chapter":"第六章 胆碱受体激动药","chapterIdx":5,"num":15},{"type":"S","stem":"简答题：简述毛果芸香碱对眼的作用及其临床应用。","answer":"①缩瞳：激动瞳孔括约肌的M受体，括约肌向心性收缩，瞳孔缩小；②降低眼内压：缩瞳后虹膜被拉长变薄、前房角扩大，房水回流增加，眼内压降低，降眼压是缩瞳的继发效应；③调节痉挛：激动睫状肌M受体，环状睫状肌向中心收缩、悬韧带松弛、晶状体变凸、屈光度增加，以致视近物清楚、视远物模糊；④临床应用：青光眼（低浓度滴眼治疗闭角型青光眼，对开角型早期也有一定疗效）、虹膜睫状体炎（与扩瞳药交替使用防止粘连）、口服治疗口腔干燥、抗胆碱药阿托品中毒的解救。","rationale":"采分点为“缩瞳—降低眼内压—调节痉挛”三联作用及对应用途。易错是把方向记反：阿托品为扩瞳、升眼压、调节麻痹，二者恰成对照。","id":"rph06_q016","chapter":"第六章 胆碱受体激动药","chapterIdx":5,"num":16},{"type":"F","stem":"填空题：乙酰胆碱激动M受体可使血管______、心脏______、内脏平滑肌收缩、腺体分泌增加。","answer":"①扩张（经内皮M3受体释放NO）②抑制（负性肌力、负性频率和负性传导）","rationale":"血管平滑肌上无ACh受体，ACh需内皮细胞完整才能经M3受体释放NO而舒张血管；心脏以M2受体为主，故表现为“三负”作用。","id":"rph06_q017","chapter":"第六章 胆碱受体激动药","chapterIdx":5,"num":17},{"type":"F","stem":"填空题：去甲肾上腺素的拮抗剂是______，毛果芸香碱的拮抗剂是______。","answer":"①酚妥拉明（或酚苄明等α受体阻断药）②阿托品等M胆碱受体阻断药","rationale":"按受体对应记忆：NA为α受体激动药，其拮抗剂为α受体阻断药；毛果芸香碱为M受体激动药，其拮抗剂为M受体阻断药阿托品。","id":"rph06_q018","chapter":"第六章 胆碱受体激动药","chapterIdx":5,"num":18},{"type":"T","stem":"判断题：乙酰胆碱作用广泛且迅速被乙酰胆碱酯酶水解，故无临床实用价值。","options":{"A":"正确","B":"错误"},"answer":["A"],"rationale":"ACh为内源性递质，激动M、N受体作用广泛，且被AChE高效水解来不及发挥作用，故无临床实用价值，仅作实验用药。","id":"rph06_q019","chapter":"第六章 胆碱受体激动药","chapterIdx":5,"num":19},{"type":"T","stem":"判断题：毛果芸香碱滴眼后可引起瞳孔扩大、眼内压升高。","options":{"A":"正确","B":"错误"},"answer":["B"],"rationale":"毛果芸香碱激动M受体，使瞳孔括约肌收缩而缩瞳，虹膜拉长变薄、前房角扩大，房水回流增加而降低眼内压；扩瞳升眼压是阿托品的作用。","id":"rph06_q020","chapter":"第六章 胆碱受体激动药","chapterIdx":5,"num":20}]},{"title":"第七章 抗胆碱酯酶药","questions":[{"type":"D","stem":"名词解释：抗胆碱酯酶药","answer":"能抑制胆碱酯酶活性、使突触间隙乙酰胆碱堆积而间接发挥拟胆碱作用的药物，按其与酶结合的可逆性分为易逆性与难逆性两类。","rationale":"出自概念手册「抗胆碱酯酶药」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph07_q001","chapter":"第七章 抗胆碱酯酶药","chapterIdx":6,"num":1},{"type":"D","stem":"名词解释：假性胆碱酯酶","answer":"又称丁酰胆碱酯酶，存在于血浆和肝脏，水解乙酰胆碱的能力弱，可水解琥珀胆碱，其活性降低易致琥珀胆碱中毒。","rationale":"出自概念手册「抗胆碱酯酶药」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph07_q002","chapter":"第七章 抗胆碱酯酶药","chapterIdx":6,"num":2},{"type":"D","stem":"名词解释：可逆性抗胆碱酯酶药","answer":"与胆碱酯酶结合后可逐渐水解、酶活性能够恢复的药物，如新斯的明、毒扁豆碱、吡斯的明和加兰他敏。","rationale":"出自概念手册「抗胆碱酯酶药」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph07_q003","chapter":"第七章 抗胆碱酯酶药","chapterIdx":6,"num":3},{"type":"D","stem":"名词解释：难逆性抗胆碱酯酶药","answer":"与胆碱酯酶结合牢固、难以水解、酶活性长期不能恢复的药物，主要为有机磷酸酯类，多用作农业杀虫剂。","rationale":"出自概念手册「抗胆碱酯酶药」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph07_q004","chapter":"第七章 抗胆碱酯酶药","chapterIdx":6,"num":4},{"type":"D","stem":"名词解释：新斯的明","answer":"易逆性抗胆碱酯酶药，抑制胆碱酯酶并直接激动N2受体、促进递质释放，对骨骼肌作用最强，是重症肌无力的首选药。","rationale":"出自概念手册「抗胆碱酯酶药」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph07_q005","chapter":"第七章 抗胆碱酯酶药","chapterIdx":6,"num":5},{"type":"D","stem":"名词解释：毒扁豆碱","answer":"又称依色林，易逆性抗胆碱酯酶药，易透过血脑屏障，全身作用强而持久，主要用于青光眼和中枢抗胆碱药中毒的解救。","rationale":"出自概念手册「抗胆碱酯酶药」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph07_q006","chapter":"第七章 抗胆碱酯酶药","chapterIdx":6,"num":6},{"type":"D","stem":"名词解释：吡斯的明","answer":"易逆性抗胆碱酯酶药，作用较新斯的明弱而持久，口服吸收较好，主要用于重症肌无力的长期维持治疗。","rationale":"出自概念手册「抗胆碱酯酶药」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph07_q007","chapter":"第七章 抗胆碱酯酶药","chapterIdx":6,"num":7},{"type":"D","stem":"名词解释：加兰他敏","answer":"易逆性抗胆碱酯酶药，可透过血脑屏障，作用温和，用于阿尔茨海默病和脊髓灰质炎后遗症的治疗。","rationale":"出自概念手册「抗胆碱酯酶药」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph07_q008","chapter":"第七章 抗胆碱酯酶药","chapterIdx":6,"num":8},{"type":"D","stem":"名词解释：依酚氯铵","answer":"又称腾喜龙，作用短而快的易逆性抗胆碱酯酶药，小剂量静脉注射用于诊断重症肌无力，也可用于鉴别肌无力危象。","rationale":"出自概念手册「抗胆碱酯酶药」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph07_q009","chapter":"第七章 抗胆碱酯酶药","chapterIdx":6,"num":9},{"type":"D","stem":"名词解释：有机磷酸酯类","answer":"难逆性抗胆碱酯酶药，包括敌敌畏、对硫磷、马拉硫磷、乐果等，与胆碱酯酶形成磷酰化复合物，多用作农业杀虫剂。","rationale":"出自概念手册「抗胆碱酯酶药」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph07_q010","chapter":"第七章 抗胆碱酯酶药","chapterIdx":6,"num":10},{"type":"D","stem":"名词解释：胆碱能危象","answer":"重症肌无力治疗中新斯的明过量，使运动终板乙酰胆碱大量堆积、持久去极化，导致肌无力加重并伴M样症状的危险状态。","rationale":"出自概念手册「抗胆碱酯酶药」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph07_q011","chapter":"第七章 抗胆碱酯酶药","chapterIdx":6,"num":11},{"type":"D","stem":"名词解释：老化","answer":"磷酰化胆碱酯酶上的烷基脱落后形成更稳定的磷酰化酶，不能再被复活药恢复活性的现象，故有机磷中毒须尽早用药。","rationale":"出自概念手册「抗胆碱酯酶药」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph07_q012","chapter":"第七章 抗胆碱酯酶药","chapterIdx":6,"num":12},{"type":"D","stem":"名词解释：胆碱酯酶复活药","answer":"能使被有机磷抑制的胆碱酯酶恢复活性的药物，如碘解磷定和氯解磷定，对N样症状与中枢症状有效。","rationale":"出自概念手册「抗胆碱酯酶药」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph07_q013","chapter":"第七章 抗胆碱酯酶药","chapterIdx":6,"num":13},{"type":"D","stem":"名词解释：碘解磷定","answer":"又称派姆，胆碱酯酶复活药，其肟基与磷酰化胆碱酯酶结合形成无毒的磷酰肟，使胆碱酯酶游离而恢复水解乙酰胆碱的能力。","rationale":"出自概念手册「抗胆碱酯酶药」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph07_q014","chapter":"第七章 抗胆碱酯酶药","chapterIdx":6,"num":14},{"type":"D","stem":"名词解释：氯解磷定","answer":"胆碱酯酶复活药，水溶性好、可肌内注射，复活胆碱酯酶的作用较碘解磷定强，为解救有机磷中毒的首选复活药。","rationale":"出自概念手册「抗胆碱酯酶药」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph07_q015","chapter":"第七章 抗胆碱酯酶药","chapterIdx":6,"num":15},{"type":"S","stem":"简答题：简述碘解磷定与阿托品合用于有机磷酸酯类中毒的优点。","answer":"①阿托品阻断M胆碱受体，能迅速解除流涎、出汗、腹痛、支气管分泌物增多、瞳孔缩小等M样症状，作用快、可及早足量重复注射，挽救生命；②碘解磷定是胆碱酯酶复活药，能使磷酰化胆碱酯酶脱磷酰化而恢复酶活性，主要缓解骨骼肌肌束震颤等N样症状；③两药作用互补：阿托品不能阻断N受体、也不能恢复酶活性，碘解磷定对已“老化”的酶无效，合用可同时兼顾M样与N样症状，标本兼治；④两药均须早期、足量、重复给药，并配合清除毒物、维持呼吸循环等支持治疗。","rationale":"采分点为“阿托品解M样症状—解磷定恢复酶活性解N样症状—互补协同—早期足量重复”。易错是称“阿托品能复活胆碱酯酶”或“解磷定对老化酶有效”。","id":"rph07_q016","chapter":"第七章 抗胆碱酯酶药","chapterIdx":6,"num":16},{"type":"F","stem":"填空题：易逆性抗胆碱酯酶药有______、______和______等，难逆性抗胆碱酯酶药为______。","answer":"①新斯的明 ②毒扁豆碱 ③吡斯的明 ④有机磷酸酯类（如敌百虫）","rationale":"易逆性药与AChE结合牢固程度有限，可逐渐水解恢复；有机磷酸酯类与AChE形成磷酰化酶，需数周才有新生AChE，故中毒凶险。","id":"rph07_q017","chapter":"第七章 抗胆碱酯酶药","chapterIdx":6,"num":17},{"type":"F","stem":"填空题：新斯的明口服吸收______，静脉注射不易透过______，故对中枢神经系统作用弱。","answer":"①少且不规则 ②血脑屏障","rationale":"新斯的明为季铵类化合物，极性高、脂溶性低，不易入脑；毒扁豆碱为叔胺类，对中枢和外周均有作用，故全身给药少用。","id":"rph07_q018","chapter":"第七章 抗胆碱酯酶药","chapterIdx":6,"num":18},{"type":"T","stem":"判断题：新斯的明除抑制胆碱酯酶外，还能直接激动骨骼肌运动终板上的N2受体，故对骨骼肌的兴奋作用较强。","options":{"A":"正确","B":"错误"},"answer":["A"],"rationale":"新斯的明为完全拟胆碱作用：既抑制AChE使ACh增多，又直接激动N2（NM）受体，故对骨骼肌兴奋作用最强，为重症肌无力首选。","id":"rph07_q019","chapter":"第七章 抗胆碱酯酶药","chapterIdx":6,"num":19},{"type":"T","stem":"判断题：碘解磷定能使已“老化”的磷酰化胆碱酯酶恢复活性。","options":{"A":"正确","B":"错误"},"answer":["B"],"rationale":"碘解磷定对“老化酶”无效，因老化后磷酰化基团脱去一个烷氧基形成更稳定的单烷氧基磷酰化AChE，不能再被复活，故必须早期用药。","id":"rph07_q020","chapter":"第七章 抗胆碱酯酶药","chapterIdx":6,"num":20}]},{"title":"第八章 胆碱受体阻断药","questions":[{"type":"D","stem":"名词解释：胆碱受体阻断药","answer":"又称抗胆碱药，能与胆碱受体结合而不产生或极少产生内在活性，从而阻断乙酰胆碱作用的药物，按受体分为M与N两类。","rationale":"出自概念手册「胆碱受体阻断药」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph08_q001","chapter":"第八章 胆碱受体阻断药","chapterIdx":7,"num":1},{"type":"D","stem":"名词解释：M胆碱受体阻断药","answer":"选择性阻断M受体的药物，产生与阿托品相似的效应：腺体分泌减少、瞳孔散大、平滑肌松弛、心率加快。","rationale":"出自概念手册「胆碱受体阻断药」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph08_q002","chapter":"第八章 胆碱受体阻断药","chapterIdx":7,"num":2},{"type":"D","stem":"名词解释：N胆碱受体阻断药","answer":"阻断N受体的药物，包括阻断神经节N1受体的神经节阻断药和阻断运动终板N2受体的骨骼肌松弛药两大类。","rationale":"出自概念手册「胆碱受体阻断药」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph08_q003","chapter":"第八章 胆碱受体阻断药","chapterIdx":7,"num":3},{"type":"D","stem":"名词解释：阿托品","answer":"从颠茄、曼陀罗等植物中提取的生物碱，非选择性M受体阻断药，作用广泛，是解除平滑肌痉挛和抢救有机磷中毒的经典药物。","rationale":"出自概念手册「胆碱受体阻断药」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph08_q004","chapter":"第八章 胆碱受体阻断药","chapterIdx":7,"num":4},{"type":"D","stem":"名词解释：山莨菪碱","answer":"又称654-2，M受体阻断药，对内脏平滑肌和血管的选择性较高，不良反应较阿托品少，用于胃肠绞痛和感染性休克。","rationale":"出自概念手册「胆碱受体阻断药」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph08_q005","chapter":"第八章 胆碱受体阻断药","chapterIdx":7,"num":5},{"type":"D","stem":"名词解释：东莨菪碱","answer":"M受体阻断药，对腺体、眼和中枢的作用强，治疗量即引起镇静催眠，用于麻醉前给药、晕动病和帕金森病。","rationale":"出自概念手册「胆碱受体阻断药」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph08_q006","chapter":"第八章 胆碱受体阻断药","chapterIdx":7,"num":6},{"type":"D","stem":"名词解释：后马托品","answer":"阿托品的合成代用品，M受体阻断药，作用快而短，主要用于散瞳检查眼底和验光，可减少作用时间过长的不便。","rationale":"出自概念手册「胆碱受体阻断药」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph08_q007","chapter":"第八章 胆碱受体阻断药","chapterIdx":7,"num":7},{"type":"D","stem":"名词解释：托吡卡胺","answer":"又称托品酰胺，合成的M受体阻断药，散瞳和调节麻痹作用快而短暂，主要用于眼底检查和验光配镜。","rationale":"出自概念手册「胆碱受体阻断药」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph08_q008","chapter":"第八章 胆碱受体阻断药","chapterIdx":7,"num":8},{"type":"D","stem":"名词解释：哌仑西平","answer":"选择性M1受体阻断药，抑制胃酸分泌而不明显影响心率和瞳孔，主要用于胃和十二指肠溃疡的治疗。","rationale":"出自概念手册「胆碱受体阻断药」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph08_q009","chapter":"第八章 胆碱受体阻断药","chapterIdx":7,"num":9},{"type":"D","stem":"名词解释：调节麻痹","answer":"阻断睫状肌M受体使睫状肌松弛、悬韧带拉紧、晶状体变扁平、屈光度降低，以致视近物模糊而视远物清楚的现象。","rationale":"出自概念手册「胆碱受体阻断药」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph08_q010","chapter":"第八章 胆碱受体阻断药","chapterIdx":7,"num":10},{"type":"D","stem":"名词解释：散瞳","answer":"阻断虹膜括约肌M受体使其松弛，瞳孔开大肌作用占优势而瞳孔扩大，同时虹膜退向周边使前房角间隙变窄、眼内压升高。","rationale":"出自概念手册「胆碱受体阻断药」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph08_q011","chapter":"第八章 胆碱受体阻断药","chapterIdx":7,"num":11},{"type":"D","stem":"名词解释：阿托品化","answer":"有机磷中毒抢救中阿托品用量恰当的指标：瞳孔较前散大、口干、皮肤干燥、面色潮红、心率加快、肺部啰音减少。","rationale":"出自概念手册「胆碱受体阻断药」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph08_q012","chapter":"第八章 胆碱受体阻断药","chapterIdx":7,"num":12},{"type":"D","stem":"名词解释：神经节阻断药","answer":"阻断自主神经节N1受体的药物，如美卡拉明、樟磺咪芬，曾用于高血压危象和控压性低血压，现已少用。","rationale":"出自概念手册「胆碱受体阻断药」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph08_q013","chapter":"第八章 胆碱受体阻断药","chapterIdx":7,"num":13},{"type":"D","stem":"名词解释：筒箭毒碱","answer":"从南美箭毒中提取的生物碱，非去极化型肌松药，竞争性阻断运动终板N2受体，用于外科麻醉辅助。","rationale":"出自概念手册「胆碱受体阻断药」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph08_q014","chapter":"第八章 胆碱受体阻断药","chapterIdx":7,"num":14},{"type":"D","stem":"名词解释：琥珀胆碱","answer":"去极化型肌松药，激动N2受体使终板膜持久去极化，静脉注射后迅速产生肌松，用于气管插管和短时检查。","rationale":"出自概念手册「胆碱受体阻断药」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph08_q015","chapter":"第八章 胆碱受体阻断药","chapterIdx":7,"num":15},{"type":"D","stem":"名词解释：非去极化型肌松药","answer":"又称竞争型肌松药，与乙酰胆碱竞争N2受体但不激动受体，使骨骼肌松弛，过量可用新斯的明解救。","rationale":"出自概念手册「胆碱受体阻断药」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph08_q016","chapter":"第八章 胆碱受体阻断药","chapterIdx":7,"num":16},{"type":"D","stem":"名词解释：去极化型肌松药","answer":"激动N2受体使终板膜持久去极化，受体对乙酰胆碱不再反应而致肌松，过量不能用新斯的明解救。","rationale":"出自概念手册「胆碱受体阻断药」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph08_q017","chapter":"第八章 胆碱受体阻断药","chapterIdx":7,"num":17},{"type":"S","stem":"简答题：比较去极化型与非去极化型肌松药的作用特点。","answer":"①去极化型（代表药琥珀胆碱）：与N2受体持久结合并产生持续除极化，用药初期出现短暂肌束震颤；抗胆碱酯酶药不能拮抗其肌松作用，反而增强，故过量不能用新斯的明解救；治疗量无神经节阻断作用；连续用药可产生快速耐受性。②非去极化型（代表药筒箭毒碱）：与ACh竞争N2受体，起效慢、作用持续时间长；吸入性麻醉药（乙醚）和氨基糖苷类抗生素可加强其肌松作用；与抗胆碱酯酶药呈拮抗，过量可用新斯的明解救；有不同程度的神经节阻断作用和组胺释放作用；同类药物之间有相加作用。③共同点：只使骨骼肌麻痹松弛，不产生麻醉作用，不使神志和感觉消失。","rationale":"采分点为两类药在“肌束震颤、与抗胆碱酯酶药的关系、神经节阻断、耐受性”四方面的对照。易错是把新斯的明的解救作用错记给琥珀胆碱。","id":"rph08_q018","chapter":"第八章 胆碱受体阻断药","chapterIdx":7,"num":18},{"type":"F","stem":"填空题：对阿托品最敏感的腺体是______和______，故治疗量即可出现口干、无汗；较大剂量才减少______分泌且对胃酸影响较小。","answer":"①唾液腺 ②汗腺 ③胃液","rationale":"腺体敏感性：唾液腺、汗腺＞泪腺、呼吸道腺体＞胃腺；胃酸分泌还受组胺、胃泌素影响，故阿托品对其影响较小。","id":"rph08_q019","chapter":"第八章 胆碱受体阻断药","chapterIdx":7,"num":19},{"type":"F","stem":"填空题：哌仑西平选择性阻断______受体，抑制胃酸及胃蛋白酶分泌，可用于治疗______。","answer":"①M1（胃壁细胞M1受体）②胃、十二指肠溃疡（消化性溃疡）","rationale":"选择性M受体阻断药是本章新增考点：哌仑西平、替仑西平阻断M1；达非那新选择性阻断M2、M3受体。","id":"rph08_q020","chapter":"第八章 胆碱受体阻断药","chapterIdx":7,"num":20},{"type":"T","stem":"判断题：阿托品阻断睫状肌M受体后，睫状肌松弛退向外缘、悬韧带拉紧、晶状体变扁平、屈光度降低，出现调节麻痹。","options":{"A":"正确","B":"错误"},"answer":["A"],"rationale":"调节麻痹表现为视近物模糊、视远物清楚，与毛果芸香碱的调节痉挛（晶状体变凸、视近物清楚）方向相反，是眼科应用与禁忌的依据。","id":"rph08_q021","chapter":"第八章 胆碱受体阻断药","chapterIdx":7,"num":21},{"type":"T","stem":"判断题：东莨菪碱的外周抗胆碱作用较阿托品强，且不易通过血脑屏障，故中枢作用很弱。","options":{"A":"正确","B":"错误"},"answer":["B"],"rationale":"东莨菪碱可迅速而完全地进入中枢，治疗量即有中枢抗胆碱、镇静和欣快作用，用于麻醉前给药、晕动病和帕金森病；不易透过血脑屏障、中枢作用很弱的是山莨菪碱。","id":"rph08_q022","chapter":"第八章 胆碱受体阻断药","chapterIdx":7,"num":22}]},{"title":"第九章 肾上腺素受体激动药","questions":[{"type":"D","stem":"名词解释：肾上腺素受体激动药","answer":"又称拟肾上腺素药，能选择性地与肾上腺素受体结合并激动受体，产生与交感神经兴奋相似的效应。按对受体的选择性分为α受体激动药、αβ受体激动药和β受体激动药三类。","rationale":"出自概念手册「肾上腺素受体激动药」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph09_q001","chapter":"第九章 肾上腺素受体激动药","chapterIdx":8,"num":1},{"type":"D","stem":"名词解释：儿茶酚胺","answer":"含儿茶酚（邻苯二酚）结构的胺类药物，包括肾上腺素、去甲肾上腺素、异丙肾上腺素和多巴胺。口服易被胃肠黏膜和肝破坏，一般须注射给药，作用时间较短。","rationale":"出自概念手册「肾上腺素受体激动药」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph09_q002","chapter":"第九章 肾上腺素受体激动药","chapterIdx":8,"num":2},{"type":"D","stem":"名词解释：非儿茶酚胺类","answer":"不含儿茶酚结构的拟肾上腺素药，如麻黄碱、间羟胺、去氧肾上腺素。化学性质稳定，不易被单胺氧化酶和儿茶酚氧位甲基转移酶破坏，可口服且作用较持久。","rationale":"出自概念手册「肾上腺素受体激动药」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph09_q003","chapter":"第九章 肾上腺素受体激动药","chapterIdx":8,"num":3},{"type":"D","stem":"名词解释：去甲肾上腺素（NA）","answer":"主要激动α受体，对β1受体作用较弱。强烈收缩全身血管、升高血压，反射性减慢心率；用于神经源性休克早期、药物中毒所致低血压及上消化道出血。","rationale":"出自概念手册「肾上腺素受体激动药」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph09_q004","chapter":"第九章 肾上腺素受体激动药","chapterIdx":8,"num":4},{"type":"D","stem":"名词解释：肾上腺素（AD）","answer":"激动α和β受体，兴奋心脏、收缩皮肤黏膜血管而舒张骨骼肌血管、舒张支气管、促进代谢。用于心脏骤停、过敏性休克、支气管哮喘急性发作及局部止血。","rationale":"出自概念手册「肾上腺素受体激动药」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph09_q005","chapter":"第九章 肾上腺素受体激动药","chapterIdx":8,"num":5},{"type":"D","stem":"名词解释：异丙肾上腺素（ISO）","answer":"选择性激动β1和β2受体，对α受体几乎无作用。兴奋心脏、舒张骨骼肌和内脏血管、舒张支气管。用于心脏骤停、房室传导阻滞和支气管哮喘急性发作。","rationale":"出自概念手册「肾上腺素受体激动药」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph09_q006","chapter":"第九章 肾上腺素受体激动药","chapterIdx":8,"num":6},{"type":"D","stem":"名词解释：多巴胺（DA）","answer":"激动DA、β1和α受体，作用随剂量而变。小剂量扩张肾和肠系膜血管、增加尿量，较大剂量兴奋心脏并收缩血管。用于各种休克和急性肾衰竭。","rationale":"出自概念手册「肾上腺素受体激动药」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph09_q007","chapter":"第九章 肾上腺素受体激动药","chapterIdx":8,"num":7},{"type":"D","stem":"名词解释：多巴酚丁胺","answer":"选择性激动β1受体，增强心肌收缩力、增加心排出量，对心率和血压影响较小。主要用于心肌梗死后或心脏手术后的心排血量降低及心力衰竭。","rationale":"出自概念手册「肾上腺素受体激动药」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph09_q008","chapter":"第九章 肾上腺素受体激动药","chapterIdx":8,"num":8},{"type":"D","stem":"名词解释：麻黄碱","answer":"直接激动α、β受体并促进去甲肾上腺素释放，性质稳定可口服，作用弱而持久，易产生快速耐受性。用于支气管哮喘的预防、鼻塞、低血压及荨麻疹。","rationale":"出自概念手册「肾上腺素受体激动药」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph09_q009","chapter":"第九章 肾上腺素受体激动药","chapterIdx":8,"num":9},{"type":"D","stem":"名词解释：间羟胺（阿拉明）","answer":"直接激动α受体并促进神经末梢释放去甲肾上腺素，升压作用较弱而持久，不易引起肾衰竭和组织坏死。用于各种休克早期及低血压。","rationale":"出自概念手册「肾上腺素受体激动药」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph09_q010","chapter":"第九章 肾上腺素受体激动药","chapterIdx":8,"num":10},{"type":"D","stem":"名词解释：去氧肾上腺素（新福林）","answer":"选择性激动α1受体，收缩血管而升压，反射性减慢心率。用于阵发性室上性心动过速、休克及散瞳检查眼底。","rationale":"出自概念手册「肾上腺素受体激动药」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph09_q011","chapter":"第九章 肾上腺素受体激动药","chapterIdx":8,"num":11},{"type":"D","stem":"名词解释：甲氧明","answer":"选择性激动α1受体，升压作用温和而持久，反射性减慢心率。用于休克、阵发性室上性心动过速及麻醉后低血压。","rationale":"出自概念手册「肾上腺素受体激动药」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph09_q012","chapter":"第九章 肾上腺素受体激动药","chapterIdx":8,"num":12},{"type":"D","stem":"名词解释：升压作用翻转","answer":"先使用α受体阻断药，再用肾上腺素时，α受体已被阻断，β2受体舒张血管的效应占优势，使原本升压的肾上腺素表现为降压。","rationale":"出自概念手册「肾上腺素受体激动药」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph09_q013","chapter":"第九章 肾上腺素受体激动药","chapterIdx":8,"num":13},{"type":"D","stem":"名词解释：麻黄碱快速耐受性","answer":"连续多次给药后效应迅速减弱的现象，麻黄碱和间羟胺较易发生，与递质耗竭和受体反应性下降有关，停药后可恢复。","rationale":"出自概念手册「肾上腺素受体激动药」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph09_q014","chapter":"第九章 肾上腺素受体激动药","chapterIdx":8,"num":14},{"type":"D","stem":"名词解释：局部组织缺血坏死","answer":"静脉滴注去甲肾上腺素浓度过高或药液外漏时，局部血管强烈收缩导致组织缺血，出现皮肤苍白、发凉甚至坏死，可用酚妥拉明局部浸润解救。","rationale":"出自概念手册「肾上腺素受体激动药」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph09_q015","chapter":"第九章 肾上腺素受体激动药","chapterIdx":8,"num":15},{"type":"S","stem":"简答题：比较肾上腺素、去甲肾上腺素和异丙肾上腺素对心血管系统的作用。","answer":"①心脏：三者均激动β1受体兴奋心脏；肾上腺素作用强而快，异丙肾上腺素的正性肌力、正性频率和加速传导作用最强、明显增加心肌耗氧量，去甲肾上腺素对心脏β1作用较弱，可因血压骤升反射性减慢心率。②血管：去甲肾上腺素强烈激动α受体，除冠脉外全身血管收缩；肾上腺素使皮肤黏膜及内脏血管收缩（α1）、骨骼肌和肝脏血管舒张（β2）、冠脉舒张；异丙肾上腺素激动β2受体使骨骼肌血管明显舒张，对α受体几无作用。③血压：去甲肾上腺素升压作用强，小剂量脉压变小；肾上腺素呈双相反应（升压后轻度下降），大剂量收缩压与舒张压均升高；异丙肾上腺素使收缩压升高、舒张压降低、脉压加大。","rationale":"采分点按“心脏—血管—血压”三条主线对比，血压表现是最易失分处：去甲肾上腺素升压、肾上腺素双相、异丙肾上腺素脉压加大。易错是把异丙肾上腺素写成升压药。","id":"rph09_q016","chapter":"第九章 肾上腺素受体激动药","chapterIdx":8,"num":16},{"type":"F","stem":"填空题：房室传导阻滞可选用______和______治疗，可用于治疗急性肾功能衰竭的拟肾上腺素药是______。","answer":"①阿托品 ②异丙肾上腺素 ③多巴胺","rationale":"阿托品解除迷走神经对心脏的抑制、缩短房室结ERP；异丙肾上腺素加速传导；多巴胺小剂量激动DA受体扩张肾血管，与利尿药合用于急性肾衰竭。","id":"rph09_q017","chapter":"第九章 肾上腺素受体激动药","chapterIdx":8,"num":17},{"type":"F","stem":"填空题：小剂量多巴胺主要激动______受体，使肾、肠系膜、脑及冠脉血管扩张；大剂量时激动______受体，使血管收缩、血压升高。","answer":"①外周多巴胺（DA）②α","rationale":"多巴胺作用呈剂量依赖性：小剂量激动DA受体扩张肾血管，中剂量激动β1受体增强心肌收缩力，大剂量激动α受体使血管收缩，故须控制滴速。","id":"rph09_q018","chapter":"第九章 肾上腺素受体激动药","chapterIdx":8,"num":18},{"type":"T","stem":"判断题：异丙肾上腺素对α受体几无作用，激动β1和β2受体后使收缩压升高、舒张压降低、脉压加大。","options":{"A":"正确","B":"错误"},"answer":["A"],"rationale":"心脏β1受体兴奋使心输出量增加而收缩压升高，骨骼肌血管β2受体舒张使外周阻力下降而舒张压降低，故脉压明显加大。","id":"rph09_q019","chapter":"第九章 肾上腺素受体激动药","chapterIdx":8,"num":19},{"type":"T","stem":"判断题：去甲肾上腺素可口服给药，适用于各种休克，且不易引起局部组织缺血坏死。","options":{"A":"正确","B":"错误"},"answer":["B"],"rationale":"去甲肾上腺素口服因胃肠黏膜血管剧烈收缩而无效，只能静脉滴注；注射外漏易致局部组织缺血坏死（可用酚妥拉明局部浸润），并可引起急性肾衰竭，现休克已多被间羟胺替代。","id":"rph09_q020","chapter":"第九章 肾上腺素受体激动药","chapterIdx":8,"num":20}]},{"title":"第十章 肾上腺素受体阻断药","questions":[{"type":"D","stem":"名词解释：肾上腺素受体阻断药","answer":"又称抗肾上腺素药，能与肾上腺素受体结合而不激动受体，或虽有微弱激动作用但以阻断激动药效应为主，按受体类型分为α受体阻断药和β受体阻断药。","rationale":"出自概念手册「肾上腺素受体阻断药」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph10_q001","chapter":"第十章 肾上腺素受体阻断药","chapterIdx":9,"num":1},{"type":"D","stem":"名词解释：α受体阻断药","answer":"选择性阻断α受体，拮抗去甲肾上腺素和肾上腺素的升压效应，使血管舒张、血压下降。分为竞争性（酚妥拉明）和非竞争性（酚苄明）两类。","rationale":"出自概念手册「肾上腺素受体阻断药」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph10_q002","chapter":"第十章 肾上腺素受体阻断药","chapterIdx":9,"num":2},{"type":"D","stem":"名词解释：酚妥拉明","answer":"竞争性阻断α1和α2受体，兼有直接舒张血管、兴奋心脏、拟胆碱和组胺样作用。用于外周血管痉挛性疾病、休克、嗜铬细胞瘤诊断与术前准备及去甲肾上腺素外漏。","rationale":"出自概念手册「肾上腺素受体阻断药」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph10_q003","chapter":"第十章 肾上腺素受体阻断药","chapterIdx":9,"num":3},{"type":"D","stem":"名词解释：酚苄明","answer":"非竞争性α受体阻断药，与受体结合牢固、作用强而持久，一次给药可维持数日。用于外周血管痉挛性疾病、休克和嗜铬细胞瘤术前准备。","rationale":"出自概念手册「肾上腺素受体阻断药」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph10_q004","chapter":"第十章 肾上腺素受体阻断药","chapterIdx":9,"num":4},{"type":"D","stem":"名词解释：哌唑嗪","answer":"选择性α1受体阻断药，舒张血管、降低血压，不引起明显反射性心动过速，首次给药可致首剂现象。用于高血压和良性前列腺增生。","rationale":"出自概念手册「肾上腺素受体阻断药」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph10_q005","chapter":"第十章 肾上腺素受体阻断药","chapterIdx":9,"num":5},{"type":"D","stem":"名词解释：育亨宾","answer":"选择性α2受体阻断药，可促进去甲肾上腺素释放，曾用于男性性功能障碍，目前主要用于实验研究，临床应用较少。","rationale":"出自概念手册「肾上腺素受体阻断药」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph10_q006","chapter":"第十章 肾上腺素受体阻断药","chapterIdx":9,"num":6},{"type":"D","stem":"名词解释：β受体阻断药","answer":"选择性阻断β受体，拮抗异丙肾上腺素和肾上腺素对心脏及支气管的效应，分为非选择性、选择性β1和α、β兼阻断三类。","rationale":"出自概念手册「肾上腺素受体阻断药」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph10_q007","chapter":"第十章 肾上腺素受体阻断药","chapterIdx":9,"num":7},{"type":"D","stem":"名词解释：普萘洛尔","answer":"非选择性β受体阻断药，无内在拟交感活性。减慢心率、降低心肌收缩力和心肌耗氧量、抑制肾素释放。用于心律失常、心绞痛、高血压和甲状腺功能亢进。","rationale":"出自概念手册「肾上腺素受体阻断药」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph10_q008","chapter":"第十章 肾上腺素受体阻断药","chapterIdx":9,"num":8},{"type":"D","stem":"名词解释：内在拟交感活性","answer":"某些β受体阻断药在阻断β受体的同时尚有微弱的激动β受体作用，如吲哚洛尔、醋丁洛尔。此类药物对心脏抑制和支气管收缩作用较轻。","rationale":"出自概念手册「肾上腺素受体阻断药」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph10_q009","chapter":"第十章 肾上腺素受体阻断药","chapterIdx":9,"num":9},{"type":"D","stem":"名词解释：膜稳定作用","answer":"β受体阻断药具有的类似奎尼丁的局部麻醉作用，可降低细胞膜对离子的通透性，与β受体阻断无关，临床意义较小。","rationale":"出自概念手册「肾上腺素受体阻断药」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph10_q010","chapter":"第十章 肾上腺素受体阻断药","chapterIdx":9,"num":10},{"type":"D","stem":"名词解释：β受体阻断药停药反跳","answer":"长期使用β受体阻断药后突然停药，可使原有疾病加重或复发，与受体向上调节有关，故停药应逐渐减量。","rationale":"出自概念手册「肾上腺素受体阻断药」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph10_q011","chapter":"第十章 肾上腺素受体阻断药","chapterIdx":9,"num":11},{"type":"D","stem":"名词解释：噻吗洛尔","answer":"作用强的非选择性β受体阻断药，局部滴眼可减少房水生成、降低眼内压，用于青光眼，全身吸收后可诱发哮喘和心动过缓。","rationale":"出自概念手册「肾上腺素受体阻断药」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph10_q012","chapter":"第十章 肾上腺素受体阻断药","chapterIdx":9,"num":12},{"type":"D","stem":"名词解释：拉贝洛尔","answer":"兼有α和β受体阻断作用，可降低血压而不明显减少心排出量。用于高血压、妊娠高血压和心绞痛。","rationale":"出自概念手册「肾上腺素受体阻断药」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph10_q013","chapter":"第十章 肾上腺素受体阻断药","chapterIdx":9,"num":13},{"type":"D","stem":"名词解释：选择性β1受体阻断药","answer":"对β1受体有较高选择性，如美托洛尔、阿替洛尔，心脏抑制作用明显而对支气管和糖代谢影响较小，哮喘患者仍需慎用。","rationale":"出自概念手册「肾上腺素受体阻断药」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph10_q014","chapter":"第十章 肾上腺素受体阻断药","chapterIdx":9,"num":14},{"type":"D","stem":"名词解释：嗜铬细胞瘤","answer":"肾上腺髓质嗜铬细胞发生的肿瘤，可阵发性释放大量儿茶酚胺引起血压骤升；α受体阻断药用于其诊断和术前准备。","rationale":"出自概念手册「肾上腺素受体阻断药」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph10_q015","chapter":"第十章 肾上腺素受体阻断药","chapterIdx":9,"num":15},{"type":"S","stem":"简答题：简述酚妥拉明的药理作用与临床应用。","answer":"①阻断α受体（对α1、α2亲和力相同，为竞争性阻断）：扩张血管、血压下降，并可翻转肾上腺素的升压作用；②直接舒张血管作用；③心脏兴奋：血压下降反射性兴奋交感神经，并阻断突触前膜α2受体促进NA释放，使心肌收缩力增强、心率加快、心输出量增加；④拟胆碱作用（胃肠道平滑肌兴奋，可被阿托品拮抗）与拟组胺作用（血管通透性增加、皮肤潮红）；⑤临床应用：外周血管痉挛性疾病（雷诺病、血栓闭塞性脉管炎）、去甲肾上腺素滴注外漏、抗休克（酚妥拉明与去甲肾上腺素合用）、顽固性充血性心力衰竭及急性心肌梗死、嗜铬细胞瘤的诊断及手术中高血压危象。","rationale":"采分点按“α阻断（含升压作用翻转）—直接扩血管—反射性心脏兴奋—拟胆碱拟组胺—临床应用”作答。易错是漏掉阻断突触前α2受体促NA释放这一机制，以及误认为常规用于高血压降压。","id":"rph10_q016","chapter":"第十章 肾上腺素受体阻断药","chapterIdx":9,"num":16},{"type":"F","stem":"填空题：长期应用β受体阻断药后突然停药可出现______现象，其机制与受体______调节、对儿茶酚胺敏感性增高有关，故应逐渐减量停药。","answer":"①反跳 ②向上（上调）","rationale":"受体调节规律：下调—受体脱敏—激动药—耐受性；上调—受体增敏—拮抗药—反跳现象，两组要对应记忆。","id":"rph10_q017","chapter":"第十章 肾上腺素受体阻断药","chapterIdx":9,"num":17},{"type":"F","stem":"填空题：β受体阻断药的药理作用包括______、______和______。","answer":"①β受体阻断作用（抑制心脏、收缩支气管、影响代谢、减少肾素分泌）②膜稳定作用 ③内在拟交感活性","rationale":"膜稳定作用需较高浓度、与治疗作用基本无关；内在拟交感活性指阻断β受体同时产生较弱的激动作用，常被阻断作用掩盖。","id":"rph10_q018","chapter":"第十章 肾上腺素受体阻断药","chapterIdx":9,"num":18},{"type":"T","stem":"判断题：普萘洛尔阻断支气管β2受体，可诱发或加重支气管哮喘，故支气管哮喘为其禁忌证。","options":{"A":"正确","B":"错误"},"answer":["A"],"rationale":"阻断β2受体使支气管平滑肌收缩、气道阻力增加；选择性β1受体阻断药对β2作用弱、一般不引起，但对哮喘患者仍应慎用。","id":"rph10_q019","chapter":"第十章 肾上腺素受体阻断药","chapterIdx":9,"num":19},{"type":"T","stem":"判断题：选择性β1受体阻断药美托洛尔对β2受体完全没有作用，因此可安全用于支气管哮喘患者。","options":{"A":"正确","B":"错误"},"answer":["B"],"rationale":"选择性是相对的：美托洛尔对β2受体作用弱但并非没有作用，增加呼吸道阻力作用较轻，可用于伴肺功能受损的高血压患者，但哮喘患者仍须慎重。","id":"rph10_q020","chapter":"第十章 肾上腺素受体阻断药","chapterIdx":9,"num":20}]},{"title":"第十一章 中枢神经系统药理学概论","questions":[{"type":"D","stem":"名词解释：中枢神经系统药理学","answer":"研究药物对中枢神经系统的作用及其规律，以及中枢功能状态对药物反应影响的学科，核心是突触传递与递质受体系统。","rationale":"出自概念手册「中枢神经系统药理学概论」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph11_q001","chapter":"第十一章 中枢神经系统药理学概论","chapterIdx":10,"num":1},{"type":"D","stem":"名词解释：神经元","answer":"中枢神经系统的基本结构和功能单位，由胞体、树突和轴突构成，通过突触接受、整合和传递信息，是中枢信息处理的基本元件。","rationale":"出自概念手册「中枢神经系统药理学概论」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph11_q002","chapter":"第十一章 中枢神经系统药理学概论","chapterIdx":10,"num":2},{"type":"D","stem":"名词解释：神经胶质细胞","answer":"中枢内数量远多于神经元的支持细胞，包括星形胶质细胞、少突胶质细胞、小胶质细胞和室管膜细胞，参与支持、营养、修复、构成血脑屏障和摄取递质。","rationale":"出自概念手册「中枢神经系统药理学概论」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph11_q003","chapter":"第十一章 中枢神经系统药理学概论","chapterIdx":10,"num":3},{"type":"D","stem":"名词解释：突触","answer":"神经元之间或神经元与效应细胞之间的特化连接，由突触前膜、突触间隙和突触后膜组成，是中枢信息传递和药物作用的关键部位。","rationale":"出自概念手册「中枢神经系统药理学概论」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph11_q005","chapter":"第十一章 中枢神经系统药理学概论","chapterIdx":10,"num":5},{"type":"F","stem":"填空题：神经元之间或神经元与效应细胞之间的特化连接，由______前膜、突触间隙和突触后膜组成，是中枢信息传递和药物作用的关键部位。","answer":"突触","rationale":"出自概念手册「中枢神经系统药理学概论」核心概念：突触。","id":"rph11_q006","chapter":"第十一章 中枢神经系统药理学概论","chapterIdx":10,"num":6},{"type":"D","stem":"名词解释：突触传递","answer":"冲动到达突触前末梢使电压门控钙通道开放，钙内流触发囊泡与前膜融合并胞裂外排释放递质，递质作用于后膜受体产生突触后电位的过程。","rationale":"出自概念手册「中枢神经系统药理学概论」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph11_q007","chapter":"第十一章 中枢神经系统药理学概论","chapterIdx":10,"num":7},{"type":"D","stem":"名词解释：兴奋性突触后电位（EPSP）","answer":"兴奋性递质使后膜对钠、钾通透性增大而产生的局部去极化电位，使神经元易于兴奋；属局部电位，可空间和时间总和。","rationale":"出自概念手册「中枢神经系统药理学概论」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph11_q008","chapter":"第十一章 中枢神经系统药理学概论","chapterIdx":10,"num":8},{"type":"D","stem":"名词解释：抑制性突触后电位（IPSP）","answer":"抑制性递质使后膜对氯、钾通透性增大而产生的超极化电位，降低神经元兴奋性，与EPSP在胞体整合后决定是否发放冲动。","rationale":"出自概念手册「中枢神经系统药理学概论」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph11_q009","chapter":"第十一章 中枢神经系统药理学概论","chapterIdx":10,"num":9},{"type":"D","stem":"名词解释：离子通道","answer":"细胞膜上由蛋白质构成、允许特定离子顺电化学梯度跨膜流动的孔道，分电压门控、配体门控和机械门控三类，是神经元兴奋性和药物作用的重要靶点。","rationale":"出自概念手册「中枢神经系统药理学概论」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph11_q010","chapter":"第十一章 中枢神经系统药理学概论","chapterIdx":10,"num":10},{"type":"D","stem":"名词解释：神经递质","answer":"由突触前末梢释放、能特异作用于后膜受体并引起信息传递的内源性物质，须具备合成、贮存、释放、受体作用和灭活等基本条件。","rationale":"出自概念手册「中枢神经系统药理学概论」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph11_q011","chapter":"第十一章 中枢神经系统药理学概论","chapterIdx":10,"num":11},{"type":"D","stem":"名词解释：神经调质","answer":"本身不直接引起明显突触后电位，而能调节递质释放或后膜反应的内源性物质，多为神经肽，常与经典递质共存。","rationale":"出自概念手册「中枢神经系统药理学概论」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph11_q012","chapter":"第十一章 中枢神经系统药理学概论","chapterIdx":10,"num":12},{"type":"D","stem":"名词解释：乙酰胆碱（ACh）","answer":"中枢胆碱能递质，由胆碱与乙酰辅酶A经胆碱乙酰化酶合成，被乙酰胆碱酯酶水解；参与觉醒、学习记忆、运动协调和体温调节。","rationale":"出自概念手册「中枢神经系统药理学概论」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph11_q013","chapter":"第十一章 中枢神经系统药理学概论","chapterIdx":10,"num":13},{"type":"D","stem":"名词解释：γ-氨基丁酸（GABA）","answer":"中枢最主要的抑制性递质，由谷氨酸经谷氨酸脱羧酶脱羧生成，经GABA转氨酶代谢，作用于GABA-A和GABA-B受体，广泛分布于皮质、海马和小脑。","rationale":"出自概念手册「中枢神经系统药理学概论」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph11_q014","chapter":"第十一章 中枢神经系统药理学概论","chapterIdx":10,"num":14},{"type":"D","stem":"名词解释：谷氨酸","answer":"中枢最主要的兴奋性递质，作用于NMDA、AMPA和KA受体，参与学习记忆和突触可塑性，过度释放可产生兴奋性毒性。","rationale":"出自概念手册「中枢神经系统药理学概论」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph11_q015","chapter":"第十一章 中枢神经系统药理学概论","chapterIdx":10,"num":15},{"type":"D","stem":"名词解释：5-羟色胺（5-HT）","answer":"由色氨酸经羟化和脱羧生成的单胺类递质，胞体集中于脑干中缝核，参与情绪、睡眠、体温、痛觉和呕吐调节，其再摄取转运体是抗抑郁药的重要靶点。","rationale":"出自概念手册「中枢神经系统药理学概论」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph11_q017","chapter":"第十一章 中枢神经系统药理学概论","chapterIdx":10,"num":17},{"type":"D","stem":"名词解释：组胺","answer":"中枢组胺能神经元胞体位于下丘脑结节乳头核，纤维投射至全脑；H1受体与觉醒警觉有关，H2受体参与认知，H3受体为突触前自身受体。","rationale":"出自概念手册「中枢神经系统药理学概论」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph11_q018","chapter":"第十一章 中枢神经系统药理学概论","chapterIdx":10,"num":18},{"type":"F","stem":"填空题：中枢______能神经元胞体位于下丘脑结节乳头核，纤维投射至全脑；H1受体与觉醒警觉有关，H2受体参与认知，H3受体为突触前自身受体。","answer":"组胺","rationale":"出自概念手册「中枢神经系统药理学概论」核心概念：组胺。","id":"rph11_q019","chapter":"第十一章 中枢神经系统药理学概论","chapterIdx":10,"num":19},{"type":"D","stem":"名词解释：神经肽","answer":"由若干氨基酸残基组成的内源性活性肽，如P物质、脑啡肽、内啡肽和神经降压肽，多作为调质与经典递质共存，主要经肽酶水解灭活。","rationale":"出自概念手册「中枢神经系统药理学概论」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph11_q020","chapter":"第十一章 中枢神经系统药理学概论","chapterIdx":10,"num":20},{"type":"S","stem":"简答题：简述中枢神经系统药物作用的基本方式及中枢用药的特点。","answer":"①作用基本点是递质和受体：可影响递质的生物合成（如影响酪氨酸羟化酶等限速酶）、贮存、释放和消除（抑制MAO、阻断再摄取、影响灭活），也可直接激动或拮抗突触后受体。②还可直接作用于离子通道及受体后的细胞内信号转导（第二信使），改变神经元兴奋性。③作用部位在突触：递质作用于后膜受体产生EPSP或IPSP，多个突触电位在胞体整合后决定神经元是否发放冲动。④中枢药物特点：脂溶性较高、分子质量小，较易透过血脑屏障；作用广泛、选择性低，治疗作用与不良反应几乎同时出现；部分药物易产生耐受性、依赖性和停药反跳，须个体化用药并避免突然停药。⑤中枢不同部位对药物敏感性不同：进化程度高的脑组织（大脑皮质新皮质）敏感性高，大脑皮质的抑制功能比兴奋功能更敏感，延髓生命中枢相对稳定。","rationale":"采分点为“作用于递质与受体—经突触传递整合—脂溶性高易入脑、作用广泛—脑组织敏感性差异”。易错是只答“激动或阻断受体”，漏掉递质合成、贮存、释放、消除等环节和血脑屏障。","id":"rph11_q021","chapter":"第十一章 中枢神经系统药理学概论","chapterIdx":10,"num":21},{"type":"F","stem":"填空题：中枢最主要的抑制性递质是______，最主要的兴奋性递质是______，前者作用于______受体使氯通道开放而产生IPSP。","answer":"①γ-氨基丁酸（GABA）②谷氨酸 ③GABA-A（GABAA）","rationale":"GABA-A受体为配体门控Cl-通道，是苯二氮䓬类和巴比妥类的作用基础；谷氨酸经NMDA、AMPA和KA受体介导快速兴奋性传递，过度激活产生兴奋性毒性。","id":"rph11_q022","chapter":"第十一章 中枢神经系统药理学概论","chapterIdx":10,"num":22},{"type":"F","stem":"填空题：脑内多巴胺的四条通路是______、______、______和______。","answer":"①黑质-纹状体通路 ②中脑-边缘系统通路 ③中脑-皮质通路 ④结节-漏斗通路","rationale":"四条通路功能各异：黑质-纹状体调节运动（抗帕金森病药与锥体外系反应的靶点），中脑-边缘与中脑-皮质系统与精神活动有关（抗精神病药靶点），结节-漏斗调控催乳素等分泌。","id":"rph11_q023","chapter":"第十一章 中枢神经系统药理学概论","chapterIdx":10,"num":23},{"type":"T","stem":"判断题：血脑屏障由脑毛细血管内皮细胞间的紧密连接、基膜及星形胶质细胞足突构成，脂溶性高、分子小的药物易通过。","options":{"A":"正确","B":"错误"},"answer":["A"],"rationale":"血脑屏障限制水溶性药物、大分子和带电物质入脑，故中枢用药多为脂溶性高、分子质量小的药物，这也是多巴胺不能入脑而须用左旋多巴的原因。","id":"rph11_q024","chapter":"第十一章 中枢神经系统药理学概论","chapterIdx":10,"num":24},{"type":"T","stem":"判断题：脑内乙酰胆碱主要激动M2受体提高皮质和海马神经元兴奋性，而M1为突触前自身受体、激动时抑制ACh释放。","options":{"A":"正确","B":"错误"},"answer":["B"],"rationale":"说反了：脑内以M1受体为主，激动提高皮质和海马神经元兴奋性，与学习记忆和觉醒有关；M2为自身受体，激动时抑制ACh释放。","id":"rph11_q025","chapter":"第十一章 中枢神经系统药理学概论","chapterIdx":10,"num":25}]},{"title":"第十二章 麻醉药","questions":[{"type":"D","stem":"名词解释：麻醉药","answer":"能可逆性地使机体局部或全身感觉暂时丧失，以便进行外科手术的药物，分为局部麻醉药和全身麻醉药两大类。","rationale":"出自概念手册「麻醉药」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph12_q001","chapter":"第十二章 麻醉药","chapterIdx":11,"num":1},{"type":"F","stem":"填空题：能可逆性地使机体局部或全身感觉暂时丧失，以便进行外科手术的药物，分为局部______和全身麻醉药两大类。","answer":"麻醉药","rationale":"出自概念手册「麻醉药」核心概念：麻醉药。","id":"rph12_q002","chapter":"第十二章 麻醉药","chapterIdx":11,"num":2},{"type":"D","stem":"名词解释：局部麻醉药","answer":"能可逆性阻断神经冲动的产生和传导，使给药局部失去痛觉等感觉的药物，作用消失后神经功能可完全恢复。","rationale":"出自概念手册「麻醉药」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph12_q003","chapter":"第十二章 麻醉药","chapterIdx":11,"num":3},{"type":"D","stem":"名词解释：局部麻醉方式","answer":"按给药和阻滞部位分为表面麻醉、浸润麻醉、传导麻醉、蛛网膜下腔麻醉和硬膜外麻醉，分别适用于黏膜、浅表组织、神经干和椎管内麻醉。","rationale":"出自概念手册「麻醉药」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph12_q004","chapter":"第十二章 麻醉药","chapterIdx":11,"num":4},{"type":"D","stem":"名词解释：普鲁卡因","answer":"短效酯类局麻药，亲脂性低、穿透力弱，只作注射用，用于浸润、传导和蛛网膜下腔麻醉，易致过敏反应，用药前需做皮试。","rationale":"出自概念手册「麻醉药」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph12_q005","chapter":"第十二章 麻醉药","chapterIdx":11,"num":5},{"type":"D","stem":"名词解释：利多卡因","answer":"酰胺类局麻药，起效快、穿透力强、弥散广、毒性相对较小，可用于各种局麻方式，也是治疗室性心律失常的常用药。","rationale":"出自概念手册「麻醉药」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph12_q006","chapter":"第十二章 麻醉药","chapterIdx":11,"num":6},{"type":"D","stem":"名词解释：丁卡因","answer":"长效酯类局麻药，穿透力强、毒性较大，主要用于表面麻醉，也可用于蛛网膜下腔麻醉和硬膜外麻醉，一般不用于浸润麻醉。","rationale":"出自概念手册「麻醉药」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph12_q007","chapter":"第十二章 麻醉药","chapterIdx":11,"num":7},{"type":"D","stem":"名词解释：布比卡因","answer":"酰胺类长效局麻药，作用强而持久，用于浸润、传导和硬膜外麻醉，心脏毒性较大，误入血管可致严重心律失常。","rationale":"出自概念手册「麻醉药」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph12_q008","chapter":"第十二章 麻醉药","chapterIdx":11,"num":8},{"type":"D","stem":"名词解释：罗哌卡因","answer":"酰胺类长效局麻药，感觉阻滞良好而运动阻滞较轻，心脏毒性低于布比卡因，适用于硬膜外麻醉、分娩镇痛和术后镇痛。","rationale":"出自概念手册「麻醉药」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph12_q009","chapter":"第十二章 麻醉药","chapterIdx":11,"num":9},{"type":"D","stem":"名词解释：局麻药中毒","answer":"剂量过大或误入血管使血药浓度过高所致，表现为眩晕、烦躁、肌肉抽搐甚至惊厥，进而呼吸和心血管抑制，处理为停药、给氧、静注地西泮和升压。","rationale":"出自概念手册「麻醉药」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph12_q010","chapter":"第十二章 麻醉药","chapterIdx":11,"num":10},{"type":"D","stem":"名词解释：全身麻醉药","answer":"经吸入或静脉注射后使机体产生可逆性意识丧失、感觉与反射消失、骨骼肌松弛，以满足手术需要的药物，分吸入麻醉药和静脉麻醉药。","rationale":"出自概念手册「麻醉药」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph12_q011","chapter":"第十二章 麻醉药","chapterIdx":11,"num":11},{"type":"D","stem":"名词解释：吸入麻醉药","answer":"经呼吸道吸入、在肺泡吸收入血并进入脑组织而发挥作用的全身麻醉药，麻醉深度随肺泡内浓度变化而易于调节，安全性较好。","rationale":"出自概念手册「麻醉药」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph12_q012","chapter":"第十二章 麻醉药","chapterIdx":11,"num":12},{"type":"D","stem":"名词解释：最低肺泡有效浓度（MAC）","answer":"在一个大气压下使50%的动物或患者对标准伤害性刺激不发生体动反应的肺泡气麻醉药浓度，是衡量吸入麻醉药强度的指标，MAC越小麻醉强度越大。","rationale":"出自概念手册「麻醉药」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph12_q013","chapter":"第十二章 麻醉药","chapterIdx":11,"num":13},{"type":"D","stem":"名词解释：血气分配系数","answer":"麻醉药在血液与气体两相中达到平衡时的浓度比值，反映药物的血液溶解度；系数小者诱导和苏醒快、可控性好，系数大者诱导慢。","rationale":"出自概念手册「麻醉药」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph12_q014","chapter":"第十二章 麻醉药","chapterIdx":11,"num":14},{"type":"D","stem":"名词解释：恩氟烷","answer":"卤化烃类吸入麻醉药，麻醉性能强、诱导平稳、肌肉松弛良好，深麻醉时脑电图可出现惊厥样改变，癫痫和颅内压增高患者不宜使用。","rationale":"出自概念手册「麻醉药」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph12_q015","chapter":"第十二章 麻醉药","chapterIdx":11,"num":15},{"type":"D","stem":"名词解释：异氟烷","answer":"恩氟烷的同分异构体，麻醉强度大于恩氟烷，诱导迅速、苏醒快，对循环抑制较轻，肌肉松弛好，是目前常用的吸入麻醉药。","rationale":"出自概念手册「麻醉药」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph12_q016","chapter":"第十二章 麻醉药","chapterIdx":11,"num":16},{"type":"D","stem":"名词解释：七氟烷","answer":"血气分配系数低的吸入麻醉药，诱导和苏醒迅速，对呼吸道刺激性小，适合小儿麻醉诱导；与钠石灰接触可生成有毒的化合物A。","rationale":"出自概念手册「麻醉药」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph12_q017","chapter":"第十二章 麻醉药","chapterIdx":11,"num":17},{"type":"D","stem":"名词解释：氧化亚氮（笑气）","answer":"麻醉效能低，单独应用不能达到外科麻醉深度，需与其他全麻药复合；诱导快、镇痛作用强、对循环呼吸影响小，可致缺氧和体内闭合腔膨胀。","rationale":"出自概念手册「麻醉药」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph12_q018","chapter":"第十二章 麻醉药","chapterIdx":11,"num":18},{"type":"D","stem":"名词解释：硫喷妥钠","answer":"超短效巴比妥类静脉麻醉药，脂溶性高，静注后迅速入脑，起效快、苏醒也快；镇痛作用弱、肌松差，可抑制呼吸并诱发喉痉挛，哮喘和卟啉症患者禁用。","rationale":"出自概念手册「麻醉药」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph12_q019","chapter":"第十二章 麻醉药","chapterIdx":11,"num":19},{"type":"D","stem":"名词解释：丙泊酚","answer":"短效静脉麻醉药，起效快、作用时间短、苏醒迅速而完全，广泛用于麻醉诱导与维持、无痛诊疗和重症监护镇静，缺点是注射痛和呼吸循环抑制。","rationale":"出自概念手册「麻醉药」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph12_q020","chapter":"第十二章 麻醉药","chapterIdx":11,"num":20},{"type":"D","stem":"名词解释：氯胺酮","answer":"非竞争性NMDA受体阻滞药，静脉注射后产生分离麻醉，镇痛作用强，可致心率加快、血压升高、分泌物增多和苏醒期幻觉。","rationale":"出自概念手册「麻醉药」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph12_q021","chapter":"第十二章 麻醉药","chapterIdx":11,"num":21},{"type":"D","stem":"名词解释：分离麻醉","answer":"氯胺酮引起的意识与感觉分离状态，患者意识消失、痛觉丧失但眼睛可睁开、肌张力增高，同时伴交感神经兴奋表现。","rationale":"出自概念手册「麻醉药」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph12_q022","chapter":"第十二章 麻醉药","chapterIdx":11,"num":22},{"type":"D","stem":"名词解释：依托咪酯","answer":"短效静脉麻醉药，起效快、对循环系统影响小，适用于心血管疾病患者的麻醉诱导，可抑制肾上腺皮质功能并引起注射痛和肌阵挛。","rationale":"出自概念手册「麻醉药」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph12_q023","chapter":"第十二章 麻醉药","chapterIdx":11,"num":23},{"type":"D","stem":"名词解释：复合麻醉","answer":"为减少单药剂量和不良反应、满足手术需要而同时或先后应用多种麻醉药及辅助药的麻醉方式，包括麻醉前给药、基础麻醉、诱导麻醉、合用肌松药和控制性降压。","rationale":"出自概念手册「麻醉药」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph12_q024","chapter":"第十二章 麻醉药","chapterIdx":11,"num":24},{"type":"S","stem":"简答题：局部麻醉药的局麻作用和中枢作用各有何特点？","answer":"①局麻作用：阻滞神经细胞膜上的电压门控Na+通道，使兴奋阈电位升高、传导速度减慢、动作电位幅度降低，严重时降低兴奋性和传导性；作用具有频率依赖性和电压依赖性，处于兴奋状态的神经更敏感。②给药与显效方式：以非解离型（亲脂）透过神经细胞膜进入细胞内，再以解离型作用于细胞膜内表面与Na+通道结合而阻滞通道。③中枢作用（吸收过量或误入血管后的毒性反应）：中枢毒性先于心脏毒性出现，因抑制性神经元对局麻药更敏感而首先被阻滞，故表现为先兴奋后抑制——兴奋期有眩晕、惊恐、震颤、焦虑、神志错乱甚至阵挛性惊厥，随后转入抑制，出现昏迷和呼吸衰竭。④处理：静脉注射地西泮可防止惊厥发作，中毒晚期维持呼吸最为重要。","rationale":"采分点为“局麻作用三项电生理变化＋频率/电压依赖性”“中枢先兴奋后抑制及其机制”“地西泮防惊厥、维持呼吸”。易错是把中枢作用写成“先抑制后兴奋”，或把心脏毒性排在前面。","id":"rph12_q025","chapter":"第十二章 麻醉药","chapterIdx":11,"num":25},{"type":"F","stem":"填空题：吸入麻醉药的主要靶位是______受体，使______通道开放、细胞膜超极化；其“脂质学说”则强调药物的高______使膜受体蛋白和离子通道构象改变。","answer":"①GABA-A ②Cl-（氯离子）③脂溶性","rationale":"“蛋白质学说”认为主要靶位是配体门控离子通道（GABA-A为主，尚有NMDA、甘氨酸、阿片和神经元胆碱受体）；“脂质学说”强调全麻药高脂溶性溶入膜脂质层。","id":"rph12_q026","chapter":"第十二章 麻醉药","chapterIdx":11,"num":26},{"type":"F","stem":"填空题：吸入麻醉药的麻醉强度可用______衡量，其值越小麻醉效能越______；血/气分配系数越小，麻醉深度的可控性越______。","answer":"①最低肺泡浓度（MAC）②强 ③好（容易控制）","rationale":"MAC是使50%病人切皮时不发生体动反应的最低肺泡浓度，与麻醉强度呈负相关；脑/血分配系数与麻醉强度正相关；血/气分配系数与可控性呈反比。","id":"rph12_q027","chapter":"第十二章 麻醉药","chapterIdx":11,"num":27},{"type":"T","stem":"判断题：恶性高热是吸入麻醉药（如氟烷）和去极化肌松药琥珀胆碱触发的遗传性肌病，其特效解救药是丹曲林。","options":{"A":"正确","B":"错误"},"answer":["A"],"rationale":"恶性高热以高代谢为特征，机制是肌浆内Ca2+异常增高；丹曲林抑制肌质网钙释放，在骨骼肌兴奋-收缩耦联水平使肌肉松弛，故为特效药。","id":"rph12_q028","chapter":"第十二章 麻醉药","chapterIdx":11,"num":28},{"type":"T","stem":"判断题：局麻药吸收过量时，心脏毒性先于中枢神经系统毒性出现。","options":{"A":"正确","B":"错误"},"answer":["B"],"rationale":"中枢神经系统毒性先于心脏毒性出现：抑制性神经元最敏感，先出现兴奋（震颤、惊厥）后转入抑制（昏迷、呼吸衰竭），心血管抑制随后发生。","id":"rph12_q029","chapter":"第十二章 麻醉药","chapterIdx":11,"num":29}]},{"title":"第十三章 镇静催眠药","questions":[{"type":"D","stem":"名词解释：镇静催眠药","answer":"能抑制中枢神经系统功能，引起镇静和催眠作用的药物。小剂量产生镇静、缓解焦虑，较大剂量引起催眠，过量可致昏迷和呼吸抑制。","rationale":"出自概念手册「镇静催眠药」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph13_q001","chapter":"第十三章 镇静催眠药","chapterIdx":12,"num":1},{"type":"D","stem":"名词解释：苯二氮䓬类","answer":"以苯二氮䓬为基本结构的镇静催眠药，代表药为地西泮。具有抗焦虑、镇静催眠、抗惊厥和中枢性肌松作用，安全范围较大。","rationale":"出自概念手册「镇静催眠药」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph13_q002","chapter":"第十三章 镇静催眠药","chapterIdx":12,"num":2},{"type":"D","stem":"名词解释：地西泮（安定）","answer":"苯二氮䓬类的代表药，口服吸收快，肌内注射吸收不规则，静脉注射用于癫痫持续状态。用于焦虑症、失眠、麻醉前给药和中枢性肌强直。","rationale":"出自概念手册「镇静催眠药」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph13_q003","chapter":"第十三章 镇静催眠药","chapterIdx":12,"num":3},{"type":"D","stem":"名词解释：氟马西尼","answer":"苯二氮䓬受体的特异性拮抗药，能迅速逆转苯二氮䓬类的中枢抑制作用，用于苯二氮䓬类过量中毒的解救和依赖性诊断。","rationale":"出自概念手册「镇静催眠药」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph13_q004","chapter":"第十三章 镇静催眠药","chapterIdx":12,"num":4},{"type":"D","stem":"名词解释：苯二氮䓬受体","answer":"存在于γ-氨基丁酸A型受体复合物上的特异性结合位点，与苯二氮䓬类结合后可增强γ-氨基丁酸的中枢抑制作用。","rationale":"出自概念手册「镇静催眠药」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph13_q005","chapter":"第十三章 镇静催眠药","chapterIdx":12,"num":5},{"type":"D","stem":"名词解释：γ-氨基丁酸A型受体","answer":"由γ-氨基丁酸识别位点、苯二氮䓬结合位点和氯离子通道组成的受体复合物，激动后氯通道开放、氯离子内流增加，使突触后膜超极化。","rationale":"出自概念手册「镇静催眠药」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph13_q006","chapter":"第十三章 镇静催眠药","chapterIdx":12,"num":6},{"type":"D","stem":"名词解释：巴比妥类","answer":"巴比妥酸的衍生物，随剂量增加依次产生镇静、催眠、抗惊厥、麻醉和呼吸麻痹。脂溶性决定起效快慢，消除方式决定作用维持时间。","rationale":"出自概念手册「镇静催眠药」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph13_q007","chapter":"第十三章 镇静催眠药","chapterIdx":12,"num":7},{"type":"D","stem":"名词解释：苯巴比妥","answer":"长效巴比妥类，脂溶性低、部分经肾排泄，作用持久。具有抗惊厥和抗癫痫作用，是治疗癫痫大发作和癫痫持续状态的常用药，也是肝药酶诱导剂。","rationale":"出自概念手册「镇静催眠药」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph13_q008","chapter":"第十三章 镇静催眠药","chapterIdx":12,"num":8},{"type":"D","stem":"名词解释：水合氯醛","answer":"醛类镇静催眠药，口服或灌肠给药，催眠作用温和，约十五分钟起效。对胃肠道刺激性强，主要用于小儿抗惊厥和顽固性失眠。","rationale":"出自概念手册「镇静催眠药」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph13_q010","chapter":"第十三章 镇静催眠药","chapterIdx":12,"num":10},{"type":"D","stem":"名词解释：唑吡坦","answer":"非苯二氮䓬类催眠药，选择性激动苯二氮䓬受体1亚型，催眠作用强、起效快，较少产生耐受性和依赖性，用于短期治疗失眠。","rationale":"出自概念手册「镇静催眠药」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph13_q011","chapter":"第十三章 镇静催眠药","chapterIdx":12,"num":11},{"type":"D","stem":"名词解释：佐匹克隆","answer":"非苯二氮䓬类催眠药，作用于苯二氮䓬受体，具有催眠、抗焦虑和肌肉松弛作用，用于失眠，次晨残留作用较轻。","rationale":"出自概念手册「镇静催眠药」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph13_q012","chapter":"第十三章 镇静催眠药","chapterIdx":12,"num":12},{"type":"D","stem":"名词解释：宿醉现象","answer":"使用镇静催眠药后次日清晨仍残留头晕、嗜睡、乏力等中枢抑制表现，多见于作用时间长、剂量偏大的药物。","rationale":"出自概念手册「镇静催眠药」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph13_q013","chapter":"第十三章 镇静催眠药","chapterIdx":12,"num":13},{"type":"D","stem":"名词解释：反跳性失眠","answer":"长期使用催眠药后突然停药，失眠症状比用药前更严重，与受体适应性改变有关，应逐渐减量停药。","rationale":"出自概念手册「镇静催眠药」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph13_q014","chapter":"第十三章 镇静催眠药","chapterIdx":12,"num":14},{"type":"D","stem":"名词解释：戒断综合征","answer":"长期使用镇静催眠药后突然停药出现焦虑、失眠、震颤甚至惊厥等表现，是药物依赖性的体现，巴比妥类比苯二氮䓬类更严重。","rationale":"出自概念手册「镇静催眠药」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph13_q015","chapter":"第十三章 镇静催眠药","chapterIdx":12,"num":15},{"type":"S","stem":"简答题：试述地西泮的药理作用与临床应用。","answer":"①抗焦虑：小于镇静剂量即可明显改善焦虑症状，对各种原因引起的焦虑均有显著疗效，是治疗焦虑症的首选药。②镇静催眠：缩短入睡时间、延长睡眠持续时间（主要延长NREMs第2期、明显缩短SWS期、对REMs影响较小），减少觉醒次数；治疗指数高、对呼吸影响小，加大剂量不引起全身麻醉，对肝药酶几无诱导作用。③抗惊厥、抗癫痫：用于破伤风、子痫、高热及药物中毒性惊厥；静脉注射地西泮是癫痫持续状态的首选。④中枢性肌肉松弛：用于脑血管意外、脊髓损伤所致肌强直，发挥肌松作用时不影响正常活动。⑤其他：较大剂量引起暂时性记忆缺失（心脏电复律及内镜检查前用药），并轻度抑制肺泡换气、降低血压、减慢心率。","rationale":"采分点为“抗焦虑—镇静催眠—抗惊厥抗癫痫—中枢性肌松”四点及对应用途，尤其“静注地西泮为癫痫持续状态首选”。易错是漏掉记忆缺失用途，或把“加大剂量引起全麻”错记在苯二氮䓬类。","id":"rph13_q016","chapter":"第十三章 镇静催眠药","chapterIdx":12,"num":16},{"type":"F","stem":"填空题：巴比妥类药物的作用随剂量增加依次出现镇静、催眠、______、______，过量则导致______。","answer":"①抗惊厥 ②麻醉 ③呼吸麻痹（呼吸深度抑制）","rationale":"巴比妥类对CNS呈普遍性抑制且呈剂量依赖性；呼吸深度抑制是急性中毒致死的主要原因，故中毒时维持呼吸最为关键。","id":"rph13_q017","chapter":"第十三章 镇静催眠药","chapterIdx":12,"num":17},{"type":"F","stem":"填空题：苯二氮䓬类通过增加GABA-A受体氯通道的______，巴比妥类则延长氯通道的______，二者均使Cl-内流增加、细胞膜超极化。","answer":"①开放频率 ②开放时间","rationale":"“频率与时间”是两类药机制的核心区别，也是苯二氮䓬类安全性高于巴比妥类的原因之一。","id":"rph13_q018","chapter":"第十三章 镇静催眠药","chapterIdx":12,"num":18},{"type":"T","stem":"判断题：苯二氮䓬类对REMs影响较小，停药后反跳性REM延长较巴比妥类轻，依赖性和戒断症状也较轻微。","options":{"A":"正确","B":"错误"},"answer":["A"],"rationale":"巴比妥类明显缩短REMs，骤然停药引起REM反跳性延长，出现焦虑、失眠、多梦；苯二氮䓬类对REMs影响小，故已取代巴比妥类成为最常用的镇静催眠药。","id":"rph13_q019","chapter":"第十三章 镇静催眠药","chapterIdx":12,"num":19},{"type":"T","stem":"判断题：地西泮肌内注射吸收迅速而完全，因此癫痫持续状态首选肌内注射给药。","options":{"A":"正确","B":"错误"},"answer":["B"],"rationale":"地西泮口服吸收迅速而完全，但肌内注射吸收缓慢而不规则；癫痫持续状态须静脉注射地西泮，肌注不能作为首选途径。","id":"rph13_q020","chapter":"第十三章 镇静催眠药","chapterIdx":12,"num":20}]},{"title":"第十四章 抗癫痫药与抗惊厥药","questions":[{"type":"D","stem":"名词解释：抗癫痫药","answer":"用于控制癫痫发作或预防其复发的药物，主要通过抑制病灶神经元异常放电的扩散或提高正常脑组织的惊厥阈值而发挥作用。","rationale":"出自概念手册「抗癫痫药与抗惊厥药」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph14_q001","chapter":"第十四章 抗癫痫药与抗惊厥药","chapterIdx":13,"num":1},{"type":"D","stem":"名词解释：癫痫","answer":"由脑内神经元异常同步放电引起的慢性反复发作性神经系统疾病，临床可表现为运动、感觉、意识或自主神经功能异常。","rationale":"出自概念手册「抗癫痫药与抗惊厥药」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph14_q002","chapter":"第十四章 抗癫痫药与抗惊厥药","chapterIdx":13,"num":2},{"type":"D","stem":"名词解释：抗惊厥药","answer":"用于控制惊厥症状的药物，包括巴比妥类、苯二氮䓬类、水合氯醛和硫酸镁等，主要用于小儿高热、破伤风、子痫、癫痫持续状态及药物中毒所致的惊厥。","rationale":"出自概念手册「抗癫痫药与抗惊厥药」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph14_q003","chapter":"第十四章 抗癫痫药与抗惊厥药","chapterIdx":13,"num":3},{"type":"D","stem":"名词解释：苯妥英钠","answer":"抗癫痫的主要药物，通过阻滞钠通道减少钠离子内流，抑制病灶高频放电的扩散。对大发作和部分性发作有效，对失神发作无效。","rationale":"出自概念手册「抗癫痫药与抗惊厥药」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph14_q004","chapter":"第十四章 抗癫痫药与抗惊厥药","chapterIdx":13,"num":4},{"type":"D","stem":"名词解释：卡马西平","answer":"阻滞钠通道，抑制神经元的重复放电。是复杂部分性发作的首选药，也是三叉神经痛的首选药，对大发作和部分性发作有效。","rationale":"出自概念手册「抗癫痫药与抗惊厥药」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph14_q005","chapter":"第十四章 抗癫痫药与抗惊厥药","chapterIdx":13,"num":5},{"type":"D","stem":"名词解释：乙琥胺","answer":"抑制丘脑神经元的低阈值钙通道，减少异常放电。为失神发作的首选药，对其他类型发作无效，甚至可诱发大发作，用于混合型发作时须与其他抗癫痫药合用。","rationale":"出自概念手册「抗癫痫药与抗惊厥药」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph14_q006","chapter":"第十四章 抗癫痫药与抗惊厥药","chapterIdx":13,"num":6},{"type":"D","stem":"名词解释：丙戊酸钠","answer":"广谱抗癫痫药，机制涉及阻滞钠通道、抑制γ-氨基丁酸转氨酶而增加脑内γ-氨基丁酸含量。对各型癫痫均有效，但有肝毒性。","rationale":"出自概念手册「抗癫痫药与抗惊厥药」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph14_q007","chapter":"第十四章 抗癫痫药与抗惊厥药","chapterIdx":13,"num":7},{"type":"D","stem":"名词解释：硫酸镁","answer":"镁离子可拮抗钙离子、抑制中枢神经系统和阻断神经肌肉接头传导，注射给药产生抗惊厥和降压作用，口服则有导泻和利胆作用。","rationale":"出自概念手册「抗癫痫药与抗惊厥药」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph14_q008","chapter":"第十四章 抗癫痫药与抗惊厥药","chapterIdx":13,"num":8},{"type":"D","stem":"名词解释：癫痫持续状态","answer":"癫痫发作持续三十分钟以上或连续多次发作、发作间期意识未恢复的危重状态，首选地西泮静脉注射，也可用苯巴比妥肌内注射。","rationale":"出自概念手册「抗癫痫药与抗惊厥药」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph14_q009","chapter":"第十四章 抗癫痫药与抗惊厥药","chapterIdx":13,"num":9},{"type":"D","stem":"名词解释：强直-阵挛性发作","answer":"又称大发作，表现为全身骨骼肌强直性收缩继以阵挛性抽搐，常伴意识丧失，首选苯妥英钠、卡马西平或丙戊酸钠。","rationale":"出自概念手册「抗癫痫药与抗惊厥药」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph14_q010","chapter":"第十四章 抗癫痫药与抗惊厥药","chapterIdx":13,"num":10},{"type":"D","stem":"名词解释：失神性发作","answer":"又称小发作，表现为短暂意识丧失、双眼凝视或动作中断，脑电图呈每秒三次棘慢波，首选乙琥胺，也可用丙戊酸钠。","rationale":"出自概念手册「抗癫痫药与抗惊厥药」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph14_q011","chapter":"第十四章 抗癫痫药与抗惊厥药","chapterIdx":13,"num":11},{"type":"D","stem":"名词解释：复杂部分性发作","answer":"又称精神运动性发作，多起源于颞叶，表现为意识障碍伴自动症，首选卡马西平，也可用丙戊酸钠或苯妥英钠，一般需长期用药。","rationale":"出自概念手册「抗癫痫药与抗惊厥药」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph14_q012","chapter":"第十四章 抗癫痫药与抗惊厥药","chapterIdx":13,"num":12},{"type":"D","stem":"名词解释：奥卡西平","answer":"卡马西平的衍生物，通过阻滞钠通道发挥抗癫痫作用，用于部分性发作和大发作，不良反应较卡马西平少，但仍可致低钠血症。","rationale":"出自概念手册「抗癫痫药与抗惊厥药」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph14_q013","chapter":"第十四章 抗癫痫药与抗惊厥药","chapterIdx":13,"num":13},{"type":"D","stem":"名词解释：拉莫三嗪","answer":"广谱抗癫痫药，阻滞钠通道并减少兴奋性递质释放，用于部分性发作、大发作和失神发作，皮疹是常见且需警惕的不良反应。","rationale":"出自概念手册「抗癫痫药与抗惊厥药」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph14_q014","chapter":"第十四章 抗癫痫药与抗惊厥药","chapterIdx":13,"num":14},{"type":"D","stem":"名词解释：牙龈增生","answer":"长期服用苯妥英钠常见的慢性毒性反应，表现为牙龈红肿、增生、易出血，与剂量和疗程有关，注意口腔卫生、按摩牙龈可减轻，停药后多可恢复。","rationale":"出自概念手册「抗癫痫药与抗惊厥药」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph14_q015","chapter":"第十四章 抗癫痫药与抗惊厥药","chapterIdx":13,"num":15},{"type":"S","stem":"简答题：简述苯妥英钠的抗癫痫作用机制、临床应用及主要不良反应。","answer":"①作用机制：阻滞细胞膜电压依赖性Na+通道，降低细胞膜兴奋性而抑制病灶异常高频放电，并提高正常脑组织兴奋阈值而抑制异常放电扩散；阻滞神经元L型Ca2+通道、抑制K+外流而延长动作电位时程和不应期；抑制GABA的摄取，增强GABA的突触后抑制作用（对T型Ca2+通道无效）。②临床应用：癫痫大发作和局限性发作（对小发作无效甚至加重）；治疗中枢性疼痛综合征如三叉神经痛、舌咽神经痛；抗心律失常，用于洋地黄中毒所致快速型心律失常。③主要不良反应：局部刺激（口服胃肠道刺激、静脉注射致静脉炎），长期应用致齿龈增生；剂量过大引起小脑-前庭功能失调（眼球震颤、复视、共济失调）及语言障碍、精神错乱；巨幼红细胞性贫血（需补充甲酰四氢叶酸钙）；过敏反应甚至再生障碍性贫血；低钙血症致佝偻样病变。④血药浓度个体差异大，＞10µg/ml按零级（恒量）消除，应监测血药浓度。","rationale":"采分点为“钠通道阻滞等三方面机制—大发作/三叉神经痛/抗心律失常三大用途—齿龈增生与共济失调等不良反应”。易错是答“对小发作有效”，或漏掉“＞10µg/ml转为零级消除”。","id":"rph14_q016","chapter":"第十四章 抗癫痫药与抗惊厥药","chapterIdx":13,"num":16},{"type":"F","stem":"填空题：癫痫持续状态首选______静脉注射，癫痫小发作首选______，大发作合并小发作时首选______。","answer":"①地西泮（安定）②乙琥胺 ③丙戊酸钠","rationale":"地西泮静注为癫痫持续状态首选（也可用苯巴比妥）；乙琥胺选择性抑制丘脑T型钙通道，是小发作首选；丙戊酸钠广谱，但因肝毒性不作小发作首选。","id":"rph14_q017","chapter":"第十四章 抗癫痫药与抗惊厥药","chapterIdx":13,"num":17},{"type":"F","stem":"填空题：硫酸镁口服产生______和______作用，注射给药则产生______和______作用。","answer":"①泻下（导泻）②利胆 ③抗惊厥（骨骼肌松弛）④降压","rationale":"硫酸镁完全解离成离子，口服因离子障不能跨膜而滞留肠内形成高渗，故泻下、利胆；注射后Mg2+抑制神经肌肉传递和血管平滑肌，用于子痫、破伤风惊厥及高血压危象。","id":"rph14_q018","chapter":"第十四章 抗癫痫药与抗惊厥药","chapterIdx":13,"num":18},{"type":"T","stem":"判断题：乙琥胺选择性抑制丘脑神经元T型钙通道，故对各型癫痫均有效。","options":{"A":"正确","B":"错误"},"answer":["B"],"rationale":"乙琥胺是防治小发作的首选药，对其他类型癫痫无效；广谱、对各型均有效的是丙戊酸钠。","id":"rph14_q019","chapter":"第十四章 抗癫痫药与抗惊厥药","chapterIdx":13,"num":19},{"type":"T","stem":"判断题：丙戊酸钠为广谱抗癫痫药，对大发作合并小发作的患者可作首选，但其主要不良反应是肝毒性。","options":{"A":"正确","B":"错误"},"answer":["A"],"rationale":"丙戊酸钠对各型癫痫均有效，大发作合并小发作时首选；其肝毒性发生率高（约25%），故小发作仍以乙琥胺为首选。","id":"rph14_q020","chapter":"第十四章 抗癫痫药与抗惊厥药","chapterIdx":13,"num":20}]},{"title":"第十五章 治疗中枢神经系统退行性疾病药","questions":[{"type":"D","stem":"名词解释：帕金森病","answer":"又称震颤麻痹，是中老年人常见的锥体外系疾病，因黑质多巴胺能神经元变性，纹状体多巴胺减少而乙酰胆碱功能相对亢进所致。","rationale":"出自概念手册「治疗中枢神经系统退行性疾病药」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph15_q001","chapter":"第十五章 治疗中枢神经系统退行性疾病药","chapterIdx":14,"num":1},{"type":"D","stem":"名词解释：抗帕金森病药","answer":"用于缓解帕金森病症状的药物，分为拟多巴胺类药和中枢性抗胆碱药，前者补充脑内多巴胺或直接激动多巴胺受体。","rationale":"出自概念手册「治疗中枢神经系统退行性疾病药」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph15_q002","chapter":"第十五章 治疗中枢神经系统退行性疾病药","chapterIdx":14,"num":2},{"type":"D","stem":"名词解释：左旋多巴","answer":"多巴胺的前体，易透过血脑屏障，在脑内脱羧转变为多巴胺而发挥作用，对肌强直和运动迟缓疗效好、对震颤较差，是治疗帕金森病的主要药物。","rationale":"出自概念手册「治疗中枢神经系统退行性疾病药」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph15_q003","chapter":"第十五章 治疗中枢神经系统退行性疾病药","chapterIdx":14,"num":3},{"type":"D","stem":"名词解释：卡比多巴","answer":"外周多巴脱羧酶抑制剂，本身不易透过血脑屏障，可减少左旋多巴在外周的脱羧，增加其入脑量并减少外周不良反应。","rationale":"出自概念手册「治疗中枢神经系统退行性疾病药」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph15_q004","chapter":"第十五章 治疗中枢神经系统退行性疾病药","chapterIdx":14,"num":4},{"type":"D","stem":"名词解释：苄丝肼","answer":"外周多巴脱羧酶抑制剂，与左旋多巴按比例组成复方制剂，作用与卡比多巴相似，可增强疗效、减轻外周不良反应。","rationale":"出自概念手册「治疗中枢神经系统退行性疾病药」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph15_q005","chapter":"第十五章 治疗中枢神经系统退行性疾病药","chapterIdx":14,"num":5},{"type":"D","stem":"名词解释：溴隐亭","answer":"多巴胺D2受体激动药，可透过血脑屏障直接激动纹状体多巴胺受体，用于帕金森病、泌乳素瘤和肢端肥大症。","rationale":"出自概念手册「治疗中枢神经系统退行性疾病药」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph15_q006","chapter":"第十五章 治疗中枢神经系统退行性疾病药","chapterIdx":14,"num":6},{"type":"D","stem":"名词解释：普拉克索","answer":"选择性多巴胺D2、D3受体激动药，用于早期帕金森病及与左旋多巴联合治疗，可减少左旋多巴用量并减轻运动并发症。","rationale":"出自概念手册「治疗中枢神经系统退行性疾病药」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph15_q007","chapter":"第十五章 治疗中枢神经系统退行性疾病药","chapterIdx":14,"num":7},{"type":"D","stem":"名词解释：金刚烷胺","answer":"促进纹状体多巴胺释放并抑制其再摄取，兼有较弱的NMDA受体拮抗和中枢抗胆碱作用，用于轻症帕金森病，也曾用于甲型流感预防。","rationale":"出自概念手册「治疗中枢神经系统退行性疾病药」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph15_q008","chapter":"第十五章 治疗中枢神经系统退行性疾病药","chapterIdx":14,"num":8},{"type":"D","stem":"名词解释：司来吉兰","answer":"选择性单胺氧化酶B抑制剂，减少脑内多巴胺降解，用于早期帕金森病及左旋多巴的辅助治疗，可减轻症状波动。","rationale":"出自概念手册「治疗中枢神经系统退行性疾病药」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph15_q009","chapter":"第十五章 治疗中枢神经系统退行性疾病药","chapterIdx":14,"num":9},{"type":"D","stem":"名词解释：雷沙吉兰","answer":"第二代选择性单胺氧化酶B抑制剂，抑制作用强而持久，用于早期帕金森病及辅助治疗，代谢产物有苯丙胺样作用。","rationale":"出自概念手册「治疗中枢神经系统退行性疾病药」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph15_q010","chapter":"第十五章 治疗中枢神经系统退行性疾病药","chapterIdx":14,"num":10},{"type":"D","stem":"名词解释：恩他卡朋","answer":"外周儿茶酚氧位甲基转移酶抑制剂，减少左旋多巴在外周的代谢，延长其作用时间，主要用于改善剂末现象。","rationale":"出自概念手册「治疗中枢神经系统退行性疾病药」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph15_q011","chapter":"第十五章 治疗中枢神经系统退行性疾病药","chapterIdx":14,"num":11},{"type":"D","stem":"名词解释：苯海索","answer":"中枢性抗胆碱药，阻断纹状体胆碱受体，改善震颤和肌强直，用于震颤明显的帕金森病及抗精神病药所致的帕金森综合征。","rationale":"出自概念手册「治疗中枢神经系统退行性疾病药」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph15_q012","chapter":"第十五章 治疗中枢神经系统退行性疾病药","chapterIdx":14,"num":12},{"type":"D","stem":"名词解释：开-关现象","answer":"长期应用左旋多巴后出现的症状波动，患者突然由活动自如转为僵直不动，又突然恢复，与药物浓度和受体敏感性变化有关。","rationale":"出自概念手册「治疗中枢神经系统退行性疾病药」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph15_q013","chapter":"第十五章 治疗中枢神经系统退行性疾病药","chapterIdx":14,"num":13},{"type":"D","stem":"名词解释：剂末现象","answer":"长期应用左旋多巴后每次给药疗效维持时间缩短，症状在下次给药前明显加重，与多巴胺能神经元贮备减少有关。","rationale":"出自概念手册「治疗中枢神经系统退行性疾病药」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph15_q014","chapter":"第十五章 治疗中枢神经系统退行性疾病药","chapterIdx":14,"num":14},{"type":"D","stem":"名词解释：异动症","answer":"长期应用左旋多巴后出现的舞蹈样、手足徐动样不自主运动，多见于血药浓度高峰时，与纹状体多巴胺受体过度激动有关。","rationale":"出自概念手册「治疗中枢神经系统退行性疾病药」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph15_q015","chapter":"第十五章 治疗中枢神经系统退行性疾病药","chapterIdx":14,"num":15},{"type":"D","stem":"名词解释：神经保护药","answer":"通过抗氧化、改善线粒体功能、抗凋亡等途径延缓多巴胺能神经元变性的药物，如辅酶Q10、雷沙吉兰和维生素E，多作为辅助治疗。","rationale":"出自概念手册「治疗中枢神经系统退行性疾病药」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph15_q016","chapter":"第十五章 治疗中枢神经系统退行性疾病药","chapterIdx":14,"num":16},{"type":"D","stem":"名词解释：阿尔茨海默病（AD）","answer":"老年人最常见的进行性痴呆，以基底前脑胆碱能神经元退变、β-淀粉样蛋白沉积和神经原纤维缠结为特征，表现为记忆和认知功能进行性减退。","rationale":"出自概念手册「治疗中枢神经系统退行性疾病药」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph15_q017","chapter":"第十五章 治疗中枢神经系统退行性疾病药","chapterIdx":14,"num":17},{"type":"D","stem":"名词解释：胆碱酯酶抑制药","answer":"抑制脑内乙酰胆碱酯酶、减少乙酰胆碱水解而改善记忆和认知的药物，是治疗轻中度阿尔茨海默病的首选，包括多奈哌齐、加兰他敏和石杉碱甲。","rationale":"出自概念手册「治疗中枢神经系统退行性疾病药」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph15_q018","chapter":"第十五章 治疗中枢神经系统退行性疾病药","chapterIdx":14,"num":18},{"type":"D","stem":"名词解释：多奈哌齐","answer":"可逆性中枢乙酰胆碱酯酶抑制药，选择性高、半衰期长，每日给药一次，是治疗轻中度阿尔茨海默病的常用药物，不良反应以恶心、腹泻和失眠多见。","rationale":"出自概念手册「治疗中枢神经系统退行性疾病药」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph15_q019","chapter":"第十五章 治疗中枢神经系统退行性疾病药","chapterIdx":14,"num":19},{"type":"D","stem":"名词解释：石杉碱甲","answer":"我国从蛇足石杉中提取的高选择性可逆性胆碱酯酶抑制药，脂溶性高、易入脑，用于记忆障碍和阿尔茨海默病，不良反应较轻。","rationale":"出自概念手册「治疗中枢神经系统退行性疾病药」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph15_q021","chapter":"第十五章 治疗中枢神经系统退行性疾病药","chapterIdx":14,"num":21},{"type":"D","stem":"名词解释：美金刚","answer":"电压依赖性、非竞争性NMDA受体拮抗药，阻断病理状态下谷氨酸的兴奋性毒性而保护神经元，用于中重度阿尔茨海默病，可与胆碱酯酶抑制药合用。","rationale":"出自概念手册「治疗中枢神经系统退行性疾病药」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph15_q022","chapter":"第十五章 治疗中枢神经系统退行性疾病药","chapterIdx":14,"num":22},{"type":"D","stem":"名词解释：神经生长因子","answer":"促进胆碱能神经元存活与分化的大分子蛋白，因不易透过血脑屏障需脑室内给药，目前尚处研究阶段，未能广泛用于阿尔茨海默病。","rationale":"出自概念手册「治疗中枢神经系统退行性疾病药」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph15_q023","chapter":"第十五章 治疗中枢神经系统退行性疾病药","chapterIdx":14,"num":23},{"type":"S","stem":"简答题：为什么治疗帕金森病用左旋多巴而不用多巴胺？合用卡比多巴的理由是什么？","answer":"①多巴胺难以透过血脑屏障，直接给药不能补充纹状体多巴胺的不足，故治疗无效。②左旋多巴是多巴胺的前体，可透过血脑屏障进入脑组织，在纹状体经多巴脱羧酶脱羧生成多巴胺，补充纹状体多巴胺的不足，从而改善运动障碍和肌强直、减轻震颤。③单用左旋多巴时95%以上在外周脱羧生成多巴胺，仅1%～3%的原形进入脑内，且外周生成的多巴胺引起恶心、呕吐、心律失常、直立性低血压等不良反应。④卡比多巴、苄丝肼抑制外周左旋芳香氨基酸脱羧酶且不易透过血脑屏障，可减少左旋多巴在外周的脱羧，使较多左旋多巴到达纹状体，从而增强疗效、减少左旋多巴用量、明显减轻其对心脏的毒性作用并更快达到有效治疗浓度。⑤两药组成复方制剂（心宁美、美多巴）。","rationale":"采分点为“多巴胺不入脑—左旋多巴为前体经多巴脱羧酶转化为多巴胺—外周脱羧致仅1%～3%入脑—脱羧酶抑制剂的作用与复方制剂”。易错是漏掉“仅1%～3%进入脑内”这一关键数字和“不易透过血脑屏障”这一前提。","id":"rph15_q024","chapter":"第十五章 治疗中枢神经系统退行性疾病药","chapterIdx":14,"num":24},{"type":"F","stem":"填空题：氯丙嗪等抗精神病药所致的帕金森综合征宜用______治疗，因其能阻断中枢______受体，恢复多巴胺与乙酰胆碱的功能平衡。","answer":"①中枢性抗胆碱药（苯海索或氢溴酸东莨菪碱）②M胆碱","rationale":"药源性帕金森综合征由阻断黑质-纹状体D2受体、胆碱能功能相对占优所致，故用中枢抗胆碱药；而帕金森病本身的震颤也以苯海索等中枢抗胆碱药改善震颤效果较好。","id":"rph15_q025","chapter":"第十五章 治疗中枢神经系统退行性疾病药","chapterIdx":14,"num":25},{"type":"F","stem":"填空题：帕金森病的主要病理改变是______多巴胺能神经元变性死亡，纹状体内多巴胺减少使多巴胺与______两种递质功能失衡。","answer":"①黑质（致密区）②乙酰胆碱（ACh）","rationale":"纹状体内多巴胺为抑制性递质（使骨骼肌张力降低）、乙酰胆碱为兴奋性递质（使张力升高），多巴胺不足则胆碱能相对亢进，故治疗原则是恢复两种递质的平衡。","id":"rph15_q026","chapter":"第十五章 治疗中枢神经系统退行性疾病药","chapterIdx":14,"num":26},{"type":"T","stem":"判断题：左旋多巴对吩噻嗪类抗精神病药引起的锥体外系症状有效，可作为首选。","options":{"A":"正确","B":"错误"},"answer":["B"],"rationale":"左旋多巴对吩噻嗪类所致锥体外系症状无效（因D2受体已被阻断），此时应选用中枢抗胆碱药苯海索。","id":"rph15_q027","chapter":"第十五章 治疗中枢神经系统退行性疾病药","chapterIdx":14,"num":27},{"type":"T","stem":"判断题：司来吉兰是MAO-B抑制剂，可抑制纹状体内多巴胺的降解，从而减少左旋多巴剂量并减轻其“开-关现象”。","options":{"A":"正确","B":"错误"},"answer":["A"],"rationale":"MAO-B主要分布于中枢，司来吉兰选择性抑制MAO-B，并具抗氧化作用、阻滞多巴胺氧化应激中自由基形成，可保护黑质多巴胺能神经元。","id":"rph15_q028","chapter":"第十五章 治疗中枢神经系统退行性疾病药","chapterIdx":14,"num":28}]},{"title":"第十六章 抗精神失常药","questions":[{"type":"D","stem":"名词解释：抗精神失常药","answer":"用于治疗精神分裂症、抑郁症、躁狂症和焦虑症等精神障碍的药物，包括抗精神病药、抗抑郁药、抗躁狂药和抗焦虑药。","rationale":"出自概念手册「抗精神失常药」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph16_q001","chapter":"第十六章 抗精神失常药","chapterIdx":15,"num":1},{"type":"D","stem":"名词解释：抗精神病药","answer":"又称神经阻滞剂，能阻断中枢多巴胺受体，消除幻觉、妄想等阳性症状，主要用于精神分裂症，按化学结构分为吩噻嗪类、丁酰苯类等。","rationale":"出自概念手册「抗精神失常药」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph16_q002","chapter":"第十六章 抗精神失常药","chapterIdx":15,"num":2},{"type":"D","stem":"名词解释：氯丙嗪","answer":"吩噻嗪类的代表药，主要阻断多巴胺D2受体，兼阻断α、M、H1和5-羟色胺受体。具有抗精神病、镇吐、调节体温和影响内分泌等作用。","rationale":"出自概念手册「抗精神失常药」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph16_q003","chapter":"第十六章 抗精神失常药","chapterIdx":15,"num":3},{"type":"D","stem":"名词解释：吩噻嗪类","answer":"具有三环结构的抗精神病药，包括氯丙嗪、奋乃静、三氟拉嗪和硫利达嗪。侧链不同使抗精神病作用和锥体外系反应强弱不同。","rationale":"出自概念手册「抗精神失常药」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph16_q004","chapter":"第十六章 抗精神失常药","chapterIdx":15,"num":4},{"type":"D","stem":"名词解释：锥体外系反应","answer":"长期使用抗精神病药阻断黑质-纹状体多巴胺受体，使胆碱能神经功能相对亢进所致，表现为帕金森综合征、急性肌张力障碍和静坐不能。","rationale":"出自概念手册「抗精神失常药」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph16_q005","chapter":"第十六章 抗精神失常药","chapterIdx":15,"num":5},{"type":"D","stem":"名词解释：迟发性运动障碍","answer":"长期使用抗精神病药后出现的锥体外系反应，表现为口面部不自主运动、肢体舞蹈样动作，停药后不易消失，抗胆碱药可使其加重。","rationale":"出自概念手册「抗精神失常药」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph16_q006","chapter":"第十六章 抗精神失常药","chapterIdx":15,"num":6},{"type":"D","stem":"名词解释：氯氮平","answer":"非典型抗精神病药，阻断多巴胺D4和5-羟色胺受体，抗精神病作用强而锥体外系反应少，但可致粒细胞减少，需定期监测血象。","rationale":"出自概念手册「抗精神失常药」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph16_q007","chapter":"第十六章 抗精神失常药","chapterIdx":15,"num":7},{"type":"D","stem":"名词解释：利培酮","answer":"非典型抗精神病药，阻断5-羟色胺2A和多巴胺D2受体，对阳性症状和阴性症状均有效，锥体外系反应与剂量相关。","rationale":"出自概念手册「抗精神失常药」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph16_q008","chapter":"第十六章 抗精神失常药","chapterIdx":15,"num":8},{"type":"D","stem":"名词解释：氟哌啶醇","answer":"丁酰苯类抗精神病药，阻断多巴胺D2受体作用强，抗精神病和抗躁狂作用显著，镇吐作用强，锥体外系反应明显。","rationale":"出自概念手册「抗精神失常药」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph16_q009","chapter":"第十六章 抗精神失常药","chapterIdx":15,"num":9},{"type":"D","stem":"名词解释：冬眠合剂","answer":"由氯丙嗪、异丙嗪和哌替啶组成的复方制剂，用于人工冬眠疗法，使机体处于低温、代谢降低的保护性抑制状态。","rationale":"出自概念手册「抗精神失常药」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph16_q010","chapter":"第十六章 抗精神失常药","chapterIdx":15,"num":10},{"type":"D","stem":"名词解释：抗抑郁药","answer":"用于治疗抑郁症和抑郁状态的药物，包括三环类、单胺氧化酶抑制剂、选择性5-羟色胺再摄取抑制剂等，作用基础是提高突触间隙单胺递质浓度。","rationale":"出自概念手册「抗精神失常药」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph16_q011","chapter":"第十六章 抗精神失常药","chapterIdx":15,"num":11},{"type":"D","stem":"名词解释：三环类抗抑郁药","answer":"具有三环结构的抗抑郁药，如丙米嗪、阿米替林，通过抑制突触前膜对去甲肾上腺素和5-羟色胺的再摄取而发挥作用，抗胆碱作用明显。","rationale":"出自概念手册「抗精神失常药」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph16_q012","chapter":"第十六章 抗精神失常药","chapterIdx":15,"num":12},{"type":"D","stem":"名词解释：选择性5-羟色胺再摄取抑制剂","answer":"简称SSRIs，如氟西汀、帕罗西汀，选择性抑制突触前膜对5-羟色胺的再摄取，疗效肯定，心血管和抗胆碱不良反应少，是常用的一线抗抑郁药。","rationale":"出自概念手册「抗精神失常药」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph16_q013","chapter":"第十六章 抗精神失常药","chapterIdx":15,"num":13},{"type":"D","stem":"名词解释：碳酸锂","answer":"治疗躁狂症的首选药，可抑制去甲肾上腺素释放、影响肌醇磷酸代谢而稳定情绪。治疗窗窄，用药期间需监测血锂浓度。","rationale":"出自概念手册「抗精神失常药」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph16_q014","chapter":"第十六章 抗精神失常药","chapterIdx":15,"num":14},{"type":"D","stem":"名词解释：抗焦虑药","answer":"用于缓解焦虑、紧张和恐惧情绪的药物，主要有苯二氮䓬类、丁螺环酮和坦度螺酮等，其中丁螺环酮无镇静和明显依赖性。","rationale":"出自概念手册「抗精神失常药」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph16_q015","chapter":"第十六章 抗精神失常药","chapterIdx":15,"num":15},{"type":"D","stem":"名词解释：丁螺环酮","answer":"非苯二氮䓬类抗焦虑药，激动5-羟色胺1A受体，抗焦虑作用起效较慢，无镇静催眠和肌肉松弛作用，依赖性小。","rationale":"出自概念手册「抗精神失常药」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph16_q016","chapter":"第十六章 抗精神失常药","chapterIdx":15,"num":16},{"type":"S","stem":"简答题：试述氯丙嗪的药理作用与临床应用。","answer":"①抗精神病作用：阻断中脑-边缘系统和中脑-皮质系统的D2受体，用药后幻觉、妄想消失，情绪安定，主要用于Ⅰ型精神分裂症（对Ⅱ型无效甚至加重），急性患者疗效显著。②镇吐作用：小剂量阻断延髓催吐化学感受区D2受体，大剂量直接抑制呕吐中枢，对多种药物和疾病所致呕吐有效，但不能对抗前庭刺激（晕动病）引起的呕吐。③对体温调节的影响：抑制下丘脑体温调节中枢，既降低发热机体体温也降低正常体温，降温作用随环境温度变化、与物理降温有协同作用，用于低温麻醉与人工冬眠（氯丙嗪＋哌替啶＋异丙嗪）。④对自主神经系统：阻断α受体致血管扩张、血压下降和直立性低血压，阻断M受体致口干、便秘、视力模糊。⑤对内分泌系统：阻断结节-漏斗通路D2受体，增加催乳素分泌，抑制促性腺激素、ACTH和生长激素的分泌。","rationale":"采分点按“中枢（抗精神病、镇吐、体温调节）—自主神经—内分泌”三层及对应应用作答。易错是漏掉“对晕动病呕吐无效”“可降低正常体温”两条限制性表述。","id":"rph16_q017","chapter":"第十六章 抗精神失常药","chapterIdx":15,"num":17},{"type":"F","stem":"填空题：长期应用氯丙嗪常见而严重的不良反应是______，原因是阻断了______通路的D2受体，可用______缓解。","answer":"①锥体外系反应 ②黑质-纹状体 ③中枢性抗胆碱药（苯海索/安坦、氢溴酸东莨菪碱）","rationale":"锥体外系反应有帕金森综合征（最常见）、急性肌张力障碍、静坐不能三种急性表现及迟发性运动障碍；前三者可用中枢抗胆碱药缓解，迟发性运动障碍停药后不消失。","id":"rph16_q018","chapter":"第十六章 抗精神失常药","chapterIdx":15,"num":18},{"type":"F","stem":"填空题：能翻转肾上腺素升压作用的药物有______和______，二者均阻断了血管上的α受体。","answer":"①氯丙嗪 ②酚妥拉明","rationale":"α受体被阻断后，肾上腺素只能表现β2受体激动的血管舒张效应，故升压作用翻转为降压；这也是氯丙嗪中毒所致低血压不能用肾上腺素纠正的原因。","id":"rph16_q019","chapter":"第十六章 抗精神失常药","chapterIdx":15,"num":19},{"type":"T","stem":"判断题：氯丙嗪镇吐作用强，对晕动病引起的呕吐也有效。","options":{"A":"正确","B":"错误"},"answer":["B"],"rationale":"氯丙嗪阻断延髓催吐化学感受区D2受体并直接抑制呕吐中枢，对多种药物和疾病所致呕吐有效，但不能对抗前庭刺激引起的呕吐，故对晕动病无效（应用东莨菪碱、苯海拉明等）。","id":"rph16_q020","chapter":"第十六章 抗精神失常药","chapterIdx":15,"num":20},{"type":"T","stem":"判断题：碳酸锂治疗指数低、安全范围窄，血药浓度超过1.6mmol/L即可出现中毒，且中毒无特效拮抗药。","options":{"A":"正确","B":"错误"},"answer":["A"],"rationale":"碳酸锂最适血药浓度为0.8～1.5mmol/L，升至1.6mmol/L即可中毒，须立即停药并对症治疗，因其无特效拮抗药，故临床必须监测血锂浓度。","id":"rph16_q021","chapter":"第十六章 抗精神失常药","chapterIdx":15,"num":21}]},{"title":"第十七章 镇痛药","questions":[{"type":"D","stem":"名词解释：镇痛药","answer":"能选择性缓解或消除疼痛，同时减轻因疼痛引起的紧张、焦虑等情绪反应的药物，按作用机制分为阿片类镇痛药和非甾体抗炎药等。","rationale":"出自概念手册「镇痛药」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph17_q001","chapter":"第十七章 镇痛药","chapterIdx":16,"num":1},{"type":"F","stem":"填空题：能选择性缓解或消除疼痛，同时减轻因疼痛引起的紧张、焦虑等情绪反应的药物，按作用机制分为阿片类______和非甾体抗炎药等。","answer":"镇痛药","rationale":"出自概念手册「镇痛药」核心概念：镇痛药。","id":"rph17_q002","chapter":"第十七章 镇痛药","chapterIdx":16,"num":2},{"type":"D","stem":"名词解释：阿片","answer":"罂粟未成熟蒴果浆汁的干燥物，含吗啡、可待因等生物碱，是阿片类镇痛药的来源，也是我国实行特殊管理的一类麻醉药品。","rationale":"出自概念手册「镇痛药」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph17_q003","chapter":"第十七章 镇痛药","chapterIdx":16,"num":3},{"type":"F","stem":"填空题：罂粟未成熟蒴果浆汁的干燥物，含吗啡、可待因等生物碱，是______类镇痛药的来源，也是我国实行特殊管理的一类麻醉药品。","answer":"阿片","rationale":"出自概念手册「镇痛药」核心概念：阿片。","id":"rph17_q004","chapter":"第十七章 镇痛药","chapterIdx":16,"num":4},{"type":"D","stem":"名词解释：阿片受体","answer":"中枢神经系统内与阿片类物质特异性结合的受体，分为μ、κ、δ三型，激动后产生镇痛、镇静、呼吸抑制和欣快等效应。","rationale":"出自概念手册「镇痛药」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph17_q005","chapter":"第十七章 镇痛药","chapterIdx":16,"num":5},{"type":"D","stem":"名词解释：阿片类镇痛药","answer":"又称麻醉性镇痛药，通过激动中枢阿片受体产生镇痛作用，包括吗啡、哌替啶、芬太尼等，长期使用可产生依赖性。","rationale":"出自概念手册「镇痛药」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph17_q006","chapter":"第十七章 镇痛药","chapterIdx":16,"num":6},{"type":"D","stem":"名词解释：吗啡","answer":"阿片受体激动药的代表，镇痛作用强大，兼有镇静、镇咳、抑制呼吸、缩瞳和抑制胃肠蠕动等作用，用于急性锐痛和心源性哮喘。","rationale":"出自概念手册「镇痛药」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph17_q007","chapter":"第十七章 镇痛药","chapterIdx":16,"num":7},{"type":"D","stem":"名词解释：哌替啶","answer":"人工合成的阿片受体激动药，镇痛强度约为吗啡的十分之一，作用时间较短，用于急性锐痛、心源性哮喘、麻醉前给药和人工冬眠。","rationale":"出自概念手册「镇痛药」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph17_q008","chapter":"第十七章 镇痛药","chapterIdx":16,"num":8},{"type":"D","stem":"名词解释：可待因","answer":"阿片生物碱，镇痛作用弱，镇咳作用强，主要用于中等程度疼痛和干咳，成瘾性较吗啡小，是目前常用的镇咳药之一。","rationale":"出自概念手册「镇痛药」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph17_q009","chapter":"第十七章 镇痛药","chapterIdx":16,"num":9},{"type":"D","stem":"名词解释：芬太尼","answer":"强效阿片受体激动药，镇痛作用约为吗啡的一百倍，起效快、作用短，用于麻醉辅助和镇痛，透皮贴剂可用于慢性癌痛。","rationale":"出自概念手册「镇痛药」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph17_q010","chapter":"第十七章 镇痛药","chapterIdx":16,"num":10},{"type":"D","stem":"名词解释：美沙酮","answer":"人工合成的阿片受体激动药，口服有效、作用持久，用于慢性疼痛和阿片类成瘾的替代治疗，戒断症状较轻，是目前脱毒治疗的常用药。","rationale":"出自概念手册「镇痛药」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph17_q011","chapter":"第十七章 镇痛药","chapterIdx":16,"num":11},{"type":"D","stem":"名词解释：喷他佐辛","answer":"阿片受体激动-拮抗药，激动κ受体并部分拮抗μ受体，镇痛作用较弱，成瘾性小，不按麻醉药品管理，但可诱发已用阿片类者的戒断症状。","rationale":"出自概念手册「镇痛药」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph17_q012","chapter":"第十七章 镇痛药","chapterIdx":16,"num":12},{"type":"D","stem":"名词解释：纳洛酮","answer":"阿片受体竞争性拮抗药，能迅速逆转阿片类药物的镇痛、呼吸抑制和昏迷，用于阿片类急性中毒的解救。","rationale":"出自概念手册「镇痛药」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph17_q013","chapter":"第十七章 镇痛药","chapterIdx":16,"num":13},{"type":"D","stem":"名词解释：纳曲酮","answer":"阿片受体拮抗药，口服有效、作用持久，用于阿片类成瘾脱毒后的维持治疗和酒精依赖的辅助治疗。","rationale":"出自概念手册「镇痛药」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph17_q014","chapter":"第十七章 镇痛药","chapterIdx":16,"num":14},{"type":"D","stem":"名词解释：麻醉药品","answer":"连续使用易产生瘾癖性、国家对其实行特殊管理的药品，如吗啡、哌替啶、芬太尼等，须凭麻醉药品专用处方按规定使用，不得滥用。","rationale":"出自概念手册「镇痛药」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph17_q015","chapter":"第十七章 镇痛药","chapterIdx":16,"num":15},{"type":"F","stem":"填空题：连续使用易产生瘾癖性、国家对其实行特殊管理的药品，如吗啡、哌替啶、芬太尼等，须凭______专用处方按规定使用，不得滥用。","answer":"麻醉药品","rationale":"出自概念手册「镇痛药」核心概念：麻醉药品。","id":"rph17_q016","chapter":"第十七章 镇痛药","chapterIdx":16,"num":16},{"type":"D","stem":"名词解释：心源性哮喘","answer":"左心衰竭引起急性肺水肿而出现的呼吸困难，表现为气促、端坐呼吸和哮鸣音，吗啡是重要的治疗药物之一，而支气管哮喘则禁用吗啡。","rationale":"出自概念手册「镇痛药」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph17_q017","chapter":"第十七章 镇痛药","chapterIdx":16,"num":17},{"type":"D","stem":"名词解释：阿片受体激动-拮抗药","answer":"对一种阿片受体亚型起激动作用、对另一种起拮抗作用的药物，如喷他佐辛、丁丙诺啡，成瘾性较小但可诱发戒断症状。","rationale":"出自概念手册「镇痛药」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph17_q018","chapter":"第十七章 镇痛药","chapterIdx":16,"num":18},{"type":"S","stem":"简答题：吗啡为什么能用于心源性哮喘的辅助治疗？","answer":"①镇静作用：消除患者烦躁、恐惧情绪，减弱交感神经兴奋带来的心脏负担；②降低呼吸中枢对CO2的敏感性，缓解急促浅表的呼吸，减轻窒息感；③扩张血管、降低外周阻力，减少回心血量、减轻心脏前负荷，有利于肺水肿消退。","rationale":"采分点为镇静、抑制呼吸中枢对CO2的反应、扩血管降负荷三条；吗啡只是心源性哮喘的辅助治疗，支气管哮喘则禁用。","id":"rph17_q019","chapter":"第十七章 镇痛药","chapterIdx":16,"num":19},{"type":"F","stem":"填空题：吗啡急性中毒的典型表现是昏迷、______呼吸抑制和______瞳孔，致死的主要原因是______。","answer":"①深度 ②针尖样 ③呼吸麻痹","rationale":"急性中毒三联征为昏迷、深度呼吸抑制、针尖样瞳孔；呼吸麻痹是致死主因，抢救用纳洛酮。","id":"rph17_q020","chapter":"第十七章 镇痛药","chapterIdx":16,"num":20},{"type":"F","stem":"填空题：喷他佐辛是阿片受体的______药，主要激动______受体并对μ受体有轻度拮抗作用，成瘾性较小。","answer":"①部分激动 ②κ","rationale":"喷他佐辛激动κ受体、轻度拮抗μ受体，属部分激动药，故欣快感不明显、成瘾性小，用于慢性疼痛。","id":"rph17_q021","chapter":"第十七章 镇痛药","chapterIdx":16,"num":21},{"type":"T","stem":"判断题：与吗啡相比，哌替啶无缩瞳作用，较少引起便秘和尿潴留，也不延长产程。","options":{"A":"正确","B":"错误"},"answer":["A"],"rationale":"哌替啶主要激动μ受体，但无缩瞳和中枢镇咳作用，对胃肠及子宫平滑肌影响小，故便秘、尿潴留少且不延长产程。","id":"rph17_q022","chapter":"第十七章 镇痛药","chapterIdx":16,"num":22},{"type":"T","stem":"判断题：可待因的镇痛作用强于吗啡，临床常用于缓解各种剧痛。","options":{"A":"正确","B":"错误"},"answer":["B"],"rationale":"可待因镇痛作用仅为吗啡的1/10~1/12，用于中等程度疼痛；其镇咳作用约为吗啡的1/4，多用于无痰干咳。","id":"rph17_q023","chapter":"第十七章 镇痛药","chapterIdx":16,"num":23}]},{"title":"第十八章 中枢兴奋药","questions":[{"type":"D","stem":"名词解释：中枢兴奋药","answer":"能提高中枢神经系统功能活动的一类药物，按主要作用部位分为兴奋大脑皮质、兴奋延髓呼吸中枢和兴奋脊髓三类，另有促脑功能恢复药。","rationale":"出自概念手册「中枢兴奋药」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph18_q001","chapter":"第十八章 中枢兴奋药","chapterIdx":17,"num":1},{"type":"D","stem":"名词解释：咖啡因","answer":"甲基黄嘌呤类中枢兴奋药，治疗量阻断腺苷A1、A2受体，大剂量抑制磷酸二酯酶并促进儿茶酚胺释放，小剂量兴奋大脑皮质，较大剂量兴奋延髓，中毒量兴奋脊髓。","rationale":"出自概念手册「中枢兴奋药」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph18_q002","chapter":"第十八章 中枢兴奋药","chapterIdx":17,"num":2},{"type":"D","stem":"名词解释：茶碱","answer":"甲基黄嘌呤类，松弛支气管平滑肌并兴奋呼吸中枢和心脏，安全范围窄，主要用于支气管哮喘和慢性阻塞性肺疾病。","rationale":"出自概念手册「中枢兴奋药」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph18_q003","chapter":"第十八章 中枢兴奋药","chapterIdx":17,"num":3},{"type":"D","stem":"名词解释：哌甲酯（利他林）","answer":"哌啶类精神兴奋药，促进脑内多巴胺和去甲肾上腺素释放并抑制其再摄取，用于儿童注意缺陷多动障碍和发作性睡病，有滥用倾向。","rationale":"出自概念手册「中枢兴奋药」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph18_q004","chapter":"第十八章 中枢兴奋药","chapterIdx":17,"num":4},{"type":"D","stem":"名词解释：尼可刹米（可拉明）","answer":"主要直接兴奋延髓呼吸中枢，作用温和而短暂，用于中枢性呼吸抑制，过量可致血压升高、心动过速、肌震颤和惊厥。","rationale":"出自概念手册「中枢兴奋药」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph18_q005","chapter":"第十八章 中枢兴奋药","chapterIdx":17,"num":5},{"type":"D","stem":"名词解释：洛贝林（山梗菜碱）","answer":"激动颈动脉体和主动脉体化学感受器，反射性兴奋呼吸中枢，作用快而弱、维持时间短，安全范围较大，用于新生儿窒息和一氧化碳中毒。","rationale":"出自概念手册「中枢兴奋药」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph18_q006","chapter":"第十八章 中枢兴奋药","chapterIdx":17,"num":6},{"type":"D","stem":"名词解释：二甲弗林（回苏灵）","answer":"直接兴奋延髓呼吸中枢，作用强而快，用于各种原因的中枢性呼吸抑制，安全范围窄，易致惊厥。","rationale":"出自概念手册「中枢兴奋药」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph18_q007","chapter":"第十八章 中枢兴奋药","chapterIdx":17,"num":7},{"type":"D","stem":"名词解释：贝美格（美解眠）","answer":"主要兴奋延髓呼吸中枢和血管运动中枢，作用迅速而短暂，主要用于巴比妥类等催眠药中毒的解救。","rationale":"出自概念手册「中枢兴奋药」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph18_q008","chapter":"第十八章 中枢兴奋药","chapterIdx":17,"num":8},{"type":"D","stem":"名词解释：多沙普仑","answer":"直接兴奋延髓呼吸中枢并通过化学感受器反射性兴奋呼吸，作用较强，用于全身麻醉后及中枢抑制药引起的呼吸抑制。","rationale":"出自概念手册「中枢兴奋药」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph18_q009","chapter":"第十八章 中枢兴奋药","chapterIdx":17,"num":9},{"type":"D","stem":"名词解释：士的宁（番木鳖碱）","answer":"选择性阻断脊髓抑制性中间神经元即Renshaw细胞的甘氨酸受体，取消抑制而使运动神经元兴奋性增高，安全范围极窄，中毒致强直性惊厥。","rationale":"出自概念手册「中枢兴奋药」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph18_q010","chapter":"第十八章 中枢兴奋药","chapterIdx":17,"num":10},{"type":"D","stem":"名词解释：一叶萩碱","answer":"作用与士的宁相似而较弱，毒性较小，曾用于面神经麻痹、小儿麻痹后遗症和神经衰弱。","rationale":"出自概念手册「中枢兴奋药」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph18_q011","chapter":"第十八章 中枢兴奋药","chapterIdx":17,"num":11},{"type":"D","stem":"名词解释：吡拉西坦","answer":"γ-氨基丁酸的环状衍生物，促进脑内ATP和蛋白质合成、增加乙酰胆碱合成与脑血流，用于脑外伤、脑血管病后的记忆减退。","rationale":"出自概念手册「中枢兴奋药」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph18_q012","chapter":"第十八章 中枢兴奋药","chapterIdx":17,"num":12},{"type":"D","stem":"名词解释：奥拉西坦","answer":"吡拉西坦的同类药，作用较强，用于脑损伤及脑血管病所致的记忆与智能障碍。","rationale":"出自概念手册「中枢兴奋药」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph18_q013","chapter":"第十八章 中枢兴奋药","chapterIdx":17,"num":13},{"type":"D","stem":"名词解释：甲氯芬酯（氯酯醒）","answer":"促进脑细胞氧化还原代谢的药物，用于脑外伤后昏迷、意识障碍及儿童精神发育迟缓。","rationale":"出自概念手册「中枢兴奋药」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph18_q014","chapter":"第十八章 中枢兴奋药","chapterIdx":17,"num":14},{"type":"D","stem":"名词解释：胞磷胆碱","answer":"核苷衍生物，促进卵磷脂合成、稳定细胞膜并改善脑能量代谢，用于脑外伤和脑手术后意识障碍。","rationale":"出自概念手册「中枢兴奋药」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph18_q015","chapter":"第十八章 中枢兴奋药","chapterIdx":17,"num":15},{"type":"D","stem":"名词解释：促脑功能恢复药","answer":"通过改善脑代谢、增加脑血流或促进神经递质合成而促进脑功能恢复的药物，如吡拉西坦、甲氯芬酯和胞磷胆碱，作用温和。","rationale":"出自概念手册「中枢兴奋药」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph18_q016","chapter":"第十八章 中枢兴奋药","chapterIdx":17,"num":16},{"type":"D","stem":"名词解释：中枢兴奋药中毒","answer":"剂量过大或反复用药使中枢过度兴奋，先出现躁动、肌震颤、反射亢进，进而发生惊厥，惊厥后转入抑制甚至呼吸循环衰竭。","rationale":"出自概念手册「中枢兴奋药」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph18_q017","chapter":"第十八章 中枢兴奋药","chapterIdx":17,"num":17},{"type":"S","stem":"简答题：应用呼吸兴奋药应遵循哪些原则和注意事项？","answer":"①仅用于中枢性呼吸抑制，对呼吸肌麻痹、气道阻塞、肺水肿等无效且有害；②用药前必须保持气道通畅、充分供氧，并准备人工呼吸和机械通气；③剂量不宜过大，密切观察惊厥先兆，必要时减量或间歇给药；④呼吸兴奋药不能代替人工呼吸和病因治疗，只是综合抢救措施之一。","rationale":"四个采分点：适应证、保持气道通畅、控制剂量防惊厥、不替代人工呼吸；易错点是把它当作通气不足的首选措施。","id":"rph18_q018","chapter":"第十八章 中枢兴奋药","chapterIdx":17,"num":18},{"type":"F","stem":"填空题：洛贝林通过激动______和主动脉体的化学感受器，反射性兴奋呼吸中枢，作用快而弱，主要用于______和一氧化碳中毒。","answer":"①颈动脉体 ②新生儿窒息","rationale":"洛贝林属反射性呼吸兴奋药，安全范围较大、不易惊厥；尼可刹米、二甲弗林则直接兴奋延髓呼吸中枢。","id":"rph18_q019","chapter":"第十八章 中枢兴奋药","chapterIdx":17,"num":19},{"type":"F","stem":"填空题：士的宁选择性阻断脊髓Renshaw细胞的______受体，取消抑制性传递，中毒时表现为______惊厥，安全范围极窄。","answer":"①甘氨酸 ②强直性","rationale":"Renshaw细胞是脊髓抑制性中间神经元，以甘氨酸为递质；士的宁阻断其受体后反射亢进，导致强直性惊厥，现临床少用。","id":"rph18_q020","chapter":"第十八章 中枢兴奋药","chapterIdx":17,"num":20},{"type":"T","stem":"判断题：尼可刹米主要直接兴奋延髓呼吸中枢，作用温和而短暂，过量可致血压升高、肌震颤甚至惊厥。","options":{"A":"正确","B":"错误"},"answer":["A"],"rationale":"尼可刹米属直接兴奋呼吸中枢的药物，作用温和短暂、可静脉注射；过量兴奋脊髓而致肌震颤和惊厥，应及时减量。","id":"rph18_q021","chapter":"第十八章 中枢兴奋药","chapterIdx":17,"num":21},{"type":"T","stem":"判断题：咖啡因治疗量的中枢兴奋作用主要通过抑制磷酸二酯酶实现。","options":{"A":"正确","B":"错误"},"answer":["B"],"rationale":"治疗量咖啡因主要阻断腺苷A1、A2受体，大剂量才抑制磷酸二酯酶并促进儿茶酚胺释放；效应随剂量呈皮质—延髓—脊髓递进。","id":"rph18_q022","chapter":"第十八章 中枢兴奋药","chapterIdx":17,"num":22}]},{"title":"第十九章 解热镇痛抗炎药与抗痛风药","questions":[{"type":"D","stem":"名词解释：解热镇痛抗炎药（NSAIDs）","answer":"通过抑制环氧酶、减少前列腺素合成而发挥解热、镇痛、抗炎作用的药物，又称非甾体抗炎药，包括水杨酸类、苯胺类、吡唑酮类及其他有机酸类。","rationale":"出自概念手册「解热镇痛抗炎药与抗痛风药」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph19_q001","chapter":"第十九章 解热镇痛抗炎药与抗痛风药","chapterIdx":18,"num":1},{"type":"D","stem":"名词解释：环氧酶（COX）","answer":"即前列腺素内过氧化物合成酶，催化花生四烯酸生成前列腺素和血栓素A2的限速酶，有COX-1与COX-2两种同工酶，是本类药物的作用靶点。","rationale":"出自概念手册「解热镇痛抗炎药与抗痛风药」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph19_q002","chapter":"第十九章 解热镇痛抗炎药与抗痛风药","chapterIdx":18,"num":2},{"type":"D","stem":"名词解释：环氧酶-1与环氧酶-2","answer":"COX-1为结构型，分布于胃黏膜、肾和血小板，维持生理性前列腺素生成；COX-2为诱导型，由炎症因子诱导产生；选择性抑制COX-2可减少胃肠损伤但增加心血管风险。","rationale":"出自概念手册「解热镇痛抗炎药与抗痛风药」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph19_q003","chapter":"第十九章 解热镇痛抗炎药与抗痛风药","chapterIdx":18,"num":3},{"type":"D","stem":"名词解释：前列腺素（PG）","answer":"由花生四烯酸经环氧酶代谢生成的局部活性物质，参与发热、疼痛、炎症和胃黏膜保护，其中PGE2和PGI2具有致炎、致痛和扩张血管作用。","rationale":"出自概念手册「解热镇痛抗炎药与抗痛风药」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph19_q004","chapter":"第十九章 解热镇痛抗炎药与抗痛风药","chapterIdx":18,"num":4},{"type":"D","stem":"名词解释：血栓素A2（TXA2）","answer":"血小板内由环氧酶-1催化生成的前列腺素类物质，可强烈收缩血管并促进血小板聚集，小剂量阿司匹林不可逆抑制其生成而发挥抗血栓作用。","rationale":"出自概念手册「解热镇痛抗炎药与抗痛风药」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph19_q005","chapter":"第十九章 解热镇痛抗炎药与抗痛风药","chapterIdx":18,"num":5},{"type":"D","stem":"名词解释：水杨酸反应","answer":"水杨酸类大剂量或长期使用时的中毒表现，可见恶心、呕吐、眩晕、耳鸣、重听和头痛，重者精神错乱和酸碱失衡，需减量停药并碱化尿液促排。","rationale":"出自概念手册「解热镇痛抗炎药与抗痛风药」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph19_q006","chapter":"第十九章 解热镇痛抗炎药与抗痛风药","chapterIdx":18,"num":6},{"type":"D","stem":"名词解释：阿司匹林哮喘","answer":"部分哮喘患者服用阿司匹林或其他解热镇痛抗炎药后诱发的支气管痉挛，与抑制环氧酶使脂氧酶途径白三烯生成增多有关，属药物不良反应而非免疫性过敏。","rationale":"出自概念手册「解热镇痛抗炎药与抗痛风药」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph19_q007","chapter":"第十九章 解热镇痛抗炎药与抗痛风药","chapterIdx":18,"num":7},{"type":"D","stem":"名词解释：瑞夷综合征","answer":"儿童或青少年在病毒感染期间使用阿司匹林后可发生的急性脑病伴肝脏脂肪变性，病情凶险、病死率高，故病毒感染发热的患儿不宜使用阿司匹林。","rationale":"出自概念手册「解热镇痛抗炎药与抗痛风药」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph19_q008","chapter":"第十九章 解热镇痛抗炎药与抗痛风药","chapterIdx":18,"num":8},{"type":"D","stem":"名词解释：阿司匹林（乙酰水杨酸）","answer":"水杨酸类的代表药，口服后迅速水解为水杨酸，具有解热、镇痛、抗炎抗风湿和抗血小板聚集作用，是风湿热、类风湿关节炎及心脑血管疾病防治的基础用药。","rationale":"出自概念手册「解热镇痛抗炎药与抗痛风药」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph19_q009","chapter":"第十九章 解热镇痛抗炎药与抗痛风药","chapterIdx":18,"num":9},{"type":"D","stem":"名词解释：对乙酰氨基酚（醋氨酚）","answer":"苯胺类解热镇痛药，主要抑制中枢前列腺素合成，解热镇痛作用与阿司匹林相当而抗炎作用很弱，不引起胃肠出血，过量可致肝坏死，可用乙酰半胱氨酸解救。","rationale":"出自概念手册「解热镇痛抗炎药与抗痛风药」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph19_q010","chapter":"第十九章 解热镇痛抗炎药与抗痛风药","chapterIdx":18,"num":10},{"type":"D","stem":"名词解释：吲哚美辛","answer":"吲哚乙酸类，抑制环氧酶作用强，解热镇痛抗炎作用在同类药中较强，但胃肠和中枢不良反应多，主要用于其他药无效或不耐受的关节炎及急性痛风。","rationale":"出自概念手册「解热镇痛抗炎药与抗痛风药」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph19_q011","chapter":"第十九章 解热镇痛抗炎药与抗痛风药","chapterIdx":18,"num":11},{"type":"D","stem":"名词解释：布洛芬","answer":"芳基丙酸类，口服吸收好，抗炎镇痛作用与阿司匹林相近而胃肠刺激较轻，是常用儿童退热药和关节炎治疗药，哮喘患者慎用。","rationale":"出自概念手册「解热镇痛抗炎药与抗痛风药」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph19_q012","chapter":"第十九章 解热镇痛抗炎药与抗痛风药","chapterIdx":18,"num":12},{"type":"D","stem":"名词解释：双氯芬酸","answer":"苯乙酸类，抗炎镇痛作用强，常用于类风湿关节炎、骨关节炎及软组织疼痛，胃肠反应较多，宜饭后服或选肠溶制剂。","rationale":"出自概念手册「解热镇痛抗炎药与抗痛风药」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph19_q013","chapter":"第十九章 解热镇痛抗炎药与抗痛风药","chapterIdx":18,"num":13},{"type":"D","stem":"名词解释：塞来昔布","answer":"选择性环氧酶-2抑制药，治疗量对COX-1影响小，胃肠道溃疡和出血风险较低，用于骨关节炎和类风湿关节炎，但可增加心血管血栓事件风险。","rationale":"出自概念手册「解热镇痛抗炎药与抗痛风药」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph19_q014","chapter":"第十九章 解热镇痛抗炎药与抗痛风药","chapterIdx":18,"num":14},{"type":"D","stem":"名词解释：痛风","answer":"嘌呤代谢紊乱或尿酸排泄减少所致的高尿酸血症，尿酸盐结晶沉积于关节、软组织和肾脏而引起的炎症性疾病，需长期控制血尿酸水平。","rationale":"出自概念手册「解热镇痛抗炎药与抗痛风药」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph19_q015","chapter":"第十九章 解热镇痛抗炎药与抗痛风药","chapterIdx":18,"num":15},{"type":"D","stem":"名词解释：抗痛风药","answer":"用于控制痛风急性发作或降低血尿酸的药物，分急性发作期用药、抑制尿酸生成药和促尿酸排泄药三类。","rationale":"出自概念手册「解热镇痛抗炎药与抗痛风药」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph19_q016","chapter":"第十九章 解热镇痛抗炎药与抗痛风药","chapterIdx":18,"num":16},{"type":"D","stem":"名词解释：秋水仙碱","answer":"急性痛风性关节炎的特异性用药，与中性粒细胞微管蛋白结合，抑制微管聚合和炎症介质释放，对一般疼痛和慢性痛风无效，胃肠道反应最常见。","rationale":"出自概念手册「解热镇痛抗炎药与抗痛风药」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph19_q017","chapter":"第十九章 解热镇痛抗炎药与抗痛风药","chapterIdx":18,"num":17},{"type":"D","stem":"名词解释：别嘌醇","answer":"黄嘌呤氧化酶抑制剂，减少尿酸生成，用于慢性痛风、痛风石和尿酸性肾病，用药初期可诱发急性发作，可致皮疹和骨髓抑制，并增强硫唑嘌呤毒性。","rationale":"出自概念手册「解热镇痛抗炎药与抗痛风药」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph19_q018","chapter":"第十九章 解热镇痛抗炎药与抗痛风药","chapterIdx":18,"num":18},{"type":"D","stem":"名词解释：非布司他","answer":"选择性非嘌呤类黄嘌呤氧化酶抑制剂，降尿酸作用强，用于别嘌醇不耐受或疗效不佳者，需注意肝功能异常和心血管事件风险。","rationale":"出自概念手册「解热镇痛抗炎药与抗痛风药」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph19_q019","chapter":"第十九章 解热镇痛抗炎药与抗痛风药","chapterIdx":18,"num":19},{"type":"D","stem":"名词解释：苯溴马隆","answer":"抑制肾小管对尿酸的重吸收而促进尿酸排泄，用于尿酸排泄减少型痛风，用药期间应多饮水并碱化尿液以防尿酸结石，可致肝损害。","rationale":"出自概念手册「解热镇痛抗炎药与抗痛风药」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph19_q020","chapter":"第十九章 解热镇痛抗炎药与抗痛风药","chapterIdx":18,"num":20},{"type":"D","stem":"名词解释：丙磺舒","answer":"抑制肾小管尿酸重吸收、促进尿酸排泄，用于慢性痛风，也可竞争性抑制青霉素的肾小管分泌而延长其作用，磺胺类过敏者禁用。","rationale":"出自概念手册「解热镇痛抗炎药与抗痛风药」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph19_q021","chapter":"第十九章 解热镇痛抗炎药与抗痛风药","chapterIdx":18,"num":21},{"type":"S","stem":"简答题：为什么用小剂量阿司匹林抗血栓，而大剂量反而可能促进血栓形成？","answer":"①阿司匹林以共价键不可逆抑制环氧酶；②小剂量主要抑制血小板COX-1，减少血小板内TXA2生成，抑制血小板聚集；③血小板无细胞核、不能再合成COX-1，故作用持久；④大剂量同时抑制血管壁COX，使内皮PGI2生成减少，抗聚集作用被削弱，可能促进血栓形成。","rationale":"采分点为不可逆抑酶、TXA2减少、血小板不能再生酶、PGI2减少四点；临床用小剂量正是基于这一选择性。","id":"rph19_q022","chapter":"第十九章 解热镇痛抗炎药与抗痛风药","chapterIdx":18,"num":22},{"type":"F","stem":"填空题：阿司匹林抑制环氧酶，使______合成减少而产生解热、镇痛、抗炎作用；其抗血栓作用主要与抑制血小板______生成有关。","answer":"①前列腺素（PGs） ②血栓素A2（TXA2）","rationale":"NSAIDs共同机制是抑制COX减少前列腺素合成；抗血栓靠减少TXA2，而胃黏膜损伤与抑制COX-1使保护性前列腺素减少有关。","id":"rph19_q023","chapter":"第十九章 解热镇痛抗炎药与抗痛风药","chapterIdx":18,"num":23},{"type":"F","stem":"填空题：秋水仙碱是急性痛风性关节炎的______用药，别嘌醇通过抑制______酶减少尿酸生成，苯溴马隆则抑制肾小管对尿酸的______。","answer":"①特异性 ②黄嘌呤氧化 ③重吸收","rationale":"痛风分期选药：急性期用秋水仙碱或NSAIDs抗炎，缓解期用别嘌醇、非布司他抑制生成，或苯溴马隆、丙磺舒促排泄。","id":"rph19_q024","chapter":"第十九章 解热镇痛抗炎药与抗痛风药","chapterIdx":18,"num":24},{"type":"T","stem":"判断题：对乙酰氨基酚的解热镇痛作用与阿司匹林相当，但抗炎作用很弱，过量中毒可致肝坏死。","options":{"A":"正确","B":"错误"},"answer":["A"],"rationale":"对乙酰氨基酚属苯胺类，几乎无抗炎抗风湿作用，不用于关节炎；过量产生毒性代谢物致肝细胞坏死，解救用巯基化合物。","id":"rph19_q025","chapter":"第十九章 解热镇痛抗炎药与抗痛风药","chapterIdx":18,"num":25},{"type":"T","stem":"判断题：阿司匹林诱发的哮喘发作可用肾上腺素解救。","options":{"A":"正确","B":"错误"},"answer":["B"],"rationale":"阿司匹林哮喘是抑制COX后脂氧酶途径白三烯增多所致，并非抗原抗体反应，肾上腺素无效；应停药并按哮喘处理。","id":"rph19_q026","chapter":"第十九章 解热镇痛抗炎药与抗痛风药","chapterIdx":18,"num":26}]},{"title":"第二十章 利尿药与脱水药","questions":[{"type":"D","stem":"名词解释：利尿药","answer":"作用于肾脏、增加电解质和水的排泄而使尿量增多的药物，主要用于水肿、高血压、心力衰竭和急性肾损伤的防治。","rationale":"出自概念手册「利尿药与脱水药」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph20_q001","chapter":"第二十章 利尿药与脱水药","chapterIdx":19,"num":1},{"type":"D","stem":"名词解释：脱水药","answer":"又称渗透性利尿药，静脉给药后可提高血浆渗透压，使组织间液水分向血浆转移而产生组织脱水作用的药物，代表药为甘露醇。","rationale":"出自概念手册「利尿药与脱水药」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph20_q002","chapter":"第二十章 利尿药与脱水药","chapterIdx":19,"num":2},{"type":"D","stem":"名词解释：利尿药按效能分类","answer":"按排钠利尿强度分为高效能（袢利尿药）、中效能（噻嗪类）、低效能（保钾利尿药与碳酸酐酶抑制药）三类，三者的作用部位和靶点各不相同。","rationale":"出自概念手册「利尿药与脱水药」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph20_q003","chapter":"第二十章 利尿药与脱水药","chapterIdx":19,"num":3},{"type":"D","stem":"名词解释：碳酸酐酶抑制药","answer":"抑制肾小管上皮细胞碳酸酐酶，减少碳酸氢盐重吸收和氢离子分泌，使尿液碱化、钠钾排出增多的一类弱利尿药，代表药为乙酰唑胺。","rationale":"出自概念手册「利尿药与脱水药」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph20_q004","chapter":"第二十章 利尿药与脱水药","chapterIdx":19,"num":4},{"type":"D","stem":"名词解释：乙酰唑胺","answer":"碳酸酐酶抑制药，利尿作用弱，但可减少房水生成而降低眼内压，用于青光眼急性发作、急性高山病和碱化尿液。","rationale":"出自概念手册「利尿药与脱水药」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph20_q005","chapter":"第二十章 利尿药与脱水药","chapterIdx":19,"num":5},{"type":"D","stem":"名词解释：袢利尿药","answer":"作用于髓袢升支粗段，抑制钠-钾-二氯共转运体，使氯化钠重吸收显著减少，排钠利尿作用最强的一类利尿药。","rationale":"出自概念手册「利尿药与脱水药」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph20_q006","chapter":"第二十章 利尿药与脱水药","chapterIdx":19,"num":6},{"type":"D","stem":"名词解释：呋塞米","answer":"袢利尿药的代表药，抑制髓袢升支粗段的钠-钾-二氯共转运体，作用强而迅速，用于严重水肿、急性肺水肿和急性肾衰竭。","rationale":"出自概念手册「利尿药与脱水药」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph20_q007","chapter":"第二十章 利尿药与脱水药","chapterIdx":19,"num":7},{"type":"D","stem":"名词解释：布美他尼","answer":"袢利尿药，作用机制与呋塞米相同，效价强度更高、耳毒性相对较低，可用于对呋塞米反应不佳的水肿患者。","rationale":"出自概念手册「利尿药与脱水药」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph20_q008","chapter":"第二十章 利尿药与脱水药","chapterIdx":19,"num":8},{"type":"D","stem":"名词解释：噻嗪类利尿药","answer":"作用于远曲小管近端，抑制钠-氯共转运体，排钠利尿作用中等而持久，是治疗高血压和轻中度水肿的基础药物。","rationale":"出自概念手册「利尿药与脱水药」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph20_q009","chapter":"第二十章 利尿药与脱水药","chapterIdx":19,"num":9},{"type":"D","stem":"名词解释：氢氯噻嗪","answer":"噻嗪类的代表药，口服有效、作用持久，用于轻中度水肿和高血压，可致低钾、高血糖、高血脂和高尿酸。","rationale":"出自概念手册「利尿药与脱水药」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph20_q010","chapter":"第二十章 利尿药与脱水药","chapterIdx":19,"num":10},{"type":"D","stem":"名词解释：保钾利尿药","answer":"作用于集合管，通过拮抗醛固酮受体或阻断钠通道而减少钠重吸收、减少钾排泄，利尿作用弱且可升高血钾的一类药物。","rationale":"出自概念手册「利尿药与脱水药」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph20_q011","chapter":"第二十章 利尿药与脱水药","chapterIdx":19,"num":11},{"type":"D","stem":"名词解释：螺内酯","answer":"醛固酮受体拮抗药，竞争性阻断醛固酮对集合管的作用而保钾排钠，用于伴醛固酮增多的水肿和慢性心力衰竭。","rationale":"出自概念手册「利尿药与脱水药」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph20_q012","chapter":"第二十章 利尿药与脱水药","chapterIdx":19,"num":12},{"type":"D","stem":"名词解释：氨苯蝶啶","answer":"直接阻断集合管上皮钠通道的保钾利尿药，作用不依赖醛固酮，常与噻嗪类或袢利尿药合用以防止低钾血症。","rationale":"出自概念手册「利尿药与脱水药」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph20_q013","chapter":"第二十章 利尿药与脱水药","chapterIdx":19,"num":13},{"type":"D","stem":"名词解释：甘露醇","answer":"脱水药的代表药，静脉滴注后提高血浆渗透压，使脑组织和房水的水分向血管内转移，经肾小球滤过后几乎不被重吸收而产生渗透性利尿。","rationale":"出自概念手册「利尿药与脱水药」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph20_q014","chapter":"第二十章 利尿药与脱水药","chapterIdx":19,"num":14},{"type":"S","stem":"简答题：呋塞米为什么能迅速缓解急性肺水肿？","answer":"①抑制髓袢升支粗段Na+-K+-2Cl-共转运子，产生强大的利尿作用，排出大量等渗尿；②扩张容量血管、增加静脉血容量，减少回心血量，此作用可发生在尿量增加之前；③降低心脏前负荷、减轻肺淤血，故能迅速缓解急性肺水肿；④利尿同时有利于消除脑水肿。","rationale":"采分点为抑制共转运子、强大利尿、扩血管降前负荷三点；扩血管作用先于利尿是常考的细节。","id":"rph20_q015","chapter":"第二十章 利尿药与脱水药","chapterIdx":19,"num":15},{"type":"F","stem":"填空题：呋塞米抑制髓袢升支粗段______共转运子，排出大量______尿，使肾脏的稀释和浓缩功能均降低。","answer":"①Na+-K+-2Cl- ②等渗","rationale":"袢利尿药作用部位是髓袢升支粗段，抑制该共转运子后NaCl重吸收受阻，稀释与浓缩功能同时下降，故排大量等渗尿。","id":"rph20_q016","chapter":"第二十章 利尿药与脱水药","chapterIdx":19,"num":16},{"type":"F","stem":"填空题：螺内酯是______受体拮抗药，仅在体内有醛固酮存在时才发挥利尿作用，久用可致______，并有性激素样作用。","answer":"①醛固酮 ②高血钾","rationale":"螺内酯竞争性拮抗醛固酮受体，保钾排钠，利尿弱而起效慢；氨苯蝶啶、阿米洛利直接阻滞管腔Na+通道，不依赖醛固酮。","id":"rph20_q017","chapter":"第二十章 利尿药与脱水药","chapterIdx":19,"num":17},{"type":"T","stem":"判断题：氢氯噻嗪可促进甲状旁腺激素调节的Ca2+重吸收，故可用于高尿钙伴肾结石的患者。","options":{"A":"正确","B":"错误"},"answer":["A"],"rationale":"噻嗪类促进远曲小管Ca2+重吸收、尿钙减少，可用于高尿钙伴肾结石；袢利尿药抑制Ca2+重吸收，可用于高钙血症。","id":"rph20_q018","chapter":"第二十章 利尿药与脱水药","chapterIdx":19,"num":18},{"type":"T","stem":"判断题：甘露醇口服后可产生脱水作用，因此可用于治疗脑水肿。","options":{"A":"正确","B":"错误"},"answer":["B"],"rationale":"甘露醇口服不吸收，只产生渗透性导泻；脱水作用须静脉注射提高血浆渗透压，静脉给药才是降低颅内压的首选。","id":"rph20_q019","chapter":"第二十章 利尿药与脱水药","chapterIdx":19,"num":19}]},{"title":"第二十一章 抗高血压药","questions":[{"type":"D","stem":"名词解释：高血压","answer":"以体循环动脉血压持续升高为主要表现的临床综合征，成人收缩压不低于140毫米汞柱和/或舒张压不低于90毫米汞柱即可诊断。","rationale":"出自概念手册「抗高血压药」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph21_q001","chapter":"第二十一章 抗高血压药","chapterIdx":20,"num":1},{"type":"D","stem":"名词解释：抗高血压药","answer":"通过影响血压调节的某一环节，降低外周血管阻力、减少心输出量或血容量，使血压下降并维持在正常水平的药物，又称降压药。","rationale":"出自概念手册「抗高血压药」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph21_q002","chapter":"第二十一章 抗高血压药","chapterIdx":20,"num":2},{"type":"D","stem":"名词解释：肾素-血管紧张素系统（RAS）","answer":"由肾素、血管紧张素原、血管紧张素转化酶及血管紧张素受体构成的血压调节系统，血管紧张素Ⅱ是最强的活性物质，可收缩血管、促进醛固酮分泌和心血管重构。","rationale":"出自概念手册「抗高血压药」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph21_q003","chapter":"第二十一章 抗高血压药","chapterIdx":20,"num":3},{"type":"D","stem":"名词解释：血管紧张素转化酶抑制药（ACEI）","answer":"抑制血管紧张素转化酶，减少血管紧张素Ⅱ生成并减少缓激肽降解，从而扩张血管、降低血压并逆转心血管重构的一类降压药。","rationale":"出自概念手册「抗高血压药」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph21_q004","chapter":"第二十一章 抗高血压药","chapterIdx":20,"num":4},{"type":"D","stem":"名词解释：血管紧张素Ⅱ受体阻断药（ARB）","answer":"选择性阻断血管紧张素Ⅱ的AT1受体，拮抗其收缩血管和促进醛固酮分泌的作用，降压平稳且不引起干咳的一类降压药。","rationale":"出自概念手册「抗高血压药」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph21_q005","chapter":"第二十一章 抗高血压药","chapterIdx":20,"num":5},{"type":"D","stem":"名词解释：卡托普利","answer":"第一个口服有效的ACEI，分子中含巯基，起效快、作用时间较短，用于高血压和心力衰竭，常见不良反应为干咳和味觉障碍。","rationale":"出自概念手册「抗高血压药」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph21_q006","chapter":"第二十一章 抗高血压药","chapterIdx":20,"num":6},{"type":"D","stem":"名词解释：氯沙坦","answer":"ARB的代表药，口服有效、作用持久，阻断AT1受体而降压，不引起干咳和血管神经性水肿，适用于不能耐受ACEI者。","rationale":"出自概念手册「抗高血压药」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph21_q007","chapter":"第二十一章 抗高血压药","chapterIdx":20,"num":7},{"type":"D","stem":"名词解释：氨氯地平","answer":"二氢吡啶类钙通道阻滞药，作用持久平稳，每日一次即可控制血压，适用于老年高血压及合并冠心病、糖尿病者。","rationale":"出自概念手册「抗高血压药」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph21_q008","chapter":"第二十一章 抗高血压药","chapterIdx":20,"num":8},{"type":"D","stem":"名词解释：硝普钠","answer":"直接扩张动脉和静脉的强效血管扩张药，静脉滴注起效快、作用短，主要用于高血压急症和急性心力衰竭，需避光使用。","rationale":"出自概念手册「抗高血压药」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph21_q009","chapter":"第二十一章 抗高血压药","chapterIdx":20,"num":9},{"type":"D","stem":"名词解释：可乐定","answer":"中枢性降压药，激动延髓孤束核α2受体和咪唑啉I1受体，减少交感神经冲动传出而降压，适用于合并肾功能不全的高血压。","rationale":"出自概念手册「抗高血压药」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph21_q010","chapter":"第二十一章 抗高血压药","chapterIdx":20,"num":10},{"type":"D","stem":"名词解释：α1受体阻断药（抗高血压）","answer":"选择性阻断血管平滑肌α1受体，扩张动脉和静脉而降压，可改善脂代谢，代表药为哌唑嗪和特拉唑嗪，适用于合并前列腺增生的高血压患者。","rationale":"出自概念手册「抗高血压药」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph21_q011","chapter":"第二十一章 抗高血压药","chapterIdx":20,"num":11},{"type":"D","stem":"名词解释：首剂现象","answer":"首次服用哌唑嗪等α1受体阻断药后出现的体位性低血压甚至晕厥，与静脉扩张、血容量相对不足有关，宜首剂减半并于睡前服用。","rationale":"出自概念手册「抗高血压药」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph21_q012","chapter":"第二十一章 抗高血压药","chapterIdx":20,"num":12},{"type":"D","stem":"名词解释：高血压急症","answer":"血压急剧升高并伴心、脑、肾等重要器官进行性损害的临床综合征，需静脉使用起效快、可控性强的降压药，如硝普钠。","rationale":"出自概念手册「抗高血压药」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph21_q013","chapter":"第二十一章 抗高血压药","chapterIdx":20,"num":13},{"type":"D","stem":"名词解释：利血平","answer":"去甲肾上腺素能神经末梢阻滞药，耗竭囊泡中的递质使交感张力下降，降压缓慢而持久，因可致抑郁等不良反应现已少用。","rationale":"出自概念手册「抗高血压药」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph21_q014","chapter":"第二十一章 抗高血压药","chapterIdx":20,"num":14},{"type":"S","stem":"简答题：ACEI 降压的主要机制及常见不良反应有哪些？","answer":"①抑制循环和局部组织的ACE，减少AngⅡ生成，减弱其缩血管、促醛固酮分泌和促增生作用；②减少缓激肽降解，缓激肽经B2受体促NO、PGI2生成而扩张血管；③减少醛固酮分泌，减轻水钠潴留；④抑制交感神经递质释放，并抑制和逆转心血管重构；⑤不良反应有干咳、血管神经性水肿、高血钾、首剂低血压和肾功能损伤。","rationale":"机制四点为抑ACE、保缓激肽、减醛固酮、抑交感及抗重构；干咳由缓激肽在肺内蓄积引起，是被迫停药的主要原因。","id":"rph21_q015","chapter":"第二十一章 抗高血压药","chapterIdx":20,"num":15},{"type":"F","stem":"填空题：硝普钠在血管平滑肌内代谢产生______，直接松弛小动脉和小静脉，须______给药，主要用于高血压急症和手术控制性降压。","answer":"①NO（一氧化氮） ②静脉滴注","rationale":"硝普钠为硝基扩血管药，作用强而快、维持短，须静脉滴注并监测血压；直接扩血管药肼屈嗪则主要扩张小动脉。","id":"rph21_q016","chapter":"第二十一章 抗高血压药","chapterIdx":20,"num":16},{"type":"F","stem":"填空题：哌唑嗪首次给药可出现______现象，表现为严重的直立性低血压和晕厥；ARB在______水平阻断AngⅡ的作用，不影响缓激肽降解。","answer":"①首剂 ②AT1受体","rationale":"哌唑嗪选择性阻断α1受体，首剂应减量并睡前服；ARB作用专一、完全，较少引起咳嗽和血管神经性水肿。","id":"rph21_q017","chapter":"第二十一章 抗高血压药","chapterIdx":20,"num":17},{"type":"T","stem":"判断题：β受体阻断药禁用于伴支气管哮喘或重度房室传导阻滞的高血压患者。","options":{"A":"正确","B":"错误"},"answer":["A"],"rationale":"阻断β2受体可诱发支气管痉挛，阻断β1受体加重传导阻滞和心功能抑制，故哮喘、重度房室传导阻滞、严重左心功能不全者禁用。","id":"rph21_q018","chapter":"第二十一章 抗高血压药","chapterIdx":20,"num":18},{"type":"T","stem":"判断题：ACEI与ARB都会引起干咳，因为二者都抑制缓激肽的降解。","options":{"A":"正确","B":"错误"},"answer":["B"],"rationale":"ARB只阻断AT1受体，不影响缓激肽降解，故干咳和血管神经性水肿明显少于ACEI，是ACEI不耐受者的替代选择。","id":"rph21_q019","chapter":"第二十一章 抗高血压药","chapterIdx":20,"num":19}]},{"title":"第二十二章 抗心律失常药","questions":[{"type":"D","stem":"名词解释：心律失常","answer":"心脏冲动的起源、频率、节律或传导发生异常，使心脏活动过快、过慢或不规则的一类病理状态，是抗心律失常药的作用对象。","rationale":"出自概念手册「抗心律失常药」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph22_q001","chapter":"第二十二章 抗心律失常药","chapterIdx":21,"num":1},{"type":"F","stem":"填空题：心脏冲动的起源、频率、节律或传导发生异常，使心脏活动过快、过慢或不规则的一类病理状态，是抗______药的作用对象。","answer":"心律失常","rationale":"出自概念手册「抗心律失常药」核心概念：心律失常。","id":"rph22_q002","chapter":"第二十二章 抗心律失常药","chapterIdx":21,"num":2},{"type":"D","stem":"名词解释：抗心律失常药","answer":"通过改变心肌细胞电生理特性，纠正冲动形成异常或传导异常，从而恢复并维持正常心律的药物，按Vaughan Williams法分为四类。","rationale":"出自概念手册「抗心律失常药」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph22_q003","chapter":"第二十二章 抗心律失常药","chapterIdx":21,"num":3},{"type":"D","stem":"名词解释：折返激动","answer":"冲动经环路传导并返回原处再次激动心肌的现象，是快速型心律失常最常见的发生机制，形成条件为存在环路、单向传导阻滞和传导缓慢。","rationale":"出自概念手册「抗心律失常药」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph22_q004","chapter":"第二十二章 抗心律失常药","chapterIdx":21,"num":4},{"type":"D","stem":"名词解释：触发活动","answer":"由一次动作电位后的后除极达到阈电位而诱发的异常冲动，包括早后除极和延迟后除极，与钙超载及细胞内钙释放异常有关。","rationale":"出自概念手册「抗心律失常药」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph22_q005","chapter":"第二十二章 抗心律失常药","chapterIdx":21,"num":5},{"type":"D","stem":"名词解释：有效不应期（ERP）","answer":"心肌细胞在除极后一段时间内对任何刺激均不能产生可扩布性兴奋的时期，延长有效不应期可使折返冲动落入不应期而终止心律失常。","rationale":"出自概念手册「抗心律失常药」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph22_q006","chapter":"第二十二章 抗心律失常药","chapterIdx":21,"num":6},{"type":"D","stem":"名词解释：膜反应性","answer":"心肌细胞膜对钠离子通透性的表现，以动作电位0相除极的最大速率表示，膜反应性高则传导快，降低膜反应性可减慢传导、消除折返。","rationale":"出自概念手册「抗心律失常药」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph22_q007","chapter":"第二十二章 抗心律失常药","chapterIdx":21,"num":7},{"type":"F","stem":"填空题：心肌细胞膜对钠离子通透性的表现，以动作电位0相除极的最大速率表示，______高则传导快，降低膜反应性可减慢传导、消除折返。","answer":"膜反应性","rationale":"出自概念手册「抗心律失常药」核心概念：膜反应性。","id":"rph22_q008","chapter":"第二十二章 抗心律失常药","chapterIdx":21,"num":8},{"type":"D","stem":"名词解释：抗心律失常药的Vaughan Williams分类","answer":"按主要电生理作用将抗心律失常药分为四类：Ⅰ类钠通道阻滞药、Ⅱ类β肾上腺素受体阻断药、Ⅲ类钾通道阻滞药、Ⅳ类钙通道阻滞药。","rationale":"出自概念手册「抗心律失常药」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph22_q009","chapter":"第二十二章 抗心律失常药","chapterIdx":21,"num":9},{"type":"D","stem":"名词解释：奎尼丁","answer":"Ⅰa类钠通道阻滞药，适度阻滞钠通道并延长动作电位时程和有效不应期，属广谱抗心律失常药，可致金鸡纳反应和奎尼丁晕厥。","rationale":"出自概念手册「抗心律失常药」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph22_q010","chapter":"第二十二章 抗心律失常药","chapterIdx":21,"num":10},{"type":"F","stem":"填空题：Ⅰa类钠通道阻滞药，适度阻滞钠通道并延长动作电位时程和有效不应期，属广谱抗心律失常药，可致金鸡纳反应和______晕厥。","answer":"奎尼丁","rationale":"出自概念手册「抗心律失常药」核心概念：奎尼丁。","id":"rph22_q011","chapter":"第二十二章 抗心律失常药","chapterIdx":21,"num":11},{"type":"D","stem":"名词解释：奎尼丁晕厥","answer":"奎尼丁引起的一种严重不良反应，表现为突发性意识丧失、抽搐甚至心室颤动，多与用药后QT间期延长和尖端扭转型室性心动过速有关，一旦发生应立即停药。","rationale":"出自概念手册「抗心律失常药」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph22_q012","chapter":"第二十二章 抗心律失常药","chapterIdx":21,"num":12},{"type":"D","stem":"名词解释：普罗帕酮","answer":"Ⅰc类钠通道阻滞药，明显阻滞钠通道并减慢传导，属广谱抗心律失常药，器质性心脏病和心功能不全者慎用。","rationale":"出自概念手册「抗心律失常药」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph22_q013","chapter":"第二十二章 抗心律失常药","chapterIdx":21,"num":13},{"type":"D","stem":"名词解释：β受体阻断药（抗心律失常）","answer":"即Ⅱ类抗心律失常药，阻断心脏β1受体，减慢窦房结自律性并延长房室结传导，用于窦性心动过速、控制房颤心室率及交感兴奋诱发的室性心律失常。","rationale":"出自概念手册「抗心律失常药」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph22_q014","chapter":"第二十二章 抗心律失常药","chapterIdx":21,"num":14},{"type":"D","stem":"名词解释：胺碘酮","answer":"Ⅲ类钾通道阻滞药，延长动作电位时程和有效不应期，兼有Ⅰ至Ⅳ类作用，为广谱抗心律失常药，长期应用可致肺纤维化和甲状腺功能异常。","rationale":"出自概念手册「抗心律失常药」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph22_q015","chapter":"第二十二章 抗心律失常药","chapterIdx":21,"num":15},{"type":"D","stem":"名词解释：维拉帕米","answer":"Ⅳ类钙通道阻滞药，阻滞L型钙通道，减慢窦房结和房室结传导，是阵发性室上性心动过速的首选药，严重心衰和低血压者禁用。","rationale":"出自概念手册「抗心律失常药」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph22_q016","chapter":"第二十二章 抗心律失常药","chapterIdx":21,"num":16},{"type":"D","stem":"名词解释：腺苷","answer":"内源性嘌呤核苷，激活心肌A1受体而减慢房室传导，静脉快速注射可迅速终止阵发性室上性心动过速，作用仅持续十余秒。","rationale":"出自概念手册「抗心律失常药」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph22_q017","chapter":"第二十二章 抗心律失常药","chapterIdx":21,"num":17},{"type":"D","stem":"名词解释：尖端扭转型室性心动过速","answer":"一种多形性室性心动过速，心电图QRS波群围绕基线扭转，常由Ⅲ类药、低钾低镁或心动过缓诱发，可用硫酸镁并加快心率治疗。","rationale":"出自概念手册「抗心律失常药」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph22_q018","chapter":"第二十二章 抗心律失常药","chapterIdx":21,"num":18},{"type":"S","stem":"简答题：抗心律失常药治疗快速型心律失常的基本作用机制有哪些？","answer":"①降低心肌组织的异常自律性，如减慢4期自动去极化速率、增加最大舒张电位绝对值或提高阈电位；②减少后除极与触发激动，早后除极靠加速复极缩短APD，迟后除极靠抑制细胞内钙超载；③消除折返，通过减慢传导使单向阻滞变为双向阻滞，或延长ERP使折返环不能维持；④部分药物通过阻断β受体或钙通道降低交感兴奋和钙内流。","rationale":"三条主线：降低自律性、减少后除极、消除折返；折返是多数快速型心律失常的机制，故改变传导性或ERP是关键。","id":"rph22_q019","chapter":"第二十二章 抗心律失常药","chapterIdx":21,"num":19},{"type":"F","stem":"填空题：利多卡因属______类抗心律失常药，促进______外流而缩短APD，是治疗______心律失常的首选药之一。","answer":"①ⅠB ②K+ ③室性","rationale":"ⅠB类轻度阻滞钠通道、促进K+外流，对缺血去极化组织作用强，故对室性心律失常有选择性；首过消除明显，须静脉给药。","id":"rph22_q020","chapter":"第二十二章 抗心律失常药","chapterIdx":21,"num":20},{"type":"F","stem":"填空题：维拉帕米主要阻滞______型钙通道，首选用于______；胺碘酮长期应用可致角膜褐色微粒沉着和______。","answer":"①L ②阵发性室上性心动过速 ③间质性肺炎或肺纤维化","rationale":"维拉帕米属Ⅳ类，抑制窦房结和房室结慢反应细胞；胺碘酮为Ⅲ类广谱药、含碘量大，肺纤维化和甲状腺功能异常是严重不良反应。","id":"rph22_q021","chapter":"第二十二章 抗心律失常药","chapterIdx":21,"num":21},{"type":"T","stem":"判断题：普罗帕酮属ⅠC类药，重度阻滞钠通道，主要用于危及生命的室性心动过速。","options":{"A":"正确","B":"错误"},"answer":["A"],"rationale":"ⅠC类降低0相去极化速率、减慢传导最明显，促心律失常风险较高，故限用于危及生命的室性心律失常。","id":"rph22_q022","chapter":"第二十二章 抗心律失常药","chapterIdx":21,"num":22},{"type":"T","stem":"判断题：腺苷应缓慢静脉滴注，用于终止折返性室上性心动过速。","options":{"A":"正确","B":"错误"},"answer":["B"],"rationale":"腺苷半衰期极短，必须快速静脉注射才能终止折返性室上性心律失常，缓慢滴注无效。","id":"rph22_q023","chapter":"第二十二章 抗心律失常药","chapterIdx":21,"num":23}]},{"title":"第二十三章 调血脂药与抗动脉粥样硬化药","questions":[{"type":"D","stem":"名词解释：高脂血症","answer":"血浆中胆固醇和/或甘油三酯水平升高，或高密度脂蛋白胆固醇降低的脂质代谢异常，是动脉粥样硬化的重要危险因素。","rationale":"出自概念手册「调血脂药与抗动脉粥样硬化药」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph23_q001","chapter":"第二十三章 调血脂药与抗动脉粥样硬化药","chapterIdx":22,"num":1},{"type":"D","stem":"名词解释：动脉粥样硬化","answer":"脂质沉积于大中动脉内膜下，形成粥样斑块并引起管壁增厚、管腔狭窄的慢性炎症性病变，是冠心病和脑卒中的病理基础。","rationale":"出自概念手册「调血脂药与抗动脉粥样硬化药」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph23_q002","chapter":"第二十三章 调血脂药与抗动脉粥样硬化药","chapterIdx":22,"num":2},{"type":"D","stem":"名词解释：脂蛋白","answer":"由载脂蛋白和脂质组成的复合物，是血脂在血液中的运输形式，按密度分为乳糜微粒、极低密度脂蛋白、低密度脂蛋白和高密度脂蛋白。","rationale":"出自概念手册「调血脂药与抗动脉粥样硬化药」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph23_q003","chapter":"第二十三章 调血脂药与抗动脉粥样硬化药","chapterIdx":22,"num":3},{"type":"F","stem":"填空题：由载______和脂质组成的复合物，是血脂在血液中的运输形式，按密度分为乳糜微粒、极低密度脂蛋白、低密度脂蛋白和高密度脂蛋白。","answer":"脂蛋白","rationale":"出自概念手册「调血脂药与抗动脉粥样硬化药」核心概念：脂蛋白。","id":"rph23_q004","chapter":"第二十三章 调血脂药与抗动脉粥样硬化药","chapterIdx":22,"num":4},{"type":"D","stem":"名词解释：低密度脂蛋白胆固醇（LDL-C）","answer":"主要由极低密度脂蛋白代谢生成，负责将胆固醇运送到外周组织，水平升高是动脉粥样硬化最重要的致病因素，也是调脂治疗的首要目标。","rationale":"出自概念手册「调血脂药与抗动脉粥样硬化药」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph23_q005","chapter":"第二十三章 调血脂药与抗动脉粥样硬化药","chapterIdx":22,"num":5},{"type":"D","stem":"名词解释：高密度脂蛋白胆固醇（HDL-C）","answer":"参与胆固醇逆向转运，将外周组织的胆固醇运回肝脏代谢，水平升高具有抗动脉粥样硬化作用，故被称为好胆固醇。","rationale":"出自概念手册「调血脂药与抗动脉粥样硬化药」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph23_q006","chapter":"第二十三章 调血脂药与抗动脉粥样硬化药","chapterIdx":22,"num":6},{"type":"D","stem":"名词解释：HMG-CoA还原酶","answer":"即羟甲基戊二酰辅酶A还原酶，是体内胆固醇生物合成的限速酶，被他汀类竞争性抑制后肝内胆固醇合成减少。","rationale":"出自概念手册「调血脂药与抗动脉粥样硬化药」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph23_q007","chapter":"第二十三章 调血脂药与抗动脉粥样硬化药","chapterIdx":22,"num":7},{"type":"D","stem":"名词解释：他汀类","answer":"即HMG-CoA还原酶抑制药，通过抑制胆固醇合成、上调肝细胞低密度脂蛋白受体而显著降低LDL-C，并具有稳定斑块和抗炎作用。","rationale":"出自概念手册「调血脂药与抗动脉粥样硬化药」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph23_q008","chapter":"第二十三章 调血脂药与抗动脉粥样硬化药","chapterIdx":22,"num":8},{"type":"D","stem":"名词解释：贝特类","answer":"即苯氧芳酸类，激活过氧化物酶体增殖物激活受体α，增强脂蛋白脂酶活性，主要降低甘油三酯并升高高密度脂蛋白。","rationale":"出自概念手册「调血脂药与抗动脉粥样硬化药」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph23_q009","chapter":"第二十三章 调血脂药与抗动脉粥样硬化药","chapterIdx":22,"num":9},{"type":"D","stem":"名词解释：烟酸","answer":"即维生素B3，大剂量可抑制脂肪组织脂解、减少肝脏合成极低密度脂蛋白，降低甘油三酯和LDL-C并显著升高HDL-C，但面部潮红明显。","rationale":"出自概念手册「调血脂药与抗动脉粥样硬化药」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph23_q010","chapter":"第二十三章 调血脂药与抗动脉粥样硬化药","chapterIdx":22,"num":10},{"type":"D","stem":"名词解释：胆汁酸螯合药","answer":"在肠道与胆汁酸结合、阻止其重吸收，促使胆固醇转化为胆汁酸而降低血浆胆固醇，代表药为考来烯胺。","rationale":"出自概念手册「调血脂药与抗动脉粥样硬化药」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph23_q011","chapter":"第二十三章 调血脂药与抗动脉粥样硬化药","chapterIdx":22,"num":11},{"type":"D","stem":"名词解释：依折麦布","answer":"选择性抑制小肠黏膜刷状缘的胆固醇转运蛋白，减少肠道胆固醇吸收，与他汀类合用可进一步降低LDL-C。","rationale":"出自概念手册「调血脂药与抗动脉粥样硬化药」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph23_q012","chapter":"第二十三章 调血脂药与抗动脉粥样硬化药","chapterIdx":22,"num":12},{"type":"D","stem":"名词解释：PCSK9抑制药","answer":"通过抑制前蛋白转化酶枯草溶菌素9，减少肝细胞低密度脂蛋白受体的降解，使LDL-C显著下降的一类新型调脂药。","rationale":"出自概念手册「调血脂药与抗动脉粥样硬化药」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph23_q013","chapter":"第二十三章 调血脂药与抗动脉粥样硬化药","chapterIdx":22,"num":13},{"type":"D","stem":"名词解释：普罗布考","answer":"抗氧化性调脂药，抑制低密度脂蛋白的氧化修饰、延缓动脉粥样硬化形成，但可降低HDL-C并延长QT间期。","rationale":"出自概念手册「调血脂药与抗动脉粥样硬化药」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph23_q014","chapter":"第二十三章 调血脂药与抗动脉粥样硬化药","chapterIdx":22,"num":14},{"type":"D","stem":"名词解释：多不饱和脂肪酸","answer":"主要为二十碳五烯酸和二十二碳六烯酸，大剂量可降低甘油三酯、抑制血小板聚集，用于高甘油三酯血症的辅助治疗。","rationale":"出自概念手册「调血脂药与抗动脉粥样硬化药」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph23_q015","chapter":"第二十三章 调血脂药与抗动脉粥样硬化药","chapterIdx":22,"num":15},{"type":"S","stem":"简答题：他汀类调血脂药的作用机制、临床应用与主要不良反应？","answer":"①竞争性抑制HMG-CoA还原酶，阻断甲羟戊酸生成，使肝内胆固醇合成减少；②肝细胞胆固醇减少后LDL受体上调，血中LDL-C和TC清除增加，TG也下降、HDL略升高；③用于Ⅱa、Ⅱb、Ⅲ型高脂蛋白血症，糖尿病和肾病综合征的高胆固醇血症，以及冠心病的一、二级预防；④不良反应有胃肠反应、转氨酶升高、肌痛甚至横纹肌溶解。","rationale":"采分点为抑限速酶、降LDL-C与TC、适应证、肌毒性与肝毒性；横纹肌溶解表现为肌痛、尿色异常和肌酸激酶升高。","id":"rph23_q016","chapter":"第二十三章 调血脂药与抗动脉粥样硬化药","chapterIdx":22,"num":16},{"type":"F","stem":"填空题：他汀类竞争性抑制______还原酶，主要降低血浆______；贝特类激活______，主要降低TG和VLDL。","answer":"①HMG-CoA ②TC和LDL-C ③PPARα","rationale":"HMG-CoA还原酶是胆固醇合成的限速酶；贝特类激动PPARα，以降TG为主，主要用于以TG或VLDL升高为主的高脂血症。","id":"rph23_q017","chapter":"第二十三章 调血脂药与抗动脉粥样硬化药","chapterIdx":22,"num":17},{"type":"F","stem":"填空题：依折麦布与小肠刷状缘______蛋白结合，抑制胆固醇吸收；考来烯胺在肠道与______结合，阻断其肝肠循环而降低TC。","answer":"①NPC1L1 ②胆汁酸","rationale":"依折麦布是胆固醇吸收抑制药，常与他汀合用；胆汁酸结合树脂口服不吸收，消耗胆固醇转化为胆汁酸，主要降低TC和LDL-C。","id":"rph23_q018","chapter":"第二十三章 调血脂药与抗动脉粥样硬化药","chapterIdx":22,"num":18},{"type":"T","stem":"判断题：普罗布考在降低血浆TC和LDL-C的同时，也使HDL-C降低。","options":{"A":"正确","B":"错误"},"answer":["A"],"rationale":"普罗布考抗氧化并降低TC、LDL-C、HDL-C和ApoA，对TG和VLDL一般无影响，主要用于Ⅱa型高胆固醇血症。","id":"rph23_q019","chapter":"第二十三章 调血脂药与抗动脉粥样硬化药","chapterIdx":22,"num":19},{"type":"T","stem":"判断题：烟酸是主要降低TC和LDL-C的药物，对TG和HDL无明显影响。","options":{"A":"正确","B":"错误"},"answer":["B"],"rationale":"烟酸主要降低TG和VLDL、升高HDL，降低LDL作用较弱，属广谱调血脂药，对Ⅱb和Ⅳ型作用最好。","id":"rph23_q020","chapter":"第二十三章 调血脂药与抗动脉粥样硬化药","chapterIdx":22,"num":20}]},{"title":"第二十四章 抗心绞痛药","questions":[{"type":"D","stem":"名词解释：心绞痛","answer":"冠状动脉供血不足导致心肌急剧、暂时缺血缺氧所引起的临床综合征，以发作性胸骨后压榨性疼痛为特征，常由劳累或情绪激动诱发。","rationale":"出自概念手册「抗心绞痛药」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph24_q001","chapter":"第二十四章 抗心绞痛药","chapterIdx":23,"num":1},{"type":"D","stem":"名词解释：抗心绞痛药","answer":"通过降低心肌耗氧量或增加心肌供血，恢复心肌氧的供需平衡，从而缓解和预防心绞痛发作的药物，包括硝酸酯类、β受体阻断药和钙通道阻滞药。","rationale":"出自概念手册「抗心绞痛药」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph24_q002","chapter":"第二十四章 抗心绞痛药","chapterIdx":23,"num":2},{"type":"D","stem":"名词解释：心肌耗氧量","answer":"心肌收缩所消耗的氧量，主要取决于心室壁张力、心肌收缩力和心率，凡能降低这三者的措施均可减少耗氧而缓解心绞痛。","rationale":"出自概念手册「抗心绞痛药」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph24_q003","chapter":"第二十四章 抗心绞痛药","chapterIdx":23,"num":3},{"type":"D","stem":"名词解释：硝酸甘油","answer":"硝酸酯类的代表药，舌下含服吸收迅速，在体内释放一氧化氮而舒张血管，是心绞痛发作时缓解症状的首选药。","rationale":"出自概念手册「抗心绞痛药」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph24_q004","chapter":"第二十四章 抗心绞痛药","chapterIdx":23,"num":4},{"type":"D","stem":"名词解释：硝酸酯类","answer":"包括硝酸甘油、硝酸异山梨酯和单硝酸异山梨酯等，通过释放一氧化氮激活鸟苷酸环化酶、增加环磷酸鸟苷而松弛血管平滑肌。","rationale":"出自概念手册「抗心绞痛药」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph24_q005","chapter":"第二十四章 抗心绞痛药","chapterIdx":23,"num":5},{"type":"D","stem":"名词解释：一氧化氮（NO）","answer":"血管内皮舒张因子，激活可溶性鸟苷酸环化酶使环磷酸鸟苷增多，降低细胞内钙并松弛血管平滑肌，硝酸酯类的舒血管作用即通过它实现。","rationale":"出自概念手册「抗心绞痛药」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph24_q006","chapter":"第二十四章 抗心绞痛药","chapterIdx":23,"num":6},{"type":"D","stem":"名词解释：硝酸酯耐受性","answer":"连续使用硝酸酯类后血管反应性降低、疗效减弱的现象，与巯基耗竭和神经内分泌激活有关，可通过偏心给药、留出无药间期减轻。","rationale":"出自概念手册「抗心绞痛药」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph24_q007","chapter":"第二十四章 抗心绞痛药","chapterIdx":23,"num":7},{"type":"D","stem":"名词解释：β受体阻断药（抗心绞痛）","answer":"通过阻断心脏β1受体减慢心率、减弱心肌收缩力、降低血压而减少心肌耗氧，是稳定型心绞痛长期治疗的基础药物。","rationale":"出自概念手册「抗心绞痛药」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph24_q008","chapter":"第二十四章 抗心绞痛药","chapterIdx":23,"num":8},{"type":"D","stem":"名词解释：钙通道阻滞药（抗心绞痛）","answer":"阻滞血管平滑肌和心肌细胞L型钙通道，扩张冠状动脉、解除血管痉挛并降低心肌收缩力，对变异型心绞痛疗效最好。","rationale":"出自概念手册「抗心绞痛药」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph24_q009","chapter":"第二十四章 抗心绞痛药","chapterIdx":23,"num":9},{"type":"D","stem":"名词解释：硝苯地平","answer":"二氢吡啶类钙通道阻滞药，对血管选择性高，扩张冠状动脉和外周血管作用强，可反射性加快心率，常用于变异型心绞痛及合并高血压者。","rationale":"出自概念手册「抗心绞痛药」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph24_q010","chapter":"第二十四章 抗心绞痛药","chapterIdx":23,"num":10},{"type":"D","stem":"名词解释：地尔硫䓬","answer":"苯硫䓬类钙通道阻滞药，对心脏和血管均有作用，可减慢心率、扩张冠状动脉，适用于变异型及稳定型心绞痛。","rationale":"出自概念手册「抗心绞痛药」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph24_q011","chapter":"第二十四章 抗心绞痛药","chapterIdx":23,"num":11},{"type":"D","stem":"名词解释：变异型心绞痛","answer":"由冠状动脉痉挛引起、多在静息或夜间发作的心绞痛，发作时心电图ST段抬高，治疗首选钙通道阻滞药和硝酸酯类，不宜单用β受体阻断药。","rationale":"出自概念手册「抗心绞痛药」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph24_q012","chapter":"第二十四章 抗心绞痛药","chapterIdx":23,"num":12},{"type":"D","stem":"名词解释：尼可地尔","answer":"钾通道开放药，兼有硝酸酯样释放一氧化氮的作用，可扩张冠状动脉并增加侧支循环，用于各型心绞痛，尤其适用于硝酸酯耐受者。","rationale":"出自概念手册「抗心绞痛药」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph24_q013","chapter":"第二十四章 抗心绞痛药","chapterIdx":23,"num":13},{"type":"D","stem":"名词解释：冠脉窃血现象","answer":"某些血管扩张药使缺血区血流转向正常区、缺血区灌注反而减少的现象，是评价抗心绞痛药扩张血管选择性的重要概念。","rationale":"出自概念手册「抗心绞痛药」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph24_q014","chapter":"第二十四章 抗心绞痛药","chapterIdx":23,"num":14},{"type":"S","stem":"简答题：硝酸甘油抗心绞痛的作用机制是什么？","answer":"①在体内释放NO，激活鸟苷酸环化酶使cGMP增多，松弛血管平滑肌；②扩张静脉，减少回心血量、降低前负荷，缩小心室容积而降低心肌耗氧量；③扩张小动脉降低后负荷，减少射血阻力；④扩张冠脉输送血管和侧支血管，增加缺血区血流灌注，促进侧支循环开放。","rationale":"采分点为NO-cGMP、扩静脉降前负荷、扩动脉降后负荷、扩冠脉与侧支；舌下含服避免首过消除是起效快的关键。","id":"rph24_q015","chapter":"第二十四章 抗心绞痛药","chapterIdx":23,"num":15},{"type":"F","stem":"填空题：硝酸甘油口服首过消除明显，生物利用度仅约______%，故缓解急性发作应______给药，1~2分钟起效。","answer":"①8 ②舌下含服","rationale":"舌下黏膜吸收直接入体循环，避免肝首过消除；硝酸甘油作用维持20~30分钟，连续用药可产生耐受性。","id":"rph24_q016","chapter":"第二十四章 抗心绞痛药","chapterIdx":23,"num":16},{"type":"F","stem":"填空题：β受体阻断药抗心绞痛的主要机制是______，与硝酸酯类合用可互相取消各自的不良反应，但不宜用于______型心绞痛。","answer":"①降低心肌耗氧量 ②变异","rationale":"β受体阻断药减慢心率、减弱收缩力而降低耗氧；变异型心绞痛由冠脉痉挛引起，阻断β受体后α受体作用占优，可加重痉挛。","id":"rph24_q017","chapter":"第二十四章 抗心绞痛药","chapterIdx":23,"num":17},{"type":"T","stem":"判断题：大剂量硝酸甘油可引起高铁血红蛋白血症，出现呕吐、发绀等表现。","options":{"A":"正确","B":"错误"},"answer":["A"],"rationale":"硝酸酯类可使血红蛋白氧化为高铁血红蛋白，大剂量时出现发绀、呕吐；此外常见搏动性头痛、面颊潮红和直立性低血压。","id":"rph24_q018","chapter":"第二十四章 抗心绞痛药","chapterIdx":23,"num":18},{"type":"T","stem":"判断题：变异型心绞痛由冠状动脉痉挛引起，应首选β受体阻断药治疗。","options":{"A":"正确","B":"错误"},"answer":["B"],"rationale":"变异型心绞痛首选钙通道阻滞药，扩张冠状动脉是其显著特点；β受体阻断药可能加重冠脉痉挛，属于禁忌。","id":"rph24_q019","chapter":"第二十四章 抗心绞痛药","chapterIdx":23,"num":19}]},{"title":"第二十五章 治疗充血性心力衰竭药","questions":[{"type":"D","stem":"名词解释：心力衰竭","answer":"各种心脏疾病导致心肌收缩力下降或充盈受限，心输出量不能满足组织代谢需要，并出现肺循环和体循环淤血的临床综合征。","rationale":"出自概念手册「治疗充血性心力衰竭药」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph25_q001","chapter":"第二十五章 治疗充血性心力衰竭药","chapterIdx":24,"num":1},{"type":"D","stem":"名词解释：抗心力衰竭药","answer":"通过增强心肌收缩力、减轻心脏负荷或阻断神经内分泌过度激活，改善心衰症状和预后的药物，包括正性肌力药、利尿药、肾素-血管紧张素系统抑制药和β受体阻断药等。","rationale":"出自概念手册「治疗充血性心力衰竭药」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph25_q002","chapter":"第二十五章 治疗充血性心力衰竭药","chapterIdx":24,"num":2},{"type":"D","stem":"名词解释：心肌重构","answer":"心衰时心肌在神经内分泌因素作用下发生肥厚、纤维化以及心室扩大和形状改变的过程，是心衰进展的关键环节，也是药物治疗的重要靶点。","rationale":"出自概念手册「治疗充血性心力衰竭药」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph25_q003","chapter":"第二十五章 治疗充血性心力衰竭药","chapterIdx":24,"num":3},{"type":"D","stem":"名词解释：前负荷与后负荷","answer":"前负荷指心室舒张末期容积所承受的负荷，主要取决于回心血量；后负荷指心室射血时遇到的阻力，主要取决于外周血管阻力。","rationale":"出自概念手册「治疗充血性心力衰竭药」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph25_q004","chapter":"第二十五章 治疗充血性心力衰竭药","chapterIdx":24,"num":4},{"type":"D","stem":"名词解释：正性肌力药","answer":"能增强心肌收缩力、提高心输出量的药物，包括强心苷类、磷酸二酯酶抑制药和钙增敏剂，用于心衰症状明显或伴低心输出量者。","rationale":"出自概念手册「治疗充血性心力衰竭药」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph25_q005","chapter":"第二十五章 治疗充血性心力衰竭药","chapterIdx":24,"num":5},{"type":"D","stem":"名词解释：强心苷","answer":"一类选择性增强心肌收缩力的苷类化合物，代表药为地高辛和洋地黄毒苷，作用机制为抑制心肌细胞膜钠-钾-腺苷三磷酸酶。","rationale":"出自概念手册「治疗充血性心力衰竭药」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph25_q006","chapter":"第二十五章 治疗充血性心力衰竭药","chapterIdx":24,"num":6},{"type":"D","stem":"名词解释：地高辛","answer":"最常用的强心苷，口服有效，主要经肾排泄，用于慢性心力衰竭伴心房颤动及室上性心动过速，治疗窗窄，易发生中毒。","rationale":"出自概念手册「治疗充血性心力衰竭药」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph25_q007","chapter":"第二十五章 治疗充血性心力衰竭药","chapterIdx":24,"num":7},{"type":"D","stem":"名词解释：洋地黄化","answer":"为迅速控制心衰症状，先给予足够剂量使强心苷达到有效血药浓度即全效量，再用维持量维持疗效的给药方法，现已趋于小剂量化。","rationale":"出自概念手册「治疗充血性心力衰竭药」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph25_q008","chapter":"第二十五章 治疗充血性心力衰竭药","chapterIdx":24,"num":8},{"type":"D","stem":"名词解释：强心苷中毒","answer":"强心苷治疗窗窄，血药浓度过高或存在低钾、低镁、高钙、肾功能不全等诱因时出现的毒性反应，以胃肠道症状、视觉异常和心律失常为特征。","rationale":"出自概念手册「治疗充血性心力衰竭药」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph25_q009","chapter":"第二十五章 治疗充血性心力衰竭药","chapterIdx":24,"num":9},{"type":"D","stem":"名词解释：血管紧张素受体-脑啡肽酶抑制药","answer":"沙库巴曲缬沙坦为代表性复方，缬沙坦阻断AT1受体，沙库巴曲的活性代谢物抑制脑啡肽酶、增加利钠肽，可改善心衰预后。","rationale":"出自概念手册「治疗充血性心力衰竭药」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph25_q010","chapter":"第二十五章 治疗充血性心力衰竭药","chapterIdx":24,"num":10},{"type":"D","stem":"名词解释：磷酸二酯酶Ⅲ抑制药","answer":"抑制心肌和血管平滑肌的磷酸二酯酶Ⅲ，使环磷酸腺苷增多、细胞内钙增加，兼具正性肌力和扩张血管作用，代表药为米力农。","rationale":"出自概念手册「治疗充血性心力衰竭药」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph25_q011","chapter":"第二十五章 治疗充血性心力衰竭药","chapterIdx":24,"num":11},{"type":"D","stem":"名词解释：左西孟旦","answer":"钙增敏剂，增加心肌收缩蛋白对钙的敏感性而增强收缩力，同时开放钾通道扩张血管，不增加心肌耗氧量。","rationale":"出自概念手册「治疗充血性心力衰竭药」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph25_q012","chapter":"第二十五章 治疗充血性心力衰竭药","chapterIdx":24,"num":12},{"type":"D","stem":"名词解释：心衰治疗的金三角","answer":"指ACEI或ARB、β受体阻断药和醛固酮受体拮抗剂三类药物联合应用，可阻断神经内分泌过度激活、逆转重构并显著降低死亡率。","rationale":"出自概念手册「治疗充血性心力衰竭药」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph25_q013","chapter":"第二十五章 治疗充血性心力衰竭药","chapterIdx":24,"num":13},{"type":"D","stem":"名词解释：射血分数降低的心力衰竭","answer":"左室射血分数低于百分之四十的心力衰竭，其治疗以阻断神经内分泌和逆转重构为核心，与射血分数保留者的用药侧重不同。","rationale":"出自概念手册「治疗充血性心力衰竭药」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph25_q014","chapter":"第二十五章 治疗充血性心力衰竭药","chapterIdx":24,"num":14},{"type":"S","stem":"简答题：地高辛正性肌力作用的机制及其对心肌耗氧量的影响如何？","answer":"①抑制心肌细胞膜Na+/K+-ATP酶，使细胞内Na+增多；②通过Na+-Ca2+交换使细胞内Ca2+增加，心肌收缩力增强、心输出量增加；③收缩力增强虽增加耗氧，但心室容积缩小、室壁张力下降，加上心率减慢，总耗氧量不增加甚至有所降低。","rationale":"采分点为抑酶、细胞内钙增加、耗氧不增三条；Na+/K+-ATP酶也是强心苷中毒的靶点，中毒时补钾可竞争性减轻毒性。","id":"rph25_q015","chapter":"第二十五章 治疗充血性心力衰竭药","chapterIdx":24,"num":15},{"type":"F","stem":"填空题：心力衰竭治疗的金三角指______、______和醛固酮拮抗药，三者均可改善预后、降低病死率。","answer":"①ACEI（或ARB） ②β受体阻断药","rationale":"利尿药、强心苷、血管扩张药只改善症状；ACEI、β受体阻断药和醛固酮拮抗药针对心肌重构，能延长生命。","id":"rph25_q016","chapter":"第二十五章 治疗充血性心力衰竭药","chapterIdx":24,"num":16},{"type":"F","stem":"填空题：强心苷中毒所致快速型心律失常可静脉滴注______或使用______，室性心动过速宜用利多卡因；缓慢型心律失常则用______。","answer":"①氯化钾 ②苯妥英钠 ③阿托品","rationale":"苯妥英钠与强心苷竞争Na+/K+-ATP酶，氯化钾补充失钾；缓慢型心律失常不宜补钾，用阿托品降低迷走张力。","id":"rph25_q017","chapter":"第二十五章 治疗充血性心力衰竭药","chapterIdx":24,"num":17},{"type":"T","stem":"判断题：地高辛对伴有心房颤动且心室率快的心力衰竭疗效最好。","options":{"A":"正确","B":"错误"},"answer":["A"],"rationale":"地高辛抑制房室传导、减慢心室率，同时产生正性肌力作用，故对房颤伴快速心室率的心衰疗效最佳。","id":"rph25_q018","chapter":"第二十五章 治疗充血性心力衰竭药","chapterIdx":24,"num":18},{"type":"T","stem":"判断题：β受体阻断药有负性肌力作用，因此禁用于所有慢性心力衰竭患者。","options":{"A":"正确","B":"错误"},"answer":["B"],"rationale":"心衰治疗理念已由禁忌转为提倡，病情稳定、无液体潴留者应从小剂量开始使用，可上调β1受体、拮抗交感过度激活并降低病死率。","id":"rph25_q019","chapter":"第二十五章 治疗充血性心力衰竭药","chapterIdx":24,"num":19}]},{"title":"第二十六章 作用于血液系统的药物","questions":[{"type":"D","stem":"名词解释：抗贫血药","answer":"用于纠正贫血的药物，包括铁剂、叶酸、维生素B12及重组人促红细胞生成素，须按贫血类型选择用药。","rationale":"出自概念手册「作用于血液系统的药物」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph26_q001","chapter":"第二十六章 作用于血液系统的药物","chapterIdx":25,"num":1},{"type":"D","stem":"名词解释：铁剂","answer":"补充体内铁储备的药物，二价铁比三价铁易吸收，用于缺铁性贫血，同服维生素C可促进铁的吸收。","rationale":"出自概念手册「作用于血液系统的药物」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph26_q002","chapter":"第二十六章 作用于血液系统的药物","chapterIdx":25,"num":2},{"type":"D","stem":"名词解释：叶酸","answer":"水溶性B族维生素，在体内转为四氢叶酸参与一碳单位转移和DNA合成，缺乏可引起巨幼细胞性贫血。","rationale":"出自概念手册「作用于血液系统的药物」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph26_q003","chapter":"第二十六章 作用于血液系统的药物","chapterIdx":25,"num":3},{"type":"F","stem":"填空题：水溶性B族维生素，在体内转为四氢______参与一碳单位转移和DNA合成，缺乏可引起巨幼细胞性贫血。","answer":"叶酸","rationale":"出自概念手册「作用于血液系统的药物」核心概念：叶酸。","id":"rph26_q004","chapter":"第二十六章 作用于血液系统的药物","chapterIdx":25,"num":4},{"type":"D","stem":"名词解释：维生素B12","answer":"参与甲基丙二酰辅酶A变位酶反应和甲硫氨酸合成，缺乏可致巨幼细胞性贫血并伴神经系统损害。","rationale":"出自概念手册「作用于血液系统的药物」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph26_q005","chapter":"第二十六章 作用于血液系统的药物","chapterIdx":25,"num":5},{"type":"D","stem":"名词解释：巨幼细胞性贫血","answer":"因叶酸或维生素B12缺乏导致DNA合成障碍的大细胞性贫血，治疗须先明确病因再补充相应维生素。","rationale":"出自概念手册「作用于血液系统的药物」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph26_q006","chapter":"第二十六章 作用于血液系统的药物","chapterIdx":25,"num":6},{"type":"D","stem":"名词解释：促凝血药","answer":"能加速血液凝固或抑制纤维蛋白溶解而止血的药物，如维生素K、氨甲环酸和血凝酶等，用于各种出血性疾病。","rationale":"出自概念手册「作用于血液系统的药物」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph26_q007","chapter":"第二十六章 作用于血液系统的药物","chapterIdx":25,"num":7},{"type":"D","stem":"名词解释：维生素K","answer":"参与凝血因子Ⅱ、Ⅶ、Ⅸ、Ⅹ的γ-羧化，缺乏时这些因子活性下降，用于香豆素类过量和新生儿出血。","rationale":"出自概念手册「作用于血液系统的药物」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph26_q008","chapter":"第二十六章 作用于血液系统的药物","chapterIdx":25,"num":8},{"type":"D","stem":"名词解释：肝素","answer":"黏多糖类抗凝血药，通过激活抗凝血酶Ⅲ灭活凝血酶和Xa因子，起效快，过量可用鱼精蛋白中和。","rationale":"出自概念手册「作用于血液系统的药物」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph26_q009","chapter":"第二十六章 作用于血液系统的药物","chapterIdx":25,"num":9},{"type":"D","stem":"名词解释：低分子肝素","answer":"肝素裂解产物，以抑制Xa因子为主，生物利用度高、半衰期长，出血和血小板减少的风险较低。","rationale":"出自概念手册「作用于血液系统的药物」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph26_q010","chapter":"第二十六章 作用于血液系统的药物","chapterIdx":25,"num":10},{"type":"D","stem":"名词解释：华法林","answer":"香豆素类口服抗凝药，抑制维生素K环氧化物还原酶，减少凝血因子Ⅱ、Ⅶ、Ⅸ、Ⅹ合成，起效较慢。","rationale":"出自概念手册「作用于血液系统的药物」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph26_q011","chapter":"第二十六章 作用于血液系统的药物","chapterIdx":25,"num":11},{"type":"D","stem":"名词解释：国际标准化比值","answer":"又称INR，是校正后的凝血酶原时间比值，用于监测华法林的抗凝强度，目标值因病情而异。","rationale":"出自概念手册「作用于血液系统的药物」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph26_q012","chapter":"第二十六章 作用于血液系统的药物","chapterIdx":25,"num":12},{"type":"D","stem":"名词解释：抗血小板药","answer":"抑制血小板黏附、聚集或释放的药物，如阿司匹林、氯吡格雷，用于动脉血栓性疾病的防治。","rationale":"出自概念手册「作用于血液系统的药物」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph26_q013","chapter":"第二十六章 作用于血液系统的药物","chapterIdx":25,"num":13},{"type":"D","stem":"名词解释：纤维蛋白溶解药","answer":"又称溶栓药，激活纤溶酶原转为纤溶酶，溶解已形成的血栓，用于急性心肌梗死和缺血性脑卒中。","rationale":"出自概念手册「作用于血液系统的药物」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph26_q014","chapter":"第二十六章 作用于血液系统的药物","chapterIdx":25,"num":14},{"type":"D","stem":"名词解释：氨甲环酸","answer":"抗纤溶药，竞争性抑制纤溶酶原激活，用于纤溶亢进引起的出血，如产后出血和手术出血。","rationale":"出自概念手册「作用于血液系统的药物」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph26_q015","chapter":"第二十六章 作用于血液系统的药物","chapterIdx":25,"num":15},{"type":"D","stem":"名词解释：重组人促红细胞生成素","answer":"刺激红系祖细胞增殖分化的造血生长因子，用于肾性贫血和肿瘤化疗相关贫血，用药需补足铁剂。","rationale":"出自概念手册「作用于血液系统的药物」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph26_q016","chapter":"第二十六章 作用于血液系统的药物","chapterIdx":25,"num":16},{"type":"D","stem":"名词解释：粒细胞集落刺激因子","answer":"促进中性粒细胞增殖、分化和释放的造血生长因子，用于化疗后粒细胞减少，常见不良反应为骨痛。","rationale":"出自概念手册「作用于血液系统的药物」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph26_q017","chapter":"第二十六章 作用于血液系统的药物","chapterIdx":25,"num":17},{"type":"D","stem":"名词解释：血容量扩充剂","answer":"能提高血浆胶体渗透压、扩充血容量的药物，如右旋糖酐，用于休克和微循环障碍的防治。","rationale":"出自概念手册「作用于血液系统的药物」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph26_q018","chapter":"第二十六章 作用于血液系统的药物","chapterIdx":25,"num":18},{"type":"S","stem":"简答题：肝素的抗凝机制及主要不良反应与解救措施？","answer":"①肝素带负电荷，与抗凝血酶Ⅲ的赖氨酸残基结合，暴露其精氨酸活性位点；②使抗凝血酶Ⅲ与凝血酶及Ⅹa、Ⅸa、Ⅺa等因子的丝氨酸活性中心结合并使其灭活，反应加速约1000倍；③体内、体外均有强大的抗凝作用；④主要不良反应是出血，严重出血用硫酸鱼精蛋白静脉注射解救；⑤还可致血小板减少、过敏反应和骨质疏松。","rationale":"采分点为AT-Ⅲ介导、灭活凝血酶及Ⅹa等因子、体内外均有效、出血与鱼精蛋白解救；肝素口服不吸收，须静脉给药。","id":"rph26_q019","chapter":"第二十六章 作用于血液系统的药物","chapterIdx":25,"num":19},{"type":"F","stem":"填空题：华法林竞争性拮抗______，抑制凝血因子______的活化，故仅体内有效且显效慢。","answer":"①维生素K ②Ⅱ、Ⅶ、Ⅸ、Ⅹ","rationale":"维生素K是γ-谷氨酸羧化酶的辅酶，华法林阻止维生素K由环氧化物还原为氢醌型，使这些因子停留于无活性的前体阶段。","id":"rph26_q020","chapter":"第二十六章 作用于血液系统的药物","chapterIdx":25,"num":20},{"type":"F","stem":"填空题：阿司匹林小剂量不可逆抑制血小板______，减少______生成而抗血小板聚集；氯吡格雷则不可逆抑制ADP与______受体的结合。","answer":"①COX-1（环氧酶-1） ②TXA2（血栓素A2） ③P2Y12","rationale":"抗血小板药按机制分四类：抑花生四烯酸代谢、增cAMP、抑ADP活化、阻断GPⅡb/Ⅲa受体；氯吡格雷属第三类。","id":"rph26_q021","chapter":"第二十六章 作用于血液系统的药物","chapterIdx":25,"num":21},{"type":"T","stem":"判断题：枸橼酸钠通过络合血中Ca2+产生抗凝作用，仅用于体外抗凝。","options":{"A":"正确","B":"错误"},"answer":["A"],"rationale":"枸橼酸钠与Ca2+形成络合物使凝血受阻，毒性较大，只在血液及血制品保存、输血时作体外抗凝剂。","id":"rph26_q022","chapter":"第二十六章 作用于血液系统的药物","chapterIdx":25,"num":22},{"type":"T","stem":"判断题：链激酶与尿激酶都能直接激活纤溶酶原，且二者均无抗原性。","options":{"A":"正确","B":"错误"},"answer":["B"],"rationale":"链激酶须先与纤溶酶原形成复合物间接激活，且有抗原性可引起过敏反应；尿激酶直接激活纤溶酶原、无抗原性。","id":"rph26_q023","chapter":"第二十六章 作用于血液系统的药物","chapterIdx":25,"num":23}]},{"title":"第二十七章 作用于呼吸系统的药物","questions":[{"type":"D","stem":"名词解释：平喘药","answer":"能缓解支气管平滑肌痉挛、减轻气道炎症而治疗哮喘和慢性阻塞性肺疾病的药物，分为抗炎与解痉两类。","rationale":"出自概念手册「作用于呼吸系统的药物」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph27_q001","chapter":"第二十七章 作用于呼吸系统的药物","chapterIdx":26,"num":1},{"type":"D","stem":"名词解释：β2肾上腺素受体激动剂","answer":"选择性激动支气管平滑肌β2受体，激活腺苷酸环化酶使细胞内cAMP升高、支气管舒张，是缓解喘息症状的主力。","rationale":"出自概念手册「作用于呼吸系统的药物」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph27_q002","chapter":"第二十七章 作用于呼吸系统的药物","chapterIdx":26,"num":2},{"type":"D","stem":"名词解释：沙丁胺醇","answer":"短效β2受体激动剂，吸入后数分钟起效，用于哮喘急性发作和运动性哮喘的缓解，过量可致心悸和手颤。","rationale":"出自概念手册「作用于呼吸系统的药物」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph27_q003","chapter":"第二十七章 作用于呼吸系统的药物","chapterIdx":26,"num":3},{"type":"D","stem":"名词解释：长效β2受体激动剂","answer":"作用维持12小时以上的β2激动剂，如沙美特罗、福莫特罗，须与吸入糖皮质激素联合用于哮喘的维持治疗。","rationale":"出自概念手册「作用于呼吸系统的药物」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph27_q004","chapter":"第二十七章 作用于呼吸系统的药物","chapterIdx":26,"num":4},{"type":"D","stem":"名词解释：吸入性糖皮质激素","answer":"又称ICS，局部抗炎作用强而全身不良反应少，是哮喘长期控制的首选药物，用后须及时漱口。","rationale":"出自概念手册「作用于呼吸系统的药物」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph27_q006","chapter":"第二十七章 作用于呼吸系统的药物","chapterIdx":26,"num":6},{"type":"D","stem":"名词解释：布地奈德","answer":"常用的吸入性糖皮质激素，局部抗炎作用强，用于哮喘和慢性阻塞性肺疾病的长期控制，雾化吸入可用于儿童。","rationale":"出自概念手册「作用于呼吸系统的药物」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph27_q007","chapter":"第二十七章 作用于呼吸系统的药物","chapterIdx":26,"num":7},{"type":"D","stem":"名词解释：白三烯受体拮抗剂","answer":"阻断半胱氨酰白三烯受体，减轻气道炎症与痉挛，口服有效，如孟鲁司特，用于运动性和阿司匹林哮喘。","rationale":"出自概念手册「作用于呼吸系统的药物」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph27_q008","chapter":"第二十七章 作用于呼吸系统的药物","chapterIdx":26,"num":8},{"type":"D","stem":"名词解释：色甘酸钠","answer":"肥大细胞膜稳定剂，抑制抗原激发后炎症介质释放，仅作预防用药，对已发作的哮喘无效。","rationale":"出自概念手册「作用于呼吸系统的药物」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph27_q009","chapter":"第二十七章 作用于呼吸系统的药物","chapterIdx":26,"num":9},{"type":"D","stem":"名词解释：吸入性抗胆碱药","answer":"阻断气道M3受体、减少迷走神经介导的支气管收缩，如异丙托溴铵和噻托溴铵，是慢性阻塞性肺疾病的常用药。","rationale":"出自概念手册「作用于呼吸系统的药物」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph27_q010","chapter":"第二十七章 作用于呼吸系统的药物","chapterIdx":26,"num":10},{"type":"D","stem":"名词解释：镇咳药","answer":"抑制咳嗽反射的药物，分中枢性与外周性两类，用于无痰干咳，痰多者不宜单独使用，以免痰液滞留。","rationale":"出自概念手册「作用于呼吸系统的药物」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph27_q011","chapter":"第二十七章 作用于呼吸系统的药物","chapterIdx":26,"num":11},{"type":"D","stem":"名词解释：中枢性镇咳药","answer":"作用于延髓咳嗽中枢、抑制咳嗽反射的药物，代表药可待因和右美沙芬，用于剧烈干咳，痰多者禁用。","rationale":"出自概念手册「作用于呼吸系统的药物」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph27_q012","chapter":"第二十七章 作用于呼吸系统的药物","chapterIdx":26,"num":12},{"type":"D","stem":"名词解释：右美沙芬","answer":"中枢性镇咳药，镇咳作用与可待因相当而无镇痛和成瘾性，用于干咳，痰多者慎用，过量可致中枢抑制。","rationale":"出自概念手册「作用于呼吸系统的药物」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph27_q013","chapter":"第二十七章 作用于呼吸系统的药物","chapterIdx":26,"num":13},{"type":"D","stem":"名词解释：祛痰药","answer":"使痰液变稀或黏度降低、易于咳出的药物，分为恶心性祛痰药和黏液溶解药两类，常与镇咳药配伍。","rationale":"出自概念手册「作用于呼吸系统的药物」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph27_q014","chapter":"第二十七章 作用于呼吸系统的药物","chapterIdx":26,"num":14},{"type":"F","stem":"填空题：使痰液变稀或黏度降低、易于咳出的药物，分为恶心性______和黏液溶解药两类，常与镇咳药配伍。","answer":"祛痰药","rationale":"出自概念手册「作用于呼吸系统的药物」核心概念：祛痰药。","id":"rph27_q015","chapter":"第二十七章 作用于呼吸系统的药物","chapterIdx":26,"num":15},{"type":"D","stem":"名词解释：乙酰半胱氨酸","answer":"黏液溶解药，断裂痰液中糖蛋白的二硫键而降低黏度，用于痰液黏稠不易咳出者，带有蒜臭味。","rationale":"出自概念手册「作用于呼吸系统的药物」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph27_q016","chapter":"第二十七章 作用于呼吸系统的药物","chapterIdx":26,"num":16},{"type":"D","stem":"名词解释：氯化铵","answer":"恶心性祛痰药，刺激胃黏膜反射性增加呼吸道分泌，使痰变稀，溃疡病和肝肾功能不全者慎用。","rationale":"出自概念手册「作用于呼吸系统的药物」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph27_q017","chapter":"第二十七章 作用于呼吸系统的药物","chapterIdx":26,"num":17},{"type":"D","stem":"名词解释：慢性阻塞性肺疾病","answer":"以持续气流受限为特征的慢性气道疾病，稳定期以长效支气管扩张剂为核心，戒烟是最重要的防治措施。","rationale":"出自概念手册「作用于呼吸系统的药物」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph27_q018","chapter":"第二十七章 作用于呼吸系统的药物","chapterIdx":26,"num":18},{"type":"S","stem":"简答题：吸入型糖皮质激素治疗支气管哮喘的作用与注意事项？","answer":"①抑制气道炎症反应和气道高反应性，抑制炎性细胞、细胞因子及炎症介质产生；②用于慢性哮喘的长期治疗，可减少或终止发作，是抗炎平喘的基础用药；③不能缓解急性症状，哮喘持续状态时不能吸入足够气雾量，不宜应用；④局部不良反应为口咽部念珠菌感染和声音嘶哑，吸入后应漱口；⑤治疗量一般无全身性激素作用，不抑制下丘脑-垂体-肾上腺轴。","rationale":"采分点为抗炎降高反应性、慢性哮喘长期预防、不能急救、口咽念珠菌感染；临床常与长效β2受体激动药联合。","id":"rph27_q019","chapter":"第二十七章 作用于呼吸系统的药物","chapterIdx":26,"num":19},{"type":"F","stem":"填空题：沙丁胺醇选择性激动支气管平滑肌______受体而松弛平滑肌；异丙肾上腺素激动β1受体可致______，激动骨骼肌β2受体可致______。","answer":"①β2 ②心率加快、心悸 ③肌震颤","rationale":"选择性β2受体激动药心血管反应小；非选择性药如异丙肾上腺素平喘强，但心率加快和肌震颤明显。","id":"rph27_q020","chapter":"第二十七章 作用于呼吸系统的药物","chapterIdx":26,"num":20},{"type":"F","stem":"填空题：色甘酸钠通过稳定______细胞膜、抑制其脱颗粒，用于哮喘的______治疗；孟鲁司特阻断______受体。","answer":"①肥大 ②预防性 ③半胱氨酰白三烯（CysLT1）","rationale":"色甘酸钠是炎症细胞膜稳定药，只在预防用药时有效；孟鲁司特属白三烯受体阻断药，用于哮喘的预防和长期治疗。","id":"rph27_q021","chapter":"第二十七章 作用于呼吸系统的药物","chapterIdx":26,"num":21},{"type":"T","stem":"判断题：氨茶碱治疗窗较窄、个体差异大，过量可致心律失常、惊厥甚至呼吸心跳停止。","options":{"A":"正确","B":"错误"},"answer":["A"],"rationale":"茶碱抑制磷酸二酯酶、阻断腺苷受体，安全范围窄，须监测血药浓度；其平喘同时兼有强心、利尿和中枢兴奋作用。","id":"rph27_q022","chapter":"第二十七章 作用于呼吸系统的药物","chapterIdx":26,"num":22},{"type":"T","stem":"判断题：咳嗽伴痰多黏稠、咳痰困难时，应首选强效镇咳药以保护气道。","options":{"A":"正确","B":"错误"},"answer":["B"],"rationale":"痰多黏稠时应先用祛痰药使痰液变稀排出，慎用镇咳药；强效镇咳会抑制排痰，加重感染和气道阻塞。","id":"rph27_q023","chapter":"第二十七章 作用于呼吸系统的药物","chapterIdx":26,"num":23}]},{"title":"第二十八章 作用于消化系统的药物","questions":[{"type":"D","stem":"名词解释：抗消化性溃疡药","answer":"通过中和胃酸、抑制胃酸分泌、保护胃黏膜或根除幽门螺杆菌而促进溃疡愈合的药物总称。","rationale":"出自概念手册「作用于消化系统的药物」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph28_q001","chapter":"第二十八章 作用于消化系统的药物","chapterIdx":27,"num":1},{"type":"D","stem":"名词解释：抗酸药","answer":"弱碱性药物，口服后中和胃酸、降低胃蛋白酶活性，起效快但作用短暂，常与其他抗溃疡药合用。","rationale":"出自概念手册「作用于消化系统的药物」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph28_q002","chapter":"第二十八章 作用于消化系统的药物","chapterIdx":27,"num":2},{"type":"D","stem":"名词解释：质子泵抑制剂","answer":"又称PPI，不可逆抑制胃壁细胞H+、K+-ATP酶，抑酸作用强而持久，是消化性溃疡和反流性食管炎的首选。","rationale":"出自概念手册「作用于消化系统的药物」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph28_q003","chapter":"第二十八章 作用于消化系统的药物","chapterIdx":27,"num":3},{"type":"D","stem":"名词解释：奥美拉唑","answer":"第一个用于临床的质子泵抑制剂，口服后在壁细胞酸性小管中活化，与H+、K+-ATP酶共价结合。","rationale":"出自概念手册「作用于消化系统的药物」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph28_q004","chapter":"第二十八章 作用于消化系统的药物","chapterIdx":27,"num":4},{"type":"D","stem":"名词解释：H2受体阻断药","answer":"竞争性阻断胃壁细胞H2受体，减少胃酸分泌，代表药有西咪替丁、雷尼替丁和法莫替丁。","rationale":"出自概念手册「作用于消化系统的药物」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph28_q005","chapter":"第二十八章 作用于消化系统的药物","chapterIdx":27,"num":5},{"type":"D","stem":"名词解释：西咪替丁","answer":"第一代H2受体阻断药，抑制基础胃酸分泌，同时抑制肝药酶并有抗雄激素作用，可致男性乳房发育。","rationale":"出自概念手册「作用于消化系统的药物」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph28_q006","chapter":"第二十八章 作用于消化系统的药物","chapterIdx":27,"num":6},{"type":"D","stem":"名词解释：胃黏膜保护药","answer":"在溃疡表面形成保护膜或促进黏液与前列腺素合成的药物，如硫糖铝、枸橼酸铋钾和米索前列醇。","rationale":"出自概念手册「作用于消化系统的药物」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph28_q007","chapter":"第二十八章 作用于消化系统的药物","chapterIdx":27,"num":7},{"type":"D","stem":"名词解释：幽门螺杆菌根除治疗","answer":"以质子泵抑制剂加铋剂加两种抗生素组成的四联方案，疗程10至14天，用于幽门螺杆菌阳性者。","rationale":"出自概念手册「作用于消化系统的药物」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph28_q008","chapter":"第二十八章 作用于消化系统的药物","chapterIdx":27,"num":8},{"type":"D","stem":"名词解释：促胃肠动力药","answer":"增强胃肠蠕动、促进胃排空的药物，如多潘立酮、莫沙必利，用于功能性消化不良和胃食管反流。","rationale":"出自概念手册「作用于消化系统的药物」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph28_q009","chapter":"第二十八章 作用于消化系统的药物","chapterIdx":27,"num":9},{"type":"D","stem":"名词解释：甲氧氯普胺","answer":"又称胃复安，阻断中枢与外周多巴胺受体，兼具止吐和促动力作用，易致锥体外系反应，儿童慎用。","rationale":"出自概念手册「作用于消化系统的药物」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph28_q010","chapter":"第二十八章 作用于消化系统的药物","chapterIdx":27,"num":10},{"type":"D","stem":"名词解释：5-HT3受体阻断药","answer":"阻断外周与中枢5-HT3受体而止吐，如昂丹司琼，主要用于化疗、放疗和术后呕吐，可致便秘和QT延长。","rationale":"出自概念手册「作用于消化系统的药物」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph28_q011","chapter":"第二十八章 作用于消化系统的药物","chapterIdx":27,"num":11},{"type":"D","stem":"名词解释：泻药","answer":"促进排便的药物，按机制分为容积性、渗透性、刺激性和润滑性四类，用于便秘和肠道准备。","rationale":"出自概念手册「作用于消化系统的药物」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph28_q012","chapter":"第二十八章 作用于消化系统的药物","chapterIdx":27,"num":12},{"type":"D","stem":"名词解释：容积性泻药","answer":"口服后不被吸收、在肠内吸水膨胀增加肠内容积而导泻，如乳果糖、硫酸镁和甲基纤维素。","rationale":"出自概念手册「作用于消化系统的药物」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph28_q013","chapter":"第二十八章 作用于消化系统的药物","chapterIdx":27,"num":13},{"type":"D","stem":"名词解释：刺激性泻药","answer":"直接刺激肠黏膜或肠神经丛增强蠕动而导泻，如比沙可啶、酚酞，长期使用可致结肠黑变。","rationale":"出自概念手册「作用于消化系统的药物」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph28_q014","chapter":"第二十八章 作用于消化系统的药物","chapterIdx":27,"num":14},{"type":"D","stem":"名词解释：止泻药","answer":"通过抑制肠蠕动、吸附毒素或保护肠黏膜而减轻腹泻的药物，如洛哌丁胺、蒙脱石散，须按腹泻类型选用。","rationale":"出自概念手册「作用于消化系统的药物」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph28_q015","chapter":"第二十八章 作用于消化系统的药物","chapterIdx":27,"num":15},{"type":"D","stem":"名词解释：微生态制剂","answer":"含活菌或其代谢产物的制剂，调节肠道菌群平衡，用于菌群失调所致腹泻，应与抗生素间隔服用。","rationale":"出自概念手册「作用于消化系统的药物」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph28_q016","chapter":"第二十八章 作用于消化系统的药物","chapterIdx":27,"num":16},{"type":"D","stem":"名词解释：熊去氧胆酸","answer":"亲水性胆汁酸，可溶解胆固醇结石并改善胆汁淤积，用于胆固醇性结石和原发性胆汁性胆管炎。","rationale":"出自概念手册「作用于消化系统的药物」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph28_q017","chapter":"第二十八章 作用于消化系统的药物","chapterIdx":27,"num":17},{"type":"S","stem":"简答题：奥美拉唑（质子泵抑制药）的作用机制与临床应用？","answer":"①为前体药物，在胃壁细胞小管的酸性环境中活化；②不可逆抑制H+-K+-ATP酶，抑制基础胃酸和各种刺激引起的胃酸分泌，并减少胃蛋白酶分泌；③用于消化性溃疡、反流性食管炎、上消化道出血和卓-艾综合征；④与抗菌药及铋剂组成三联或四联疗法根除幽门螺杆菌；⑤抑制肝药酶，可减慢华法林、地西泮、苯妥英钠的代谢。","rationale":"采分点为酸性环境活化、不可逆抑质子泵、抑酸全面、联合根除幽门螺杆菌；连续服药效果优于单次服用。","id":"rph28_q018","chapter":"第二十八章 作用于消化系统的药物","chapterIdx":27,"num":18},{"type":"F","stem":"填空题：H2受体阻断药竞争性阻断胃壁细胞基底膜______受体，对______胃酸分泌的抑制作用强；西咪替丁是肝药酶______药，并有抗雄激素作用。","answer":"①H2 ②基础及夜间 ③抑制","rationale":"西咪替丁抑制肝药酶而与其他药物相互作用，并有抗雄激素作用可致男性乳房发育；雷尼替丁、法莫替丁作用更强、副作用较少。","id":"rph28_q019","chapter":"第二十八章 作用于消化系统的药物","chapterIdx":27,"num":19},{"type":"F","stem":"填空题：硫糖铝在胃内形成保护膜，促进胃黏液和______分泌，并抑制______的繁殖；米索前列醇是前列腺素E1衍生物，可用于______引起的消化性溃疡。","answer":"①碳酸氢盐 ②幽门螺杆菌 ③非甾体抗炎药","rationale":"胃黏膜保护药通过形成保护膜、促进黏液和HCO3-分泌、改善黏膜血流起作用；米索前列醇补充前列腺素，对NSAIDs溃疡有效。","id":"rph28_q020","chapter":"第二十八章 作用于消化系统的药物","chapterIdx":27,"num":20},{"type":"T","stem":"判断题：昂丹司琼选择性阻断5-HT3受体，用于肿瘤放疗、化疗及手术后引起的呕吐。","options":{"A":"正确","B":"错误"},"answer":["A"],"rationale":"5-HT3受体阻断药阻断中枢及迷走传入纤维的5-HT3受体，止吐迅速、强大而持久，是放化疗呕吐的首选。","id":"rph28_q021","chapter":"第二十八章 作用于消化系统的药物","chapterIdx":27,"num":21},{"type":"T","stem":"判断题：多潘立酮通过阻断中枢多巴胺D2受体发挥止吐作用，可用于帕金森病患者。","options":{"A":"正确","B":"错误"},"answer":["B"],"rationale":"多潘立酮主要阻断外周胃肠D2受体、不易透过血脑屏障，不拮抗左旋多巴的中枢作用，故可用于左旋多巴所致呕吐；阻断中枢D2受体的是氯丙嗪和甲氧氯普胺。","id":"rph28_q022","chapter":"第二十八章 作用于消化系统的药物","chapterIdx":27,"num":22}]},{"title":"第二十九章 自体活性物质及其影响药物","questions":[{"type":"D","stem":"名词解释：自体活性物质","answer":"又称局部激素，指存在于机体某些组织、生成后释放并以旁分泌或自分泌方式作用于局部的一类内源性活性物质，如组胺、5-羟色胺、前列腺素、白三烯与激肽，多数不进入血液循环或仅短暂进入。","rationale":"出自概念手册「自体活性物质及其影响药物」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph29_q001","chapter":"第二十九章 自体活性物质及其影响药物","chapterIdx":28,"num":1},{"type":"D","stem":"名词解释：H1受体","answer":"分布于血管内皮、支气管与胃肠平滑肌、感觉神经末梢等处，激动后引起血管扩张、毛细血管通透性增高、平滑肌收缩与瘙痒，是过敏反应的主要中介。","rationale":"出自概念手册「自体活性物质及其影响药物」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph29_q003","chapter":"第二十九章 自体活性物质及其影响药物","chapterIdx":28,"num":3},{"type":"D","stem":"名词解释：H2受体","answer":"主要分布于胃壁细胞、心肌与子宫，激动后使胃酸分泌增加、心率加快、心肌收缩力增强，可被西咪替丁等H2受体阻断药竞争性阻断。","rationale":"出自概念手册「自体活性物质及其影响药物」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph29_q004","chapter":"第二十九章 自体活性物质及其影响药物","chapterIdx":28,"num":4},{"type":"F","stem":"填空题：主要分布于胃壁细胞、心肌与子宫，激动后使胃酸分泌增加、心率加快、心肌收缩力增强，可被西咪替丁等______阻断药竞争性阻断。","answer":"H2受体","rationale":"出自概念手册「自体活性物质及其影响药物」核心概念：H2受体。","id":"rph29_q005","chapter":"第二十九章 自体活性物质及其影响药物","chapterIdx":28,"num":5},{"type":"D","stem":"名词解释：H3受体","answer":"主要作为突触前自身受体存在于中枢与外周神经末梢，激动后抑制组胺的合成与释放，并调节其他神经递质的释放，属负反馈调节环节。","rationale":"出自概念手册「自体活性物质及其影响药物」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph29_q006","chapter":"第二十九章 自体活性物质及其影响药物","chapterIdx":28,"num":6},{"type":"D","stem":"名词解释：H4受体","answer":"主要表达于嗜酸性粒细胞、肥大细胞与树突状细胞等免疫细胞，参与趋化、炎症细胞聚集与瘙痒的调节，其选择性配体尚处研究阶段。","rationale":"出自概念手册「自体活性物质及其影响药物」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph29_q007","chapter":"第二十九章 自体活性物质及其影响药物","chapterIdx":28,"num":7},{"type":"D","stem":"名词解释：组胺休克","answer":"快速静脉注射大剂量组胺时，全身小血管扩张、毛细血管通透性急剧增高、血压骤降并伴支气管痉挛，可致休克，故组胺不作静脉注射给药。","rationale":"出自概念手册「自体活性物质及其影响药物」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph29_q008","chapter":"第二十九章 自体活性物质及其影响药物","chapterIdx":28,"num":8},{"type":"D","stem":"名词解释：H1受体阻断药","answer":"竞争性阻断H1受体，对抗组胺引起的血管扩张、通透性增高与平滑肌收缩，主要用于皮肤黏膜变态反应性疾病、晕动病与呕吐，并分第一、二代。","rationale":"出自概念手册「自体活性物质及其影响药物」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph29_q009","chapter":"第二十九章 自体活性物质及其影响药物","chapterIdx":28,"num":9},{"type":"D","stem":"名词解释：第一代H1受体阻断药","answer":"苯海拉明、异丙嗪、氯苯那敏、赛庚啶等，脂溶性高易透过血脑屏障，镇静作用与抗胆碱作用明显，故有嗜睡、口干等不良反应。","rationale":"出自概念手册「自体活性物质及其影响药物」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph29_q010","chapter":"第二十九章 自体活性物质及其影响药物","chapterIdx":28,"num":10},{"type":"D","stem":"名词解释：第二代H1受体阻断药","answer":"氯雷他定、西替利嗪、特非那定、阿司咪唑等，不易透过血脑屏障，镇静与抗胆碱作用弱，但部分品种有心脏毒性。","rationale":"出自概念手册「自体活性物质及其影响药物」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph29_q011","chapter":"第二十九章 自体活性物质及其影响药物","chapterIdx":28,"num":11},{"type":"D","stem":"名词解释：5-羟色胺","answer":"又称血清素，由色氨酸羟化并脱羧生成，约九成存在于肠嗜铬细胞，其余在血小板与中枢，参与情绪、睡眠、体温、摄食与血管张力的调节。","rationale":"出自概念手册「自体活性物质及其影响药物」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph29_q013","chapter":"第二十九章 自体活性物质及其影响药物","chapterIdx":28,"num":13},{"type":"D","stem":"名词解释：5-HT综合征","answer":"应用或合用增强5-羟色胺能神经功能的药物（如单胺氧化酶抑制药与选择性5-羟色胺再摄取抑制药）所致，表现为高热、肌震颤、精神错乱与自主神经功能紊乱。","rationale":"出自概念手册「自体活性物质及其影响药物」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph29_q014","chapter":"第二十九章 自体活性物质及其影响药物","chapterIdx":28,"num":14},{"type":"D","stem":"名词解释：前列腺素","answer":"由花生四烯酸经环氧合酶生成的一类二十碳不饱和脂肪酸，按五碳环结构分A至I等型，作用广泛而强烈，参与炎症、疼痛、发热与生殖调节。","rationale":"出自概念手册「自体活性物质及其影响药物」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph29_q015","chapter":"第二十九章 自体活性物质及其影响药物","chapterIdx":28,"num":15},{"type":"D","stem":"名词解释：米索前列醇","answer":"前列腺素E1衍生物，抑制胃酸分泌并增强胃黏膜保护，用于非甾体抗炎药所致溃疡；与米非司酮序贯应用可终止早期妊娠。","rationale":"出自概念手册「自体活性物质及其影响药物」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph29_q016","chapter":"第二十九章 自体活性物质及其影响药物","chapterIdx":28,"num":16},{"type":"D","stem":"名词解释：白三烯受体阻断药","answer":"孟鲁司特、扎鲁司特等，阻断半胱氨酰白三烯CysLT1受体，减轻气道平滑肌收缩、黏膜水肿与嗜酸性粒细胞浸润，用于哮喘的预防与长期治疗。","rationale":"出自概念手册「自体活性物质及其影响药物」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph29_q017","chapter":"第二十九章 自体活性物质及其影响药物","chapterIdx":28,"num":17},{"type":"D","stem":"名词解释：激肽系统","answer":"由激肽原在激肽释放酶作用下生成缓激肽与赖氨酰缓激肽，作用于B1、B2受体引起血管扩张、血浆外渗、平滑肌收缩与致痛，是炎症的重要介质系统。","rationale":"出自概念手册「自体活性物质及其影响药物」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph29_q018","chapter":"第二十九章 自体活性物质及其影响药物","chapterIdx":28,"num":18},{"type":"D","stem":"名词解释：抑肽酶","answer":"广谱蛋白酶抑制药，可抑制激肽释放酶、纤溶酶与胰蛋白酶，用于急性胰腺炎、休克及体外循环手术中减少出血。","rationale":"出自概念手册「自体活性物质及其影响药物」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph29_q019","chapter":"第二十九章 自体活性物质及其影响药物","chapterIdx":28,"num":19},{"type":"S","stem":"简答题：H1受体阻断药的药理作用与临床应用有哪些？","answer":"①阻断H1受体，对抗组胺引起的支气管和胃肠道平滑肌收缩；②对抗组胺引起的毛细血管扩张与通透性增加，减轻水肿；③第一代药物有中枢抑制作用，表现为镇静、嗜睡；④苯海拉明、异丙嗪有抗胆碱作用，可止吐、防晕；⑤用于荨麻疹、过敏性鼻炎等皮肤黏膜变态反应及晕动病呕吐，对支气管哮喘效果差、过敏性休克无效。","rationale":"采分点为抗H1效应、中枢抑制、抗胆碱止吐防晕、适应证与无效情形；过敏性休克必须用肾上腺素。","id":"rph29_q020","chapter":"第二十九章 自体活性物质及其影响药物","chapterIdx":28,"num":20},{"type":"F","stem":"填空题：组胺由______脱羧生成，外周主要储存于______内；H2受体阻断药的代表药西咪替丁主要用于______。","answer":"①组氨酸 ②肥大细胞 ③消化性溃疡","rationale":"组胺在肥大细胞和嗜碱性粒细胞内合成储存，中枢特定神经元中作为递质；H2受体阻断药抑制胃酸分泌，用于溃疡病。","id":"rph29_q021","chapter":"第二十九章 自体活性物质及其影响药物","chapterIdx":28,"num":21},{"type":"F","stem":"填空题：5-羟色胺又称______，由______脱羧生成；倍他司汀是H1受体激动药，主要用于______。","answer":"①血清素 ②色氨酸 ③内耳眩晕病","rationale":"5-HT由色氨酸羟化再脱羧生成，属自体活性物质；倍他司汀扩张脑干和内耳血管、纠正内耳血管痉挛，用于内耳眩晕病。","id":"rph29_q022","chapter":"第二十九章 自体活性物质及其影响药物","chapterIdx":28,"num":22},{"type":"T","stem":"判断题：H1受体阻断药可用于过敏性休克的抢救。","options":{"A":"正确","B":"错误"},"answer":["B"],"rationale":"过敏性休克时组胺已大量释放，H1受体阻断药不能对抗已发生的强烈病理反应，抢救首选肾上腺素，H1受体阻断药仅作辅助。","id":"rph29_q023","chapter":"第二十九章 自体活性物质及其影响药物","chapterIdx":28,"num":23},{"type":"T","stem":"判断题：第二代H1受体阻断药如氯雷他定不易透过血脑屏障，中枢镇静作用弱。","options":{"A":"正确","B":"错误"},"answer":["A"],"rationale":"第二代药物对H1受体选择性高、脂溶性低，进入中枢少，故嗜睡轻微、适合日间应用，但部分药物需注意心脏毒性。","id":"rph29_q024","chapter":"第二十九章 自体活性物质及其影响药物","chapterIdx":28,"num":24}]},{"title":"第三十章 雌激素、孕激素和女性生殖道药物","questions":[{"type":"D","stem":"名词解释：雌激素受体","answer":"属核受体超家族，有ERα与ERβ两种亚型，分布于生殖器官、乳腺、骨骼、心血管与中枢神经系统，配体结合后调控靶基因转录而发挥效应。","rationale":"出自概念手册「雌激素、孕激素和女性生殖道药物」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph30_q001","chapter":"第三十章 雌激素、孕激素和女性生殖道药物","chapterIdx":29,"num":1},{"type":"D","stem":"名词解释：雌二醇","answer":"卵巢分泌的主要天然雌激素，活性最强，口服易被肝破坏，临床多用其酯类衍生物或经皮、经阴道制剂。","rationale":"出自概念手册「雌激素、孕激素和女性生殖道药物」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph30_q002","chapter":"第三十章 雌激素、孕激素和女性生殖道药物","chapterIdx":29,"num":2},{"type":"D","stem":"名词解释：己烯雌酚","answer":"人工合成的非甾体雌激素，作用强、价廉，曾广泛用于雌激素替代，因可致子代女性生殖道腺癌及子宫内膜癌现已少用。","rationale":"出自概念手册「雌激素、孕激素和女性生殖道药物」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph30_q003","chapter":"第三十章 雌激素、孕激素和女性生殖道药物","chapterIdx":29,"num":3},{"type":"D","stem":"名词解释：尼尔雌醇","answer":"雌三醇衍生物，长效口服雌激素，对阴道与子宫颈有选择性作用而对子宫内膜影响较小，用于绝经后萎缩性阴道炎与老年性尿道炎。","rationale":"出自概念手册「雌激素、孕激素和女性生殖道药物」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph30_q004","chapter":"第三十章 雌激素、孕激素和女性生殖道药物","chapterIdx":29,"num":4},{"type":"D","stem":"名词解释：选择性雌激素受体调节剂","answer":"在不同组织对雌激素受体分别发挥激动或拮抗作用的药物，如他莫昔芬在乳腺拮抗、在骨与子宫内膜激动，雷洛昔芬在骨激动、在乳腺与子宫内膜拮抗。","rationale":"出自概念手册「雌激素、孕激素和女性生殖道药物」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph30_q005","chapter":"第三十章 雌激素、孕激素和女性生殖道药物","chapterIdx":29,"num":5},{"type":"D","stem":"名词解释：他莫昔芬","answer":"竞争性阻断乳腺组织的雌激素受体，用于乳腺癌术后辅助治疗与晚期乳腺癌，可致子宫内膜增生、潮热与静脉血栓。","rationale":"出自概念手册「雌激素、孕激素和女性生殖道药物」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph30_q006","chapter":"第三十章 雌激素、孕激素和女性生殖道药物","chapterIdx":29,"num":6},{"type":"D","stem":"名词解释：氯米芬","answer":"拮抗下丘脑与垂体的雌激素受体，解除雌激素对促性腺激素的负反馈，促进卵泡发育与排卵，用于无排卵性不孕与闭经。","rationale":"出自概念手册「雌激素、孕激素和女性生殖道药物」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph30_q007","chapter":"第三十章 雌激素、孕激素和女性生殖道药物","chapterIdx":29,"num":7},{"type":"D","stem":"名词解释：孕激素","answer":"由黄体与胎盘分泌，以孕酮为代表，使增殖期子宫内膜转为分泌期、降低子宫平滑肌兴奋性、抑制排卵并促进乳腺腺泡发育。","rationale":"出自概念手册「雌激素、孕激素和女性生殖道药物」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph30_q008","chapter":"第三十章 雌激素、孕激素和女性生殖道药物","chapterIdx":29,"num":8},{"type":"D","stem":"名词解释：黄体酮","answer":"天然孕激素，口服易被胃肠与肝破坏，多用肌内注射或阴道给药，用于先兆流产、功能性子宫出血与黄体功能不足。","rationale":"出自概念手册「雌激素、孕激素和女性生殖道药物」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph30_q009","chapter":"第三十章 雌激素、孕激素和女性生殖道药物","chapterIdx":29,"num":9},{"type":"D","stem":"名词解释：甲羟孕酮","answer":"人工合成孕激素，口服有效、作用持久，用于月经失调、功能性子宫出血、子宫内膜癌及长效避孕。","rationale":"出自概念手册「雌激素、孕激素和女性生殖道药物」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph30_q010","chapter":"第三十章 雌激素、孕激素和女性生殖道药物","chapterIdx":29,"num":10},{"type":"D","stem":"名词解释：米非司酮","answer":"抗孕激素药，竞争性阻断孕激素受体，使蜕膜变性坏死、绒毛膜促性腺激素下降，与米索前列醇序贯应用终止早期妊娠。","rationale":"出自概念手册「雌激素、孕激素和女性生殖道药物」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph30_q011","chapter":"第三十章 雌激素、孕激素和女性生殖道药物","chapterIdx":29,"num":11},{"type":"D","stem":"名词解释：缩宫素","answer":"垂体后叶释放的九肽激素，选择性兴奋子宫平滑肌，小剂量加强节律性收缩，大剂量引起强直性收缩，用于引产、催产与产后止血。","rationale":"出自概念手册「雌激素、孕激素和女性生殖道药物」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph30_q012","chapter":"第三十章 雌激素、孕激素和女性生殖道药物","chapterIdx":29,"num":12},{"type":"D","stem":"名词解释：麦角新碱","answer":"麦角生物碱，选择性兴奋子宫平滑肌且作用强而持久，对子宫体与子宫颈均有兴奋作用，主要用于产后出血与子宫复旧，禁用于催产与引产。","rationale":"出自概念手册「雌激素、孕激素和女性生殖道药物」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph30_q013","chapter":"第三十章 雌激素、孕激素和女性生殖道药物","chapterIdx":29,"num":13},{"type":"D","stem":"名词解释：麦角胺","answer":"麦角生物碱，能收缩脑血管与子宫血管，用于偏头痛急性发作，与咖啡因合用可增强疗效并减少用量。","rationale":"出自概念手册「雌激素、孕激素和女性生殖道药物」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph30_q014","chapter":"第三十章 雌激素、孕激素和女性生殖道药物","chapterIdx":29,"num":14},{"type":"D","stem":"名词解释：子宫平滑肌抑制药","answer":"又称保胎药，包括利托君、硫酸镁、硝苯地平与阿托西班等，通过降低子宫平滑肌细胞内钙或抑制收缩蛋白磷酸化而抑制宫缩，用于防治早产。","rationale":"出自概念手册「雌激素、孕激素和女性生殖道药物」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph30_q015","chapter":"第三十章 雌激素、孕激素和女性生殖道药物","chapterIdx":29,"num":15},{"type":"D","stem":"名词解释：利托君","answer":"β2受体激动药，兴奋子宫平滑肌β2受体而抑制宫缩，用于早产防治，可致母体心率增快、心悸、震颤与血糖升高。","rationale":"出自概念手册「雌激素、孕激素和女性生殖道药物」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph30_q016","chapter":"第三十章 雌激素、孕激素和女性生殖道药物","chapterIdx":29,"num":16},{"type":"D","stem":"名词解释：复方短效口服避孕药","answer":"由雌激素与孕激素配伍制成的甾体避孕药，通过抑制排卵、改变宫颈黏液性状与子宫内膜形态而避孕，如复方炔诺酮片。","rationale":"出自概念手册「雌激素、孕激素和女性生殖道药物」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph30_q017","chapter":"第三十章 雌激素、孕激素和女性生殖道药物","chapterIdx":29,"num":17},{"type":"D","stem":"名词解释：紧急避孕药","answer":"无保护性生活后一定时间内应用的补救避孕药，常用大剂量左炔诺孕酮或米非司酮，通过阻止或延迟排卵、干扰着床而发挥作用。","rationale":"出自概念手册「雌激素、孕激素和女性生殖道药物」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph30_q018","chapter":"第三十章 雌激素、孕激素和女性生殖道药物","chapterIdx":29,"num":18},{"type":"S","stem":"简答题：缩宫素与麦角新碱对子宫作用的区别及其用途？","answer":"①缩宫素选择性兴奋子宫平滑肌，小剂量加强子宫体的节律性收缩、对子宫颈作用弱，可用于引产、催产和产后止血；②麦角新碱对子宫体和子宫颈均有强直性收缩作用，作用强而持久，只用于产后出血和子宫复旧；③麦角新碱禁用于催产和引产，以免引起子宫破裂和胎儿窒息；④缩宫素的敏感性随妊娠进展而升高，妊娠早期不敏感、临产时最敏感。","rationale":"采分点为节律性与强直性收缩之别、缩宫素可催产引产、麦角新碱只能产后用、敏感性随孕周变化，这是二者用途分野的药理依据。","id":"rph30_q019","chapter":"第三十章 雌激素、孕激素和女性生殖道药物","chapterIdx":29,"num":19},{"type":"F","stem":"填空题：雌激素使子宫内膜______，孕激素使增殖期子宫内膜转为______；有子宫的妇女单用雌激素可增加______癌的风险，故须加用孕激素。","answer":"①增生 ②分泌期 ③子宫内膜","rationale":"雌激素促内膜增生、孕激素使其转化为分泌期，即所谓孕激素保护；长期单用雌激素与子宫内膜癌相关。","id":"rph30_q020","chapter":"第三十章 雌激素、孕激素和女性生殖道药物","chapterIdx":29,"num":20},{"type":"F","stem":"填空题：他莫昔芬在乳腺组织______雌激素受体，用于______的辅助治疗；氯米芬拮抗下丘脑与垂体的雌激素受体，用于______。","answer":"①竞争性阻断 ②乳腺癌 ③无排卵性不孕","rationale":"二者同属选择性雌激素受体调节剂，但组织选择性不同：他莫昔芬在乳腺拮抗、在骨与子宫内膜激动，氯米芬解除负反馈而促排卵。","id":"rph30_q021","chapter":"第三十章 雌激素、孕激素和女性生殖道药物","chapterIdx":29,"num":21},{"type":"T","stem":"判断题：米非司酮竞争性阻断孕激素受体，与米索前列醇序贯应用可用于终止早期妊娠。","options":{"A":"正确","B":"错误"},"answer":["A"],"rationale":"米非司酮使蜕膜变性坏死、绒毛膜促性腺激素下降，米索前列醇兴奋子宫并促宫颈成熟，二者序贯用于药物流产。","id":"rph30_q022","chapter":"第三十章 雌激素、孕激素和女性生殖道药物","chapterIdx":29,"num":22},{"type":"T","stem":"判断题：黄体酮口服吸收好、首过消除小，是治疗先兆流产的首选口服制剂。","options":{"A":"正确","B":"错误"},"answer":["B"],"rationale":"天然黄体酮口服易被胃肠和肝破坏、生物利用度低，多用肌内注射或阴道给药；口服有效的是甲羟孕酮等合成孕激素。","id":"rph30_q023","chapter":"第三十章 雌激素、孕激素和女性生殖道药物","chapterIdx":29,"num":23}]},{"title":"第三十一章 雄激素和男科药物","questions":[{"type":"D","stem":"名词解释：雄激素","answer":"由睾丸间质细胞分泌的甾体激素，主要为睾酮，促进男性生殖器官发育、第二性征出现与精子生成，并有促进蛋白质合成的作用。","rationale":"出自概念手册「雄激素和男科药物」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph31_q001","chapter":"第三十一章 雄激素和男科药物","chapterIdx":30,"num":1},{"type":"D","stem":"名词解释：睾酮","answer":"天然雄激素，口服易被肝迅速破坏，须肌内注射或经皮给药；在体内部分经5α-还原酶转化为双氢睾酮，部分芳香化为雌二醇。","rationale":"出自概念手册「雄激素和男科药物」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph31_q002","chapter":"第三十一章 雄激素和男科药物","chapterIdx":30,"num":2},{"type":"F","stem":"填空题：天然雄激素，口服易被肝迅速破坏，须肌内注射或经皮给药；在体内部分经5α-还原酶转化为双氢______，部分芳香化为雌二醇。","answer":"睾酮","rationale":"出自概念手册「雄激素和男科药物」核心概念：睾酮。","id":"rph31_q003","chapter":"第三十一章 雄激素和男科药物","chapterIdx":30,"num":3},{"type":"D","stem":"名词解释：双氢睾酮","answer":"睾酮经5α-还原酶转化的活性代谢物，与雄激素受体亲和力高于睾酮，是前列腺增生、痤疮与雄激素性脱发的重要中介。","rationale":"出自概念手册「雄激素和男科药物」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph31_q004","chapter":"第三十一章 雄激素和男科药物","chapterIdx":30,"num":4},{"type":"D","stem":"名词解释：甲睾酮","answer":"口服有效的雄激素制剂，因经肝代谢而肝损害明显，现已少用，可用于男性性腺功能减退与绝经后乳腺癌。","rationale":"出自概念手册「雄激素和男科药物」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph31_q005","chapter":"第三十一章 雄激素和男科药物","chapterIdx":30,"num":5},{"type":"D","stem":"名词解释：丙酸睾酮","answer":"睾酮的丙酸酯，肌内注射后吸收缓慢、作用持久，是临床常用的雄激素制剂，用于性腺功能减退与功能性子宫出血。","rationale":"出自概念手册「雄激素和男科药物」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph31_q006","chapter":"第三十一章 雄激素和男科药物","chapterIdx":30,"num":6},{"type":"D","stem":"名词解释：同化激素","answer":"雄激素作用减弱而同化作用相对增强的睾酮衍生物，如苯丙酸诺龙、司坦唑醇，用于蛋白质分解过强的消耗性疾病。","rationale":"出自概念手册「雄激素和男科药物」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph31_q007","chapter":"第三十一章 雄激素和男科药物","chapterIdx":30,"num":7},{"type":"D","stem":"名词解释：苯丙酸诺龙","answer":"同化作用强而雄激素作用弱的衍生物，肌内注射作用持久，用于严重烧伤、慢性消耗性疾病与骨质疏松，长期应用可致女性男性化。","rationale":"出自概念手册「雄激素和男科药物」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph31_q008","chapter":"第三十一章 雄激素和男科药物","chapterIdx":30,"num":8},{"type":"D","stem":"名词解释：5α-还原酶抑制药","answer":"非那雄胺、依普甾胺等抑制睾酮转化为双氢睾酮，使前列腺体积缩小、尿道阻力下降，用于良性前列腺增生。","rationale":"出自概念手册「雄激素和男科药物」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph31_q009","chapter":"第三十一章 雄激素和男科药物","chapterIdx":30,"num":9},{"type":"D","stem":"名词解释：非那雄胺","answer":"选择性抑制Ⅱ型5α-还原酶，降低前列腺内双氢睾酮浓度，起效慢需长期服用，可致性欲减退与勃起功能障碍。","rationale":"出自概念手册「雄激素和男科药物」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph31_q010","chapter":"第三十一章 雄激素和男科药物","chapterIdx":30,"num":10},{"type":"D","stem":"名词解释：α1受体阻断药","answer":"特拉唑嗪、坦索罗辛等阻断前列腺与膀胱颈的α1受体，松弛平滑肌、迅速改善排尿症状，是治疗前列腺增生的一线药物。","rationale":"出自概念手册「雄激素和男科药物」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph31_q011","chapter":"第三十一章 雄激素和男科药物","chapterIdx":30,"num":11},{"type":"D","stem":"名词解释：良性前列腺增生","answer":"中老年男性前列腺组织良性增生引起膀胱出口梗阻的疾病，表现为尿频、尿急、夜尿增多、排尿困难与尿线变细。","rationale":"出自概念手册「雄激素和男科药物」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph31_q012","chapter":"第三十一章 雄激素和男科药物","chapterIdx":30,"num":12},{"type":"D","stem":"名词解释：磷酸二酯酶5抑制药","answer":"西地那非、他达拉非、伐地那非等抑制磷酸二酯酶5、减少环磷酸鸟苷降解，使阴茎海绵体平滑肌舒张，用于勃起功能障碍。","rationale":"出自概念手册「雄激素和男科药物」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph31_q013","chapter":"第三十一章 雄激素和男科药物","chapterIdx":30,"num":13},{"type":"D","stem":"名词解释：勃起功能障碍","answer":"阴茎持续不能达到或维持足够勃起以完成满意性生活的状态，多与血管、神经、内分泌及心理因素有关，是男科常见病。","rationale":"出自概念手册「雄激素和男科药物」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph31_q014","chapter":"第三十一章 雄激素和男科药物","chapterIdx":30,"num":14},{"type":"D","stem":"名词解释：西地那非","answer":"选择性磷酸二酯酶5抑制药，须在性刺激下才能增强勃起，禁与硝酸酯类药物合用，否则可致严重低血压。","rationale":"出自概念手册「雄激素和男科药物」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph31_q015","chapter":"第三十一章 雄激素和男科药物","chapterIdx":30,"num":15},{"type":"D","stem":"名词解释：男性避孕药","answer":"通过抑制精子生成或干扰精子成熟而达到避孕目的的药物，包括激素类与非激素类，目前多处于研究阶段，尚无成熟上市产品。","rationale":"出自概念手册「雄激素和男科药物」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph31_q017","chapter":"第三十一章 雄激素和男科药物","chapterIdx":30,"num":17},{"type":"D","stem":"名词解释：棉酚","answer":"从棉花根皮中提取的多元酚类化合物，可抑制精子生成，曾试用为男性避孕药，因可致低血钾与不可逆性不育而受限。","rationale":"出自概念手册「雄激素和男科药物」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph31_q018","chapter":"第三十一章 雄激素和男科药物","chapterIdx":30,"num":18},{"type":"S","stem":"简答题：治疗良性前列腺增生的两类主要药物及其特点？","answer":"①α1受体阻断药如特拉唑嗪、坦索罗辛，阻断前列腺和膀胱颈α1受体，松弛平滑肌，迅速改善排尿症状，是一线对症用药；②5α-还原酶抑制药如非那雄胺，抑制睾酮转化为双氢睾酮，使前列腺体积缩小、尿道阻力下降，但起效慢需长期服用；③α1受体阻断药首剂可致体位性低血压，应从小剂量开始并睡前服；④非那雄胺可使血清前列腺特异性抗原下降约一半，用药前应排除前列腺癌；⑤两类药可联合应用，兼顾近期症状与远期体积缩小。","rationale":"记一快一慢：α1受体阻断药改善症状快，5α-还原酶抑制药缩小体积慢；PSA下降易掩盖前列腺癌是易忽略的考点。","id":"rph31_q019","chapter":"第三十一章 雄激素和男科药物","chapterIdx":30,"num":19},{"type":"F","stem":"填空题：睾酮在体内经______酶转化为双氢睾酮，非那雄胺选择性抑制______型该酶；西地那非抑制______，禁与______类药物合用。","answer":"①5α-还原 ②Ⅱ ③磷酸二酯酶5（PDE5） ④硝酸酯","rationale":"双氢睾酮与雄激素受体亲和力高于睾酮，是前列腺增生的重要中介；PDE5抑制药与硝酸酯类均升高cGMP，合用可致血压骤降。","id":"rph31_q020","chapter":"第三十一章 雄激素和男科药物","chapterIdx":30,"num":20},{"type":"F","stem":"填空题：同化激素的______作用相对增强而雄激素作用减弱；儿童过早应用雄激素可致______过早闭合而身材矮小。","answer":"①同化（蛋白质合成） ②骨骺","rationale":"同化激素只是作用比例改变，仍不能完全避免男性化；雄激素促进骨骺闭合，儿童使用须严格掌握适应证与疗程。","id":"rph31_q021","chapter":"第三十一章 雄激素和男科药物","chapterIdx":30,"num":21},{"type":"T","stem":"判断题：西地那非在无性刺激的情况下也能直接引起阴茎勃起。","options":{"A":"正确","B":"错误"},"answer":["B"],"rationale":"PDE5抑制药须在性刺激下由NO-cGMP通路启动才能增强勃起，单用不能诱发勃起；且禁与硝酸酯类合用。","id":"rph31_q022","chapter":"第三十一章 雄激素和男科药物","chapterIdx":30,"num":22},{"type":"T","stem":"判断题：雄激素可促进蛋白质合成、减少氨基酸分解，使机体呈正氮平衡，并促进骨钙沉积。","options":{"A":"正确","B":"错误"},"answer":["A"],"rationale":"这是雄激素的同化作用，可用于慢性消耗性疾病；但可致水钠潴留、肝功能损害，女性出现男性化表现。","id":"rph31_q023","chapter":"第三十一章 雄激素和男科药物","chapterIdx":30,"num":23}]},{"title":"第三十二章 肾上腺皮质激素类药物","questions":[{"type":"D","stem":"名词解释：肾上腺皮质激素","answer":"肾上腺皮质分泌的甾体激素总称，按作用分为盐皮质激素、糖皮质激素和性激素三类，临床多用其人工合成类似物。","rationale":"出自概念手册「肾上腺皮质激素类药物」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph32_q001","chapter":"第三十二章 肾上腺皮质激素类药物","chapterIdx":31,"num":1},{"type":"D","stem":"名词解释：糖皮质激素（GC）","answer":"由肾上腺皮质束状带合成和分泌，受促肾上腺皮质激素调节，主要影响糖、脂肪和蛋白质代谢，并具有强大的抗炎与免疫抑制作用。","rationale":"出自概念手册「肾上腺皮质激素类药物」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph32_q002","chapter":"第三十二章 肾上腺皮质激素类药物","chapterIdx":31,"num":2},{"type":"D","stem":"名词解释：盐皮质激素","answer":"由球状带分泌，以醛固酮和去氧皮质酮为代表，促进肾远曲小管和集合管保钠排钾，维持水盐平衡，分泌主要受肾素-血管紧张素系统调节。","rationale":"出自概念手册「肾上腺皮质激素类药物」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph32_q003","chapter":"第三十二章 肾上腺皮质激素类药物","chapterIdx":31,"num":3},{"type":"D","stem":"名词解释：下丘脑-垂体-肾上腺轴（HPA轴）","answer":"由促肾上腺皮质激素释放激素、促肾上腺皮质激素和皮质醇构成的负反馈调节系统，长期大剂量应用糖皮质激素可抑制该轴。","rationale":"出自概念手册「肾上腺皮质激素类药物」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph32_q004","chapter":"第三十二章 肾上腺皮质激素类药物","chapterIdx":31,"num":4},{"type":"D","stem":"名词解释：糖皮质激素受体（GR）","answer":"位于胞质内的甾体激素受体，激素进入细胞后与之结合形成复合物转入核内，调控靶基因转录而发挥基因效应。","rationale":"出自概念手册「肾上腺皮质激素类药物」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph32_q005","chapter":"第三十二章 肾上腺皮质激素类药物","chapterIdx":31,"num":5},{"type":"D","stem":"名词解释：允许作用","answer":"糖皮质激素本身不产生直接效应，但可为其他激素或递质发挥作用创造条件，如增强儿茶酚胺的缩血管作用，提高支气管平滑肌对儿茶酚胺的敏感性。","rationale":"出自概念手册「肾上腺皮质激素类药物」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph32_q006","chapter":"第三十二章 肾上腺皮质激素类药物","chapterIdx":31,"num":6},{"type":"D","stem":"名词解释：糖皮质激素停药反跳","answer":"长期用药后突然停药，原有疾病复发或加重，系HPA轴受抑、内源性激素分泌不足所致，需缓慢减量停药。","rationale":"出自概念手册「肾上腺皮质激素类药物」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph32_q007","chapter":"第三十二章 肾上腺皮质激素类药物","chapterIdx":31,"num":7},{"type":"D","stem":"名词解释：医源性肾上腺皮质功能不全","answer":"长期大剂量应用糖皮质激素致HPA轴抑制、肾上腺皮质萎缩，停药后内源性激素分泌不足，遇感染、创伤等应激可诱发危象。","rationale":"出自概念手册「肾上腺皮质激素类药物」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph32_q008","chapter":"第三十二章 肾上腺皮质激素类药物","chapterIdx":31,"num":8},{"type":"D","stem":"名词解释：隔日疗法","answer":"将两日总量于隔日清晨一次顿服，使血药浓度在夜间降至最低，以减轻对HPA轴的抑制，适用于需长期维持治疗者。","rationale":"出自概念手册「肾上腺皮质激素类药物」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph32_q009","chapter":"第三十二章 肾上腺皮质激素类药物","chapterIdx":31,"num":9},{"type":"D","stem":"名词解释：替代疗法","answer":"对肾上腺皮质功能减退者补充生理需要量的糖皮质激素，必要时加用盐皮质激素，以维持正常生理功能。","rationale":"出自概念手册「肾上腺皮质激素类药物」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph32_q010","chapter":"第三十二章 肾上腺皮质激素类药物","chapterIdx":31,"num":10},{"type":"D","stem":"名词解释：氢化可的松","answer":"天然糖皮质激素，抗炎作用弱、水钠潴留明显，可用于生理性替代治疗，且有静脉制剂，适用于急症抢救。","rationale":"出自概念手册「肾上腺皮质激素类药物」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph32_q011","chapter":"第三十二章 肾上腺皮质激素类药物","chapterIdx":31,"num":11},{"type":"D","stem":"名词解释：泼尼松","answer":"人工合成中效糖皮质激素，须在肝内转化为泼尼松龙才有活性，故严重肝功能不全者宜改用泼尼松龙。","rationale":"出自概念手册「肾上腺皮质激素类药物」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph32_q012","chapter":"第三十二章 肾上腺皮质激素类药物","chapterIdx":31,"num":12},{"type":"F","stem":"填空题：人工合成中效糖皮质激素，须在肝内转化为______龙才有活性，故严重肝功能不全者宜改用泼尼松龙。","answer":"泼尼松","rationale":"出自概念手册「肾上腺皮质激素类药物」核心概念：泼尼松。","id":"rph32_q013","chapter":"第三十二章 肾上腺皮质激素类药物","chapterIdx":31,"num":13},{"type":"D","stem":"名词解释：地塞米松","answer":"长效强效含氟糖皮质激素，抗炎作用强而水钠潴留弱，可用于脑水肿、过敏性疾病及地塞米松抑制试验。","rationale":"出自概念手册「肾上腺皮质激素类药物」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph32_q014","chapter":"第三十二章 肾上腺皮质激素类药物","chapterIdx":31,"num":14},{"type":"F","stem":"填空题：长效强效含氟糖皮质激素，抗炎作用强而水钠潴留弱，可用于脑水肿、过敏性疾病及______抑制试验。","answer":"地塞米松","rationale":"出自概念手册「肾上腺皮质激素类药物」核心概念：地塞米松。","id":"rph32_q015","chapter":"第三十二章 肾上腺皮质激素类药物","chapterIdx":31,"num":15},{"type":"D","stem":"名词解释：库欣综合征","answer":"糖皮质激素过多引起的向心性肥胖、满月脸、水牛背、皮肤紫纹、血糖升高等症候群，长期大剂量用药可产生类似表现，停药后多逐渐恢复。","rationale":"出自概念手册「肾上腺皮质激素类药物」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph32_q016","chapter":"第三十二章 肾上腺皮质激素类药物","chapterIdx":31,"num":16},{"type":"D","stem":"名词解释：促肾上腺皮质激素（ACTH）","answer":"腺垂体分泌的激素，促进肾上腺皮质合成与分泌糖皮质激素，仅对皮质功能尚存者有效，反复使用可产生抗体。","rationale":"出自概念手册「肾上腺皮质激素类药物」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph32_q017","chapter":"第三十二章 肾上腺皮质激素类药物","chapterIdx":31,"num":17},{"type":"D","stem":"名词解释：肾上腺危象","answer":"肾上腺皮质功能急性衰竭的危重状态，表现为高热、恶心呕吐、血压下降和休克，须立即静脉补充氢化可的松。","rationale":"出自概念手册「肾上腺皮质激素类药物」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph32_q018","chapter":"第三十二章 肾上腺皮质激素类药物","chapterIdx":31,"num":18},{"type":"S","stem":"简答题：糖皮质激素抗炎作用的特点及其二重性？","answer":"①抗炎作用强大，可抑制物理性、化学性、生物性、免疫性及无菌性炎症；②炎症早期减轻血管反应、降低毛细血管通透性，减少渗出和水肿，抑制白细胞浸润与吞噬，改善红、肿、热、痛；③炎症后期抑制毛细血管和成纤维细胞增生，延缓胶原与肉芽组织增生，防止粘连和瘢痕形成；④抗炎不抗菌，抑制炎症的同时降低机体防御功能，可致感染扩散、阻碍创面愈合，故感染时必须合用足量有效抗菌药。","rationale":"采分点为抗炎范围广、早期作用、后期作用、二重性；抗炎药不等于抗菌药是常考的辨析点。","id":"rph32_q019","chapter":"第三十二章 肾上腺皮质激素类药物","chapterIdx":31,"num":19},{"type":"F","stem":"填空题：可的松和泼尼松须在肝内C11位由______转变为羟基才有活性，故严重肝功能不全时应选用______或泼尼松龙。","answer":"①酮基 ②氢化可的松","rationale":"C11为酮基者需经肝转化才有活性，C11为羟基者直接有活性，这是肝病患者选药的依据。","id":"rph32_q020","chapter":"第三十二章 肾上腺皮质激素类药物","chapterIdx":31,"num":20},{"type":"F","stem":"填空题：长期大量应用糖皮质激素可致______肾上腺皮质功能亢进，并诱发或加重感染、骨质疏松；停药时须______，不可骤停。","answer":"①医源性 ②缓慢减量","rationale":"长期用药反馈抑制垂体-肾上腺皮质轴，骤停可致皮质功能不全和反跳现象；停药须缓慢减量，必要时连用ACTH。","id":"rph32_q021","chapter":"第三十二章 肾上腺皮质激素类药物","chapterIdx":31,"num":21},{"type":"T","stem":"判断题：糖皮质激素具有强大的抗炎作用，能直接中和内毒素并对抗外毒素。","options":{"A":"正确","B":"错误"},"answer":["B"],"rationale":"激素可提高机体对内毒素的耐受力、缓解毒血症状，但不能中和内毒素，对革兰阳性菌产生的外毒素也无效。","id":"rph32_q022","chapter":"第三十二章 肾上腺皮质激素类药物","chapterIdx":31,"num":22},{"type":"T","stem":"判断题：糖皮质激素可用于感染中毒性休克的辅助治疗，但必须以足量有效的抗菌药物治疗为前提。","options":{"A":"正确","B":"错误"},"answer":["A"],"rationale":"抗休克时激素大剂量短程使用，抑制炎症因子、稳定溶酶体膜，同时必须用足量抗菌药，疗程一般不超过3天。","id":"rph32_q023","chapter":"第三十二章 肾上腺皮质激素类药物","chapterIdx":31,"num":23}]},{"title":"第三十三章 甲状腺激素与抗甲状腺药","questions":[{"type":"D","stem":"名词解释：甲状腺激素","answer":"甲状腺滤泡上皮细胞合成的酪氨酸碘化物，包括甲状腺素（T4）和三碘甲状腺原氨酸（T3），调节生长发育和物质代谢。","rationale":"出自概念手册「甲状腺激素与抗甲状腺药」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph33_q001","chapter":"第三十三章 甲状腺激素与抗甲状腺药","chapterIdx":32,"num":1},{"type":"D","stem":"名词解释：甲状腺素（T4）","answer":"甲状腺分泌的主要形式，在外周组织脱碘生成T3后发挥作用，本身作用弱而持久，半衰期较长。","rationale":"出自概念手册「甲状腺激素与抗甲状腺药」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph33_q002","chapter":"第三十三章 甲状腺激素与抗甲状腺药","chapterIdx":32,"num":2},{"type":"D","stem":"名词解释：三碘甲状腺原氨酸（T3）","answer":"活性最强的甲状腺激素，与核受体亲和力高，起效快，是甲状腺激素发挥作用的主要形式。","rationale":"出自概念手册「甲状腺激素与抗甲状腺药」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph33_q003","chapter":"第三十三章 甲状腺激素与抗甲状腺药","chapterIdx":32,"num":3},{"type":"D","stem":"名词解释：钠-碘同向转运体（NIS，碘泵）","answer":"位于甲状腺滤泡上皮基侧膜的转运蛋白，能逆电化学梯度主动摄取血浆中的碘，是甲状腺聚碘的基础。","rationale":"出自概念手册「甲状腺激素与抗甲状腺药」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph33_q004","chapter":"第三十三章 甲状腺激素与抗甲状腺药","chapterIdx":32,"num":4},{"type":"D","stem":"名词解释：甲状腺过氧化物酶（TPO）","answer":"催化碘离子氧化、酪氨酸碘化以及碘化酪氨酸偶联的关键酶，是硫脲类抗甲状腺药的作用靶点。","rationale":"出自概念手册「甲状腺激素与抗甲状腺药」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph33_q005","chapter":"第三十三章 甲状腺激素与抗甲状腺药","chapterIdx":32,"num":5},{"type":"D","stem":"名词解释：甲状腺球蛋白（TG）","answer":"甲状腺滤泡腔内的糖蛋白，甲状腺激素以碘化酪氨酸形式储存于其上，经蛋白水解后释放T3、T4入血。","rationale":"出自概念手册「甲状腺激素与抗甲状腺药」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph33_q006","chapter":"第三十三章 甲状腺激素与抗甲状腺药","chapterIdx":32,"num":6},{"type":"D","stem":"名词解释：抗甲状腺药","answer":"能抑制甲状腺激素合成与释放、破坏甲状腺组织或阻断其外周效应的药物，包括硫脲类、碘及碘化物、放射性碘和β受体阻断药。","rationale":"出自概念手册「甲状腺激素与抗甲状腺药」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph33_q007","chapter":"第三十三章 甲状腺激素与抗甲状腺药","chapterIdx":32,"num":7},{"type":"D","stem":"名词解释：硫脲类","answer":"包括硫氧嘧啶类的丙硫氧嘧啶和咪唑类的甲巯咪唑、卡比马唑，通过抑制甲状腺过氧化物酶阻碍甲状腺激素合成。","rationale":"出自概念手册「甲状腺激素与抗甲状腺药」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph33_q008","chapter":"第三十三章 甲状腺激素与抗甲状腺药","chapterIdx":32,"num":8},{"type":"D","stem":"名词解释：丙硫氧嘧啶（PTU）","answer":"硫脲类代表药，除抑制TPO外还能抑制外周T4脱碘生成T3，起效较快，适用于甲亢危象和妊娠早期。","rationale":"出自概念手册「甲状腺激素与抗甲状腺药」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph33_q009","chapter":"第三十三章 甲状腺激素与抗甲状腺药","chapterIdx":32,"num":9},{"type":"D","stem":"名词解释：甲巯咪唑","answer":"咪唑类抗甲状腺药，抑制TPO的作用强而持久，半衰期较长，是甲亢内科治疗的常用首选药。","rationale":"出自概念手册「甲状腺激素与抗甲状腺药」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph33_q010","chapter":"第三十三章 甲状腺激素与抗甲状腺药","chapterIdx":32,"num":10},{"type":"D","stem":"名词解释：放射性碘（131I）","answer":"被甲状腺高度摄取后释放β射线，破坏甲状腺实质而减少激素分泌，用于甲亢和甲状腺癌的辅助治疗。","rationale":"出自概念手册「甲状腺激素与抗甲状腺药」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph33_q011","chapter":"第三十三章 甲状腺激素与抗甲状腺药","chapterIdx":32,"num":11},{"type":"D","stem":"名词解释：甲状腺危象","answer":"甲亢在感染、手术、创伤等诱因下急剧加重的急症，表现为高热、心动过速、烦躁和呕吐，须综合抢救。","rationale":"出自概念手册「甲状腺激素与抗甲状腺药」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph33_q012","chapter":"第三十三章 甲状腺激素与抗甲状腺药","chapterIdx":32,"num":12},{"type":"D","stem":"名词解释：呆小病（克汀病）","answer":"胎儿或婴幼儿期甲状腺激素不足所致的身材矮小、智力低下和听力障碍，强调早期诊断和尽早替代治疗。","rationale":"出自概念手册「甲状腺激素与抗甲状腺药」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph33_q013","chapter":"第三十三章 甲状腺激素与抗甲状腺药","chapterIdx":32,"num":13},{"type":"D","stem":"名词解释：黏液性水肿","answer":"成人甲状腺功能减退时黏多糖在皮下和组织间隙堆积形成的水肿，按压无凹陷，需用甲状腺激素替代治疗。","rationale":"出自概念手册「甲状腺激素与抗甲状腺药」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph33_q014","chapter":"第三十三章 甲状腺激素与抗甲状腺药","chapterIdx":32,"num":14},{"type":"D","stem":"名词解释：促甲状腺激素（TSH）","answer":"腺垂体分泌的激素，促进甲状腺腺体增生和激素合成释放，起效慢而持久，可用于诊断与辅助治疗。","rationale":"出自概念手册「甲状腺激素与抗甲状腺药」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph33_q015","chapter":"第三十三章 甲状腺激素与抗甲状腺药","chapterIdx":32,"num":15},{"type":"D","stem":"名词解释：Wolff-Chaikoff效应","answer":"大剂量碘抑制甲状腺激素释放和合成的现象，起效快而短暂，是碘剂用于甲状腺危象和术前准备的药理基础。","rationale":"出自概念手册「甲状腺激素与抗甲状腺药」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph33_q016","chapter":"第三十三章 甲状腺激素与抗甲状腺药","chapterIdx":32,"num":16},{"type":"S","stem":"简答题：简述硫脲类抗甲状腺药的作用机制和主要不良反应。","answer":"①抑制甲状腺过氧化物酶，从而抑制酪氨酸的碘化以及碘化酪氨酸的耦联，减少甲状腺激素的合成；②不影响碘的摄取，也不影响已合成甲状腺激素的释放，故对已合成的激素无效，须待腺体内储存的激素耗竭后才显效；③丙硫氧嘧啶还能抑制外周组织T4转化为T3，并抑制甲状腺刺激性免疫球蛋白的生成；④最严重的不良反应是粒细胞缺乏症，用药期间须定期检查血象；⑤其他不良反应有变态反应（斑丘疹、皮肤瘙痒、药疹、发热）、消化道反应，以及因反馈性TSH分泌增多所致的甲状腺肿与甲状腺功能减退。","rationale":"采分点：抑制过氧化物酶→抑制碘化与耦联；对已合成激素无效；丙硫氧嘧啶抑制外周T4→T3；最严重不良反应为粒细胞缺乏症。易错：误答“抑制激素释放”或“抑制碘摄取”，二者都不是硫脲类的机制。","id":"rph33_q017","chapter":"第三十三章 甲状腺激素与抗甲状腺药","chapterIdx":32,"num":17},{"type":"F","stem":"填空题：甲状腺激素主要有甲状腺素（T4）和生物活性较高的______；硫脲类通过抑制甲状腺______而减少激素合成。","answer":"①三碘甲腺原氨酸（T3） ②过氧化物酶","rationale":"T3生物活性高于T4；硫脲类的靶点是过氧化物酶，不是碘泵、也不是蛋白水解酶。","id":"rph33_q018","chapter":"第三十三章 甲状腺激素与抗甲状腺药","chapterIdx":32,"num":18},{"type":"F","stem":"填空题：大剂量碘及碘化物抗甲状腺作用迅速，主要通过抑制甲状腺球蛋白的______而减少T3、T4释放；硫脲类作术前准备后，须在术前______加服大剂量碘剂，使腺体缩小变韧、血管减少。","answer":"①水解 ②2周","rationale":"小剂量碘是合成激素的原料，大剂量碘才产生抗甲状腺作用；术前加碘时间为2周，目的是拮抗TSH、减少腺体充血与出血。","id":"rph33_q019","chapter":"第三十三章 甲状腺激素与抗甲状腺药","chapterIdx":32,"num":19},{"type":"T","stem":"判断题：硫脲类抗甲状腺药能抑制已合成甲状腺激素的释放，因此可迅速缓解甲状腺危象的症状。","options":{"A":"正确","B":"错误"},"answer":["B"],"rationale":"硫脲类只抑制激素合成，不影响释放，对已合成激素无效，起效慢，不能迅速缓解危象。甲状腺危象须用大剂量碘抑制释放，加丙硫氧嘧啶与β受体阻断药。","id":"rph33_q020","chapter":"第三十三章 甲状腺激素与抗甲状腺药","chapterIdx":32,"num":20},{"type":"T","stem":"判断题：β受体阻断药可用于甲亢及甲状腺危象的辅助治疗，其机制之一是抑制外周T4转化为T3。","options":{"A":"正确","B":"错误"},"answer":["A"],"rationale":"β受体阻断药拮抗β受体改善心悸等交感兴奋症状，拮抗中枢β受体减轻焦虑，并可抑制外周T4转化为T3，是危象综合治疗的一部分。","id":"rph33_q021","chapter":"第三十三章 甲状腺激素与抗甲状腺药","chapterIdx":32,"num":21}]},{"title":"第三十四章 胰岛素与口服降糖药","questions":[{"type":"D","stem":"名词解释：胰岛素","answer":"胰岛B细胞分泌的肽类激素，由A、B两条链经二硫键连接而成，是体内唯一降低血糖的激素，也是治疗糖尿病的核心药物。","rationale":"出自概念手册「胰岛素与口服降糖药」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph34_q001","chapter":"第三十四章 胰岛素与口服降糖药","chapterIdx":33,"num":1},{"type":"D","stem":"名词解释：胰岛素类似物","answer":"通过基因重组改变氨基酸序列得到的人胰岛素衍生物，可改变吸收速度和作用时程，如赖脯胰岛素、甘精胰岛素。","rationale":"出自概念手册「胰岛素与口服降糖药」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph34_q002","chapter":"第三十四章 胰岛素与口服降糖药","chapterIdx":33,"num":2},{"type":"D","stem":"名词解释：胰岛素受体","answer":"靶细胞膜上的酪氨酸激酶受体，胰岛素与之结合后激活受体底物，促进葡萄糖转运、糖原合成和脂肪合成。","rationale":"出自概念手册「胰岛素与口服降糖药」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph34_q003","chapter":"第三十四章 胰岛素与口服降糖药","chapterIdx":33,"num":3},{"type":"D","stem":"名词解释：胰岛素抵抗","answer":"靶组织对胰岛素的敏感性降低，相同剂量胰岛素的降糖作用减弱，是2型糖尿病发病的重要病理环节。","rationale":"出自概念手册「胰岛素与口服降糖药」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph34_q004","chapter":"第三十四章 胰岛素与口服降糖药","chapterIdx":33,"num":4},{"type":"D","stem":"名词解释：磺酰脲类","answer":"与胰岛B细胞膜ATP敏感性钾通道上的磺酰脲受体结合，使钾通道关闭、钙内流增加，刺激胰岛素释放的降糖药。","rationale":"出自概念手册「胰岛素与口服降糖药」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph34_q005","chapter":"第三十四章 胰岛素与口服降糖药","chapterIdx":33,"num":5},{"type":"D","stem":"名词解释：双胍类","answer":"以二甲双胍为代表，通过抑制肝糖异生、减少肠道吸收并增加外周组织对葡萄糖的摄取利用而降糖，不刺激胰岛素分泌。","rationale":"出自概念手册「胰岛素与口服降糖药」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph34_q006","chapter":"第三十四章 胰岛素与口服降糖药","chapterIdx":33,"num":6},{"type":"D","stem":"名词解释：α-葡萄糖苷酶抑制剂","answer":"在小肠刷状缘竞争性抑制α-葡萄糖苷酶，延缓碳水化合物分解和吸收，主要降低餐后血糖，代表药阿卡波糖。","rationale":"出自概念手册「胰岛素与口服降糖药」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph34_q007","chapter":"第三十四章 胰岛素与口服降糖药","chapterIdx":33,"num":7},{"type":"D","stem":"名词解释：噻唑烷二酮类（格列酮类）","answer":"激动过氧化物酶体增殖物激活受体γ，改善胰岛素抵抗并增加外周组织对葡萄糖的摄取，代表药罗格列酮、吡格列酮。","rationale":"出自概念手册「胰岛素与口服降糖药」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph34_q008","chapter":"第三十四章 胰岛素与口服降糖药","chapterIdx":33,"num":8},{"type":"D","stem":"名词解释：格列奈类","answer":"非磺酰脲类促胰岛素分泌药，作用于ATP敏感性钾通道的不同位点，起效快、作用短，用于控制餐后血糖。","rationale":"出自概念手册「胰岛素与口服降糖药」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph34_q009","chapter":"第三十四章 胰岛素与口服降糖药","chapterIdx":33,"num":9},{"type":"D","stem":"名词解释：二肽基肽酶-4（DPP-4）抑制剂","answer":"抑制DPP-4活性，减少肠促胰素GLP-1和GIP的降解，促进葡萄糖依赖性的胰岛素分泌，代表药西格列汀。","rationale":"出自概念手册「胰岛素与口服降糖药」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph34_q010","chapter":"第三十四章 胰岛素与口服降糖药","chapterIdx":33,"num":10},{"type":"D","stem":"名词解释：胰高血糖素样肽-1（GLP-1）受体激动剂","answer":"模拟GLP-1的作用，促进胰岛素分泌、抑制胰高血糖素释放并延缓胃排空，代表药艾塞那肽、利拉鲁肽。","rationale":"出自概念手册「胰岛素与口服降糖药」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph34_q011","chapter":"第三十四章 胰岛素与口服降糖药","chapterIdx":33,"num":11},{"type":"D","stem":"名词解释：钠-葡萄糖共转运蛋白2（SGLT2）抑制剂","answer":"抑制肾近曲小管对葡萄糖的重吸收，促进尿糖排出而降低血糖，代表药达格列净，兼有减重和降压作用。","rationale":"出自概念手册「胰岛素与口服降糖药」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph34_q012","chapter":"第三十四章 胰岛素与口服降糖药","chapterIdx":33,"num":12},{"type":"D","stem":"名词解释：低血糖反应","answer":"血糖过低引起的心悸、出汗、饥饿感、震颤甚至昏迷，是胰岛素和促胰岛素分泌药最常见也最危险的不良反应。","rationale":"出自概念手册「胰岛素与口服降糖药」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph34_q013","chapter":"第三十四章 胰岛素与口服降糖药","chapterIdx":33,"num":13},{"type":"D","stem":"名词解释：黎明现象","answer":"糖尿病患者夜间血糖控制尚可而清晨血糖升高的现象，与夜间生长激素、皮质醇等升糖激素分泌增多有关。","rationale":"出自概念手册「胰岛素与口服降糖药」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph34_q014","chapter":"第三十四章 胰岛素与口服降糖药","chapterIdx":33,"num":14},{"type":"D","stem":"名词解释：苏木杰效应","answer":"夜间发生低血糖后反跳性出现清晨高血糖的现象，表现与黎明现象相似但处理相反，须减少夜间胰岛素用量。","rationale":"出自概念手册「胰岛素与口服降糖药」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph34_q015","chapter":"第三十四章 胰岛素与口服降糖药","chapterIdx":33,"num":15},{"type":"D","stem":"名词解释：糖尿病酮症酸中毒","answer":"胰岛素严重不足使脂肪分解加速、酮体堆积的急症，表现为深大呼吸、烂苹果味和脱水，抢救以补液加小剂量胰岛素静滴为主。","rationale":"出自概念手册「胰岛素与口服降糖药」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph34_q016","chapter":"第三十四章 胰岛素与口服降糖药","chapterIdx":33,"num":16},{"type":"S","stem":"简答题：简述二甲双胍的药理作用特点及其中2型糖尿病一线用药的地位。","answer":"①明显降低糖尿病患者的血糖，对正常人血糖影响小，单用一般不引起低血糖反应；②抑制过多的内源性肝葡萄糖生成，增加周围组织对胰岛素的摄取和利用，并抑制或延迟糖在胃肠道的吸收；③有降血脂作用，可延缓糖尿病血管并发症的发生，并有抗衰老作用；④主要用于轻、中度2型糖尿病，尤其适用于有胰岛素抵抗的肥胖患者；⑤国内外糖尿病指南均推荐其为2型糖尿病治疗的一线首选药和全程药物，也是联合治疗的首选，且应一直保留在治疗方案中。","rationale":"采分点：不刺激胰岛素分泌、单用不引起低血糖；抑制肝糖输出＋增加外周利用＋延缓肠道吸收；肥胖伴胰岛素抵抗者首选；一线全程用药。易错：把二甲双胍当成胰岛素促泌剂。","id":"rph34_q017","chapter":"第三十四章 胰岛素与口服降糖药","chapterIdx":33,"num":17},{"type":"F","stem":"填空题：磺酰脲类降糖药属于______药，通过刺激胰岛β细胞释放胰岛素而降低血糖；其中氯磺丙脲还有______作用，可用于尿崩症。","answer":"①胰岛素促泌（促胰岛素分泌） ②抗利尿","rationale":"磺酰脲类降糖的前提是胰岛β细胞功能尚存（≥30%）；抗利尿作用来自增强ADH的分泌及作用，是氯磺丙脲的独特用途。","id":"rph34_q018","chapter":"第三十四章 胰岛素与口服降糖药","chapterIdx":33,"num":18},{"type":"F","stem":"填空题：阿卡波糖抑制小肠______，减慢碳水化合物水解及寡糖分解为单糖的速度，延缓葡萄糖吸收，从而明显降低______血糖。","answer":"①α-葡萄糖苷酶 ②餐后","rationale":"α-葡萄糖苷酶抑制药的作用部位在小肠上皮刷状缘，特点是降餐后血糖、减少血糖波动，尤适用于老年轻中度2型糖尿病。","id":"rph34_q019","chapter":"第三十四章 胰岛素与口服降糖药","chapterIdx":33,"num":19},{"type":"T","stem":"判断题：胰岛素是治疗1型糖尿病的必需药物，也是抢救糖尿病酮症酸中毒和糖尿病高渗性昏迷的关键药物。","options":{"A":"正确","B":"错误"},"answer":["A"],"rationale":"1型糖尿病胰岛素绝对缺乏，须终身替代；酮症酸中毒、高渗性昏迷、乳酸性酸中毒伴高血糖均须用胰岛素，此外还可与葡萄糖、氯化钾组成极化液纠正细胞内缺钾。","id":"rph34_q020","chapter":"第三十四章 胰岛素与口服降糖药","chapterIdx":33,"num":20},{"type":"T","stem":"判断题：磺酰脲类药物可用于胰岛功能完全丧失的1型糖尿病患者。","options":{"A":"正确","B":"错误"},"answer":["B"],"rationale":"磺酰脲类靠刺激残存β细胞释放胰岛素起效，要求胰岛功能尚存（≥30%），对1型糖尿病及胰腺全切除者无效。","id":"rph34_q021","chapter":"第三十四章 胰岛素与口服降糖药","chapterIdx":33,"num":21}]},{"title":"第三十五章 调节骨代谢与形成药","questions":[{"type":"D","stem":"名词解释：骨重建","answer":"由破骨细胞吸收旧骨与成骨细胞形成新骨构成的动态偶联过程，受甲状旁腺激素、维生素D、降钙素与性激素等调节，失衡即导致骨量减少。","rationale":"出自概念手册「调节骨代谢与形成药」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph35_q001","chapter":"第三十五章 调节骨代谢与形成药","chapterIdx":34,"num":1},{"type":"D","stem":"名词解释：骨矿化剂","answer":"提供骨矿化所需的钙与磷并促进其沉积于骨基质的药物，包括钙剂与维生素D及其活性代谢物，是骨质疏松防治的基础用药。","rationale":"出自概念手册「调节骨代谢与形成药」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph35_q002","chapter":"第三十五章 调节骨代谢与形成药","chapterIdx":34,"num":2},{"type":"D","stem":"名词解释：钙剂","answer":"常用碳酸钙、葡萄糖酸钙与乳酸钙，补充钙源以维持钙平衡，用于钙缺乏、骨质疏松与低钙血症的防治，常与维生素D合用。","rationale":"出自概念手册「调节骨代谢与形成药」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph35_q003","chapter":"第三十五章 调节骨代谢与形成药","chapterIdx":34,"num":3},{"type":"D","stem":"名词解释：维生素D","answer":"脂溶性维生素，经肝转化为25-羟维生素D、再经肾转化为1,25-二羟维生素D后发挥作用，促进肠钙吸收、骨矿化与肾小管钙重吸收。","rationale":"出自概念手册「调节骨代谢与形成药」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph35_q004","chapter":"第三十五章 调节骨代谢与形成药","chapterIdx":34,"num":4},{"type":"F","stem":"填空题：脂溶性维生素，经肝转化为25-羟______、再经肾转化为1,25-二羟维生素D后发挥作用，促进肠钙吸收、骨矿化与肾小管钙重吸收。","answer":"维生素D","rationale":"出自概念手册「调节骨代谢与形成药」核心概念：维生素D。","id":"rph35_q005","chapter":"第三十五章 调节骨代谢与形成药","chapterIdx":34,"num":5},{"type":"D","stem":"名词解释：骨化三醇","answer":"即1,25-二羟维生素D3，活性最强的维生素D代谢物，无须经肝肾活化，用于肾性骨营养不良、骨质疏松与甲状旁腺功能减退。","rationale":"出自概念手册「调节骨代谢与形成药」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph35_q006","chapter":"第三十五章 调节骨代谢与形成药","chapterIdx":34,"num":6},{"type":"D","stem":"名词解释：双膦酸盐类","answer":"与骨基质羟磷灰石牢固结合、被破骨细胞摄取后抑制其功能与存活的一类药物，是抑制骨吸收、治疗骨质疏松的主力药物。","rationale":"出自概念手册「调节骨代谢与形成药」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph35_q007","chapter":"第三十五章 调节骨代谢与形成药","chapterIdx":34,"num":7},{"type":"D","stem":"名词解释：阿仑膦酸钠","answer":"第三代含氮双膦酸盐，抑制破骨细胞介导的骨吸收，增加骨密度并降低椎体与非椎体骨折风险，用于绝经后骨质疏松与变形性骨炎。","rationale":"出自概念手册「调节骨代谢与形成药」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph35_q008","chapter":"第三十五章 调节骨代谢与形成药","chapterIdx":34,"num":8},{"type":"D","stem":"名词解释：雌激素替代治疗","answer":"绝经后补充雌激素以抑制破骨细胞活性、减少骨量丢失，须加用孕激素保护子宫内膜，适用于绝经早期骨质疏松的预防。","rationale":"出自概念手册「调节骨代谢与形成药」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph35_q009","chapter":"第三十五章 调节骨代谢与形成药","chapterIdx":34,"num":9},{"type":"D","stem":"名词解释：雌激素受体调节剂","answer":"在骨与心血管系统激动雌激素受体、在乳腺与子宫内膜拮抗的药物，如雷洛昔芬，用于绝经后骨质疏松且不增加乳腺癌风险。","rationale":"出自概念手册「调节骨代谢与形成药」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph35_q010","chapter":"第三十五章 调节骨代谢与形成药","chapterIdx":34,"num":10},{"type":"D","stem":"名词解释：雷洛昔芬","answer":"用于绝经后骨质疏松的选择性雌激素受体调节剂，增加骨密度、降低椎体骨折风险，不刺激乳腺与子宫内膜，但可加重潮热并增加静脉血栓风险。","rationale":"出自概念手册「调节骨代谢与形成药」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph35_q011","chapter":"第三十五章 调节骨代谢与形成药","chapterIdx":34,"num":11},{"type":"D","stem":"名词解释：降钙素","answer":"由甲状腺滤泡旁细胞分泌的肽类激素，抑制破骨细胞活性并减少肾小管对钙的重吸收，用于高钙血症、骨质疏松及骨质疏松性骨痛。","rationale":"出自概念手册「调节骨代谢与形成药」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph35_q012","chapter":"第三十五章 调节骨代谢与形成药","chapterIdx":34,"num":12},{"type":"D","stem":"名词解释：氟化物","answer":"氟化钠等无机氟制剂，直接刺激成骨细胞增殖与骨基质形成，可增加骨密度，但形成的新骨矿化不良，骨折风险未必下降。","rationale":"出自概念手册「调节骨代谢与形成药」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph35_q013","chapter":"第三十五章 调节骨代谢与形成药","chapterIdx":34,"num":13},{"type":"D","stem":"名词解释：甲状旁腺激素","answer":"由甲状旁腺主细胞分泌的肽类激素，间断小剂量给药促进骨形成，持续大剂量给药则促进骨吸收，是骨代谢的双向调节者。","rationale":"出自概念手册「调节骨代谢与形成药」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph35_q014","chapter":"第三十五章 调节骨代谢与形成药","chapterIdx":34,"num":14},{"type":"D","stem":"名词解释：特立帕肽","answer":"甲状旁腺激素的1-34片段，间断皮下注射促进成骨细胞活性，用于严重骨质疏松与骨折高风险者，疗程一般不超过两年。","rationale":"出自概念手册「调节骨代谢与形成药」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph35_q015","chapter":"第三十五章 调节骨代谢与形成药","chapterIdx":34,"num":15},{"type":"D","stem":"名词解释：骨质疏松症","answer":"以骨量减少、骨微结构破坏、骨脆性增加和易发生骨折为特征的全身性骨病，分原发性与继发性两类，绝经后女性和老年人多见。","rationale":"出自概念手册「调节骨代谢与形成药」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph35_q016","chapter":"第三十五章 调节骨代谢与形成药","chapterIdx":34,"num":16},{"type":"D","stem":"名词解释：骨吸收抑制剂","answer":"通过抑制破骨细胞的分化、功能或存活而减少骨量丢失的药物，包括双膦酸盐、雌激素、选择性雌激素受体调节剂与降钙素。","rationale":"出自概念手册「调节骨代谢与形成药」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph35_q017","chapter":"第三十五章 调节骨代谢与形成药","chapterIdx":34,"num":17},{"type":"S","stem":"简答题：简述双膦酸盐类药物治疗骨质疏松的作用机制、服药要求与主要不良反应。","answer":"①与骨基质羟磷灰石牢固结合，被破骨细胞摄取后抑制其功能与存活，从而抑制破骨细胞介导的骨吸收；②增加骨密度，降低椎体与非椎体骨折风险，用于绝经后骨质疏松与变形性骨炎；③服药方法特殊：须空腹用足量白水送服，服后至少30分钟内保持直立且不进食，以防食管炎与食管溃疡；④与钙剂、抗酸药、含铁制剂同服会显著减少吸收，必须间隔至少2小时；⑤长期应用可致下颌骨坏死与非典型股骨骨折，用药前应处理口腔疾患，长期用药须定期评估风险与获益。","rationale":"采分点：抑制破骨细胞介导的骨吸收；空腹足量水送服＋服后30分钟直立不进食（防食管损伤）；与钙剂等间隔2小时；下颌骨坏死。易错：把双膦酸盐说成促进骨形成的药物。","id":"rph35_q018","chapter":"第三十五章 调节骨代谢与形成药","chapterIdx":34,"num":18},{"type":"F","stem":"填空题：甲状旁腺激素对骨代谢有双向作用，______小剂量给药促进骨形成，______大剂量给药则促进骨吸收。","answer":"①间断 ②持续","rationale":"给药方式决定药理方向：间断给药为合成代谢，持续给药为分解代谢，故特立帕肽须每日小剂量皮下注射，不能持续静脉输注。","id":"rph35_q019","chapter":"第三十五章 调节骨代谢与形成药","chapterIdx":34,"num":19},{"type":"F","stem":"填空题：维生素D须经肝转化为25-羟维生素D，再经______转化为1,25-二羟维生素D3即______才有活性，故严重肝肾功能不全者应直接使用活性制剂。","answer":"①肾 ②骨化三醇","rationale":"活化需肝、肾两次羟化；骨化三醇（1,25-二羟维生素D3）是活性最强的代谢物，无须再经肝肾活化。","id":"rph35_q020","chapter":"第三十五章 调节骨代谢与形成药","chapterIdx":34,"num":20},{"type":"T","stem":"判断题：氟化物能明显增加骨密度，因此可确切降低骨质疏松患者的骨折发生率。","options":{"A":"正确","B":"错误"},"answer":["B"],"rationale":"氟化物刺激成骨、增加骨密度，但形成的新骨结构异常、矿化不良，骨折风险未必下降，说明骨密度与骨质量、骨折风险并不平行。","id":"rph35_q021","chapter":"第三十五章 调节骨代谢与形成药","chapterIdx":34,"num":21},{"type":"T","stem":"判断题：雷洛昔芬在骨与心血管系统激动雌激素受体，而在乳腺与子宫内膜呈拮抗作用，故不增加乳腺癌与子宫内膜癌风险。","options":{"A":"正确","B":"错误"},"answer":["A"],"rationale":"选择性雌激素受体调节剂的作用有组织选择性，用于绝经后骨质疏松可增加骨密度、降低椎体骨折风险；但可加重潮热并增加静脉血栓风险。","id":"rph35_q022","chapter":"第三十五章 调节骨代谢与形成药","chapterIdx":34,"num":22}]},{"title":"第三十六章 抗病原微生物药概论","questions":[{"type":"D","stem":"名词解释：抗菌药","answer":"对病原菌具有抑制或杀灭作用的药物，包括天然抗生素和人工合成抗菌药，用于治疗细菌感染性疾病。","rationale":"出自概念手册「抗病原微生物药概论」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph36_q001","chapter":"第三十六章 抗病原微生物药概论","chapterIdx":35,"num":1},{"type":"F","stem":"填空题：对病原菌具有抑制或杀灭作用的药物，包括天然抗生素和人工合成______，用于治疗细菌感染性疾病。","answer":"抗菌药","rationale":"出自概念手册「抗病原微生物药概论」核心概念：抗菌药。","id":"rph36_q002","chapter":"第三十六章 抗病原微生物药概论","chapterIdx":35,"num":2},{"type":"D","stem":"名词解释：抗生素","answer":"由微生物（放线菌、真菌、细菌等）产生、能抑制或杀灭其他微生物的代谢产物，也可经半合成或全合成制得。","rationale":"出自概念手册「抗病原微生物药概论」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph36_q003","chapter":"第三十六章 抗病原微生物药概论","chapterIdx":35,"num":3},{"type":"D","stem":"名词解释：抑菌药","answer":"仅能抑制病原菌生长繁殖而无杀灭作用的药物，如四环素类、大环内酯类和磺胺类，其疗效依赖机体免疫功能。","rationale":"出自概念手册「抗病原微生物药概论」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph36_q004","chapter":"第三十六章 抗病原微生物药概论","chapterIdx":35,"num":4},{"type":"D","stem":"名词解释：杀菌药","answer":"能杀灭病原菌的药物，如β-内酰胺类、氨基糖苷类和喹诺酮类，疗效与血药峰浓度和杀菌速率关系密切。","rationale":"出自概念手册「抗病原微生物药概论」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph36_q005","chapter":"第三十六章 抗病原微生物药概论","chapterIdx":35,"num":5},{"type":"D","stem":"名词解释：抗菌谱","answer":"药物抑制或杀灭病原菌的范围，分窄谱与广谱，是抗菌药分类和临床选药的重要依据，抗菌谱越广越易致二重感染。","rationale":"出自概念手册「抗病原微生物药概论」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph36_q006","chapter":"第三十六章 抗病原微生物药概论","chapterIdx":35,"num":6},{"type":"F","stem":"填空题：药物抑制或杀灭病原菌的范围，分窄谱与广谱，是抗菌药分类和临床选药的重要依据，______越广越易致二重感染。","answer":"抗菌谱","rationale":"出自概念手册「抗病原微生物药概论」核心概念：抗菌谱。","id":"rph36_q007","chapter":"第三十六章 抗病原微生物药概论","chapterIdx":35,"num":7},{"type":"D","stem":"名词解释：最低抑菌浓度（MIC）","answer":"体外培养18至24小时后能抑制细菌肉眼可见生长的最低药物浓度，是评价抗菌活性的常用定量指标。","rationale":"出自概念手册「抗病原微生物药概论」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph36_q008","chapter":"第三十六章 抗病原微生物药概论","chapterIdx":35,"num":8},{"type":"D","stem":"名词解释：最低杀菌浓度（MBC）","answer":"能杀灭99.9%以上测试菌的最低药物浓度，反映药物的杀菌能力，与MIC结合可判断药物属抑菌或杀菌。","rationale":"出自概念手册「抗病原微生物药概论」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph36_q009","chapter":"第三十六章 抗病原微生物药概论","chapterIdx":35,"num":9},{"type":"D","stem":"名词解释：化疗指数","answer":"半数致死量与半数有效量的比值，即LD50与ED50之比，数值越大相对越安全，但化疗指数大并不等于绝对安全。","rationale":"出自概念手册「抗病原微生物药概论」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph36_q010","chapter":"第三十六章 抗病原微生物药概论","chapterIdx":35,"num":10},{"type":"F","stem":"填空题：半数致死量与半数有效量的比值，即LD50与ED50之比，数值越大相对越安全，但______大并不等于绝对安全。","answer":"化疗指数","rationale":"出自概念手册「抗病原微生物药概论」核心概念：化疗指数。","id":"rph36_q011","chapter":"第三十六章 抗病原微生物药概论","chapterIdx":35,"num":11},{"type":"D","stem":"名词解释：抗菌后效应（PAE）","answer":"药物浓度降至最低抑菌浓度以下后仍对细菌生长持续抑制的效应，是设计给药间隔的重要依据。","rationale":"出自概念手册「抗病原微生物药概论」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph36_q012","chapter":"第三十六章 抗病原微生物药概论","chapterIdx":35,"num":12},{"type":"D","stem":"名词解释：抗菌药耐药性","answer":"细菌对药物的敏感性降低甚至完全消失，分为固有耐药和获得性耐药两类，是抗菌治疗失败的主要原因。","rationale":"出自概念手册「抗病原微生物药概论」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph36_q013","chapter":"第三十六章 抗病原微生物药概论","chapterIdx":35,"num":13},{"type":"D","stem":"名词解释：固有耐药","answer":"某些菌种天然对某类药物不敏感，由染色体基因决定并可遗传，如铜绿假单胞菌对多种抗菌药天然耐药。","rationale":"出自概念手册「抗病原微生物药概论」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph36_q014","chapter":"第三十六章 抗病原微生物药概论","chapterIdx":35,"num":14},{"type":"D","stem":"名词解释：获得性耐药","answer":"敏感菌在接触药物后通过基因突变或获得耐药基因而产生的耐药性，可通过质粒在细菌间传播。","rationale":"出自概念手册「抗病原微生物药概论」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph36_q015","chapter":"第三十六章 抗病原微生物药概论","chapterIdx":35,"num":15},{"type":"D","stem":"名词解释：多重耐药","answer":"细菌对三类或三类以上抗菌药物同时耐药的现象，常见于医院获得性感染，使临床治疗十分困难。","rationale":"出自概念手册「抗病原微生物药概论」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph36_q016","chapter":"第三十六章 抗病原微生物药概论","chapterIdx":35,"num":16},{"type":"D","stem":"名词解释：二重感染","answer":"长期应用广谱抗菌药使敏感菌受抑、耐药菌或真菌大量繁殖而引起的新的感染，又称菌群交替症。","rationale":"出自概念手册「抗病原微生物药概论」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph36_q017","chapter":"第三十六章 抗病原微生物药概论","chapterIdx":35,"num":17},{"type":"D","stem":"名词解释：首次接触效应","answer":"抗菌药首次接触细菌时杀菌作用强大，再度接触时杀菌作用减弱甚至消失的现象，见于氨基糖苷类。","rationale":"出自概念手册「抗病原微生物药概论」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph36_q018","chapter":"第三十六章 抗病原微生物药概论","chapterIdx":35,"num":18},{"type":"D","stem":"名词解释：药敏试验","answer":"测定病原菌对多种抗菌药物敏感性的体外试验，常用纸片扩散法或稀释法测MIC，为临床选药提供依据。","rationale":"出自概念手册「抗病原微生物药概论」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph36_q019","chapter":"第三十六章 抗病原微生物药概论","chapterIdx":35,"num":19},{"type":"S","stem":"简答题：简述细菌耐药性产生的主要机制。","answer":"①产生灭活抗菌药物的酶：如β-内酰胺酶水解β-内酰胺环，氨基糖苷钝化酶（乙酰化酶、磷酸化酶、腺苷化酶）使药物失活，氯霉素乙酰基转移酶使氯霉素灭活；②药物作用靶位改变：改变靶蛋白结构而降低与药物的亲和力（如肺炎链球菌对青霉素耐药）、产生新的耐药靶蛋白（MRSA比敏感菌多一个PBP2a）、增加靶蛋白数量以维持正常功能；③降低细菌外膜通透性：改变通道蛋白（porin）的性质和数量，减少药物进入菌体；④影响主动流出系统：由膜蛋白组成的流出系统将已进入菌体的药物泵出，降低菌体内有效药物浓度，该机制无特异性。","rationale":"采分点为“灭活酶、靶位改变、通透性下降、主动外排”四大机制。易错：把“改变代谢途径”当作主要机制；改变靶位要能举出PBP2a（MRSA）这一典型例子。","id":"rph36_q020","chapter":"第三十六章 抗病原微生物药概论","chapterIdx":35,"num":20},{"type":"F","stem":"填空题：化疗指数是化疗药物的______与治疗感染动物的______的比值，化疗指数越大，提示药物毒性越______、临床价值越高。","answer":"①半数致死量（LD50） ②半数有效量（ED50） ③小","rationale":"化疗指数＝LD50/ED50（或LD5/ED95），是评价化疗药物有效性与安全性的指标；但并非绝对，如青霉素化疗指数很高却可致过敏性休克。","id":"rph36_q021","chapter":"第三十六章 抗病原微生物药概论","chapterIdx":35,"num":21},{"type":"F","stem":"填空题：抗菌药物抑制细菌蛋白质合成时，作用于30S亚基的有______类和四环素类，作用于50S亚基的有大环内酯类、氯霉素和______类。","answer":"①氨基糖苷 ②林可霉素","rationale":"口诀“三十而立四环素，红绿林中五十栽”：30S为氨基糖苷类与四环素类，50S为大环内酯类、氯霉素、林可霉素类。","id":"rph36_q022","chapter":"第三十六章 抗病原微生物药概论","chapterIdx":35,"num":22},{"type":"T","stem":"判断题：抑菌药是仅能抑制细菌生长繁殖而无杀灭作用的药物，杀菌药则既有抑制作用又有杀灭作用。","options":{"A":"正确","B":"错误"},"answer":["A"],"rationale":"抑菌药与杀菌药按对细菌的作用性质划分，前者需依靠机体免疫功能清除细菌，后者可直接杀灭；这种划分是相对的，与药物浓度和菌种有关。","id":"rph36_q023","chapter":"第三十六章 抗病原微生物药概论","chapterIdx":35,"num":23},{"type":"T","stem":"判断题：β-内酰胺类抗生素具有明显的抗生素后效应，因此可以大幅延长给药间隔。","options":{"A":"正确","B":"错误"},"answer":["B"],"rationale":"β-内酰胺类无明显抗生素后效应，其疗效主要取决于血药浓度高于MIC的时间（T＞MIC）；PAE较长的是抑制蛋白质合成的药物和喹诺酮类。","id":"rph36_q024","chapter":"第三十六章 抗病原微生物药概论","chapterIdx":35,"num":24}]},{"title":"第三十七章 人工合成抗菌药","questions":[{"type":"D","stem":"名词解释：喹诺酮类抗菌药","answer":"含4-喹诺酮母核的人工合成抗菌药，通过抑制细菌DNA拓扑异构酶阻断DNA复制而杀菌，代表药有诺氟沙星、环丙沙星、左氧氟沙星。","rationale":"出自概念手册「人工合成抗菌药」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph37_q001","chapter":"第三十七章 人工合成抗菌药","chapterIdx":36,"num":1},{"type":"D","stem":"名词解释：氟喹诺酮类","answer":"喹诺酮母核C6位引入氟原子、C7位引入哌嗪基的衍生物，抗菌活性明显增强、口服吸收好、组织与细胞内浓度高，是目前临床常用品种。","rationale":"出自概念手册「人工合成抗菌药」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph37_q002","chapter":"第三十七章 人工合成抗菌药","chapterIdx":36,"num":2},{"type":"D","stem":"名词解释：DNA回旋酶","answer":"即拓扑异构酶Ⅱ，负责使DNA双链形成负超螺旋，是氟喹诺酮类作用于革兰阴性菌的主要靶点，被抑制后DNA复制受阻。","rationale":"出自概念手册「人工合成抗菌药」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph37_q003","chapter":"第三十七章 人工合成抗菌药","chapterIdx":36,"num":3},{"type":"D","stem":"名词解释：DNA拓扑异构酶Ⅳ","answer":"催化子代染色体解连环的酶，是氟喹诺酮类作用于革兰阳性菌的主要靶点，被抑制后细菌染色体分配障碍而死亡。","rationale":"出自概念手册「人工合成抗菌药」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph37_q004","chapter":"第三十七章 人工合成抗菌药","chapterIdx":36,"num":4},{"type":"D","stem":"名词解释：环丙沙星","answer":"对革兰阴性杆菌与铜绿假单胞菌作用强的氟喹诺酮，常用于泌尿生殖系、肠道、腹腔及下呼吸道感染，可静脉给药。","rationale":"出自概念手册「人工合成抗菌药」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph37_q005","chapter":"第三十七章 人工合成抗菌药","chapterIdx":36,"num":5},{"type":"D","stem":"名词解释：左氧氟沙星","answer":"氧氟沙星的左旋异构体，抗菌活性约为消旋体的两倍，肺组织浓度高，广泛用于社区获得性肺炎，也是二线抗结核药。","rationale":"出自概念手册「人工合成抗菌药」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph37_q006","chapter":"第三十七章 人工合成抗菌药","chapterIdx":36,"num":6},{"type":"D","stem":"名词解释：莫西沙星","answer":"抗革兰阳性菌、支原体、衣原体及厌氧菌作用强，对铜绿假单胞菌作用弱，尿中浓度低，不用于泌尿系感染。","rationale":"出自概念手册「人工合成抗菌药」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph37_q007","chapter":"第三十七章 人工合成抗菌药","chapterIdx":36,"num":7},{"type":"D","stem":"名词解释：诺氟沙星","answer":"第一个用于临床的氟喹诺酮，口服吸收较少，尿中浓度高，主要用于敏感菌所致的单纯性泌尿系感染和肠道感染。","rationale":"出自概念手册「人工合成抗菌药」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph37_q008","chapter":"第三十七章 人工合成抗菌药","chapterIdx":36,"num":8},{"type":"D","stem":"名词解释：磺胺类抗菌药","answer":"对氨基苯磺酰胺的衍生物，与对氨基苯甲酸竞争二氢蝶酸合酶，抑制细菌二氢叶酸合成，属广谱抑菌药。","rationale":"出自概念手册「人工合成抗菌药」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph37_q009","chapter":"第三十七章 人工合成抗菌药","chapterIdx":36,"num":9},{"type":"D","stem":"名词解释：二氢蝶酸合酶","answer":"又称二氢叶酸合成酶，催化对氨基苯甲酸与蝶啶缩合生成二氢蝶酸，是磺胺类药物竞争性抑制的靶点。","rationale":"出自概念手册「人工合成抗菌药」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph37_q010","chapter":"第三十七章 人工合成抗菌药","chapterIdx":36,"num":10},{"type":"D","stem":"名词解释：甲氧苄啶","answer":"又称TMP，抑制细菌二氢叶酸还原酶，与磺胺类合用可双重阻断叶酸合成，使抗菌作用增强数十倍。","rationale":"出自概念手册「人工合成抗菌药」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph37_q011","chapter":"第三十七章 人工合成抗菌药","chapterIdx":36,"num":11},{"type":"D","stem":"名词解释：抗菌增效剂","answer":"本身抗菌作用较弱，但能增强其他抗菌药疗效的药物，甲氧苄啶为代表，常与磺胺甲噁唑组成复方制剂。","rationale":"出自概念手册「人工合成抗菌药」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph37_q012","chapter":"第三十七章 人工合成抗菌药","chapterIdx":36,"num":12},{"type":"D","stem":"名词解释：复方磺胺甲噁唑","answer":"由磺胺甲噁唑与甲氧苄啶按5比1配成的复方制剂，双重阻断叶酸代谢，用于泌尿系、呼吸道及肠道感染。","rationale":"出自概念手册「人工合成抗菌药」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph37_q013","chapter":"第三十七章 人工合成抗菌药","chapterIdx":36,"num":13},{"type":"D","stem":"名词解释：磺胺嘧啶","answer":"血浆蛋白结合率低、易透过血脑屏障，脑脊液中浓度高，是流行性脑脊髓膜炎的首选药物之一。","rationale":"出自概念手册「人工合成抗菌药」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph37_q014","chapter":"第三十七章 人工合成抗菌药","chapterIdx":36,"num":14},{"type":"D","stem":"名词解释：柳氮磺吡啶","answer":"口服后在肠道被细菌分解为磺胺吡啶与5-氨基水杨酸，后者发挥抗炎作用，用于溃疡性结肠炎和类风湿关节炎。","rationale":"出自概念手册「人工合成抗菌药」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph37_q015","chapter":"第三十七章 人工合成抗菌药","chapterIdx":36,"num":15},{"type":"D","stem":"名词解释：磺胺醋酰","answer":"局部应用的磺胺药，水溶液近中性、对眼刺激性小，滴眼用于沙眼、结膜炎及角膜炎等眼部感染。","rationale":"出自概念手册「人工合成抗菌药」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph37_q016","chapter":"第三十七章 人工合成抗菌药","chapterIdx":36,"num":16},{"type":"S","stem":"简答题：简述氟喹诺酮类抗菌药的主要不良反应及用药注意事项。","answer":"①胃肠道反应：恶心、呕吐、腹痛、腹泻；②中枢神经系统反应：抑制GABAA受体，出现焦虑、失眠、精神异常，甚至抽搐、惊厥；③变态反应：血管神经性水肿、药疹、红斑、皮肤瘙痒，以及紫外线诱发的光敏性皮炎；④软骨组织损害：药物与软骨组织中Mg2+形成络合物，致负重关节水肿、疼痛，故18岁以下未成年人、妊娠期与哺乳期禁用；⑤心脏、肝、肾损害偶见，且可抑制茶碱类、咖啡因和华法林在肝内代谢，应避免与抗酸药及含金属离子药物同服，用药期间避免日照。","rationale":"采分点：胃肠道、中枢兴奋（抑制GABAA受体）、光敏性皮炎、软骨损害（18岁以下禁用）、肝药酶抑制与金属离子络合。易错：漏掉“软骨损害”这一限制未成年人使用的关键点。","id":"rph37_q017","chapter":"第三十七章 人工合成抗菌药","chapterIdx":36,"num":17},{"type":"F","stem":"填空题：氟喹诺酮类作用于细菌DNA回旋酶的______亚基，形成药物-酶-DNA复合物而阻碍DNA复制；该类药物还可抑制茶碱类、咖啡因和华法林在______的代谢。","answer":"①A ②肝","rationale":"靶点为回旋酶A亚基，gyrA基因突变是低水平耐药的基础；肝药酶抑制是茶碱中毒等相互作用的原因。","id":"rph37_q018","chapter":"第三十七章 人工合成抗菌药","chapterIdx":36,"num":18},{"type":"F","stem":"填空题：磺胺类通过与PABA竞争而抑制细菌______，阻碍叶酸合成；甲氧苄啶则抑制二氢叶酸______，二者合用可双重阻断细菌叶酸代谢。","answer":"①二氢蝶酸合酶（二氢叶酸合成酶） ②还原酶","rationale":"双重阻断使抗菌活性增强、甚至呈杀菌作用，并减少耐药产生；复方磺胺甲噁唑即SMZ与TMP按5:1配成。","id":"rph37_q019","chapter":"第三十七章 人工合成抗菌药","chapterIdx":36,"num":19},{"type":"T","stem":"判断题：磺胺嘧啶易透过血脑屏障，是流行性脑脊髓膜炎的首选药物。","options":{"A":"正确","B":"错误"},"answer":["A"],"rationale":"SD血浆蛋白结合率低、易透过血脑屏障，脑脊液浓度高，故为流脑首选；用于流脑预防时也可选SD或利福平。","id":"rph37_q020","chapter":"第三十七章 人工合成抗菌药","chapterIdx":36,"num":20},{"type":"T","stem":"判断题：呋喃妥因口服吸收少，主要在肠道发挥抗菌作用，故用于肠炎和菌痢。","options":{"A":"正确","B":"错误"},"answer":["B"],"rationale":"口服吸收少、肠道浓度高的是呋喃唑酮，用于肠炎、菌痢及抗幽门螺杆菌；呋喃妥因尿中浓度高、酸性尿中作用增强，用于敏感菌所致泌尿系统感染。","id":"rph37_q021","chapter":"第三十七章 人工合成抗菌药","chapterIdx":36,"num":21}]},{"title":"第三十八章 β-内酰胺类抗生素","questions":[{"type":"D","stem":"名词解释：β-内酰胺类抗生素","answer":"化学结构中含有β-内酰胺环的一大类抗生素，包括青霉素类、头孢菌素类和非典型β-内酰胺类，通过抑制细胞壁合成杀菌。","rationale":"出自概念手册「β-内酰胺类抗生素」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph38_q001","chapter":"第三十八章 β-内酰胺类抗生素","chapterIdx":37,"num":1},{"type":"D","stem":"名词解释：β-内酰胺环","answer":"该类药物的活性必需结构，与青霉素结合蛋白结合发挥抗菌作用，同时也是β-内酰胺酶水解的靶点。","rationale":"出自概念手册「β-内酰胺类抗生素」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph38_q002","chapter":"第三十八章 β-内酰胺类抗生素","chapterIdx":37,"num":2},{"type":"D","stem":"名词解释：青霉素结合蛋白（PBPs）","answer":"细菌细胞膜上的转肽酶等蛋白，是β-内酰胺类的结合靶点，药物结合后肽聚糖交联受阻，细胞壁缺损。","rationale":"出自概念手册「β-内酰胺类抗生素」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph38_q003","chapter":"第三十八章 β-内酰胺类抗生素","chapterIdx":37,"num":3},{"type":"D","stem":"名词解释：青霉素G","answer":"天然青霉素，对革兰阳性菌、革兰阴性球菌和螺旋体作用强，不耐酸、不耐酶，须注射给药。","rationale":"出自概念手册「β-内酰胺类抗生素」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph38_q004","chapter":"第三十八章 β-内酰胺类抗生素","chapterIdx":37,"num":4},{"type":"D","stem":"名词解释：长效青霉素","answer":"青霉素G的难溶盐或酯类制剂，如苄星青霉素、普鲁卡因青霉素，吸收慢、血药浓度低而维持时间长，用于风湿热预防。","rationale":"出自概念手册「β-内酰胺类抗生素」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph38_q005","chapter":"第三十八章 β-内酰胺类抗生素","chapterIdx":37,"num":5},{"type":"D","stem":"名词解释：耐酶青霉素","answer":"侧链有空间位阻保护β-内酰胺环的药物，如苯唑西林、氯唑西林，主要用于耐青霉素金黄色葡萄球菌感染。","rationale":"出自概念手册「β-内酰胺类抗生素」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph38_q006","chapter":"第三十八章 β-内酰胺类抗生素","chapterIdx":37,"num":6},{"type":"D","stem":"名词解释：广谱青霉素","answer":"对革兰阴性杆菌也有抗菌作用的青霉素类，如氨苄西林、阿莫西林，但对铜绿假单胞菌无效。","rationale":"出自概念手册「β-内酰胺类抗生素」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph38_q007","chapter":"第三十八章 β-内酰胺类抗生素","chapterIdx":37,"num":7},{"type":"D","stem":"名词解释：抗铜绿假单胞菌青霉素","answer":"如羧苄西林、哌拉西林，对铜绿假单胞菌有效，常用于烧伤创面感染、医院获得性肺炎和粒细胞缺乏伴发热的经验治疗。","rationale":"出自概念手册「β-内酰胺类抗生素」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph38_q008","chapter":"第三十八章 β-内酰胺类抗生素","chapterIdx":37,"num":8},{"type":"D","stem":"名词解释：头孢菌素类","answer":"以7-氨基头孢烷酸为母核的半合成抗生素，按抗菌谱和耐酶性分为四代，耐酶性与对革兰阴性菌作用逐代增强。","rationale":"出自概念手册「β-内酰胺类抗生素」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph38_q009","chapter":"第三十八章 β-内酰胺类抗生素","chapterIdx":37,"num":9},{"type":"D","stem":"名词解释：第一代头孢菌素","answer":"如头孢唑林，对革兰阳性菌作用强，对革兰阴性菌作用弱，对β-内酰胺酶不稳定，有一定肾毒性。","rationale":"出自概念手册「β-内酰胺类抗生素」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph38_q010","chapter":"第三十八章 β-内酰胺类抗生素","chapterIdx":37,"num":10},{"type":"D","stem":"名词解释：第三代头孢菌素","answer":"如头孢噻肟、头孢曲松，对革兰阴性菌及铜绿假单胞菌作用强，易透过血脑屏障，基本无肾毒性。","rationale":"出自概念手册「β-内酰胺类抗生素」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph38_q011","chapter":"第三十八章 β-内酰胺类抗生素","chapterIdx":37,"num":11},{"type":"D","stem":"名词解释：第四代头孢菌素","answer":"如头孢吡肟，对革兰阳性菌和阴性菌均有较强作用，对β-内酰胺酶高度稳定，肾毒性小。","rationale":"出自概念手册「β-内酰胺类抗生素」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph38_q012","chapter":"第三十八章 β-内酰胺类抗生素","chapterIdx":37,"num":12},{"type":"D","stem":"名词解释：β-内酰胺酶抑制剂","answer":"本身抗菌活性弱，但能不可逆抑制β-内酰胺酶而保护配伍药物，如克拉维酸、舒巴坦、他唑巴坦。","rationale":"出自概念手册「β-内酰胺类抗生素」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph38_q013","chapter":"第三十八章 β-内酰胺类抗生素","chapterIdx":37,"num":13},{"type":"D","stem":"名词解释：碳青霉烯类","answer":"非典型β-内酰胺类，抗菌谱最广、对β-内酰胺酶稳定，如亚胺培南、美罗培南，属特殊使用级抗菌药。","rationale":"出自概念手册「β-内酰胺类抗生素」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph38_q014","chapter":"第三十八章 β-内酰胺类抗生素","chapterIdx":37,"num":14},{"type":"D","stem":"名词解释：青霉素过敏性休克","answer":"青霉素最常见也最严重的变态反应，表现为呼吸困难、血压下降和意识丧失，须立即注射肾上腺素抢救。","rationale":"出自概念手册「β-内酰胺类抗生素」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph38_q015","chapter":"第三十八章 β-内酰胺类抗生素","chapterIdx":37,"num":15},{"type":"D","stem":"名词解释：赫氏反应","answer":"用青霉素治疗梅毒等螺旋体感染时，大量病原体被杀灭释放内毒素所致的寒战、发热和症状加重现象。","rationale":"出自概念手册「β-内酰胺类抗生素」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph38_q016","chapter":"第三十八章 β-内酰胺类抗生素","chapterIdx":37,"num":16},{"type":"D","stem":"名词解释：青霉素脑病","answer":"大剂量青霉素静脉给药或肾功能不全时药物在脑内蓄积，引起惊厥、昏迷等中枢神经毒性反应。","rationale":"出自概念手册「β-内酰胺类抗生素」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph38_q017","chapter":"第三十八章 β-内酰胺类抗生素","chapterIdx":37,"num":17},{"type":"S","stem":"简答题：简述青霉素G过敏性休克的防治措施。","answer":"①严格掌握适应证，用药前详细询问病史、用药过敏史及家族过敏史；②必须做青霉素皮肤过敏试验，初次使用、更换批号以及间隔时间超过24小时者均须重做，皮试阳性者禁用；③避免在病人饥饿时注射，并避免局部用药，以减少过敏反应发生；④注射后应留观半小时以上，同时做好急救准备；⑤一旦发生过敏性休克，首选肾上腺素抢救。","rationale":"采分点：问诊＋皮试（首次、换批号、停药超24小时）＋避免饥饿时注射与局部用药＋留观半小时＋肾上腺素为抢救首选。易错：把糖皮质激素或抗组胺药当作抢救首选药。","id":"rph38_q018","chapter":"第三十八章 β-内酰胺类抗生素","chapterIdx":37,"num":18},{"type":"F","stem":"填空题：β-内酰胺类抗生素的作用靶点是细菌细胞膜上的______，通过抑制其______活性而阻碍细胞壁肽聚糖的合成。","answer":"①青霉素结合蛋白（PBPs） ②转肽酶","rationale":"PBPs从细菌角度是肽聚糖合成的转肽酶，从药物角度是结合靶点；此外药物还可促发自溶酶活性，活化内源性自溶机制（次要机制）。","id":"rph38_q019","chapter":"第三十八章 β-内酰胺类抗生素","chapterIdx":37,"num":19},{"type":"F","stem":"填空题：头孢菌素类中第一、二代对G+菌作用强但有一定______毒性，第三、四代基本无毒；第三代对G-杆菌作用明显加强，且组织穿透力强、可透过______屏障。","answer":"①肾 ②血脑","rationale":"肾毒性大小是头孢菌素分代的重要差别：一、二代损害近曲小管细胞，三、四代基本无毒；能透过血脑屏障是第三代可用于中枢感染的基础。","id":"rph38_q020","chapter":"第三十八章 β-内酰胺类抗生素","chapterIdx":37,"num":20},{"type":"T","stem":"判断题：青霉素G对繁殖期细菌有强大杀菌作用，而对静止期细菌作用弱。","options":{"A":"正确","B":"错误"},"answer":["A"],"rationale":"青霉素G抑制细胞壁合成，繁殖期细菌正在合成肽聚糖，故对其作用强；静止期细菌不合成细胞壁，因此作用弱。这也是β-内酰胺类属繁殖期杀菌药的原因。","id":"rph38_q021","chapter":"第三十八章 β-内酰胺类抗生素","chapterIdx":37,"num":21},{"type":"T","stem":"判断题：MRSA对甲氧西林耐药是因为产生了β-内酰胺酶，因此改用β-内酰胺酶抑制剂复方即可恢复对它的敏感性。","options":{"A":"正确","B":"错误"},"answer":["B"],"rationale":"MRSA的耐药机制是产生了新的青霉素结合蛋白PBP2a，与β-内酰胺酶无关，故对全部β-内酰胺类耐药，加酶抑制剂无效，应选用万古霉素等。","id":"rph38_q022","chapter":"第三十八章 β-内酰胺类抗生素","chapterIdx":37,"num":22}]},{"title":"第三十九章 大环内酯类与林可霉素类抗生素","questions":[{"type":"D","stem":"名词解释：大环内酯类抗生素","answer":"含14、15或16元大环内酯环的一类抗生素，代表药有红霉素、阿奇霉素、克拉霉素、罗红霉素，属快速抑菌药，高浓度对敏感菌有杀菌作用。","rationale":"出自概念手册「大环内酯类与林可霉素类抗生素」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph39_q001","chapter":"第三十九章 大环内酯类与林可霉素类抗生素","chapterIdx":38,"num":1},{"type":"D","stem":"名词解释：红霉素","answer":"大环内酯类代表药，14元环，对革兰阳性菌及支原体、衣原体、军团菌作用强，口服易被胃酸破坏，多用肠溶片或酯化制剂，是青霉素过敏者的常用替代药。","rationale":"出自概念手册「大环内酯类与林可霉素类抗生素」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph39_q002","chapter":"第三十九章 大环内酯类与林可霉素类抗生素","chapterIdx":38,"num":2},{"type":"D","stem":"名词解释：阿奇霉素","answer":"15元环的氮杂内酯类，半衰期长达数十小时，组织与细胞内浓度高、释放缓慢，对革兰阴性菌及支原体、衣原体作用增强，可每日一次、短程给药。","rationale":"出自概念手册「大环内酯类与林可霉素类抗生素」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph39_q003","chapter":"第三十九章 大环内酯类与林可霉素类抗生素","chapterIdx":38,"num":3},{"type":"D","stem":"名词解释：克拉霉素","answer":"14元环大环内酯类，对幽门螺杆菌、鸟分枝杆菌、肺炎链球菌作用强，是根除幽门螺杆菌联合方案的重要组成，对肝药酶CYP3A4的抑制作用强。","rationale":"出自概念手册「大环内酯类与林可霉素类抗生素」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph39_q004","chapter":"第三十九章 大环内酯类与林可霉素类抗生素","chapterIdx":38,"num":4},{"type":"D","stem":"名词解释：罗红霉素","answer":"14元环半合成大环内酯类，口服吸收好、半衰期较长，血药浓度和组织浓度较高，胃肠道反应较红霉素轻，常用于呼吸道与泌尿生殖道感染。","rationale":"出自概念手册「大环内酯类与林可霉素类抗生素」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph39_q005","chapter":"第三十九章 大环内酯类与林可霉素类抗生素","chapterIdx":38,"num":5},{"type":"D","stem":"名词解释：泰利霉素","answer":"酮内酯类半合成大环内酯，与50S亚基23S rRNA的结构域Ⅱ结合，对耐大环内酯的肺炎链球菌有效，曾用于社区获得性肺炎，因肝毒性应用受限。","rationale":"出自概念手册「大环内酯类与林可霉素类抗生素」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph39_q006","chapter":"第三十九章 大环内酯类与林可霉素类抗生素","chapterIdx":38,"num":6},{"type":"D","stem":"名词解释：大环内酯类的作用机制","answer":"与细菌核糖体50S亚基的23S rRNA结合，抑制转肽酶和mRNA的移位，阻碍肽链延长，从而抑制蛋白质合成，属快速抑菌药。","rationale":"出自概念手册「大环内酯类与林可霉素类抗生素」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph39_q007","chapter":"第三十九章 大环内酯类与林可霉素类抗生素","chapterIdx":38,"num":7},{"type":"D","stem":"名词解释：大环内酯类的抗菌谱","answer":"抗菌谱较窄，对革兰阳性球菌、部分革兰阴性球菌、厌氧菌以及支原体、衣原体、军团菌、螺旋体、弯曲菌、百日咳鲍特菌等有良好作用。","rationale":"出自概念手册「大环内酯类与林可霉素类抗生素」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph39_q008","chapter":"第三十九章 大环内酯类与林可霉素类抗生素","chapterIdx":38,"num":8},{"type":"D","stem":"名词解释：非典型病原体","answer":"指支原体、衣原体、军团菌、立克次体等无典型细胞壁结构的病原体，β-内酰胺类对其无效，大环内酯类与四环素类是主要治疗药物。","rationale":"出自概念手册「大环内酯类与林可霉素类抗生素」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph39_q009","chapter":"第三十九章 大环内酯类与林可霉素类抗生素","chapterIdx":38,"num":9},{"type":"D","stem":"名词解释：大环内酯类的耐药机制","answer":"细菌可经erm基因甲基化23S rRNA使靶位改变、产生酯酶或磷酸化酶灭活药物、以主动外排泵泵出药物或减少摄入，同类药物间存在交叉耐药。","rationale":"出自概念手册「大环内酯类与林可霉素类抗生素」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph39_q010","chapter":"第三十九章 大环内酯类与林可霉素类抗生素","chapterIdx":38,"num":10},{"type":"D","stem":"名词解释：红霉素的体内过程","answer":"红霉素为碱性药物，口服易被胃酸破坏；吸收后广泛分布于组织和细胞内，组织浓度高于血药浓度；主要经胆汁排泄，可形成肝肠循环。","rationale":"出自概念手册「大环内酯类与林可霉素类抗生素」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph39_q011","chapter":"第三十九章 大环内酯类与林可霉素类抗生素","chapterIdx":38,"num":11},{"type":"D","stem":"名词解释：大环内酯类的肝损害","answer":"多由红霉素酯化物引起，表现为胆汁淤积性肝炎，有黄疸、转氨酶升高和嗜酸性粒细胞增多，多在用药后数日至数周发生，停药后多可恢复。","rationale":"出自概念手册「大环内酯类与林可霉素类抗生素」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph39_q012","chapter":"第三十九章 大环内酯类与林可霉素类抗生素","chapterIdx":38,"num":12},{"type":"D","stem":"名词解释：大环内酯类的耳毒性","answer":"大剂量、长疗程或肾功能不全时出现耳鸣、听力下降，多为双侧感音性耳聋，停药后大多可恢复，与氨基糖苷类的不可逆耳毒性不同。","rationale":"出自概念手册「大环内酯类与林可霉素类抗生素」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph39_q013","chapter":"第三十九章 大环内酯类与林可霉素类抗生素","chapterIdx":38,"num":13},{"type":"D","stem":"名词解释：大环内酯类的胃肠道反应","answer":"本类最常见的不良反应，与激动胃肠道促胃动素受体、促进胃肠蠕动有关，表现为恶心、呕吐、上腹不适、腹痛和腹泻，阿奇霉素相对较轻。","rationale":"出自概念手册「大环内酯类与林可霉素类抗生素」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph39_q014","chapter":"第三十九章 大环内酯类与林可霉素类抗生素","chapterIdx":38,"num":14},{"type":"D","stem":"名词解释：肝药酶抑制","answer":"红霉素、克拉霉素等14元环大环内酯类抑制CYP3A4，可使华法林、他汀类、茶碱、地高辛、麦角胺等合用药物浓度升高，引起出血、横纹肌溶解或中毒。","rationale":"出自概念手册「大环内酯类与林可霉素类抗生素」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph39_q015","chapter":"第三十九章 大环内酯类与林可霉素类抗生素","chapterIdx":38,"num":15},{"type":"D","stem":"名词解释：林可霉素类抗生素","answer":"包括林可霉素（洁霉素）与克林霉素（氯洁霉素），结构与作用机制类似大环内酯类，结合50S亚基抑制肽链延长，对革兰阳性菌和厌氧菌有效。","rationale":"出自概念手册「大环内酯类与林可霉素类抗生素」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph39_q016","chapter":"第三十九章 大环内酯类与林可霉素类抗生素","chapterIdx":38,"num":16},{"type":"D","stem":"名词解释：克林霉素","answer":"林可霉素的半合成衍生物，抗菌活性比林可霉素强4至8倍，口服吸收完全且不受食物影响，在骨组织中浓度高，是金葡菌性骨髓炎的常用药。","rationale":"出自概念手册「大环内酯类与林可霉素类抗生素」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph39_q017","chapter":"第三十九章 大环内酯类与林可霉素类抗生素","chapterIdx":38,"num":17},{"type":"D","stem":"名词解释：假膜性肠炎","answer":"林可霉素类最严重的不良反应，因肠道菌群失调致难辨梭菌大量繁殖并产生毒素，表现为水样腹泻、腹痛、发热和伪膜排出，重者可致脱水与休克。","rationale":"出自概念手册「大环内酯类与林可霉素类抗生素」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph39_q018","chapter":"第三十九章 大环内酯类与林可霉素类抗生素","chapterIdx":38,"num":18},{"type":"S","stem":"简答题：简述大环内酯类抗生素的抗菌作用机制、耐药机制和主要不良反应。","answer":"①抗菌机制：不可逆地与细菌核糖体50S亚基结合，抑制肽酰基转移酶、阻止新生肽链延伸，从而抑制细菌蛋白质合成，通常呈抑菌作用，高浓度对敏感菌可呈杀菌作用；②耐药机制：靶位结构改变（核糖体保护）、产生灭活酶（酯酶）水解或修饰药物、菌体内有效药物浓度降低（摄入减少、外排增多）；③刺激反应：口服致消化道反应，静脉给药可致血栓性静脉炎，并可有肝损害；④大剂量可致耳鸣、暂时性听觉障碍和心脏毒性；⑤长期应用可致二重感染，如舌炎、口角炎、伪膜性肠炎。","rationale":"采分点为“结合50S亚基、抑制肽酰基转移酶”“核糖体保护＋灭活酶＋外排”“胃肠道刺激、肝损害、耳与心脏毒性、二重感染”。易错：说成作用于30S亚基或抑制转肽酶（那是β-内酰胺类的靶点）。","id":"rph39_q019","chapter":"第三十九章 大环内酯类与林可霉素类抗生素","chapterIdx":38,"num":19},{"type":"F","stem":"填空题：大环内酯类、林可霉素类和氯霉素都作用于细菌核糖体的______亚基，结合位点相同或相近，故这几类药物合用可能发生______。","answer":"①50S ②拮抗","rationale":"结合位点相同或邻近会相互竞争，导致疗效降低而非增强；这是联合用药中“作用机制（靶点）相似者不宜合用”的典型例子。","id":"rph39_q020","chapter":"第三十九章 大环内酯类与林可霉素类抗生素","chapterIdx":38,"num":20},{"type":"F","stem":"填空题：林可霉素类在体内分布广泛，在______组织中浓度更高，故金葡菌所致______的首选药物是克林霉素。","answer":"①骨 ②骨髓炎","rationale":"骨组织浓度高是林可霉素类的突出药动学特点，也是其“金葡菌骨髓炎首选”的依据；该类药物不能透过血脑屏障。","id":"rph39_q021","chapter":"第三十九章 大环内酯类与林可霉素类抗生素","chapterIdx":38,"num":21},{"type":"T","stem":"判断题：万古霉素对耐甲氧西林金黄色葡萄球菌（MRSA）有强大杀菌作用，静脉滴注过快可引起红人综合征。","options":{"A":"正确","B":"错误"},"answer":["A"],"rationale":"万古霉素属多肽类，抑制细胞壁肽聚糖合成，是治疗MRSA、MRSE及肠球菌严重感染的重要药物；“红人综合征”由注射过快引起组胺释放所致，应缓慢滴注。","id":"rph39_q022","chapter":"第三十九章 大环内酯类与林可霉素类抗生素","chapterIdx":38,"num":22},{"type":"T","stem":"判断题：阿奇霉素属于14元环大环内酯类，是治疗幽门螺杆菌感染不可被同类其他药物替代的药物。","options":{"A":"正确","B":"错误"},"answer":["B"],"rationale":"阿奇霉素是15元环，14元环的代表是红霉素、克拉霉素；治疗幽门螺杆菌不可替代的是克拉霉素，它也是大环内酯类中抗菌活性最强者。","id":"rph39_q023","chapter":"第三十九章 大环内酯类与林可霉素类抗生素","chapterIdx":38,"num":23}]},{"title":"第四十章 氨基糖苷类与多肽类抗生素","questions":[{"type":"D","stem":"名词解释：多肽类抗生素","answer":"由肽键连接氨基酸组成的一类抗生素，包括万古霉素类、多黏菌素类和杆菌肽，多数抗菌作用强但毒性较大，主要用于耐药菌和严重感染。","rationale":"出自概念手册「氨基糖苷类与多肽类抗生素」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph40_q001","chapter":"第四十章 氨基糖苷类与多肽类抗生素","chapterIdx":39,"num":1},{"type":"D","stem":"名词解释：氨基糖苷类抗生素","answer":"由氨基糖分子与氨基环醇通过氧桥连接而成的苷类抗生素，包括链霉素、庆大霉素、阿米卡星等，对需氧革兰阴性杆菌作用强。","rationale":"出自概念手册「氨基糖苷类与多肽类抗生素」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph40_q002","chapter":"第四十章 氨基糖苷类与多肽类抗生素","chapterIdx":39,"num":2},{"type":"D","stem":"名词解释：链霉素","answer":"第一个用于临床的氨基糖苷类，对结核分枝杆菌作用强，是抗结核一线药物，耳毒性和变态反应较突出，现用于结核病联合治疗、鼠疫和兔热病。","rationale":"出自概念手册「氨基糖苷类与多肽类抗生素」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph40_q003","chapter":"第四十章 氨基糖苷类与多肽类抗生素","chapterIdx":39,"num":3},{"type":"D","stem":"名词解释：庆大霉素","answer":"氨基糖苷类代表药，对革兰阴性杆菌包括铜绿假单胞菌作用强，是治疗严重革兰阴性杆菌感染的重要药物，肾毒性较明显。","rationale":"出自概念手册「氨基糖苷类与多肽类抗生素」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph40_q004","chapter":"第四十章 氨基糖苷类与多肽类抗生素","chapterIdx":39,"num":4},{"type":"D","stem":"名词解释：妥布霉素","answer":"抗铜绿假单胞菌作用较庆大霉素强，耳毒性和肾毒性相对较低，常用于铜绿假单胞菌所致感染。","rationale":"出自概念手册「氨基糖苷类与多肽类抗生素」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph40_q005","chapter":"第四十章 氨基糖苷类与多肽类抗生素","chapterIdx":39,"num":5},{"type":"D","stem":"名词解释：阿米卡星（丁胺卡那霉素）","answer":"氨基糖苷类中对细菌钝化酶最稳定的药物，抗菌谱较广，用于对庆大霉素耐药的革兰阴性杆菌感染。","rationale":"出自概念手册「氨基糖苷类与多肽类抗生素」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph40_q006","chapter":"第四十章 氨基糖苷类与多肽类抗生素","chapterIdx":39,"num":6},{"type":"D","stem":"名词解释：奈替米星","answer":"氨基糖苷类中耳肾毒性相对较低的品种，对革兰阴性杆菌及部分耐药菌有效，适用于需较长期用药的革兰阴性杆菌感染。","rationale":"出自概念手册「氨基糖苷类与多肽类抗生素」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph40_q007","chapter":"第四十章 氨基糖苷类与多肽类抗生素","chapterIdx":39,"num":7},{"type":"D","stem":"名词解释：异帕米星","answer":"半合成氨基糖苷类，对多种钝化酶稳定，抗菌活性与阿米卡星相近，耳毒性和肾毒性相对较低。","rationale":"出自概念手册「氨基糖苷类与多肽类抗生素」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph40_q008","chapter":"第四十章 氨基糖苷类与多肽类抗生素","chapterIdx":39,"num":8},{"type":"D","stem":"名词解释：新霉素","answer":"抗菌谱广但毒性大，全身应用已被淘汰；口服难吸收，仅用于肠道感染和腹部手术前肠道消毒，局部外用可致接触性皮炎。","rationale":"出自概念手册「氨基糖苷类与多肽类抗生素」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph40_q009","chapter":"第四十章 氨基糖苷类与多肽类抗生素","chapterIdx":39,"num":9},{"type":"D","stem":"名词解释：大观霉素","answer":"氨基糖苷类中的特殊品种，对淋病奈瑟菌作用强，用于对青霉素过敏或耐药的单纯性淋病治疗。","rationale":"出自概念手册「氨基糖苷类与多肽类抗生素」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph40_q010","chapter":"第四十章 氨基糖苷类与多肽类抗生素","chapterIdx":39,"num":10},{"type":"D","stem":"名词解释：氨基糖苷钝化酶","answer":"细菌产生的使氨基糖苷类分子上的羟基或氨基被磷酸化、腺苷化或乙酰化而失活的酶，是本类最主要的耐药机制。","rationale":"出自概念手册「氨基糖苷类与多肽类抗生素」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph40_q011","chapter":"第四十章 氨基糖苷类与多肽类抗生素","chapterIdx":39,"num":11},{"type":"D","stem":"名词解释：氨基糖苷类的体内过程","answer":"口服难吸收，须注射给药；血浆蛋白结合率低，主要经肾小球滤过以原形排泄，可透过胎盘但不易透过血脑屏障。","rationale":"出自概念手册「氨基糖苷类与多肽类抗生素」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph40_q012","chapter":"第四十章 氨基糖苷类与多肽类抗生素","chapterIdx":39,"num":12},{"type":"D","stem":"名词解释：耳毒性","answer":"氨基糖苷类损害第Ⅷ对脑神经，表现为前庭功能失调（眩晕、平衡障碍）和耳蜗神经损害（耳鸣、听力下降甚至耳聋），后者常不可逆。","rationale":"出自概念手册「氨基糖苷类与多肽类抗生素」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph40_q013","chapter":"第四十章 氨基糖苷类与多肽类抗生素","chapterIdx":39,"num":13},{"type":"D","stem":"名词解释：肾毒性","answer":"药物经肾排泄并在近曲小管上皮细胞蓄积，引起蛋白尿、管型尿和血尿素氮升高，严重者可致急性肾衰竭，停药后多可恢复。","rationale":"出自概念手册「氨基糖苷类与多肽类抗生素」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph40_q014","chapter":"第四十章 氨基糖苷类与多肽类抗生素","chapterIdx":39,"num":14},{"type":"D","stem":"名词解释：神经肌肉阻滞","answer":"氨基糖苷类抑制神经末梢乙酰胆碱释放并降低突触后膜对递质的敏感性，引起肌无力甚至呼吸抑制，可用钙剂或新斯的明解救。","rationale":"出自概念手册「氨基糖苷类与多肽类抗生素」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph40_q015","chapter":"第四十章 氨基糖苷类与多肽类抗生素","chapterIdx":39,"num":15},{"type":"D","stem":"名词解释：浓度依赖性杀菌","answer":"氨基糖苷类的杀菌作用随药物浓度升高而增强，峰浓度与最低抑菌浓度的比值越高疗效越好，是每日一次给药的依据。","rationale":"出自概念手册「氨基糖苷类与多肽类抗生素」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph40_q016","chapter":"第四十章 氨基糖苷类与多肽类抗生素","chapterIdx":39,"num":16},{"type":"D","stem":"名词解释：每日一次给药方案","answer":"将全天剂量一次给予的给药方法，利用浓度依赖性杀菌和明显的抗菌后效应，疗效不降而耳肾毒性减轻。","rationale":"出自概念手册「氨基糖苷类与多肽类抗生素」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph40_q017","chapter":"第四十章 氨基糖苷类与多肽类抗生素","chapterIdx":39,"num":17},{"type":"D","stem":"名词解释：万古霉素","answer":"糖肽类抗生素，与细菌细胞壁前体D-丙氨酰-D-丙氨酸结合，抑制肽聚糖合成，对耐甲氧西林金葡菌等革兰阳性球菌是重要药物。","rationale":"出自概念手册「氨基糖苷类与多肽类抗生素」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph40_q018","chapter":"第四十章 氨基糖苷类与多肽类抗生素","chapterIdx":39,"num":18},{"type":"D","stem":"名词解释：去甲万古霉素","answer":"我国自行生产的糖肽类抗生素，抗菌作用与万古霉素相似而效价略高，主要用于耐甲氧西林金葡菌所致严重感染。","rationale":"出自概念手册「氨基糖苷类与多肽类抗生素」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph40_q019","chapter":"第四十章 氨基糖苷类与多肽类抗生素","chapterIdx":39,"num":19},{"type":"D","stem":"名词解释：替考拉宁","answer":"糖肽类抗生素，作用机制与万古霉素相同，半衰期长可每日给药一次，肌内注射耐受性好，耳毒性和肾毒性较低。","rationale":"出自概念手册「氨基糖苷类与多肽类抗生素」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph40_q020","chapter":"第四十章 氨基糖苷类与多肽类抗生素","chapterIdx":39,"num":20},{"type":"D","stem":"名词解释：万古霉素类的作用机制","answer":"与细胞壁肽聚糖前体末端的D-丙氨酰-D-丙氨酸结合，阻止转糖基和转肽反应，使肽聚糖不能延伸，对生长繁殖期细菌有杀菌作用。","rationale":"出自概念手册「氨基糖苷类与多肽类抗生素」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph40_q021","chapter":"第四十章 氨基糖苷类与多肽类抗生素","chapterIdx":39,"num":21},{"type":"D","stem":"名词解释：红人综合征","answer":"万古霉素快速静脉滴注时组胺释放引起的面部、颈部和躯干上部潮红、瘙痒和低血压，减慢滴速并预先给予抗组胺药可预防。","rationale":"出自概念手册「氨基糖苷类与多肽类抗生素」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph40_q022","chapter":"第四十章 氨基糖苷类与多肽类抗生素","chapterIdx":39,"num":22},{"type":"D","stem":"名词解释：多黏菌素类","answer":"多肽类抗生素，包括多黏菌素B和多黏菌素E（黏菌素），与革兰阴性菌外膜脂多糖结合使膜通透性增加而杀菌，肾毒性与神经毒性明显。","rationale":"出自概念手册「氨基糖苷类与多肽类抗生素」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph40_q023","chapter":"第四十章 氨基糖苷类与多肽类抗生素","chapterIdx":39,"num":23},{"type":"D","stem":"名词解释：杆菌肽","answer":"多肽类抗生素，抑制细菌细胞壁合成中的焦磷酸酯载体反应，对革兰阳性菌作用强，全身应用肾毒性大，仅作局部外用。","rationale":"出自概念手册「氨基糖苷类与多肽类抗生素」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph40_q024","chapter":"第四十章 氨基糖苷类与多肽类抗生素","chapterIdx":39,"num":24},{"type":"S","stem":"简答题：简述氨基糖苷类抗生素的主要不良反应及应用注意事项。","answer":"①耳毒性：可致前庭功能障碍（头昏、眩晕、眼球震颤、共济失调）和耳蜗听神经损伤（耳鸣、听力减退、耳聋），所有氨基糖苷类均有耳毒性；②肾毒性：药物在肾皮质聚积，主要损害近曲小管上皮细胞，轻者出现蛋白尿、血尿，重者肾小管坏死、无尿、氮质血症甚至肾衰竭；③神经肌肉麻痹：与突触前膜“钙结合部位”结合，抑制神经末梢释放乙酰胆碱，阻断神经肌肉接头处传递；④变态反应：皮疹、发热、血管神经性水肿等，链霉素可致过敏性休克，其发生率仅次于青霉素G；⑤注意事项：严格掌握适应证、控制剂量与疗程，监测听力与肾功能并定期测血药浓度，避免与高效利尿药、万古霉素类、甘露醇、镇吐药及镇静催眠药等合用。","rationale":"采分点为“耳毒性、肾毒性、神经肌肉麻痹、变态反应”四大不良反应，以及监测听力与肾功能、避免合用其他耳毒性与肾毒性药物。易错：漏掉神经肌肉麻痹可被镇静催眠药加重这一要点。","id":"rph40_q025","chapter":"第四十章 氨基糖苷类与多肽类抗生素","chapterIdx":39,"num":25},{"type":"F","stem":"填空题：氨基糖苷类抗生素主要抑制细菌蛋白质合成的______，结合位点是核糖体______亚基，并使mRNA错译而合成无功能的蛋白质。","answer":"①全过程（起始、延伸、终止三个阶段） ②30S","rationale":"作用环节包括起始期抑制始动复合物形成、延伸期与30S亚基P10蛋白结合致mRNA错译、终止期阻止终止因子结合；抑制全过程是它区别于其他50S亚基药物的特点。","id":"rph40_q026","chapter":"第四十章 氨基糖苷类与多肽类抗生素","chapterIdx":39,"num":26},{"type":"F","stem":"填空题：氨基糖苷类口服难吸收，主要分布于______液，不易透过血脑屏障但可透过胎盘，以原形经______排出，故肾功能不全时易蓄积中毒。","answer":"①细胞外 ②肾小球滤过","rationale":"极性大、解离度大决定了其分布特点；不经代谢、以原形经肾小球滤过排出，故肾功能减退时须调整剂量并监测血药浓度。","id":"rph40_q027","chapter":"第四十章 氨基糖苷类与多肽类抗生素","chapterIdx":39,"num":27},{"type":"T","stem":"判断题：氨基糖苷类对厌氧菌天然耐药，原因是该类药物进入菌体需要氧依赖性的主动跨膜转运系统。","options":{"A":"正确","B":"错误"},"answer":["A"],"rationale":"氨基糖苷类极性大，必须依靠氧依赖性主动转运进入细菌，厌氧菌缺乏该转运系统，故天然耐药，这是其抗菌谱只覆盖需氧菌的根本原因。","id":"rph40_q028","chapter":"第四十章 氨基糖苷类与多肽类抗生素","chapterIdx":39,"num":28},{"type":"T","stem":"判断题：氨基糖苷类属于繁殖期杀菌药，其杀菌速率不呈浓度依赖性。","options":{"A":"正确","B":"错误"},"answer":["B"],"rationale":"氨基糖苷类是静止期杀菌药，杀菌速率与时程呈浓度依赖性，并有较长的抗生素后效应和明显的首次接触效应，故给药方案不同于β-内酰胺类。","id":"rph40_q029","chapter":"第四十章 氨基糖苷类与多肽类抗生素","chapterIdx":39,"num":29}]},{"title":"第四十一章 四环素类与氯霉素类抗生素","questions":[{"type":"D","stem":"名词解释：四环素类抗生素","answer":"含并四苯母核的广谱抗生素，包括四环素、土霉素、多西环素、米诺环素和替加环素，与核糖体30S亚基结合抑制蛋白质合成而抑菌。","rationale":"出自概念手册「四环素类与氯霉素类抗生素」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph41_q001","chapter":"第四十一章 四环素类与氯霉素类抗生素","chapterIdx":40,"num":1},{"type":"D","stem":"名词解释：四环素","answer":"天然四环素类的代表，抗菌谱广但不良反应多、耐药普遍，口服受食物和金属离子影响大，现多用于局部或少数特定感染。","rationale":"出自概念手册「四环素类与氯霉素类抗生素」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph41_q002","chapter":"第四十一章 四环素类与氯霉素类抗生素","chapterIdx":40,"num":2},{"type":"F","stem":"填空题：天然______类的代表，抗菌谱广但不良反应多、耐药普遍，口服受食物和金属离子影响大，现多用于局部或少数特定感染。","answer":"四环素","rationale":"出自概念手册「四环素类与氯霉素类抗生素」核心概念：四环素。","id":"rph41_q003","chapter":"第四十一章 四环素类与氯霉素类抗生素","chapterIdx":40,"num":3},{"type":"D","stem":"名词解释：土霉素","answer":"天然四环素类，抗菌作用较四环素弱，不良反应相似，因耐药与疗效问题现主要用于肠道感染和兽医领域。","rationale":"出自概念手册「四环素类与氯霉素类抗生素」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph41_q004","chapter":"第四十一章 四环素类与氯霉素类抗生素","chapterIdx":40,"num":4},{"type":"D","stem":"名词解释：多西环素（强力霉素）","answer":"半合成四环素类，脂溶性高、口服吸收好且不受食物影响，半衰期长可每日给药一至两次，抗菌作用强，是四环素类中的首选药物。","rationale":"出自概念手册「四环素类与氯霉素类抗生素」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph41_q005","chapter":"第四十一章 四环素类与氯霉素类抗生素","chapterIdx":40,"num":5},{"type":"D","stem":"名词解释：米诺环素（二甲胺四环素）","answer":"四环素类中抗菌作用最强者，脂溶性高、易透过血脑屏障，但较易引起可逆的前庭反应，表现为眩晕和共济失调。","rationale":"出自概念手册「四环素类与氯霉素类抗生素」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph41_q006","chapter":"第四十一章 四环素类与氯霉素类抗生素","chapterIdx":40,"num":6},{"type":"D","stem":"名词解释：替加环素","answer":"甘氨酰环素类，为米诺环素的衍生物，不受外排泵和核糖体保护蛋白所致耐药影响，用于复杂性腹腔感染和复杂皮肤软组织感染。","rationale":"出自概念手册「四环素类与氯霉素类抗生素」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph41_q007","chapter":"第四十一章 四环素类与氯霉素类抗生素","chapterIdx":40,"num":7},{"type":"D","stem":"名词解释：四环素类的作用机制","answer":"与细菌核糖体30S亚基的A位结合，阻止氨基酰tRNA进入A位，抑制肽链延长和蛋白质合成，属快速抑菌药，高浓度对部分细菌有杀菌作用。","rationale":"出自概念手册「四环素类与氯霉素类抗生素」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph41_q008","chapter":"第四十一章 四环素类与氯霉素类抗生素","chapterIdx":40,"num":8},{"type":"D","stem":"名词解释：四环素类的抗菌谱","answer":"抗菌谱广，对革兰阳性菌与阴性菌、立克次体、衣原体、支原体、螺旋体、放线菌、阿米巴原虫等均有作用，但对铜绿假单胞菌和真菌无效。","rationale":"出自概念手册「四环素类与氯霉素类抗生素」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph41_q009","chapter":"第四十一章 四环素类与氯霉素类抗生素","chapterIdx":40,"num":9},{"type":"D","stem":"名词解释：四环素牙与骨生长抑制","answer":"四环素类与钙络合沉积于牙齿和骨骼，致牙齿黄染、釉质发育不全和骨生长抑制，孕妇及8岁以下儿童禁用。","rationale":"出自概念手册「四环素类与氯霉素类抗生素」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph41_q010","chapter":"第四十一章 四环素类与氯霉素类抗生素","chapterIdx":40,"num":10},{"type":"D","stem":"名词解释：四环素类的吸收干扰","answer":"与含钙、镁、铝、铁、铋的药物或食物同服可形成络合物而减少吸收，故应空腹服用并与上述药物间隔2小时以上。","rationale":"出自概念手册「四环素类与氯霉素类抗生素」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph41_q011","chapter":"第四十一章 四环素类与氯霉素类抗生素","chapterIdx":40,"num":11},{"type":"D","stem":"名词解释：四环素类的二重感染","answer":"长期或大剂量用药使敏感菌被抑制、菌群失调，耐药菌和真菌趁机繁殖，常见白色念珠菌感染和难辨梭菌性肠炎。","rationale":"出自概念手册「四环素类与氯霉素类抗生素」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph41_q012","chapter":"第四十一章 四环素类与氯霉素类抗生素","chapterIdx":40,"num":12},{"type":"D","stem":"名词解释：四环素类的肝损害","answer":"大剂量静脉给药、孕妇或原有肝病者易发生，表现为肝脂肪变性、转氨酶升高和黄疸，严重者可致肝性脑病。","rationale":"出自概念手册「四环素类与氯霉素类抗生素」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph41_q013","chapter":"第四十一章 四环素类与氯霉素类抗生素","chapterIdx":40,"num":13},{"type":"D","stem":"名词解释：光敏反应","answer":"多西环素和地美环素等使皮肤对紫外线敏感性增高，曝晒后出现红斑、水疱和色素沉着，用药期间应避免日晒。","rationale":"出自概念手册「四环素类与氯霉素类抗生素」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph41_q014","chapter":"第四十一章 四环素类与氯霉素类抗生素","chapterIdx":40,"num":14},{"type":"D","stem":"名词解释：前庭反应","answer":"米诺环素较易引起眩晕、恶心、共济失调和平衡障碍，多在用药后数日出现，停药后可恢复，属可逆性反应。","rationale":"出自概念手册「四环素类与氯霉素类抗生素」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph41_q015","chapter":"第四十一章 四环素类与氯霉素类抗生素","chapterIdx":40,"num":15},{"type":"D","stem":"名词解释：四环素类的耐药性","answer":"细菌主要通过主动外排泵、产生核糖体保护蛋白和灭活酶而耐药，耐药基因多位于质粒或转座子上，同类药物间交叉耐药明显。","rationale":"出自概念手册「四环素类与氯霉素类抗生素」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph41_q016","chapter":"第四十一章 四环素类与氯霉素类抗生素","chapterIdx":40,"num":16},{"type":"D","stem":"名词解释：氯霉素","answer":"广谱抗生素，与核糖体50S亚基的肽酰转移酶结合、抑制肽键形成，因可致再生障碍性贫血而限制全身应用，多用于伤寒和细菌性脑膜炎。","rationale":"出自概念手册「四环素类与氯霉素类抗生素」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph41_q017","chapter":"第四十一章 四环素类与氯霉素类抗生素","chapterIdx":40,"num":17},{"type":"D","stem":"名词解释：氯霉素的骨髓抑制","answer":"分两型：与剂量和疗程相关的可逆性骨髓抑制，以及发生率低、与剂量无关且不可逆的再生障碍性贫血。","rationale":"出自概念手册「四环素类与氯霉素类抗生素」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph41_q018","chapter":"第四十一章 四环素类与氯霉素类抗生素","chapterIdx":40,"num":18},{"type":"D","stem":"名词解释：灰婴综合征","answer":"新生儿肝葡萄糖醛酸转移酶不足使氯霉素蓄积，引起腹胀、呕吐、皮肤灰紫和循环衰竭的严重毒性反应，故新生儿与早产儿禁用。","rationale":"出自概念手册「四环素类与氯霉素类抗生素」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph41_q019","chapter":"第四十一章 四环素类与氯霉素类抗生素","chapterIdx":40,"num":19},{"type":"D","stem":"名词解释：氯霉素的体内过程","answer":"口服吸收完全，血浆蛋白结合率低，易透过血脑屏障使脑脊液浓度达血药浓度的半数以上，主要在肝内与葡萄糖醛酸结合后经肾排泄。","rationale":"出自概念手册「四环素类与氯霉素类抗生素」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph41_q020","chapter":"第四十一章 四环素类与氯霉素类抗生素","chapterIdx":40,"num":20},{"type":"D","stem":"名词解释：氯霉素的肝药酶抑制","answer":"氯霉素抑制肝药酶，可使华法林、苯妥英钠、甲苯磺丁脲等合用药物代谢减慢、血药浓度升高，联用时需调整剂量。","rationale":"出自概念手册「四环素类与氯霉素类抗生素」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph41_q021","chapter":"第四十一章 四环素类与氯霉素类抗生素","chapterIdx":40,"num":21},{"type":"S","stem":"简答题：简述四环素类药物的主要不良反应。","answer":"①胃肠道反应：恶心、呕吐、食欲减退等；②二重感染：长期应用广谱抗生素引起继发感染，如白色念珠菌所致鹅口疮与肠炎、难辨梭菌所致假膜性肠炎；③对牙齿和骨骼发育的影响：与钙化组织中的钙结合，致牙齿黄染、牙釉质发育不全（四环素牙），并可抑制骨质生成、影响骨骼生长，故孕妇与婴幼儿禁用；④肝毒性：可致急性肝细胞脂肪性坏死；⑤光敏反应：药物在皮肤聚积吸收紫外线而损伤皮肤，此外尚有肾毒性和前庭反应。","rationale":"采分点：胃肠道反应、二重感染、牙齿黄染与骨骼影响（孕妇与婴幼儿禁用）、肝毒性、光敏反应。易错：把灰婴综合征当作四环素类的不良反应（它属氯霉素）。","id":"rph41_q022","chapter":"第四十一章 四环素类与氯霉素类抗生素","chapterIdx":40,"num":22},{"type":"F","stem":"填空题：四环素类与氯霉素类均属______抗生素；四环素类结合细菌核糖体______亚基的A位，阻止氨基酰-tRNA进入A位而阻断肽链延伸。","answer":"①广谱 ②30S","rationale":"四环素类作用于30S亚基A位，氯霉素作用于50S亚基肽酰基转移酶部位，两者作用位点不同但均抑制蛋白质合成。","id":"rph41_q023","chapter":"第四十一章 四环素类与氯霉素类抗生素","chapterIdx":40,"num":23},{"type":"F","stem":"填空题：氯霉素的血液系统毒性有两型，一是与剂量相关的可逆性______减少，二是与剂量及疗程无关的______性贫血。","answer":"①血小板 ②再生障碍","rationale":"前者与抑制宿主骨髓细胞线粒体（其核糖体与细菌相似）的血红蛋白合成有关，后者属特异质反应、与剂量疗程无关且死亡率高，故氯霉素应用受限。","id":"rph41_q024","chapter":"第四十一章 四环素类与氯霉素类抗生素","chapterIdx":40,"num":24},{"type":"T","stem":"判断题：四环素类可引起灰婴综合征，因早产儿与新生儿肝脏葡萄糖醛酸转移酶缺乏、肾脏排泄功能不完善。","options":{"A":"正确","B":"错误"},"answer":["B"],"rationale":"灰婴综合征是氯霉素的严重不良反应，表现为循环衰竭、呼吸困难、进行性血压下降、皮肤苍白发绀，死亡率高；四环素类主要损害牙齿与骨骼发育，二者不可混淆。","id":"rph41_q025","chapter":"第四十一章 四环素类与氯霉素类抗生素","chapterIdx":40,"num":25},{"type":"T","stem":"判断题：氯霉素与青霉素合用治疗脑脓肿时，两药不能置于同一容器内滴注，且应先给青霉素、间隔后再给氯霉素。","options":{"A":"正确","B":"错误"},"answer":["A"],"rationale":"氯霉素为快速抑菌药，会使细菌停止繁殖，从而干扰青霉素这一繁殖期杀菌药的杀菌作用，故必须按顺序间隔给药，不能同时混合滴注。","id":"rph41_q026","chapter":"第四十一章 四环素类与氯霉素类抗生素","chapterIdx":40,"num":26}]},{"title":"第四十二章 抗病毒药与抗真菌药","questions":[{"type":"D","stem":"名词解释：抗病毒药","answer":"抑制病毒吸附、穿入、脱壳、核酸复制或装配释放的药物，多数只能抑制正在复制的病毒，对潜伏状态的病毒无效。","rationale":"出自概念手册「抗病毒药与抗真菌药」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph42_q001","chapter":"第四十二章 抗病毒药与抗真菌药","chapterIdx":41,"num":1},{"type":"D","stem":"名词解释：阿昔洛韦","answer":"鸟苷类似物，需经病毒胸苷激酶磷酸化后竞争性抑制病毒DNA聚合酶并终止DNA链延伸，对单纯疱疹病毒和水痘带状疱疹病毒有效。","rationale":"出自概念手册「抗病毒药与抗真菌药」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph42_q002","chapter":"第四十二章 抗病毒药与抗真菌药","chapterIdx":41,"num":2},{"type":"D","stem":"名词解释：伐昔洛韦","answer":"阿昔洛韦的缬氨酸酯前体药，口服生物利用度提高数倍，在体内迅速水解为阿昔洛韦，用于带状疱疹和生殖器疱疹，服药次数少。","rationale":"出自概念手册「抗病毒药与抗真菌药」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph42_q003","chapter":"第四十二章 抗病毒药与抗真菌药","chapterIdx":41,"num":3},{"type":"D","stem":"名词解释：更昔洛韦","answer":"又称丙氧鸟苷，抗病毒谱以巨细胞病毒为主，不需病毒胸苷激酶活化即可被细胞激酶磷酸化，主要毒性为骨髓抑制。","rationale":"出自概念手册「抗病毒药与抗真菌药」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph42_q004","chapter":"第四十二章 抗病毒药与抗真菌药","chapterIdx":41,"num":4},{"type":"D","stem":"名词解释：奥司他韦","answer":"神经氨酸酶抑制剂，阻断流感病毒从感染细胞释放和扩散，对甲型与乙型流感均有效，发病早期用药可缩短病程。","rationale":"出自概念手册「抗病毒药与抗真菌药」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph42_q005","chapter":"第四十二章 抗病毒药与抗真菌药","chapterIdx":41,"num":5},{"type":"D","stem":"名词解释：干扰素","answer":"机体细胞在病毒感染等诱导下产生的糖蛋白，与细胞表面受体结合后激活抗病毒蛋白合成，具有抗病毒、免疫调节和抗增殖作用。","rationale":"出自概念手册「抗病毒药与抗真菌药」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph42_q007","chapter":"第四十二章 抗病毒药与抗真菌药","chapterIdx":41,"num":7},{"type":"D","stem":"名词解释：拉米夫定","answer":"胞嘧啶核苷类似物，抑制乙型肝炎病毒DNA聚合酶和HIV逆转录酶，停药后易出现肝炎反跳，也用于艾滋病联合治疗。","rationale":"出自概念手册「抗病毒药与抗真菌药」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph42_q008","chapter":"第四十二章 抗病毒药与抗真菌药","chapterIdx":41,"num":8},{"type":"D","stem":"名词解释：恩替卡韦","answer":"鸟苷类似物，对乙型肝炎病毒DNA聚合酶有强抑制作用，耐药发生率低，是慢性乙型肝炎的一线口服药物。","rationale":"出自概念手册「抗病毒药与抗真菌药」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph42_q009","chapter":"第四十二章 抗病毒药与抗真菌药","chapterIdx":41,"num":9},{"type":"D","stem":"名词解释：齐多夫定","answer":"又称AZT，核苷类逆转录酶抑制剂，在体内磷酸化后竞争性抑制HIV逆转录酶并终止DNA链合成，主要不良反应为骨髓抑制。","rationale":"出自概念手册「抗病毒药与抗真菌药」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph42_q010","chapter":"第四十二章 抗病毒药与抗真菌药","chapterIdx":41,"num":10},{"type":"D","stem":"名词解释：奈韦拉平","answer":"非核苷类逆转录酶抑制剂，与逆转录酶的非底物结合位点结合而使酶失活，不需细胞内磷酸化，可致严重肝毒性和皮疹。","rationale":"出自概念手册「抗病毒药与抗真菌药」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph42_q011","chapter":"第四十二章 抗病毒药与抗真菌药","chapterIdx":41,"num":11},{"type":"D","stem":"名词解释：蛋白酶抑制药","answer":"抑制HIV天冬氨酸蛋白酶、使病毒前体蛋白不能裂解为成熟蛋白的药物，如利托那韦、洛匹那韦，常与低剂量利托那韦合用增效。","rationale":"出自概念手册「抗病毒药与抗真菌药」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph42_q012","chapter":"第四十二章 抗病毒药与抗真菌药","chapterIdx":41,"num":12},{"type":"D","stem":"名词解释：高效抗逆转录病毒治疗","answer":"又称HAART，联合三种以上抗HIV药物作用于不同环节，可长期抑制病毒复制、重建免疫功能，需终身用药。","rationale":"出自概念手册「抗病毒药与抗真菌药」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph42_q013","chapter":"第四十二章 抗病毒药与抗真菌药","chapterIdx":41,"num":13},{"type":"D","stem":"名词解释：抗真菌药","answer":"能抑制或杀灭真菌的药物，按化学结构分为抗真菌抗生素（多烯类、灰黄霉素）、唑类、棘白菌素类、氟胞嘧啶类及丙烯胺类。","rationale":"出自概念手册「抗病毒药与抗真菌药」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph42_q014","chapter":"第四十二章 抗病毒药与抗真菌药","chapterIdx":41,"num":14},{"type":"D","stem":"名词解释：两性霉素B","answer":"多烯类抗真菌抗生素，与真菌细胞膜麦角固醇结合形成孔道使胞内物质外漏，是治疗重症深部真菌病的经典药物。","rationale":"出自概念手册「抗病毒药与抗真菌药」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph42_q015","chapter":"第四十二章 抗病毒药与抗真菌药","chapterIdx":41,"num":15},{"type":"D","stem":"名词解释：制霉菌素","answer":"多烯类抗真菌抗生素，作用机制与两性霉素B相同，因毒性大不作全身应用，口服难吸收，用于口腔、皮肤和阴道念珠菌感染。","rationale":"出自概念手册「抗病毒药与抗真菌药」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph42_q016","chapter":"第四十二章 抗病毒药与抗真菌药","chapterIdx":41,"num":16},{"type":"D","stem":"名词解释：灰黄霉素","answer":"抗真菌抗生素，干扰真菌微管功能、抑制有丝分裂，仅对皮肤癣菌有效，用于头癣等浅部真菌感染，疗程较长。","rationale":"出自概念手册「抗病毒药与抗真菌药」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph42_q017","chapter":"第四十二章 抗病毒药与抗真菌药","chapterIdx":41,"num":17},{"type":"D","stem":"名词解释：唑类抗真菌药","answer":"咪唑类与三唑类的总称，抑制真菌14α-去甲基化酶、减少麦角固醇合成，使膜通透性增加而发挥抑菌作用。","rationale":"出自概念手册「抗病毒药与抗真菌药」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph42_q018","chapter":"第四十二章 抗病毒药与抗真菌药","chapterIdx":41,"num":18},{"type":"D","stem":"名词解释：氟康唑","answer":"三唑类，口服吸收完全、脑脊液浓度高，是隐球菌脑膜炎和念珠菌病的常用药，对曲霉作用差。","rationale":"出自概念手册「抗病毒药与抗真菌药」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph42_q019","chapter":"第四十二章 抗病毒药与抗真菌药","chapterIdx":41,"num":19},{"type":"D","stem":"名词解释：伊曲康唑","answer":"三唑类广谱抗真菌药，对皮肤癣菌、曲霉和隐球菌有效，胶囊剂需在酸性环境与餐后服用才吸收好。","rationale":"出自概念手册「抗病毒药与抗真菌药」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph42_q020","chapter":"第四十二章 抗病毒药与抗真菌药","chapterIdx":41,"num":20},{"type":"D","stem":"名词解释：伏立康唑","answer":"三唑类广谱抗真菌药，抗曲霉作用强，是侵袭性曲霉病的首选药物，需监测血药浓度和肝功能，并注意视觉异常。","rationale":"出自概念手册「抗病毒药与抗真菌药」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph42_q021","chapter":"第四十二章 抗病毒药与抗真菌药","chapterIdx":41,"num":21},{"type":"D","stem":"名词解释：氟胞嘧啶","answer":"又称5-FC，在真菌体内转为5-氟尿嘧啶，干扰DNA与RNA合成，单用易耐药，常与两性霉素B联用。","rationale":"出自概念手册「抗病毒药与抗真菌药」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph42_q022","chapter":"第四十二章 抗病毒药与抗真菌药","chapterIdx":41,"num":22},{"type":"D","stem":"名词解释：特比萘芬","answer":"丙烯胺类抗真菌药，抑制角鲨烯环氧化酶，对皮肤癣菌有杀菌作用，口服可治疗甲真菌病。","rationale":"出自概念手册「抗病毒药与抗真菌药」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph42_q023","chapter":"第四十二章 抗病毒药与抗真菌药","chapterIdx":41,"num":23},{"type":"D","stem":"名词解释：棘白菌素类","answer":"如卡泊芬净，抑制真菌β-1,3-葡聚糖合成酶、破坏细胞壁，对念珠菌和曲霉有效，对隐球菌无效。","rationale":"出自概念手册「抗病毒药与抗真菌药」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph42_q024","chapter":"第四十二章 抗病毒药与抗真菌药","chapterIdx":41,"num":24},{"type":"S","stem":"简答题：简述两性霉素B的抗真菌作用机制及主要不良反应。","answer":"①作用机制：选择性地与真菌细胞膜的特有成分麦角固醇结合，使细胞膜通透性增加，细胞内小分子物质和电解质外漏，致真菌停止生长或死亡；②抗真菌谱广，几乎对所有真菌均有抗菌活性，是治疗多种深部真菌感染的首选药物，但对细菌、立克次体和病毒无活性；③急性毒性反应最常见，表现为寒战、高热、严重头痛、恶心，也可有过敏性休克、皮疹与血栓性静脉炎；④肾毒性可致氮质血症甚至肾衰竭，此外还有神经系统毒性、心血管系统反应、低钾血症、低血镁、贫血、血小板减少及肝毒性；⑤采用缓慢静滴给药，与氟胞嘧啶合用可产生协同作用，从而降低剂量、减少不良反应和耐药性。","rationale":"采分点：结合麦角固醇→膜通透性增加→内容物外漏；深部真菌感染首选；急性毒性反应（寒战、高热）与肾毒性；缓慢静滴、与氟胞嘧啶协同。易错：误说两性霉素B对细菌或病毒有效。","id":"rph42_q025","chapter":"第四十二章 抗病毒药与抗真菌药","chapterIdx":41,"num":25},{"type":"F","stem":"填空题：唑类抗真菌药抑制真菌细胞膜的______，使麦角固醇合成受阻；特比萘芬则抑制______，二者最终都使细胞膜通透性增加而致真菌死亡。","answer":"①14α-去甲基酶 ②角鲨烯环氧化酶","rationale":"唑类（咪唑类与三唑类）作用靶点为细胞色素P450依赖的14α-去甲基酶，特比萘芬作用于角鲨烯环氧化酶，靶点不同但都阻断麦角固醇合成。","id":"rph42_q026","chapter":"第四十二章 抗病毒药与抗真菌药","chapterIdx":41,"num":26},{"type":"F","stem":"填空题：阿昔洛韦在宿主细胞内磷酸化为三磷酸盐，竞争性抑制病毒______而抑制病毒DNA复制，并掺入病毒DNA链中终止______的延长。","answer":"①DNA多聚酶 ②DNA链","rationale":"阿昔洛韦是嘌呤核苷衍生物，仅对DNA病毒有效、对RNA病毒无效，对单纯疱疹病毒作用较强，可作单纯疱疹病毒感染的首选药。","id":"rph42_q027","chapter":"第四十二章 抗病毒药与抗真菌药","chapterIdx":41,"num":27},{"type":"T","stem":"判断题：两性霉素B除抗真菌外，对细菌、立克次体和病毒也有抗菌活性。","options":{"A":"正确","B":"错误"},"answer":["B"],"rationale":"两性霉素B的作用基础是与真菌细胞膜特有的麦角固醇结合，细菌细胞膜不含麦角固醇，故对细菌、立克次体和病毒均无活性，这也是其选择性所在。","id":"rph42_q028","chapter":"第四十二章 抗病毒药与抗真菌药","chapterIdx":41,"num":28},{"type":"T","stem":"判断题：氟胞嘧啶易透过血脑屏障，但不宜单用，常与两性霉素B合用产生协同抗菌作用。","options":{"A":"正确","B":"错误"},"answer":["A"],"rationale":"两性霉素B增加真菌细胞膜通透性，使氟胞嘧啶更易进入菌体，故两者协同；合用还可降低剂量、减少不良反应与耐药产生。","id":"rph42_q029","chapter":"第四十二章 抗病毒药与抗真菌药","chapterIdx":41,"num":29}]},{"title":"第四十三章 抗结核药与抗麻风药","questions":[{"type":"D","stem":"名词解释：抗结核病药","answer":"用于治疗结核分枝杆菌感染的药物，按疗效与安全性分为一线药和二线药，临床多采用联合化疗方案。","rationale":"出自概念手册「抗结核药与抗麻风药」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph43_q001","chapter":"第四十三章 抗结核药与抗麻风药","chapterIdx":42,"num":1},{"type":"D","stem":"名词解释：一线抗结核药","answer":"疗效高、不良反应少、患者易耐受的品种，包括异烟肼、利福平、乙胺丁醇、吡嗪酰胺和链霉素。","rationale":"出自概念手册「抗结核药与抗麻风药」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph43_q002","chapter":"第四十三章 抗结核药与抗麻风药","chapterIdx":42,"num":2},{"type":"D","stem":"名词解释：二线抗结核药","answer":"疗效较低或毒性较大的品种，用于耐药结核或对一线药不能耐受者，如对氨基水杨酸、阿米卡星、卷曲霉素和氟喹诺酮类。","rationale":"出自概念手册「抗结核药与抗麻风药」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph43_q003","chapter":"第四十三章 抗结核药与抗麻风药","chapterIdx":42,"num":3},{"type":"D","stem":"名词解释：异烟肼","answer":"又称INH，抑制结核分枝杆菌分枝菌酸的合成，对繁殖期细菌有杀菌作用，穿透性强，可进入脑脊液和细胞内。","rationale":"出自概念手册「抗结核药与抗麻风药」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph43_q004","chapter":"第四十三章 抗结核药与抗麻风药","chapterIdx":42,"num":4},{"type":"D","stem":"名词解释：利福平","answer":"又称RFP，抑制细菌DNA依赖的RNA聚合酶而阻断转录，抗菌谱广，对结核分枝杆菌、麻风杆菌及多种球菌有效。","rationale":"出自概念手册「抗结核药与抗麻风药」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph43_q005","chapter":"第四十三章 抗结核药与抗麻风药","chapterIdx":42,"num":5},{"type":"D","stem":"名词解释：乙胺丁醇","answer":"人工合成抑菌药，抑制阿拉伯糖基转移酶干扰细胞壁合成，与其他药合用可延缓耐药，主要不良反应为球后视神经炎。","rationale":"出自概念手册「抗结核药与抗麻风药」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph43_q006","chapter":"第四十三章 抗结核药与抗麻风药","chapterIdx":42,"num":6},{"type":"D","stem":"名词解释：吡嗪酰胺","answer":"又称PZA，在酸性环境中杀菌力强，可杀灭巨噬细胞内和空洞中的半休眠菌，是短程化疗的关键药物。","rationale":"出自概念手册「抗结核药与抗麻风药」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph43_q007","chapter":"第四十三章 抗结核药与抗麻风药","chapterIdx":42,"num":7},{"type":"D","stem":"名词解释：结核分枝杆菌","answer":"细胞壁富含脂质和分枝菌酸、生长缓慢，可长期处于半休眠状态，是结核病必须长疗程联合化疗的生物学基础。","rationale":"出自概念手册「抗结核药与抗麻风药」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph43_q008","chapter":"第四十三章 抗结核药与抗麻风药","chapterIdx":42,"num":8},{"type":"D","stem":"名词解释：对氨基水杨酸","answer":"二线抑菌药，与对氨基苯甲酸竞争抑制结核菌叶酸合成，仅对细胞外菌有效，可竞争性抑制异烟肼乙酰化。","rationale":"出自概念手册「抗结核药与抗麻风药」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph43_q009","chapter":"第四十三章 抗结核药与抗麻风药","chapterIdx":42,"num":9},{"type":"D","stem":"名词解释：结核病化学治疗原则","answer":"早期、规律、全程、适量、联合五项原则，目的是杀灭繁殖期与半休眠菌、防止耐药产生并减少复发。","rationale":"出自概念手册「抗结核药与抗麻风药」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph43_q010","chapter":"第四十三章 抗结核药与抗麻风药","chapterIdx":42,"num":10},{"type":"D","stem":"名词解释：短程化疗","answer":"以异烟肼和利福平为核心的6个月方案，通常为2个月强化期加4个月巩固期，疗效与长疗程相当而依从性更好。","rationale":"出自概念手册「抗结核药与抗麻风药」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph43_q011","chapter":"第四十三章 抗结核药与抗麻风药","chapterIdx":42,"num":11},{"type":"D","stem":"名词解释：直接面视下督导化疗","answer":"又称DOTS，由医务人员或督导员看着患者服下每剂抗结核药，以保证规律全程用药、防止耐药和复发。","rationale":"出自概念手册「抗结核药与抗麻风药」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph43_q012","chapter":"第四十三章 抗结核药与抗麻风药","chapterIdx":42,"num":12},{"type":"D","stem":"名词解释：多重耐药结核","answer":"至少同时对异烟肼和利福平耐药的结核病，治疗需选用二线药物并延长疗程，治愈率低、传播风险大。","rationale":"出自概念手册「抗结核药与抗麻风药」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph43_q013","chapter":"第四十三章 抗结核药与抗麻风药","chapterIdx":42,"num":13},{"type":"D","stem":"名词解释：乙酰化表型","answer":"异烟肼在肝内由N-乙酰转移酶代谢，人群分快乙酰化型和慢乙酰化型，后者血药浓度高，易发生肝损害和周围神经炎。","rationale":"出自概念手册「抗结核药与抗麻风药」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph43_q014","chapter":"第四十三章 抗结核药与抗麻风药","chapterIdx":42,"num":14},{"type":"D","stem":"名词解释：预防性化学治疗","answer":"对结核菌素试验强阳性者、密切接触者及免疫功能低下者给予异烟肼等药物，以降低发病风险。","rationale":"出自概念手册「抗结核药与抗麻风药」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph43_q015","chapter":"第四十三章 抗结核药与抗麻风药","chapterIdx":42,"num":15},{"type":"D","stem":"名词解释：利福喷汀","answer":"长效利福霉素类衍生物，抑制细菌DNA依赖的RNA聚合酶，抗结核活性强于利福平，半衰期长可每周给药一至两次。","rationale":"出自概念手册「抗结核药与抗麻风药」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph43_q016","chapter":"第四十三章 抗结核药与抗麻风药","chapterIdx":42,"num":16},{"type":"D","stem":"名词解释：卷曲霉素","answer":"多肽类二线抗结核药，抑制细菌蛋白质合成，用于耐药结核病，须注射给药，主要不良反应为肾毒性和耳毒性。","rationale":"出自概念手册「抗结核药与抗麻风药」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph43_q017","chapter":"第四十三章 抗结核药与抗麻风药","chapterIdx":42,"num":17},{"type":"D","stem":"名词解释：抗麻风药","answer":"用于治疗麻风分枝杆菌感染的药物，主要包括氨苯砜、利福平和氯法齐明，多采用两种以上药物联合的方案以减少耐药。","rationale":"出自概念手册「抗结核药与抗麻风药」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph43_q018","chapter":"第四十三章 抗结核药与抗麻风药","chapterIdx":42,"num":18},{"type":"D","stem":"名词解释：麻风病","answer":"由麻风分枝杆菌引起的慢性传染病，主要侵犯皮肤和周围神经，病程长、传染性低，治疗需长期联合用药。","rationale":"出自概念手册「抗结核药与抗麻风药」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph43_q019","chapter":"第四十三章 抗结核药与抗麻风药","chapterIdx":42,"num":19},{"type":"D","stem":"名词解释：氨苯砜","answer":"抗麻风病首选药，抑制二氢蝶酸合酶干扰叶酸合成，作用缓慢，单用易耐药，可致溶血性贫血和高铁血红蛋白血症。","rationale":"出自概念手册「抗结核药与抗麻风药」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph43_q020","chapter":"第四十三章 抗结核药与抗麻风药","chapterIdx":42,"num":20},{"type":"D","stem":"名词解释：氯法齐明","answer":"吩嗪类抗麻风药，与菌体DNA结合抑制复制并具抗炎作用，用于氨苯砜耐药者及麻风反应的防治，可使皮肤与分泌物呈红棕色。","rationale":"出自概念手册「抗结核药与抗麻风药」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph43_q021","chapter":"第四十三章 抗结核药与抗麻风药","chapterIdx":42,"num":21},{"type":"D","stem":"名词解释：麻风反应","answer":"抗麻风治疗过程中出现的病情急性加重，分Ⅰ型（细胞免疫增强）和Ⅱ型（免疫复合物所致结节性红斑），需用糖皮质激素等控制。","rationale":"出自概念手册「抗结核药与抗麻风药」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph43_q022","chapter":"第四十三章 抗结核药与抗麻风药","chapterIdx":42,"num":22},{"type":"S","stem":"简答题：简述抗结核病药物的应用原则及其理由。","answer":"①早期用药：一旦确诊立即给药，此时病灶多处于渗出阶段，结核杆菌生长旺盛、对药物敏感，且机体抵抗力较强、局部血运丰富，疗效最佳；②联合用药：联合两种或两种以上药物，一般在异烟肼基础上二联、三联或四联，可增强疗效、避免严重不良反应、延缓耐药性产生；③适量：剂量不足达不到有效抗菌浓度并易诱发耐药，剂量过大则产生严重不良反应；④规律全程用药：结核病易复发，必须坚持全程规律用药，不能随意改变剂量或品种、不能过早停药，轻症肺结核持续治疗9～12个月，中、重度肺结核18～24个月。","rationale":"采分点为“早期、联合、适量、规律全程”四原则及各自理由；其中“联合延缓耐药”“全程规律防复发”是高频得分点，疗程数字（9～12个月、18～24个月）应记准。","id":"rph43_q023","chapter":"第四十三章 抗结核药与抗麻风药","chapterIdx":42,"num":23},{"type":"F","stem":"填空题：异烟肼通过抑制结核杆菌______的合成而使细胞壁合成受阻，使细菌丧失耐酸性、疏水性和增殖力；该药对繁殖期细菌有______作用。","answer":"①分枝菌酸 ②杀菌","rationale":"分枝菌酸是结核杆菌细胞壁独特而重要的成分，是异烟肼高度选择性的基础；异烟肼对繁殖期细菌杀菌、对静止期细菌抑菌。","id":"rph43_q024","chapter":"第四十三章 抗结核药与抗麻风药","chapterIdx":42,"num":24},{"type":"F","stem":"填空题：乙胺丁醇与Mg2+络合，干扰细菌______的合成；其最严重的毒性反应是______，与用药疗程和剂量有关。","answer":"①RNA ②视神经炎","rationale":"乙胺丁醇安全有效、不良反应发生率低、耐药产生慢，但须警惕视神经炎，用药期间应关注视力变化。","id":"rph43_q025","chapter":"第四十三章 抗结核药与抗麻风药","chapterIdx":42,"num":25},{"type":"T","stem":"判断题：异烟肼引起的周围神经炎可用维生素B6防治，因为该药影响维生素B6的生物利用而使GABA减少。","options":{"A":"正确","B":"错误"},"answer":["A"],"rationale":"异烟肼影响维生素B6的生物利用，使GABA生成减少，故出现手脚麻木、肌肉震颤、步态不稳等周围神经炎表现及中枢兴奋症状，多见于慢代谢型患者，可预防性应用维生素B6。","id":"rph43_q026","chapter":"第四十三章 抗结核药与抗麻风药","chapterIdx":42,"num":26},{"type":"T","stem":"判断题：对氨基水杨酸为二线抗结核药，与利福平合用可增强利福平的吸收而提高疗效。","options":{"A":"正确","B":"错误"},"answer":["B"],"rationale":"对氨基水杨酸仅对细胞外结核杆菌有抑菌作用，且不宜与利福平合用，因其会影响利福平的吸收；它主要与异烟肼、链霉素合用以延缓耐药产生。","id":"rph43_q027","chapter":"第四十三章 抗结核药与抗麻风药","chapterIdx":42,"num":27}]},{"title":"第四十四章 抗寄生虫药","questions":[{"type":"D","stem":"名词解释：抗疟药","answer":"用于预防和治疗疟疾的药物，按作用于疟原虫生活史的不同环节分为控制症状的红内期裂殖体杀灭药、控制复发与传播的组织期药及病因性预防药。","rationale":"出自概念手册「抗寄生虫药」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph44_q001","chapter":"第四十四章 抗寄生虫药","chapterIdx":43,"num":1},{"type":"D","stem":"名词解释：红内期","answer":"疟原虫在红细胞内发育繁殖的阶段，裂殖体胀破红细胞引起寒战、高热与贫血等症状，是氯喹与青蒿素类的作用环节。","rationale":"出自概念手册「抗寄生虫药」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph44_q002","chapter":"第四十四章 抗寄生虫药","chapterIdx":43,"num":2},{"type":"D","stem":"名词解释：红外期","answer":"疟原虫在肝细胞内的发育阶段，尚未引起临床症状，乙胺嘧啶等可杀灭红外期裂殖体而用于病因性预防。","rationale":"出自概念手册「抗寄生虫药」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph44_q003","chapter":"第四十四章 抗寄生虫药","chapterIdx":43,"num":3},{"type":"F","stem":"填空题：疟原虫在肝细胞内的发育阶段，尚未引起临床症状，乙胺嘧啶等可杀灭______裂殖体而用于病因性预防。","answer":"红外期","rationale":"出自概念手册「抗寄生虫药」核心概念：红外期。","id":"rph44_q004","chapter":"第四十四章 抗寄生虫药","chapterIdx":43,"num":4},{"type":"D","stem":"名词解释：休眠子","answer":"间日疟与卵形疟原虫在肝细胞内形成的休眠状态虫体，可数月后复苏引起复发，是疟疾复发的根源，伯氨喹可将其杀灭。","rationale":"出自概念手册「抗寄生虫药」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph44_q005","chapter":"第四十四章 抗寄生虫药","chapterIdx":43,"num":5},{"type":"D","stem":"名词解释：配子体","answer":"疟原虫的有性生殖阶段，存在于患者血液中并可被按蚊吸入而传播疟疾，伯氨喹对配子体有杀灭作用，可阻断传播。","rationale":"出自概念手册「抗寄生虫药」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph44_q006","chapter":"第四十四章 抗寄生虫药","chapterIdx":43,"num":6},{"type":"F","stem":"填空题：疟原虫的有性生殖阶段，存在于患者血液中并可被按蚊吸入而传播疟疾，伯氨喹对______有杀灭作用，可阻断传播。","answer":"配子体","rationale":"出自概念手册「抗寄生虫药」核心概念：配子体。","id":"rph44_q007","chapter":"第四十四章 抗寄生虫药","chapterIdx":43,"num":7},{"type":"D","stem":"名词解释：氯喹","answer":"4-氨基喹啉类抗疟药，浓集于疟原虫食物泡、抑制血红蛋白分解并干扰虫体核酸代谢，是控制疟疾症状的首选药之一。","rationale":"出自概念手册「抗寄生虫药」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph44_q008","chapter":"第四十四章 抗寄生虫药","chapterIdx":43,"num":8},{"type":"D","stem":"名词解释：青蒿素","answer":"从黄花蒿中提取的含过氧桥的倍半萜内酯，作用于疟原虫膜结构与线粒体，对耐氯喹虫株有效，是重症与脑型疟疾的首选药。","rationale":"出自概念手册「抗寄生虫药」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph44_q009","chapter":"第四十四章 抗寄生虫药","chapterIdx":43,"num":9},{"type":"D","stem":"名词解释：伯氨喹","answer":"8-氨基喹啉类，杀灭肝内休眠子与血中配子体，用于控制复发与阻断传播，可致葡萄糖-6-磷酸脱氢酶缺乏者急性溶血。","rationale":"出自概念手册「抗寄生虫药」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph44_q010","chapter":"第四十四章 抗寄生虫药","chapterIdx":43,"num":10},{"type":"D","stem":"名词解释：乙胺嘧啶","answer":"抑制疟原虫二氢叶酸还原酶而阻碍叶酸合成，主要杀灭红外期裂殖体用于病因性预防，与磺胺多辛合用可增强疗效。","rationale":"出自概念手册「抗寄生虫药」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph44_q011","chapter":"第四十四章 抗寄生虫药","chapterIdx":43,"num":11},{"type":"D","stem":"名词解释：甲硝唑","answer":"硝基咪唑类抗厌氧菌与抗原虫药，在厌氧环境中还原生成活性代谢物损伤虫体DNA，是治疗阿米巴病与滴虫病的首选药。","rationale":"出自概念手册「抗寄生虫药」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph44_q012","chapter":"第四十四章 抗寄生虫药","chapterIdx":43,"num":12},{"type":"D","stem":"名词解释：阿米巴病","answer":"溶组织内阿米巴寄生于肠道或侵入肝、肺等器官引起的疾病，分肠阿米巴病与肠外阿米巴病，两者选药与疗程不同。","rationale":"出自概念手册「抗寄生虫药」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph44_q013","chapter":"第四十四章 抗寄生虫药","chapterIdx":43,"num":13},{"type":"F","stem":"填空题：溶组织内阿米巴寄生于肠道或侵入肝、肺等器官引起的疾病，分肠______与肠外阿米巴病，两者选药与疗程不同。","answer":"阿米巴病","rationale":"出自概念手册「抗寄生虫药」核心概念：阿米巴病。","id":"rph44_q014","chapter":"第四十四章 抗寄生虫药","chapterIdx":43,"num":14},{"type":"D","stem":"名词解释：吡喹酮","answer":"吡嗪异喹啉类，增加血吸虫体表对钙离子的通透性而使虫体痉挛、麻痹并脱落，是治疗血吸虫病的首选药，对绦虫病亦有效。","rationale":"出自概念手册「抗寄生虫药」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph44_q015","chapter":"第四十四章 抗寄生虫药","chapterIdx":43,"num":15},{"type":"D","stem":"名词解释：乙胺嗪","answer":"哌嗪类衍生物，使血中微丝蚴肌组织变性、失去活动能力而被网状内皮系统吞噬，用于丝虫病的治疗与预防。","rationale":"出自概念手册「抗寄生虫药」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph44_q016","chapter":"第四十四章 抗寄生虫药","chapterIdx":43,"num":16},{"type":"D","stem":"名词解释：阿苯达唑","answer":"苯并咪唑类广谱抗肠蠕虫药，抑制虫体微管聚合与葡萄糖摄取，对蛔虫、钩虫、鞭虫、蛲虫及囊虫、包虫均有效。","rationale":"出自概念手册「抗寄生虫药」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph44_q017","chapter":"第四十四章 抗寄生虫药","chapterIdx":43,"num":17},{"type":"D","stem":"名词解释：甲苯咪唑","answer":"苯并咪唑类广谱驱虫药，抑制虫体微管形成而阻碍营养摄取，对蛔虫、钩虫、蛲虫与鞭虫感染有效，吸收少、全身毒性低。","rationale":"出自概念手册「抗寄生虫药」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph44_q018","chapter":"第四十四章 抗寄生虫药","chapterIdx":43,"num":18},{"type":"D","stem":"名词解释：哌嗪","answer":"通过阻断虫体神经肌肉接头处的胆碱受体、使虫体产生松弛性麻痹而随粪便排出，用于蛔虫与蛲虫感染，毒性低、适合儿童。","rationale":"出自概念手册「抗寄生虫药」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph44_q019","chapter":"第四十四章 抗寄生虫药","chapterIdx":43,"num":19},{"type":"D","stem":"名词解释：抗肠蠕虫药","answer":"用于驱除肠道线虫的药物，包括苯并咪唑类、哌嗪类、嘧啶类与阿维菌素类等，选药依据虫种、感染程度与患者年龄。","rationale":"出自概念手册「抗寄生虫药」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph44_q020","chapter":"第四十四章 抗寄生虫药","chapterIdx":43,"num":20},{"type":"S","stem":"简答题：简述抗疟药按作用于疟原虫生活史环节的分类，并写出各类代表药与主要用途。","answer":"①杀灭红内期裂殖体药：代表药为氯喹与青蒿素类，用于控制症状；氯喹起效快、作用持久，是控制症状的首选药，青蒿素类对耐氯喹虫株有效并能透过血脑屏障，为脑型疟与重症疟疾首选；②杀灭肝内休眠子与血中配子体药：代表药为伯氨喹，用于控制复发与阻断传播，是根治间日疟的关键药；③杀灭红外期裂殖体药：代表药为乙胺嘧啶，用于病因性预防；④联合用药原则：控制症状药加组织期药，如氯喹加伯氨喹可根治间日疟，重症疟疾则采用以青蒿素类为基础的联合疗法。","rationale":"采分点为“红内期管治、红外期管防、休眠子与配子体管根治与阻断传播”三个环节及各自代表药。易错：误认为氯喹能杀灭休眠子或配子体，故单用氯喹不能根治间日疟。","id":"rph44_q021","chapter":"第四十四章 抗寄生虫药","chapterIdx":43,"num":21},{"type":"F","stem":"填空题：氯喹杀灭疟原虫的______裂殖体而控制症状，对红外期与配子体无效；伯氨喹则杀灭肝内______与血中配子体，用于控制复发和阻断传播。","answer":"①红内期 ②休眠子","rationale":"间日疟与卵形疟原虫在肝细胞形成休眠子，是复发的根源；伯氨喹可杀灭休眠子，但可致葡萄糖-6-磷酸脱氢酶缺乏者急性溶血。","id":"rph44_q022","chapter":"第四十四章 抗寄生虫药","chapterIdx":43,"num":22},{"type":"F","stem":"填空题：吡喹酮通过增加血吸虫体表对______的通透性，使虫体痉挛、麻痹并脱落，是治疗______病的首选药。","answer":"①钙离子 ②血吸虫","rationale":"吡喹酮高效、低毒、疗程短、可口服，对华支睾吸虫病与绦虫病同样有效，是寄生虫病化疗的重大进步。","id":"rph44_q023","chapter":"第四十四章 抗寄生虫药","chapterIdx":43,"num":23},{"type":"T","stem":"判断题：甲硝唑是治疗阿米巴病与滴虫病的首选药，服药期间饮酒可引起双硫仑样反应。","options":{"A":"正确","B":"错误"},"answer":["A"],"rationale":"甲硝唑在厌氧环境中还原生成活性代谢物损伤虫体DNA，对肠内、肠外阿米巴病及滴虫病均首选，并是各种厌氧菌感染的首选药；服药期间饮酒可致双硫仑样反应，妊娠早期禁用。","id":"rph44_q024","chapter":"第四十四章 抗寄生虫药","chapterIdx":43,"num":24},{"type":"T","stem":"判断题：乙胺嗪对丝虫成虫作用强而对微丝蚴作用弱，故治疗丝虫病时过敏反应少见。","options":{"A":"正确","B":"错误"},"answer":["B"],"rationale":"乙胺嗪对微丝蚴作用强而对成虫作用弱；大量微丝蚴死亡释放抗原可引起过敏反应，故须从小剂量开始并加用抗组胺药。","id":"rph44_q025","chapter":"第四十四章 抗寄生虫药","chapterIdx":43,"num":25}]},{"title":"第四十五章 抗肿瘤药","questions":[{"type":"D","stem":"名词解释：抗恶性肿瘤药","answer":"用于治疗恶性肿瘤的药物，通过干扰肿瘤细胞增殖、诱导凋亡或调节机体免疫而发挥作用，临床多联合应用。","rationale":"出自概念手册「抗肿瘤药」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph45_q001","chapter":"第四十五章 抗肿瘤药","chapterIdx":44,"num":1},{"type":"D","stem":"名词解释：细胞周期特异性药物","answer":"仅对增殖周期某一时相（多为S期或M期）的肿瘤细胞有效的药物，如抗代谢药、长春碱类和紫杉类。","rationale":"出自概念手册「抗肿瘤药」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph45_q002","chapter":"第四十五章 抗肿瘤药","chapterIdx":44,"num":2},{"type":"D","stem":"名词解释：细胞周期非特异性药物","answer":"对增殖期与非增殖期细胞均有杀伤作用的药物，如烷化剂、铂类和蒽环类抗生素，疗效呈剂量依赖性。","rationale":"出自概念手册「抗肿瘤药」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph45_q003","chapter":"第四十五章 抗肿瘤药","chapterIdx":44,"num":3},{"type":"D","stem":"名词解释：烷化剂","answer":"含活泼烷基的化合物，能与DNA发生共价交联，破坏DNA结构与功能，属细胞周期非特异性药物。","rationale":"出自概念手册「抗肿瘤药」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph45_q004","chapter":"第四十五章 抗肿瘤药","chapterIdx":44,"num":4},{"type":"D","stem":"名词解释：环磷酰胺","answer":"氮芥类烷化剂，需经肝药酶活化，抗瘤谱广，代谢物丙烯醛可致出血性膀胱炎，可用美司钠解救。","rationale":"出自概念手册「抗肿瘤药」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph45_q005","chapter":"第四十五章 抗肿瘤药","chapterIdx":44,"num":5},{"type":"D","stem":"名词解释：抗代谢药","answer":"化学结构与叶酸、嘌呤或嘧啶相似的药物，干扰核酸合成，主要作用于S期，属细胞周期特异性药物。","rationale":"出自概念手册「抗肿瘤药」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph45_q006","chapter":"第四十五章 抗肿瘤药","chapterIdx":44,"num":6},{"type":"D","stem":"名词解释：甲氨蝶呤","answer":"又称MTX，抑制二氢叶酸还原酶，阻碍四氢叶酸和胸苷酸生成，用于白血病、绒毛膜上皮癌和实体瘤。","rationale":"出自概念手册「抗肿瘤药」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph45_q007","chapter":"第四十五章 抗肿瘤药","chapterIdx":44,"num":7},{"type":"D","stem":"名词解释：亚叶酸钙解救","answer":"大剂量甲氨蝶呤治疗后给予亚叶酸钙，绕过被阻断的二氢叶酸还原酶补充四氢叶酸，减轻骨髓与黏膜毒性。","rationale":"出自概念手册「抗肿瘤药」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph45_q008","chapter":"第四十五章 抗肿瘤药","chapterIdx":44,"num":8},{"type":"D","stem":"名词解释：氟尿嘧啶","answer":"又称5-FU，在体内转为氟尿嘧啶脱氧核苷酸，抑制胸苷酸合成酶，主要作用于S期，用于消化道肿瘤。","rationale":"出自概念手册「抗肿瘤药」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph45_q009","chapter":"第四十五章 抗肿瘤药","chapterIdx":44,"num":9},{"type":"F","stem":"填空题：又称5-FU，在体内转为______脱氧核苷酸，抑制胸苷酸合成酶，主要作用于S期，用于消化道肿瘤。","answer":"氟尿嘧啶","rationale":"出自概念手册「抗肿瘤药」核心概念：氟尿嘧啶。","id":"rph45_q010","chapter":"第四十五章 抗肿瘤药","chapterIdx":44,"num":10},{"type":"D","stem":"名词解释：巯嘌呤","answer":"又称6-MP，嘌呤类似物，抑制嘌呤核苷酸合成，用于急性白血病，主要由黄嘌呤氧化酶代谢。","rationale":"出自概念手册「抗肿瘤药」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph45_q011","chapter":"第四十五章 抗肿瘤药","chapterIdx":44,"num":11},{"type":"D","stem":"名词解释：多柔比星","answer":"蒽环类抗肿瘤抗生素，嵌入DNA并抑制拓扑异构酶Ⅱ，可产生自由基，剂量限制性毒性为心脏毒性。","rationale":"出自概念手册「抗肿瘤药」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph45_q012","chapter":"第四十五章 抗肿瘤药","chapterIdx":44,"num":12},{"type":"D","stem":"名词解释：长春新碱","answer":"长春碱类抗肿瘤药，抑制微管蛋白聚合使有丝分裂停止于中期，主要不良反应为外周神经毒性，骨髓抑制较轻。","rationale":"出自概念手册「抗肿瘤药」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph45_q013","chapter":"第四十五章 抗肿瘤药","chapterIdx":44,"num":13},{"type":"D","stem":"名词解释：紫杉醇","answer":"促进微管蛋白聚合并稳定微管，使细胞停止于有丝分裂期，用于乳腺癌、卵巢癌和非小细胞肺癌。","rationale":"出自概念手册「抗肿瘤药」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph45_q014","chapter":"第四十五章 抗肿瘤药","chapterIdx":44,"num":14},{"type":"D","stem":"名词解释：顺铂","answer":"铂类配合物，与DNA形成交联，属细胞周期非特异性药物，主要毒性为肾损害、耳毒性和强致吐。","rationale":"出自概念手册「抗肿瘤药」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph45_q015","chapter":"第四十五章 抗肿瘤药","chapterIdx":44,"num":15},{"type":"D","stem":"名词解释：分子靶向药","answer":"针对肿瘤特定分子靶点（如酪氨酸激酶、受体、血管生成）的药物，选择性较高，如伊马替尼、曲妥珠单抗。","rationale":"出自概念手册「抗肿瘤药」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph45_q017","chapter":"第四十五章 抗肿瘤药","chapterIdx":44,"num":17},{"type":"D","stem":"名词解释：多药耐药","answer":"肿瘤细胞对一种药物产生耐药后同时对多种结构无关药物交叉耐药的现象，常与P-糖蛋白外排泵有关。","rationale":"出自概念手册「抗肿瘤药」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph45_q018","chapter":"第四十五章 抗肿瘤药","chapterIdx":44,"num":18},{"type":"S","stem":"简答题：比较细胞周期特异性药物与细胞周期非特异性药物的概念、代表药、剂量效应与主要毒性。","answer":"①概念：细胞周期特异性药物仅对增殖周期某一时相（多为S期或M期）的肿瘤细胞有效；细胞周期非特异性药物对增殖期与非增殖期细胞均有杀伤作用；②代表药：特异性者为甲氨蝶呤、氟尿嘧啶、巯嘌呤、长春新碱与紫杉醇；非特异性者为环磷酰胺等烷化剂、顺铂与多柔比星等蒽环类；③剂量效应与给药：特异性药物作用弱而慢、呈时间依赖性，宜持续或分次给药；非特异性药物杀伤强而快、呈剂量依赖性，宜大剂量间歇给药；④作用与毒性：特异性药物对增殖比例高的肿瘤疗效较好、骨髓毒性相对较轻；非特异性药物对增殖缓慢的肿瘤亦有效、骨髓毒性相对较重。","rationale":"采分点为“周期特异性看时相、非特异性看剂量”这一核心对比，以及各类代表药与骨髓毒性轻重。易错：把长春新碱、紫杉醇归入非特异性药物，或说特异性药物宜大剂量间歇给药。","id":"rph45_q019","chapter":"第四十五章 抗肿瘤药","chapterIdx":44,"num":19},{"type":"F","stem":"填空题：环磷酰胺属______类抗肿瘤药，需经肝药酶活化后发挥细胞毒作用，其代谢物______可致出血性膀胱炎，可用美司钠解救。","answer":"①烷化剂 ②丙烯醛","rationale":"烷化剂与DNA共价交联，属细胞周期非特异性药物；预防出血性膀胱炎须用美司钠并充分补液。","id":"rph45_q020","chapter":"第四十五章 抗肿瘤药","chapterIdx":44,"num":20},{"type":"F","stem":"填空题：甲氨蝶呤抑制______，阻碍四氢叶酸与胸苷酸生成；大剂量用药后须用______解救，以减轻骨髓抑制与黏膜炎。","answer":"①二氢叶酸还原酶 ②亚叶酸钙","rationale":"亚叶酸钙绕过被阻断的二氢叶酸还原酶直接补充四氢叶酸，是“解救疗法”的典型；口诀“甲氨蝶呤用亚叶酸钙、环磷酰胺用美司钠、多柔比星用右丙亚胺、顺铂靠水化利尿”。","id":"rph45_q021","chapter":"第四十五章 抗肿瘤药","chapterIdx":44,"num":21},{"type":"T","stem":"判断题：长春新碱通过促进微管蛋白聚合并稳定微管，使细胞停止于有丝分裂期，其主要毒性为外周神经毒性。","options":{"A":"正确","B":"错误"},"answer":["B"],"rationale":"长春碱类抑制微管蛋白聚合，紫杉醇才促进微管聚合并稳定微管；两者作用方向相反但都使细胞停止于有丝分裂期。长春新碱主要毒性确为外周神经毒性、骨髓抑制较轻。","id":"rph45_q022","chapter":"第四十五章 抗肿瘤药","chapterIdx":44,"num":22},{"type":"T","stem":"判断题：肿瘤细胞的多药耐药常与细胞膜上P-糖蛋白过度表达有关，该跨膜蛋白可将药物泵出细胞外。","options":{"A":"正确","B":"错误"},"answer":["A"],"rationale":"多药耐药指接触一种抗肿瘤药后对多种结构不同、机制各异的药物交叉耐药，突出特点是耐药细胞膜出现P-糖蛋白；维拉帕米、环孢素可逆转，但尚未广泛用于临床。","id":"rph45_q023","chapter":"第四十五章 抗肿瘤药","chapterIdx":44,"num":23}]},{"title":"第四十六章 免疫功能调节剂","questions":[{"type":"D","stem":"名词解释：免疫功能调节剂","answer":"能增强或抑制机体免疫功能的药物总称，分为免疫抑制药与免疫增强药两类，多数对免疫系统缺乏选择性，用药须权衡疗效与风险。","rationale":"出自概念手册「免疫功能调节剂」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph46_q001","chapter":"第四十六章 免疫功能调节剂","chapterIdx":45,"num":1},{"type":"D","stem":"名词解释：免疫抑制药","answer":"抑制机体免疫反应、主要用于器官移植抗排斥反应与自身免疫性疾病的药物，多作用于淋巴细胞识别、增殖与活化环节。","rationale":"出自概念手册「免疫功能调节剂」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph46_q002","chapter":"第四十六章 免疫功能调节剂","chapterIdx":45,"num":2},{"type":"D","stem":"名词解释：环孢素","answer":"从真菌中提取的环状多肽，与胞内亲环蛋白结合后抑制钙调磷酸酶，阻断T细胞活化与白介素-2生成，是器官移植抗排斥的一线药物。","rationale":"出自概念手册「免疫功能调节剂」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph46_q003","chapter":"第四十六章 免疫功能调节剂","chapterIdx":45,"num":3},{"type":"D","stem":"名词解释：他克莫司","answer":"大环内酯类免疫抑制药，与FK结合蛋白结合后抑制钙调磷酸酶，作用强于环孢素，肝移植中常优先选用，肾毒性与神经毒性较明显。","rationale":"出自概念手册「免疫功能调节剂」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph46_q004","chapter":"第四十六章 免疫功能调节剂","chapterIdx":45,"num":4},{"type":"D","stem":"名词解释：西罗莫司","answer":"又称雷帕霉素，与FK结合蛋白结合后抑制mTOR，阻断T细胞由G1期进入S期，用于移植抗排斥及药物涂层支架预防再狭窄。","rationale":"出自概念手册「免疫功能调节剂」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph46_q005","chapter":"第四十六章 免疫功能调节剂","chapterIdx":45,"num":5},{"type":"D","stem":"名词解释：吗替麦考酚酯","answer":"体内水解为霉酚酸，选择性抑制次黄嘌呤核苷酸脱氢酶而阻断淋巴细胞鸟嘌呤核苷酸合成，用于移植抗排斥与狼疮性肾炎。","rationale":"出自概念手册「免疫功能调节剂」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph46_q006","chapter":"第四十六章 免疫功能调节剂","chapterIdx":45,"num":6},{"type":"D","stem":"名词解释：硫唑嘌呤","answer":"嘌呤类抗代谢药，体内转化为硫鸟嘌呤核苷酸掺入DNA，抑制淋巴细胞增殖，用于器官移植与自身免疫性疾病。","rationale":"出自概念手册「免疫功能调节剂」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph46_q007","chapter":"第四十六章 免疫功能调节剂","chapterIdx":45,"num":7},{"type":"D","stem":"名词解释：抗淋巴细胞抗体","answer":"包括抗胸腺细胞球蛋白与抗CD3单克隆抗体，直接破坏或封闭T细胞，用于急性排斥反应的治疗与预防。","rationale":"出自概念手册「免疫功能调节剂」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph46_q008","chapter":"第四十六章 免疫功能调节剂","chapterIdx":45,"num":8},{"type":"D","stem":"名词解释：钙调磷酸酶抑制药","answer":"以环孢素与他克莫司为代表，通过抑制钙调磷酸酶而阻断白介素-2等细胞因子基因转录，是器官移植免疫抑制方案的核心。","rationale":"出自概念手册「免疫功能调节剂」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph46_q009","chapter":"第四十六章 免疫功能调节剂","chapterIdx":45,"num":9},{"type":"D","stem":"名词解释：治疗药物监测","answer":"对治疗窗窄、个体差异大的药物测定血药浓度并据此调整剂量的方法，环孢素与他克莫司必须进行血药浓度监测。","rationale":"出自概念手册「免疫功能调节剂」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph46_q010","chapter":"第四十六章 免疫功能调节剂","chapterIdx":45,"num":10},{"type":"D","stem":"名词解释：免疫增强药","answer":"能促进机体免疫功能的药物，主要用于免疫缺陷病、慢性感染与肿瘤的辅助治疗，多数疗效有限，须与病因治疗配合。","rationale":"出自概念手册「免疫功能调节剂」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph46_q011","chapter":"第四十六章 免疫功能调节剂","chapterIdx":45,"num":11},{"type":"D","stem":"名词解释：卡介苗","answer":"减毒牛型结核分枝杆菌活菌苗，用于预防结核病；膀胱内灌注可治疗表浅膀胱癌，机制为诱发局部非特异性炎症与免疫反应。","rationale":"出自概念手册「免疫功能调节剂」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph46_q012","chapter":"第四十六章 免疫功能调节剂","chapterIdx":45,"num":12},{"type":"D","stem":"名词解释：胸腺肽","answer":"从动物胸腺提取的多肽制剂，促进T细胞分化成熟并增强细胞免疫功能，用于免疫缺陷病与肿瘤的辅助治疗。","rationale":"出自概念手册「免疫功能调节剂」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph46_q013","chapter":"第四十六章 免疫功能调节剂","chapterIdx":45,"num":13},{"type":"D","stem":"名词解释：转移因子","answer":"从致敏淋巴细胞提取的小分子多肽与核苷酸复合物，可将供体的细胞免疫信息转移给受者，用于免疫缺陷与病毒感染的辅助治疗。","rationale":"出自概念手册「免疫功能调节剂」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph46_q014","chapter":"第四十六章 免疫功能调节剂","chapterIdx":45,"num":14},{"type":"D","stem":"名词解释：聚肌胞","answer":"人工合成的双链核糖核酸，能诱导机体产生干扰素，用于病毒性角膜炎、带状疱疹与慢性乙型肝炎的辅助治疗。","rationale":"出自概念手册「免疫功能调节剂」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph46_q015","chapter":"第四十六章 免疫功能调节剂","chapterIdx":45,"num":15},{"type":"D","stem":"名词解释：免疫核糖核酸","answer":"从致敏动物淋巴细胞提取的核糖核酸，可传递特异性免疫信息，曾用于肿瘤的辅助治疗，疗效尚待评价。","rationale":"出自概念手册「免疫功能调节剂」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph46_q016","chapter":"第四十六章 免疫功能调节剂","chapterIdx":45,"num":16},{"type":"D","stem":"名词解释：自身免疫病","answer":"机体免疫系统对自身抗原产生免疫应答并造成组织损伤的疾病，如类风湿关节炎、系统性红斑狼疮与肾小球肾炎。","rationale":"出自概念手册「免疫功能调节剂」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph46_q017","chapter":"第四十六章 免疫功能调节剂","chapterIdx":45,"num":17},{"type":"D","stem":"名词解释：器官移植排斥反应","answer":"受者免疫系统对移植物抗原产生应答而致移植物损伤的过程，分超急性、急性与慢性排斥反应，是免疫抑制治疗的主要适应证。","rationale":"出自概念手册「免疫功能调节剂」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph46_q018","chapter":"第四十六章 免疫功能调节剂","chapterIdx":45,"num":18},{"type":"S","stem":"简答题：比较环孢素与他克莫司的作用机制、临床应用与主要不良反应。","answer":"①两者同属钙调磷酸酶抑制药，通过抑制钙调磷酸酶而阻断白介素-2等细胞因子基因转录，从而阻断T细胞活化，是器官移植免疫抑制方案的核心；②结合蛋白不同：环孢素与胞内亲环蛋白结合，他克莫司与FK结合蛋白结合，靶点相同而结合蛋白各异；③临床应用：环孢素用于器官移植抗排斥反应及自身免疫病，他克莫司作用强于环孢素，肝移植中常优先选用；④不良反应：环孢素主要为肾毒性、高血压、牙龈增生与多毛，他克莫司肾毒性与神经毒性更明显并可致血糖升高；⑤两者治疗窗均窄、个体差异大，必须监测血药浓度（谷浓度）以指导调整剂量。","rationale":"采分点：同属钙调磷酸酶抑制药、均减少白介素-2生成；环孢素配亲环蛋白、他克莫司配FK结合蛋白；环孢素肾毒性与牙龈增生、他克莫司神经毒性与高血糖；均须做治疗药物监测。","id":"rph46_q019","chapter":"第四十六章 免疫功能调节剂","chapterIdx":45,"num":19},{"type":"F","stem":"填空题：西罗莫司（雷帕霉素）与FK结合蛋白结合后抑制______，阻断T细胞由G1期进入S期；吗替麦考酚酯则选择性抑制______，阻断淋巴细胞鸟嘌呤核苷酸合成。","answer":"①mTOR ②次黄嘌呤核苷酸脱氢酶","rationale":"西罗莫司机制不同于钙调磷酸酶抑制药，作用于细胞增殖环节；吗替麦考酚酯因淋巴细胞依赖补救途径合成嘌呤而对淋巴细胞选择性较高，骨髓抑制相对较轻。","id":"rph46_q020","chapter":"第四十六章 免疫功能调节剂","chapterIdx":45,"num":20},{"type":"F","stem":"填空题：硫唑嘌呤与______合用会因黄嘌呤氧化酶被抑制而使硫唑嘌呤代谢受阻、药物蓄积，引起严重______抑制，故须减量或避免合用。","answer":"①别嘌醇 ②骨髓","rationale":"这是免疫抑制药中最凶险的相互作用之一；硫唑嘌呤体内转化为硫鸟嘌呤核苷酸掺入DNA，蓄积后骨髓抑制可致命。","id":"rph46_q021","chapter":"第四十六章 免疫功能调节剂","chapterIdx":45,"num":21},{"type":"T","stem":"判断题：免疫抑制药对免疫系统缺乏选择性，长期应用会增加感染与肿瘤的发生率。","options":{"A":"正确","B":"错误"},"answer":["A"],"rationale":"免疫抑制药在抑制免疫反应的同时也降低机体抗感染与抗肿瘤能力，并多有肝肾毒性，故强调最低有效剂量、联合用药并定期检查血象、肝肾功能与血药浓度。","id":"rph46_q022","chapter":"第四十六章 免疫功能调节剂","chapterIdx":45,"num":22},{"type":"T","stem":"判断题：卡介苗只能用于预防结核病，不能用于肿瘤的治疗。","options":{"A":"正确","B":"错误"},"answer":["B"],"rationale":"卡介苗有两种用途：作为减毒活疫苗预防结核病；膀胱内灌注可治疗表浅膀胱癌，机制为诱发局部非特异性炎症与免疫反应。活动性结核与免疫缺陷者禁用。","id":"rph46_q023","chapter":"第四十六章 免疫功能调节剂","chapterIdx":45,"num":23}]},{"title":"第四十七章 生物技术药物","questions":[{"type":"D","stem":"名词解释：生物技术药物","answer":"利用生物体、生物组织或其成分，通过基因工程、细胞工程与发酵工程等技术生产的用于预防、治疗和诊断疾病的药物，多为蛋白质、多肽或核酸。","rationale":"出自概念手册「生物技术药物」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph47_q001","chapter":"第四十七章 生物技术药物","chapterIdx":46,"num":1},{"type":"D","stem":"名词解释：细胞因子","answer":"由免疫细胞与非免疫细胞分泌的小分子蛋白质，结合特异性受体后发挥免疫调节、抗病毒、抗肿瘤与促进造血等作用，具有多效性与网络性。","rationale":"出自概念手册「生物技术药物」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph47_q002","chapter":"第四十七章 生物技术药物","chapterIdx":46,"num":2},{"type":"D","stem":"名词解释：干扰素α","answer":"由白细胞产生的一类糖蛋白，具有抗病毒、抗肿瘤与免疫调节作用，用于慢性乙型与丙型病毒性肝炎、毛细胞白血病与肾细胞癌。","rationale":"出自概念手册「生物技术药物」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph47_q003","chapter":"第四十七章 生物技术药物","chapterIdx":46,"num":3},{"type":"D","stem":"名词解释：白细胞介素-2","answer":"主要由活化T细胞产生的细胞因子，促进T细胞增殖与杀伤活性，用于转移性肾癌与黑色素瘤，大剂量可致毛细血管渗漏综合征。","rationale":"出自概念手册「生物技术药物」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph47_q004","chapter":"第四十七章 生物技术药物","chapterIdx":46,"num":4},{"type":"D","stem":"名词解释：促红细胞生成素","answer":"由肾皮质间质细胞分泌的糖蛋白，作用于红系祖细胞促进其增殖分化，用于肾性贫血、肿瘤化疗相关贫血与外科自体输血。","rationale":"出自概念手册「生物技术药物」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph47_q005","chapter":"第四十七章 生物技术药物","chapterIdx":46,"num":5},{"type":"D","stem":"名词解释：重组人粒细胞集落刺激因子","answer":"基因工程制备的集落刺激因子，刺激中性粒细胞前体增殖分化并增强其吞噬功能，用于化疗后中性粒细胞减少。","rationale":"出自概念手册「生物技术药物」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph47_q006","chapter":"第四十七章 生物技术药物","chapterIdx":46,"num":6},{"type":"D","stem":"名词解释：粒细胞-巨噬细胞集落刺激因子","answer":"刺激粒细胞与巨噬细胞系增殖分化的细胞因子，用于骨髓移植后与化疗后的造血恢复，可致发热、骨痛与皮疹。","rationale":"出自概念手册「生物技术药物」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph47_q007","chapter":"第四十七章 生物技术药物","chapterIdx":46,"num":7},{"type":"D","stem":"名词解释：肿瘤坏死因子","answer":"主要由巨噬细胞产生，可直接杀伤肿瘤细胞并引起炎症反应，全身用药毒性大，现主要用于肢体肿瘤的局部隔离灌注。","rationale":"出自概念手册「生物技术药物」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph47_q008","chapter":"第四十七章 生物技术药物","chapterIdx":46,"num":8},{"type":"D","stem":"名词解释：生长因子类","answer":"包括表皮生长因子、成纤维细胞生长因子、胰岛素样生长因子与血小板衍生生长因子等，促进细胞增殖与创面修复，局部外用较安全。","rationale":"出自概念手册「生物技术药物」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph47_q009","chapter":"第四十七章 生物技术药物","chapterIdx":46,"num":9},{"type":"D","stem":"名词解释：疫苗","answer":"用病原微生物或其抗原成分制成、用于人工主动免疫以预防传染病的生物制品，分减毒活疫苗、灭活疫苗、亚单位疫苗与核酸疫苗等。","rationale":"出自概念手册「生物技术药物」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph47_q010","chapter":"第四十七章 生物技术药物","chapterIdx":46,"num":10},{"type":"F","stem":"填空题：用病原微生物或其抗原成分制成、用于人工主动免疫以预防传染病的生物制品，分减毒活______、灭活疫苗、亚单位疫苗与核酸疫苗等。","answer":"疫苗","rationale":"出自概念手册「生物技术药物」核心概念：疫苗。","id":"rph47_q011","chapter":"第四十七章 生物技术药物","chapterIdx":46,"num":11},{"type":"D","stem":"名词解释：减毒活疫苗","answer":"用毒力减弱的活微生物制成，接种后近似自然感染，免疫应答持久、常只需一次，但免疫缺陷者与孕妇禁用。","rationale":"出自概念手册「生物技术药物」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph47_q012","chapter":"第四十七章 生物技术药物","chapterIdx":46,"num":12},{"type":"D","stem":"名词解释：类毒素","answer":"细菌外毒素经甲醛处理失去毒性而保留免疫原性的制品，如破伤风类毒素与白喉类毒素，用于人工主动免疫。","rationale":"出自概念手册「生物技术药物」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph47_q013","chapter":"第四十七章 生物技术药物","chapterIdx":46,"num":13},{"type":"F","stem":"填空题：细菌外毒素经甲醛处理失去毒性而保留免疫原性的制品，如破伤风______与白喉类毒素，用于人工主动免疫。","answer":"类毒素","rationale":"出自概念手册「生物技术药物」核心概念：类毒素。","id":"rph47_q014","chapter":"第四十七章 生物技术药物","chapterIdx":46,"num":14},{"type":"D","stem":"名词解释：人血液制品","answer":"由健康人血浆或胎盘血提取的制品，包括人血白蛋白、免疫球蛋白、凝血因子Ⅷ与纤维蛋白原等，用于扩容、补充抗体与纠正凝血障碍。","rationale":"出自概念手册「生物技术药物」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph47_q015","chapter":"第四十七章 生物技术药物","chapterIdx":46,"num":15},{"type":"D","stem":"名词解释：抗毒素","answer":"用类毒素免疫动物后取得的含抗体的血清制品，用于治疗与紧急预防外毒素所致疾病，使用前必须做皮肤过敏试验。","rationale":"出自概念手册「生物技术药物」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph47_q016","chapter":"第四十七章 生物技术药物","chapterIdx":46,"num":16},{"type":"D","stem":"名词解释：治疗性抗体","answer":"通过基因工程制备的针对特定抗原的单克隆抗体，如曲妥珠单抗、利妥昔单抗与英夫利西单抗，用于肿瘤与自身免疫病的靶向治疗。","rationale":"出自概念手册「生物技术药物」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph47_q017","chapter":"第四十七章 生物技术药物","chapterIdx":46,"num":17},{"type":"D","stem":"名词解释：基因治疗","answer":"将外源正常基因导入靶细胞以纠正或补偿基因缺陷、从而达到治疗目的的方法，关键在于安全高效的载体与稳定的基因表达。","rationale":"出自概念手册「生物技术药物」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph47_q018","chapter":"第四十七章 生物技术药物","chapterIdx":46,"num":18},{"type":"D","stem":"名词解释：重组人胰岛素","answer":"通过基因工程由大肠埃希菌或酵母菌生产的胰岛素，纯度高、可大量供应且不易引起过敏，用于糖尿病的替代治疗。","rationale":"出自概念手册「生物技术药物」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph47_q019","chapter":"第四十七章 生物技术药物","chapterIdx":46,"num":19},{"type":"D","stem":"名词解释：酶类生物制品","answer":"作为药物应用的酶制剂，如链激酶、尿激酶用于溶栓，阿糖苷酶用于酶缺陷病的替代治疗，多具有抗原性。","rationale":"出自概念手册「生物技术药物」核心概念；背完后可对照该单元的可背诵版核对。","id":"rph47_q020","chapter":"第四十七章 生物技术药物","chapterIdx":46,"num":20},{"type":"S","stem":"简答题：简述生物技术药物的主要类别及其代表品种。","answer":"①细胞因子类：干扰素α、白细胞介素-2、促红细胞生成素、粒细胞集落刺激因子等，用于抗病毒、抗肿瘤及纠正贫血与粒细胞减少；②疫苗与类毒素：卡介苗、乙型肝炎疫苗、破伤风类毒素，用于人工主动免疫预防传染病；③抗毒素与人血液制品：破伤风抗毒素用于人工被动免疫，人血白蛋白、静脉注射免疫球蛋白用于扩容、补充抗体与纠正凝血障碍；④治疗性抗体：曲妥珠单抗、利妥昔单抗、英夫利西单抗，用于肿瘤与自身免疫病的靶向治疗；⑤基因治疗与酶类制品：以腺相关病毒等为载体治疗单基因遗传病与部分肿瘤，链激酶、尿激酶用于溶栓。","rationale":"采分点为“细胞因子、疫苗与类毒素、抗毒素与血液制品、治疗性抗体、基因治疗”五类及代表品种。易错：混淆类毒素（主动免疫）与抗毒素（被动免疫）的用途。","id":"rph47_q021","chapter":"第四十七章 生物技术药物","chapterIdx":46,"num":21},{"type":"F","stem":"填空题：生物技术药物多为蛋白质或多肽，口服易被______破坏，一般须______给药，并具有种属特异性和免疫原性。","answer":"①消化酶 ②注射","rationale":"这是生物技术药物与化学药物的根本差别；种属特异性与免疫原性还决定了其不良反应以过敏与输注反应多见。","id":"rph47_q022","chapter":"第四十七章 生物技术药物","chapterIdx":46,"num":22},{"type":"F","stem":"填空题：疫苗与类毒素属人工______免疫，起效慢但维持持久；抗毒素与免疫球蛋白属人工______免疫，起效快但维持短暂。","answer":"①主动 ②被动","rationale":"主动免疫激发机体自身产生抗体，故持久；被动免疫直接输入现成抗体，故起效快而短暂，抗毒素还须做皮肤过敏试验。","id":"rph47_q023","chapter":"第四十七章 生物技术药物","chapterIdx":46,"num":23},{"type":"T","stem":"判断题：抗毒素为异种血清蛋白，使用前必须做皮肤过敏试验，并备好肾上腺素以应对过敏性休克。","options":{"A":"正确","B":"错误"},"answer":["A"],"rationale":"抗毒素多用类毒素免疫动物后取得，属异种蛋白，可致过敏反应甚至过敏性休克，故用前必须皮试并备肾上腺素等急救药品。","id":"rph47_q024","chapter":"第四十七章 生物技术药物","chapterIdx":46,"num":24},{"type":"T","stem":"判断题：促红细胞生成素与粒细胞集落刺激因子同属造血生长因子，前者针对粒系、后者针对红系。","options":{"A":"正确","B":"错误"},"answer":["B"],"rationale":"两者作用相反：促红细胞生成素作用于红系祖细胞，用于肾性贫血与化疗相关贫血；粒细胞集落刺激因子针对粒系，用于化疗后中性粒细胞减少。","id":"rph47_q025","chapter":"第四十七章 生物技术药物","chapterIdx":46,"num":25}]}]};
